  ('official_bank_gst111', 'retire', 100, $official_bank_source$"c2d905dc-6c49-5318-aa0c-4bf9d0a6c371"$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 1, $official_bank_source${"itemId":"499f18cf-1efe-5a10-9f2c-53010010e406","questionId":"7c68dc81-acf9-5a81-8aad-9b1e4f05d941","sourceKey":"bank:GST111:GST111-0001","payload":{"prompt":"Listening entails;","options":["Specifying what a speaker would say","The ability to identify and understand what a speaker is saying","Making assertions and statement that guide the speakers speech","Keeping quite so that the speaker is not distracted"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Listening is the ability to receive, perceive and decode the meaning of spoken words, so B is correct. It is a receptive skill: you take in and understand what the speaker is saying. Options A and C describe the listener acting on the speaker (predicting or guiding the speech), and D, keeping quiet, is just good manners, not listening itself."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 2, $official_bank_source${"itemId":"ebe5e835-2aa2-5dca-bb01-ac86b1282ee2","questionId":"c11e274d-8e34-5c8f-ba56-099e721ffdf1","sourceKey":"bank:GST111:GST111-0002","payload":{"prompt":"Effective listening requires that;","options":["The listener dictates the pace and speed of the speakers delivery","The listener must pay total attention to what the speaker is saying","The listener interrupts the speaker whenever a point seems wrong","Examining the speakers attitude and comportment"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Effective listening starts with giving total attention to what the speaker is saying, which is option B. You concentrate on the content and wait for the speaker to finish a point before judging it. Option C is wrong because interrupting breaks your concentration and leads to hasty conclusions, and options A and D focus on controlling or judging the speaker instead of receiving the message."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 3, $official_bank_source${"itemId":"c32136a5-e410-5a8e-87e0-6f304c69b4d4","questionId":"e0a7dea3-98a4-5ab4-95bc-f4926b2fa57c","sourceKey":"bank:GST111:GST111-0003","payload":{"prompt":"The skills involved in listening are;","options":["Reading through the topic carefully","Preparing ahead of the lecture","Understanding the speaker's accent, vocabulary and presentation of the topic.","Writing down verbatim everything the speaker says"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"Listening is about decoding a spoken message, so the skills involved include understanding the speaker's accent, vocabulary and way of presenting the topic, which is option C. A lecturer's pronunciation and intonation can become barriers, which is why listeners learn to pick up cues like accent and word stress. Options A and B are things you do before the lecture, not listening skills, and D, writing down everything verbatim, is a note-taking habit you should avoid."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 4, $official_bank_source${"itemId":"73b4f8ef-b4f0-5d85-a9aa-7ba863168b8c","questionId":"9cb19fa9-c1b7-56cc-b446-9a0229d35268","sourceKey":"bank:GST111:GST111-0004","payload":{"prompt":"Which of these does not negatively affect listening","options":["Interfering background noise","Unfamiliar accent and speech affectation","Difficult vocabulary","Organized and cohesive speech"],"correctOption":3,"section":"Listening Skills and Note-taking","explanation":"Organized and cohesive speech helps the listener follow the message, so it does not harm listening, and that makes D the answer to this 'does not' question. Listening becomes unproductive because of things like noise in the environment, a speaker's pronunciation problems and the listener's state of mind. Background noise (A), an unfamiliar accent (B) and difficult vocabulary (C) are all barriers, so they do hurt listening."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 5, $official_bank_source${"itemId":"75092682-530a-53a3-adf0-263caf50eb52","questionId":"eae413c8-320f-59bf-a2bd-7a060ce593c6","sourceKey":"bank:GST111:GST111-0005","payload":{"prompt":"All but one of the following are necessary in pre-lecture preparations;","options":["Conducting surveys of course outlines and topic before hand","Making intelligent speculations about the lecturers sources","Arrival at lectures ahead of the lecturer","A reading of some introductory surveys if the topic is unfamiliar"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Option B is the odd one out: guessing about the lecturer's sources is not part of preparing for a lecture. Good preparation means revising related earlier lectures, reading about the topic, checking the meaning of new key words, and arriving early to sit close to the lecturer. Options A, C and D all match those habits, so they are necessary and cannot be the answer to this 'all but one' question."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 6, $official_bank_source${"itemId":"8405fca2-42f3-56bc-b3a8-682fad05c65f","questionId":"8a3f619c-5886-5ab5-bdf6-62e036869375","sourceKey":"bank:GST111:GST111-0006","payload":{"prompt":"The main goal of a lecture is to;","options":["Give course outline to students","Impart knowledge to students","Trade information between lecturer and students","Introduce lecturers to students"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"The main goal of a lecture is to impart knowledge to students, which is option B. The lecturer speaks on a subject so that students can capture its essence. Giving a course outline (A) or introducing lecturers (D) are small administrative matters, and C is wrong because a lecture is mostly one-way delivery from lecturer to students, not an equal trade of information."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 7, $official_bank_source${"itemId":"ed353e4d-510c-5adb-8bd0-93b020b19fd9","questionId":"4f91ec7b-88b2-5fed-bda0-d978b1c381be","sourceKey":"bank:GST111:GST111-0007","payload":{"prompt":"Lecturer delivery usually has three parts. These are;","options":["Introduction, main lecture and conclusion","Outline, main discussion and question time","Summary, main lecture and expansion of outlined points","Introduction, revision and conclusion"],"correctOption":0,"section":"Listening Skills and Note-taking","explanation":"Like any well-organized piece of communication, a lecture has an introduction, a main body and a conclusion, so A is correct. Lecturers even use transition words such as however and consequently to move from one part to the next. Options B and D include items like question time or revision that are not standard parts of the delivery itself, and C wrongly puts a summary at the start."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 8, $official_bank_source${"itemId":"40f1bf39-e61f-5e47-8746-008f79cc5673","questionId":"b5223c03-2d74-5a0e-92b9-d80ba4bc13f6","sourceKey":"bank:GST111:GST111-0008","payload":{"prompt":"One of the following is not a recommended practice in note taking;","options":["Verbatim recording","Use of personal abbreviations","Logical thinking of ideas","Summary of main points"],"correctOption":0,"section":"Listening Skills and Note-taking","explanation":"Verbatim recording, option A, is not recommended because you cannot and should not try to write down everything the lecturer says. Instead, reduce the lecture to note form using shorthand, symbols and abbreviations. Options B, C and D (personal abbreviations, logical organization of ideas and summarizing main points) are all good note-taking practices."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 9, $official_bank_source${"itemId":"d364220a-93b6-597e-bfcf-aac006e1fff0","questionId":"6b2470de-b523-5ca7-93ff-b3966b3b68dc","sourceKey":"bank:GST111:GST111-0010","payload":{"prompt":"All but one of the following are bad habits in note taking;","options":["Verbatim recording of everything in note taking","Recording main points with all the illustration","Recording main points and a selection of illustrations and examples","Recording all that the lecturer says"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"Good note-taking means separating main points from elaborations, examples and repetitions, and reducing the lecture to compact form. Recording the main points with just a selection of illustrations and examples (option C) does exactly this, so it is the one good habit. Options A and D both mean writing down everything, and B, recording every illustration, defeats the purpose of condensing the lecture."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 10, $official_bank_source${"itemId":"bd05b256-ed4e-583e-8233-a8c72599d02a","questionId":"73706b32-6985-59cf-921a-0ad173c142ec","sourceKey":"bank:GST111:GST111-0011","payload":{"prompt":"Note taking involves the following except;","options":["Summarizing the main point","Using inconsistent personal abbreviations","Making a selection from illustrations","Disregarding digressions"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Inconsistent personal abbreviations (option B) are not part of good note-taking. You may invent your own symbols and abbreviations, but you must use them consistently, otherwise you will not be able to read your own notes later. Summarizing main points (A), selecting from illustrations (C) and ignoring digressions (D) are all things effective note-takers do."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 11, $official_bank_source${"itemId":"7c2e121c-77a2-5a00-8b21-a82b7b0cf4f0","questionId":"9c2bbb25-5f5d-50c6-bf6f-50b33536c300","sourceKey":"bank:GST111:GST111-0012","payload":{"prompt":"A pre-lecture survey is basically","options":["Asking relevant questions at the beginning of a lecture","Listening and taking down notes during a lecture","Reading up on a topic before the lecture","Discussing a topic with classmates after the lecture"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"A pre-lecture survey simply means reading up on a topic before the lecture, so C is correct. It prepares you by giving you background, along with revising earlier related lectures and checking new key terms. Option A happens at the start of the lecture, B during it and D after it, so none of them is done beforehand."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 12, $official_bank_source${"itemId":"276ec181-93d4-5053-99f0-2b6dcfd93596","questionId":"78f8d2b4-735d-59e6-aee1-36dff99547fb","sourceKey":"bank:GST111:GST111-0013","payload":{"prompt":"A course outline is a listing of the","options":["Specific points raised during a lecture","Relevant topics to be treated in a particular course","Form and content of a topic","Main points articulated during a lecture"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"A course outline lists the relevant topics to be treated in a particular course, so B is correct. It is prepared before teaching begins, so it cannot be a record of the specific or main points raised in a lecture (A and D); those belong in lecture notes. Option C, the form and content of a topic, is much narrower than an outline that covers a whole course."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 13, $official_bank_source${"itemId":"f55babce-3126-524d-a4e1-ba5fcf2aafa3","questionId":"ce1b8577-0b86-54cc-a6e0-d5d3a8da65ed","sourceKey":"bank:GST111:GST111-0014","payload":{"prompt":"A good note taken from listening to lecturers is not","options":["Brief and concise","Legible","All that is said in class","Systemic and orderly"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"A good note is not a record of all that is said in class, so C is the answer. You should not write down everything the lecturer says; good notes use shorthand, abbreviations and summary to capture the main ideas and relevant details. Being brief and concise (A), legible (B) and systematic and orderly (D) are all qualities of good notes, so they are not the answer to this 'is not' question."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 14, $official_bank_source${"itemId":"3bf59736-ba5d-5243-ad1d-e6b625228717","questionId":"e0d0e3c0-ffb6-5a2f-b916-435743b1f87a","sourceKey":"bank:GST111:GST111-0037","payload":{"prompt":"Direct quotation can be distinguished from paraphrase in note taking by","options":["Underlining the quotation","Using quotation marks","Writing the quotation in capital letter","Writing in capital letters as well as underlining it"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"When taking notes, a direct quotation is shown by putting it in quotation marks, so B is correct. Short quotations are set within your text and enclosed in double quotation marks. Underlining (A) or writing in capitals (C and D) are not the recognized ways of showing that words are quoted exactly."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 15, $official_bank_source${"itemId":"c5f25096-207a-52c4-bc0d-1fcba4c48fcf","questionId":"e7595bf7-1bff-55c1-b99a-3a354f3b7122","sourceKey":"bank:GST111:GST111-0076","payload":{"prompt":"The course outline is usually provided by ____","options":["The department","Course representatives","Lecturers","All of the above"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"The course outline is prepared and handed out by the lecturer who will teach the course, option C, because the lecturer decides which topics will be covered and in what order. The department (A) approves the overall curriculum but does not give out an outline for each course, and course representatives (B) only pass on what the lecturer provides. Since A and B are not sources of the outline, D, all of the above, is also wrong."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 16, $official_bank_source${"itemId":"f35820fb-c96c-5681-aef2-35b4e3800a40","questionId":"4eceea78-1b7a-50c6-8932-ed76c32b739c","sourceKey":"bank:GST111:GST111-0079","payload":{"prompt":"All except the following are included in the course outline of GST105: Use of English","options":["Use of the library","Grammar","Phonology","Epistemology"],"correctOption":3,"section":"Listening Skills and Note-taking","explanation":"In this course, GST 105 (now GST 111) covers listening and speaking skills including the sounds of English (phonology), reading and writing skills, grammar, and the use of the library. So A, B and C are all in the outline. Epistemology (option D), the philosophical study of knowledge, is not part of a Use of English course, so it is the exception."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 17, $official_bank_source${"itemId":"d07d2da6-63bf-5a09-865b-2ae7bf7291eb","questionId":"2362943b-3f64-5c69-8a03-c78668c2424f","sourceKey":"bank:GST111:GST111-0184","payload":{"prompt":"Which receptive skill involves receiving, perceiving and decoding spoken words?","options":["listening","speaking","reading","writing"],"correctOption":0,"section":"Listening Skills and Note-taking","explanation":"Listening is the receptive skill of receiving, perceiving and decoding the meaning of spoken words, so A is correct. Reading (C) is also receptive, but it decodes written symbols, not speech. Speaking (B) and writing (D) are productive skills, since they create language rather than receive it."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 18, $official_bank_source${"itemId":"e91f8b03-bf37-5d2c-9fd0-081dd81bdeaf","questionId":"f4df54f9-9578-59c2-a7af-0be03fbe6b4d","sourceKey":"bank:GST111:GST111-0232","payload":{"prompt":"Post-lecture activities include all the following except ------------","options":["review","summary","disposal","revision"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"After a lecture you should revise or review your notes quickly, compare them with course-mates, tidy up and fill in missing bits, and try a summary in your own words. Disposal means throwing the notes away, which defeats the purpose of note-taking, so C is the odd one out. Review, summary and revision (A, B and D) are all post-lecture activities."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 19, $official_bank_source${"itemId":"82ce778d-8477-58a2-baef-63289bb9134e","questionId":"aeedc51e-615d-50ad-833f-d95678d429a6","sourceKey":"bank:GST111:GST111-0234","payload":{"prompt":"Noise is a ---------------- condition.","options":["physiological","physical","psychological","spiritual"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Noise is a physical condition, because it belongs to the environment, like a noisy or ill-ventilated room. Listening is hindered by physical conditions of the environment, physiological conditions of the speaker (A, such as speech defects) and psychological conditions of the listener (C, such as emotional state). Option D is not one of these categories."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 20, $official_bank_source${"itemId":"c119b6cf-5a85-5d77-8af5-37ae7e49296e","questionId":"8a1263f9-407d-52f3-87bf-f2fac671baa4","sourceKey":"bank:GST111:GST111-0269","payload":{"prompt":"Listening is not the ability to ------------------ the meaning of what is being said.","options":["perceive","denounce","receive","decode"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Listening is the ability to receive, perceive and decode the meaning of what is being said. To denounce means to condemn publicly, which has nothing to do with taking in meaning, so B is the odd one out. A, C and D all describe parts of listening."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 21, $official_bank_source${"itemId":"43ee4aaa-674d-5af1-ad62-ed1e5f4d6fdb","questionId":"5b37c3f0-3e8a-5caa-ac8d-013d8cf5ce64","sourceKey":"bank:GST111:GST111-0333","payload":{"prompt":"The abbreviation NEC in note-taking means --------------------","options":["Non-Essential Creatures","National Executive Council","Necessary","National Electoral Commission"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"In note-taking, NEC is a shorthand for 'necessary', in the same way that no. stands for number and gov for government. Options B and D read NEC as the initials of an organisation, but that is not its meaning when you are making notes."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 22, $official_bank_source${"itemId":"8c58f9fd-0b1e-52d7-b0fa-cc84463b5a00","questionId":"478eb235-e107-52ec-b494-b61a0eaf6932","sourceKey":"bank:GST111:GST111-0345","payload":{"prompt":"One of the following conditions does not affect listening.","options":["the physiological","the physical","the spiritual","the psychological"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"Three conditions affect listening: the physical condition of the environment, the physiological condition of the speaker and the psychological condition of the listener. Spiritual conditions are not among them, so C is the one that does not affect listening, while A, B and D do."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 23, $official_bank_source${"itemId":"50e1d112-1b17-509b-a078-c7b91eac8e2e","questionId":"6389d181-5be9-5ef7-8fac-82607cd5c192","sourceKey":"bank:GST111:GST111-0382","payload":{"prompt":"Listening to a lecturer does not include -------","options":["watching out for non-verbal cues","observing illustrations and demonstrations","admiring his/her outfit and composure","listening to phonological cues"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"Admiring the lecturer's outfit is a distraction created by dressing, not part of listening, so C is the answer. When listening to a lecturer you should watch for non-verbal cues, observe illustrations and demonstrations, and listen for phonological cues such as voice changes and stress, which are options A, B and D."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 24, $official_bank_source${"itemId":"54015da9-fdee-559b-8261-80f6d1ba2171","questionId":"cbe5ec43-5a40-5f66-a4c3-58776b5ff436","sourceKey":"bank:GST111:GST111-0392","payload":{"prompt":"Students are advised to maintain ---------------- contact with their lecturers during classes.","options":["eye","virtual","full","close"],"correctOption":0,"section":"Listening Skills and Note-taking","explanation":"Maintaining eye contact with your lecturer is the beginning of effective listening, because it links your mind with the speaker's and shows you are ready to process the message. So A is correct. Close contact (D) only suggests sitting near the lecturer, and virtual and full contact (B and C) are not the listening strategy being described."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 25, $official_bank_source${"itemId":"64bf5cd0-a0ae-5c0b-a311-e28997fb86da","questionId":"74c2b51f-7ff7-553f-96b1-2fb92ae3e65f","sourceKey":"bank:GST111:GST111-0418","payload":{"prompt":"During lectures, we engage in ------------------- listening.","options":["informal","formal","total","partial"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Formal listening takes place in formal or academic settings, so during lectures we engage in formal listening (B). Informal listening (A) happens in everyday conversation and helps relationships. Total and partial listening (C and D) are not recognised types of listening."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 26, $official_bank_source${"itemId":"dd095964-3d02-57ad-bdc5-38829d497d66","questionId":"9785a6ec-fa75-5901-87ef-71e1dc15542c","sourceKey":"bank:GST111:GST111-0458","payload":{"prompt":"One of the following skills is not necessary in note-taking.","options":["sound articulation","sentence reduction","summary","paraphrasing"],"correctOption":0,"section":"Listening Skills and Note-taking","explanation":"Sound articulation is a speaking skill, not a note-taking skill, so A is the odd one out. Effective note-taking needs skills such as recognising main ideas, reducing content to note form, sentence reduction, summary and paraphrasing, which are B, C and D."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 27, $official_bank_source${"itemId":"68cf1438-117a-5462-960e-3c92693279bb","questionId":"a74fbc96-14bf-55c8-acaa-ee4fd4c3f3d8","sourceKey":"bank:GST111:GST111-0479","payload":{"prompt":"Not waiting for the lecture to end before drawing yourconclusion on the content suggests --------------","options":["hasty generalisation","emotional attachment","distraction","mental challenge"],"correctOption":0,"section":"Listening Skills and Note-taking","explanation":"Not waiting for the lecture to end before drawing a conclusion is hasty generalisation (A); a good listener is patient enough to let the speaker finish the point before reacting. Emotional attachment (B) refers to prejudice about the topic or lecturer, distraction (C) refers to noise and other interruptions, and mental challenge (D) is actually a positive attitude to adopt."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 28, $official_bank_source${"itemId":"adea6f5c-bb94-5d06-8888-7b95eebc18e2","questionId":"cdb88813-bb4d-5192-8483-44b01245c9f6","sourceKey":"bank:GST111:G111N1-001","payload":{"prompt":"A 100L student at UNILAG who is grieving the loss of a relative finds it hard to follow a lecture. Which condition is causing her ineffective listening?","options":["The linguistic condition of the lecture","The psychological condition of the listener","The physiological condition of the lecturer","The physical condition of the environment"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Grief is an emotional state, and the emotional state or mind of the listener is a psychological condition. The physical condition refers to the environment, such as noise or poor ventilation, not to the listener's feelings."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 29, $official_bank_source${"itemId":"6a81d1a7-8662-5bab-83e7-07f1137e1e7f","questionId":"e95cdf7b-1f3c-53cc-ab89-d7ac6ec3f612","sourceKey":"bank:GST111:G111N1-002","payload":{"prompt":"Which of the following is NOT a purpose of formal listening?","options":["To analyse a method or step","To evaluate or criticise a theory or argument","To improve social relationships in normal conversation","To remember a formula or concept"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"Improving relationships is what informal listening does in normal conversation. Evaluating a theory, remembering a formula and analysing a method are all purposes of formal listening in academic settings such as classes."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 30, $official_bank_source${"itemId":"7a9c7df6-ee89-52d7-a8b8-0da2e687e62d","questionId":"7719c94d-6ab0-577a-b8fa-e238375347f2","sourceKey":"bank:GST111:G111N1-003","payload":{"prompt":"The skill of keeping a record of a speaker's message and recording the essential points from written materials is called","options":["note-taking","transcription","paraphrasing","skimming"],"correctOption":0,"section":"Listening Skills and Note-taking","explanation":"Note-taking is exactly this: keeping a record of what a speaker says and of the essential points in written texts. Paraphrasing is only one skill used within note-taking, namely restating an idea in your own words."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 31, $official_bank_source${"itemId":"c05ec53e-4291-50d4-8360-2dd82060a190","questionId":"4ec277a8-6df0-550c-b201-0dc75e2b3968","sourceKey":"bank:GST111:G111N1-004","payload":{"prompt":"To take notes effectively, a student needs skill in which of the following?","options":["Using a different set of symbols for each lecture","Writing down only the speaker's examples","Citing and referencing sources correctly","Recording everything the speaker says word for word"],"correctOption":2,"section":"Listening Skills and Note-taking","explanation":"Citing and referencing the works you use correctly is one of the six requirements for effective note-taking. Recording everything word for word is wrong because effective note-taking reduces content to a short, summarised form and avoids verbatim writing."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 32, $official_bank_source${"itemId":"57c026bd-1bab-5d4e-ba5b-20572302a7b0","questionId":"9a0a8d38-0fe0-5afa-99e0-bb472ba8f9cf","sourceKey":"bank:GST111:G111N1-005","payload":{"prompt":"A lecturer in a firm's training session in Ikeja first explains what drives inflation in Nigeria and then explains what inflation does to households. Which organising principle is the lecture following?","options":["Past to present","General to specific","Problem and solution","Cause and result"],"correctOption":3,"section":"Listening Skills and Note-taking","explanation":"Moving from what produces something to what it leads to is the cause-and-result organising principle. Problem and solution would require the speaker to propose remedies, which this talk does not do."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 33, $official_bank_source${"itemId":"0e01783f-0efd-5e6a-a73e-e4b63fab7bdd","questionId":"83d78fe2-a448-5df4-b828-b0b4f8cad076","sourceKey":"bank:GST111:G111N1-006","payload":{"prompt":"While listening to a lecture, words such as 'in addition', 'however', 'moreover' and 'consequently' should be noted as","options":["visual illustrations","phonological cues","non-verbal cues","transition cues"],"correctOption":3,"section":"Listening Skills and Note-taking","explanation":"These connecting words are transition cues that show how the speaker's ideas link and where the talk is heading. Phonological cues are features of the voice, such as accent, stress and speed, not linking words."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 34, $official_bank_source${"itemId":"d412e10e-909f-5ae0-aa90-add6fe9e3a85","questionId":"b07d7268-5e01-5393-8a1b-26b34e0a2f47","sourceKey":"bank:GST111:G111N1-007","payload":{"prompt":"During a lecture, changes in the lecturer's voice, accent, word stress and speed are examples of","options":["transition cues","phonological cues","visual illustrations","non-verbal cues"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Features carried by the sound of the voice, such as accent, word stress, speed and emotional nuance, are phonological cues. Non-verbal cues are different because they are seen, not heard: facial expressions, gestures and body movement."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 35, $official_bank_source${"itemId":"42bb685c-cbe1-557f-b57d-19b0b6304f5d","questionId":"f59dbfd3-c9d3-5c4e-aaaa-0e99f94e3b45","sourceKey":"bank:GST111:G111N1-008","payload":{"prompt":"Which of the following is an AFTER-lecture activity for effective note-taking?","options":["Checking new words related to the topic","Preparing the format of your notes","Arriving early and sitting close to the lecturer","Comparing your notes with those of course-mates"],"correctOption":3,"section":"Listening Skills and Note-taking","explanation":"Comparing what you wrote with course-mates soon after the class helps you fill in gaps. Arriving early and sitting close to the speaker is a step taken before the class, as are checking new words and preparing the format you will write in."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 36, $official_bank_source${"itemId":"55564b8e-d4c7-5efa-9619-39f7168da35f","questionId":"803a2a31-7582-5fcb-95e1-debe35987264","sourceKey":"bank:GST111:G111N1-009","payload":{"prompt":"In note-taking, the abbreviation 'c.f.' stands for","options":["that is","note well","including","confer or compare"],"correctOption":3,"section":"Listening Skills and Note-taking","explanation":"'c.f.' means confer, that is, compare one point with another. 'That is' is written as 'i.e.', 'note well' as 'NB' and 'including' as 'incl.'."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 37, $official_bank_source${"itemId":"3e71549b-b898-5926-99ef-748befd1af70","questionId":"34d8d292-a5d0-500f-826d-fae8fcbea0a2","sourceKey":"bank:GST111:G111N1-010","payload":{"prompt":"A student deliberately ignores her tribal and religious bias against a guest lecturer so that she can follow his argument. Which listening strategy is she applying?","options":["Avoiding hasty generalisations","Suppressing emotional attachment","Treating listening as a mental challenge","Asking mental questions"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Putting aside religious, cultural, tribal or financial bias and personal emotions is the strategy of suppressing emotional attachment. Avoiding hasty generalisations is about waiting for the speaker to finish before drawing conclusions, which is a different strategy."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 38, $official_bank_source${"itemId":"41c85ec9-4473-5476-ad5b-781082d0b8bd","questionId":"7f891fa5-9b51-5a9c-8f05-1f1cbd91902f","sourceKey":"bank:GST111:G111N1-011","payload":{"prompt":"When taking notes, where should you write your own thoughts about what the lecturer is saying?","options":["Mixed in with the lecturer's main points","In a separate column or in the margin","In a separate notebook kept at home","Nowhere, because personal thoughts are not allowed"],"correctOption":1,"section":"Listening Skills and Note-taking","explanation":"Your own thoughts should be added in a separate column or in the margin so that they stay distinct from the speaker's points. Mixing them in with the main points makes it hard to tell later which ideas came from the speaker."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 39, $official_bank_source${"itemId":"a27c5ca8-0e2a-5cc2-871d-d4988e6f2bb2","questionId":"b2b92adb-db52-56d4-9918-5a1a56e449f6","sourceKey":"bank:GST111:GST111-0126","payload":{"prompt":"Phonetics is to pronunciation what ---------------- is to spelling.","options":["syntax","semantics","interpretation","orthography"],"correctOption":3,"section":"Speaking Skills I: Sounds of English","explanation":"Phonetics is the systematic study of how words are pronounced, and orthography, option D, is the conventional system of spelling words in a language, so the two are parallel. Syntax (A) deals with sentence structure and semantics (B) with meaning, while interpretation (C) is not a branch of language study, so none of them relates to spelling."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 40, $official_bank_source${"itemId":"015178fc-c691-54da-8346-2723b3424ad1","questionId":"70bf6cce-3d96-5c1d-bdbe-a18bc07d8511","sourceKey":"bank:GST111:GST111-0136","payload":{"prompt":"The symbol ':' used alongside a phonetic symbol suggests ----------------","options":["labialisation","colony","length","aspiration"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"A colon-like mark written after a vowel symbol is a length mark showing that the vowel is long, as in the contrast between /i:/ in seat and /I/ in sit, so C is correct. It changes only the length, not the quality of the sound. Aspiration (D) and labialisation (A) are different features of consonants, and colony (B) is not a phonetic term at all."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 41, $official_bank_source${"itemId":"03a9de5a-0521-5246-9a7c-cd15c5852ac3","questionId":"c917386b-30b7-563a-af17-4aa251e6e7af","sourceKey":"bank:GST111:GST111-0152","payload":{"prompt":"The word 'youth' can be transcribed as ------------------","options":["/ju:θ/","/ju:ð/","/yu:θ/","/yu:ð/"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"Youth begins with the palatal glide /j/ (the sound spelt y), followed by the long vowel /u:/ as in food, and ends with the voiceless th sound /θ/, so A is correct. Options C and D wrongly use the letter y instead of the phonetic symbol /j/, and options B and D end in the voiced /ð/ of this and mother, which is not the sound in youth."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 42, $official_bank_source${"itemId":"0d3146e7-4df7-59e7-b819-bfb75f4c8da5","questionId":"a5a597b5-ef00-5541-9e2a-4cee67ac2a8b","sourceKey":"bank:GST111:GST111-0164","payload":{"prompt":"One of the following is not a distinction made between vowels.","options":["rounded/around","long/short","high/low","open/close"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"Vowels are described by tongue height (high/low), openness (close/open), length (long/short, also called tense/lax) and lip shape, where the lips may be spread, neutral or rounded. Rounded contrasts with spread or neutral, never with 'around', which is not a phonetic term, so A is the one that is not a real distinction. Options B, C and D are all genuine pairs."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 43, $official_bank_source${"itemId":"221840d4-f6c0-59a0-9abf-b6065eba0a39","questionId":"fa33a2e6-75e2-532c-a0ae-7a803782762f","sourceKey":"bank:GST111:GST111-0175","payload":{"prompt":"/s/ /t/ and /n/ are related based on their --------------- of articulation.","options":["place","manner","nature","length"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"The sounds /s/, /t/ and /n/ are all alveolar, made with the tip or blade of the tongue touching the alveolar ridge behind the upper teeth, so what they share is place of articulation. Option B (manner) is wrong because their manners differ: /s/ is a fricative, /t/ a stop and /n/ a nasal. Nature and length are not ways of describing consonants."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 44, $official_bank_source${"itemId":"b774452b-43f7-511f-8933-aa4610bc01ad","questionId":"3da0ae9a-ac74-5aa0-8764-92523e8a2101","sourceKey":"bank:GST111:GST111-0193","payload":{"prompt":"There are -------------- sounds altogether in English.","options":["20","26","44","24"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"English has forty-four significant sounds (phonemes): twenty vowels and twenty-four consonants, so C is correct. Options A (20) and D (24) are only the vowel count and the consonant count on their own, and B (26) is the number of letters in the alphabet. Letters and sounds do not correspond one to one."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 45, $official_bank_source${"itemId":"8f361337-85e3-5ab4-b364-2bc5e5d0b29a","questionId":"f431fa50-e476-55d6-8798-3cd9b06ea110","sourceKey":"bank:GST111:GST111-0194","payload":{"prompt":"The term 'lateral' refers to -----------------","options":["/r/","/l/","/j/","/w/"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"A lateral consonant is made when the tip of the tongue touches the alveolar ridge and air escapes along the sides of the tongue, and that sound is /l/. Option A (/r/) is a post-alveolar approximant, while C and D (/j/ and /w/) are glides, a sub-group of approximants."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 46, $official_bank_source${"itemId":"9e49fdce-19c9-52e5-95e9-0ab0b2a59e6e","questionId":"c3858598-0322-598a-a174-067425d97b7f","sourceKey":"bank:GST111:GST111-0221","payload":{"prompt":"The airstream that is used for the production of most English sounds is the ----------- ------ airstream.","options":["laryngeal","pulmonic","glottalic","velaric"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"The lungs provide the airstream for most speech, and this air pushed out from the lungs is called the pulmonic egressive airstream. Option A (laryngeal) names where the vocal folds are rather than an airstream, while C and D (glottalic, velaric) are other airstream mechanisms used in some languages but not for ordinary English sounds."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 47, $official_bank_source${"itemId":"dfafc578-7e1b-5812-8aaf-4b7f3b9e6f26","questionId":"7c491497-a550-5afc-af04-0d616625a886","sourceKey":"bank:GST111:GST111-0230","payload":{"prompt":"Which of the following words contains three sounds?","options":["trust","cheap","frog","thoughts"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"Cheap has three sounds because the ch is a single affricate consonant, as in church, followed by the long vowel in seat and then p. The other words have more: trust (A) has five sounds, frog (C) has four, and thoughts (D) has four (th, the vowel, t, s), so only B fits."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 48, $official_bank_source${"itemId":"e3cdae64-f8e9-5867-8720-83a8d09097c0","questionId":"9b4efcaa-43d2-5b30-889c-a13461d9c6d9","sourceKey":"bank:GST111:GST111-0240","payload":{"prompt":"Which of the following is NOT one of the lip positions used to describe English vowels?","options":["rounded","neutral","pursed","spread"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"English vowels are described by three lip positions: spread (as in seat), neutral (as in cup) and rounded (as in food). Pursed is not one of these positions, so C is correct, while A, B and D are all genuine lip positions."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 49, $official_bank_source${"itemId":"95acfcb6-58bd-518b-ad72-b25d080ca3a5","questionId":"faaa2d3c-1d8a-5839-aaa6-ad6a28a54bd4","sourceKey":"bank:GST111:GST111-0246","payload":{"prompt":"--------------- combines the manner of articulation of stops and fricatives.","options":["glides","vowels","affricates","nasals"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"Affricates begin like plosives (stops) and end like fricatives: the airflow is first blocked completely and then released gradually with friction, as in the first sounds of church and judge. Option D is wrong because nasals start with a closure but release air through the nose, and A is wrong because glides are approximants with no closure and no friction."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 50, $official_bank_source${"itemId":"dabf8379-3e7b-5386-a4f8-7e5c83cc578a","questionId":"1643d598-908d-53eb-bbff-ec4e10e38acf","sourceKey":"bank:GST111:GST111-0253","payload":{"prompt":"High vowels are also described as -------------------- vowels.","options":["long","rounded","open","close"],"correctOption":3,"section":"Speaking Skills I: Sounds of English","explanation":"When the tongue is held up close to the roof of the mouth, high vowels such as /i:/ and /u:/ are produced, and these are also called close vowels, so D is correct. Option C (open) is the opposite, since low vowels are open, and A and B describe length and lip shape, not tongue height."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 51, $official_bank_source${"itemId":"61bbfc15-3787-56a6-98c9-49e32602ba33","questionId":"9426054a-e1f3-5548-8c58-bd10b5588a7e","sourceKey":"bank:GST111:GST111-0271","payload":{"prompt":"-------------------- is not a bilabial sound.","options":["/b/","/p/","/m/","/f/"],"correctOption":3,"section":"Speaking Skills I: Sounds of English","explanation":"Bilabial sounds are made with the two lips coming together, as in /p/, /b/, /m/ and /w/. The sound /f/ is labio-dental, made with the lower lip touching the upper front teeth, so D is not bilabial, while A, B and C are."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 52, $official_bank_source${"itemId":"bc8be633-a05e-5871-923f-ba5edd922a2c","questionId":"9631de0f-3c67-5aec-8e7e-7bfd17d3789e","sourceKey":"bank:GST111:GST111-0324","payload":{"prompt":"One of the following is not involved in vowel articulation","options":["tongue movement","lip shaping","length","contact"],"correctOption":3,"section":"Speaking Skills I: Sounds of English","explanation":"Vowels are produced with no obstruction to the airflow, so the articulators do not touch each other; that is why contact (D) is not involved in vowel articulation. Contact belongs to consonants. Tongue movement, lip shaping and length (A, B and C) are all used to describe vowels, so they are not the odd one out."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 53, $official_bank_source${"itemId":"328acfa9-ccbf-5d6e-872e-3fd2f39c281f","questionId":"366ca551-1950-58f4-8f02-b262e3e7e8a2","sourceKey":"bank:GST111:GST111-0353","payload":{"prompt":"----------------- is the high, back tense vowel.","options":["/ɜ:/","/ɑ:/","/u:/","/i:/"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"/u:/ is the high, back, tense vowel, heard in words like rule, food and who. Option D, /i:/, is also high and tense but it is a front vowel, A is a central vowel, and B is low and back."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 54, $official_bank_source${"itemId":"14355f05-c545-5319-96e5-05b66e602105","questionId":"c1e6bb55-0bae-5e62-90c6-7dfbb1f00b0d","sourceKey":"bank:GST111:GST111-0385","payload":{"prompt":"Vowel distinctions do not include:","options":["triphthongs","monophthongs","quadriphthongs","diphthongs"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"English vowels are divided into pure vowels or monophthongs (12) and diphthongs (8), and triphthongs are also mentioned when discussing strong syllables. There is no class called quadriphthongs in English phonology, so C is the odd one out, while A, B and D are genuine vowel distinctions."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 55, $official_bank_source${"itemId":"cb4d2f02-b9d2-5c59-b2d7-69a7cef07c13","questionId":"6d8b21dd-ba4f-5e6d-80e8-a7b8a5167f26","sourceKey":"bank:GST111:GST111-0406","payload":{"prompt":"Symbols used in phonetic transcription are adapted from -----------------","options":["PLA","APA","IPA","MLA"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"The symbols used to represent English sounds are adapted from the International Phonetic Association's alphabet, usually called the IPA (C). APA and MLA (B and D) are referencing styles, not phonetic systems, and PLA (A) is not a recognised source of phonetic symbols."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 56, $official_bank_source${"itemId":"b0b67f4e-34a9-5684-87e9-559a1186e1e3","questionId":"061cc758-c79f-5c23-995e-6d84c68e286b","sourceKey":"bank:GST111:GST111-0419","payload":{"prompt":"The lungs are housed in the -------------------------","options":["spinal cord","pharynx","larynx","rib cage"],"correctOption":3,"section":"Speaking Skills I: Sounds of English","explanation":"The lungs are sponge-like tissues housed in the rib cage, and they provide the airstream used for speech (D). The larynx (C) is tempting because it is part of the airway, but it houses the vocal folds, not the lungs. The pharynx (B) is part of the throat above the larynx, and the spinal cord (A) is part of the nervous system."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 57, $official_bank_source${"itemId":"7e2d38a8-bbed-5018-a166-9c451d9d7a19","questionId":"0521af4f-5655-5017-ad8c-7e02249cdfb2","sourceKey":"bank:GST111:GST111-0455","payload":{"prompt":"Voicing occurs as a result the ------------------ of the vocal folds.","options":["agitation","vibration","separation","relaxation"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"Voicing happens when the glottis is relatively closed and the vocal folds vibrate under air pressure from the lungs, so the answer is vibration (B). Separation (C) describes the open glottis that produces voiceless sounds, and agitation and relaxation (A and D) are not the terms used for voicing."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 58, $official_bank_source${"itemId":"392eba9b-15a1-5446-86f6-bac02d3639f9","questionId":"832a7e4c-572a-5179-94fd-34c9b0d69871","sourceKey":"bank:GST111:GST111-0478","payload":{"prompt":"---------------- is a glottal sound.","options":["/k/","/w/","/h/","/j/"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"/h/ is a voiceless glottal fricative, made with friction at the glottis, the gap between the vocal folds (C). /k/ (A) is a voiceless velar stop made with the back of the tongue against the soft palate. /w/ (B) is a bilabial glide and /j/ (D) is a palatal glide, so neither is made at the glottis."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 59, $official_bank_source${"itemId":"19d29d02-0171-5716-bd36-7e2f7fd44b27","questionId":"f17165d0-7658-5159-8b70-e458a775ae0b","sourceKey":"bank:GST111:G111N1-012","payload":{"prompt":"Of the 20 vowel sounds of English, how many are pure vowels (monophthongs)?","options":["12","20","24","8"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"English has 20 vowels made up of 12 pure vowels and 8 diphthongs. The figure 8 is the number of diphthongs, not of pure vowels."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 60, $official_bank_source${"itemId":"d1a028bb-8fe4-5adf-9c3a-0a83ce7b45f7","questionId":"dc222962-9235-5ce1-b50c-1705bc66e2cc","sourceKey":"bank:GST111:G111N1-013","payload":{"prompt":"How many diphthongs are there in English?","options":["3","8","12","5"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"English has 8 diphthongs, made up of 5 closing diphthongs and 3 centring diphthongs. The figure 5 counts only the closing group, not all the diphthongs."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 61, $official_bank_source${"itemId":"99ea38f9-cd8c-515c-a817-2b1fa890c975","questionId":"42ab1290-0070-5c88-88f6-accb42763b4a","sourceKey":"bank:GST111:G111N1-014","payload":{"prompt":"How many of the English diphthongs are closing (rising) diphthongs?","options":["5","8","12","3"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"Five of the eight diphthongs are closing: they start with a mid or low element and glide to a high one. The other 3 are the centring diphthongs, which end in the schwa."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 62, $official_bank_source${"itemId":"fca8daf8-fa9b-5c7c-a2ab-8baf73991b03","questionId":"89e9d931-fa78-5247-a041-b36548e6ede8","sourceKey":"bank:GST111:G111N1-015","payload":{"prompt":"The centring diphthongs of English are so called because they all end in","options":["a back rounded vowel","a nasal consonant","a high front vowel","the schwa, a central vowel"],"correctOption":3,"section":"Speaking Skills I: Sounds of English","explanation":"A centring diphthong glides towards the centre of the mouth and ends in the schwa. Ending in a high vowel is what marks the closing diphthongs instead."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 63, $official_bank_source${"itemId":"7173262b-e754-500e-8936-635bd4256e27","questionId":"345497aa-1662-5557-9bdd-6803d110bba0","sourceKey":"bank:GST111:G111N1-016","payload":{"prompt":"How many consonant phonemes does English have?","options":["24","12","44","20"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"Of the 44 English phonemes, 24 are consonants and 20 are vowels. The figure 44 is the total of all sounds, not the consonants alone."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 64, $official_bank_source${"itemId":"d68114b8-9e8f-5f0c-ae43-20f6caa62300","questionId":"618740b0-a13c-51f7-bd50-7900f6166625","sourceKey":"bank:GST111:G111N1-017","payload":{"prompt":"Which of the following is NOT one of the parameters for describing English consonants?","options":["State of the glottis","Place of articulation","Manner of articulation","Lip rounding"],"correctOption":3,"section":"Speaking Skills I: Sounds of English","explanation":"Consonants are described by place of articulation, manner of articulation and the state of the glottis (voicing). Lip rounding is one of the parameters used for vowels, not consonants."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 65, $official_bank_source${"itemId":"e83972bd-0a39-540b-aac9-873e988b31b4","questionId":"dba62e6d-4e34-551d-a9d3-63a29419d3a1","sourceKey":"bank:GST111:G111N1-018","payload":{"prompt":"English vowels are described WITHOUT reference to which of the following?","options":["Tongue height","Manner of articulation","Lip rounding","Duration"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"Vowels are described by tongue height, tongue horizontality, lip rounding and duration, not by place or manner. Manner of articulation belongs to consonants, which involve an obstruction of the airflow."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 66, $official_bank_source${"itemId":"7297502a-eff4-5fe3-9ecb-68ca87e5bfa9","questionId":"21357bd8-c322-5699-a435-0acd88c6e3eb","sourceKey":"bank:GST111:G111N1-019","payload":{"prompt":"When the glottis is wide open so that air passes freely through it, the sound produced is","options":["voiceless","lateral","voiced","nasal"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"An open glottis lets the air through without making the vocal folds vibrate, so the sound is voiceless. A voiced sound needs the glottis nearly closed so that the folds vibrate."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 67, $official_bank_source${"itemId":"3b0f9565-406f-5590-b408-591cfe9af59f","questionId":"2b047441-3599-5dcb-9ff5-66f8c6d8b1bd","sourceKey":"bank:GST111:G111N1-020","payload":{"prompt":"The gap between the vocal folds is called the","options":["larynx","glottis","pharynx","velum"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"The glottis is the space between the two vocal folds. The larynx is the structure that houses the vocal folds, not the gap between them."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 68, $official_bank_source${"itemId":"425b0bfb-9eb6-5eac-92c5-8f77533269e8","questionId":"e807ae21-5552-5f3c-9d9b-6a03f4a351f9","sourceKey":"bank:GST111:G111N1-021","payload":{"prompt":"Which articulator is a muscular flap that is raised to shut off the nasal tract?","options":["The alveolar ridge","The hard palate","The soft palate","The glottis"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"The soft palate (velum) is the muscular flap that rises to close off the nose. The hard palate is the bony front part of the roof of the mouth and cannot move."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 69, $official_bank_source${"itemId":"b894e42e-d54b-5b7a-92b0-19bcafd31c23","questionId":"aed3972a-5d7f-5b2f-b513-0a52039cf2b4","sourceKey":"bank:GST111:G111N1-022","payload":{"prompt":"Which of the following is the most flexible articulator?","options":["The lips","The tongue","The soft palate","The lower teeth"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"The tongue is the most flexible articulator, with parts such as the tip, blade, front, centre, back and root. The lips are also active articulators, but they are less flexible than the tongue."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 70, $official_bank_source${"itemId":"78ca03fb-938d-5bcb-9d8c-5a0213eb012c","questionId":"28db6706-d0a6-538e-837b-c6eaa0da6f11","sourceKey":"bank:GST111:G111N1-023","payload":{"prompt":"Which of the following is a passive (fixed) articulator?","options":["The hard palate","The tongue","The soft palate","The lips"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"Passive articulators do not move; the teeth and the hard palate are the fixed ones. The soft palate looks close to the hard palate but it is movable, so it is an active articulator."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 71, $official_bank_source${"itemId":"63fa5203-db51-5adc-9897-9008e32f733f","questionId":"e376783b-5db0-5939-ba23-f9ebce1799a5","sourceKey":"bank:GST111:G111N1-024","payload":{"prompt":"Consonants produced with a closure in the mouth and the velum lowered, so that the air escapes through the nose, are called","options":["laterals","fricatives","approximants","nasals"],"correctOption":3,"section":"Speaking Skills I: Sounds of English","explanation":"Nasals such as /m/ and /n/ block the mouth while the lowered velum lets the air out through the nose. A lateral, such as /l/, lets the air pass along the sides of the tongue instead."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 72, $official_bank_source${"itemId":"5a20d873-b6d6-50fd-a8d9-4db799c63556","questionId":"cc97654b-56ce-5c6e-a923-e690a3a10d4d","sourceKey":"bank:GST111:G111N1-025","payload":{"prompt":"The approximants /w/ and /j/ form the sub-group of sounds known as","options":["glides","affricates","laterals","liquids"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"/w/ and /j/ are the glides within the approximant class. Liquids is the name given to /l/ and /r/ together."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 73, $official_bank_source${"itemId":"c4935ee1-9c60-5588-9ae0-66ed944e6c20","questionId":"b138797f-1d1b-5fe6-bddc-e3bec9084bd5","sourceKey":"bank:GST111:G111N1-026","payload":{"prompt":"Taken together, the consonants /l/ and /r/ are known as","options":["stops","liquids","glides","nasals"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"/l/ and /r/ are grouped together as the liquids. The glides are /w/ and /j/, a different sub-group."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 74, $official_bank_source${"itemId":"481543ca-2fda-5814-b79f-7483eabe181f","questionId":"630391e2-b1c1-51a5-936e-bc82a625e7a8","sourceKey":"bank:GST111:G111N1-027","payload":{"prompt":"Using the order voicing, place, manner, the English consonant /p/ is described as a","options":["voiceless labio-dental fricative","voiced bilabial stop","voiceless bilabial stop","voiceless alveolar stop"],"correctOption":2,"section":"Speaking Skills I: Sounds of English","explanation":"/p/ is made with both lips (bilabial), with total closure and sudden release (stop), and without vibration of the vocal folds (voiceless). A voiced bilabial stop describes /b/, the voiced partner of /p/."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 75, $official_bank_source${"itemId":"5156c8ee-2a70-5fdb-bc83-f1a9e5ed10ce","questionId":"7b158f78-f45f-50a5-8e89-caac506dc59b","sourceKey":"bank:GST111:G111N1-028","payload":{"prompt":"The consonants /f/ and /v/ share the same place of articulation, which is","options":["bilabial","labio-dental","dental","alveolar"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"/f/ and /v/ are made with the lower lip against the upper teeth, so they are labio-dental. Bilabial sounds use both lips, as in /p/, /b/ and /m/."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 76, $official_bank_source${"itemId":"8c0f2c47-13bb-53f2-ad28-41937af90a4d","questionId":"71ce21a5-65af-57e8-a37c-eb5b99bd7ae0","sourceKey":"bank:GST111:G111N1-029","payload":{"prompt":"Which pair of English consonants is velar?","options":["/f/ and /v/","/k/ and /g/","/p/ and /b/","/t/ and /d/"],"correctOption":1,"section":"Speaking Skills I: Sounds of English","explanation":"/k/ and /g/ are made with the back of the tongue against the soft palate (velum), so they are velar. /t/ and /d/ are also stops, but they are alveolar."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 77, $official_bank_source${"itemId":"a2aff879-e38d-584f-b1eb-43d541f10a05","questionId":"b28a0459-3c63-5d89-9eb7-ae9fd66f53ec","sourceKey":"bank:GST111:G111N1-030","payload":{"prompt":"The fact that the letter 'a' is pronounced differently in 'gate', 'woman', 'many' and 'village' shows that","options":["each English letter has one fixed sound","English spelling reliably shows pronunciation","the letter 'a' is always a diphthong","English has little or no sound-letter correspondence"],"correctOption":3,"section":"Speaking Skills I: Sounds of English","explanation":"The same letter stands for different sounds in these words, so English spelling does not match its sounds closely. That is why spelling cannot be trusted to show how a word is pronounced."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 78, $official_bank_source${"itemId":"b2f02613-f683-5b69-a541-6ffd682e033e","questionId":"ab171a7c-9677-5e56-9e1d-82b6db36c6eb","sourceKey":"bank:GST111:G111N1-031","payload":{"prompt":"How many sounds are there in the word 'trust'?","options":["5","4","6","3"],"correctOption":0,"section":"Speaking Skills I: Sounds of English","explanation":"'trust' has five sounds: /t/, /r/, the short vowel heard in 'cut', /s/ and /t/. A common mistake is to count 4 by treating the cluster 'tr' or 'st' as a single sound."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 79, $official_bank_source${"itemId":"5dc70ec8-20d4-5908-a2fc-7ff9dab992e9","questionId":"407ff5f0-bb7c-5782-bdbb-8c9e294bc41e","sourceKey":"bank:GST111:GST111-0062","payload":{"prompt":"'humble:","options":["Report","Regret","Standard","Return"],"correctOption":2,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Humble is stressed on the first syllable (HUM-ble), and standard (STAN-dard), option C, has the same pattern. Report (re-PORT), regret (re-GRET) and return (re-TURN), options A, B and D, all carry their stress on the second syllable, so they do not match."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 80, $official_bank_source${"itemId":"58ba7c12-e33b-5868-8629-b51a3d39a0ae","questionId":"45728976-7e5e-57dd-bff1-7c94f2718c81","sourceKey":"bank:GST111:GST111-0063","payload":{"prompt":"Com'plaint:","options":["success","saddle","punish","marvel"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Complaint is stressed on the second syllable (com-PLAINT), and success (suc-CESS), option A, has the same pattern. Saddle (SAD-dle), punish (PUN-ish) and marvel (MAR-vel), options B, C and D, are all stressed on the first syllable."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 81, $official_bank_source${"itemId":"f46869ff-7b95-5060-a94e-4b8c014e2741","questionId":"3acfb8d1-4f66-59d4-8818-e00719c824eb","sourceKey":"bank:GST111:GST111-0067","payload":{"prompt":"con'cern","options":["pretext","combine","concert","comment"],"correctOption":1,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Concern is stressed on the second syllable (con-CERN), and the verb combine (com-BINE) has the same pattern, so B is correct. Pretext (PRE-text), concert (CON-cert) and comment (COM-ment) are all stressed on the first syllable. Concert may look tempting because it starts with con- like concern, but as a noun its stress falls on the first syllable."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 82, $official_bank_source${"itemId":"2012b0b5-a9a3-5172-aab5-14275ed4e6eb","questionId":"d40a820a-9967-554f-83e0-63899438bf14","sourceKey":"bank:GST111:GST111-0068","payload":{"prompt":"pro'fessor","options":["creator","activist","company","minister"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Professor has its stress on the second syllable (pro-FES-sor), and creator (cre-A-tor) has the same pattern, so A is correct. Activist (AC-ti-vist), company (COM-pa-ny) and minister (MIN-is-ter) all take their stress on the first syllable, so they do not match."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 83, $official_bank_source${"itemId":"9bc3e0cf-cf32-517f-a15e-89603dcfa06b","questionId":"4caaebd3-59ab-5158-8198-373b80bbbeb5","sourceKey":"bank:GST111:GST111-0069","payload":{"prompt":"indi'cation","options":["ambition","reaction","education","competitor"],"correctOption":2,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Indication has four syllables with the main stress on the third (in-di-CA-tion), and education (ed-u-CA-tion) follows the same pattern, so C is correct. Words ending in -tion usually take their stress on the syllable just before the ending. Ambition (am-BI-tion) and reaction (re-AC-tion) have only three syllables, and competitor (com-PE-ti-tor) is stressed on the second syllable, so none of them matches."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 84, $official_bank_source${"itemId":"0ca32043-1fc6-5b7a-a141-b5bd27b5edbc","questionId":"75e1d7a4-3f25-596b-b405-43d19a839bf2","sourceKey":"bank:GST111:GST111-0070","payload":{"prompt":"'capitalism","options":["Occurrence","Insurance","Regionalism","Development"],"correctOption":2,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Capitalism takes its main stress on the first syllable (CAP-i-tal-ism), and regionalism (RE-gion-al-ism) has the same pattern, so C is correct. The suffix -ism does not move the stress, so each word keeps the stress of its base (capital, region). Occurrence (oc-CUR-rence), insurance (in-SUR-ance) and development (de-VEL-op-ment) are all stressed on the second syllable."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 85, $official_bank_source${"itemId":"2202ac07-f0d7-5e8d-bb1d-f5ee563b9e3c","questionId":"f188a23c-c5bc-5bb6-8f34-a8e5d1540f87","sourceKey":"bank:GST111:GST111-0105","payload":{"prompt":"Affixes which cause stress to move from one syllable to another are known as -------- --------------- affixes.","options":["stress-conserving","stress-neutral","stress-moving","stress-bearing"],"correctOption":2,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Affixes that shift the stress to a different syllable of the stem are called stress-moving affixes, option C, for example -ic and -ity, as in MAGnet becoming magNETic and INfidel becoming infiDELity. Stress-neutral affixes (B) leave the original stress unchanged, like un- in unPLEASant, and stress-bearing affixes (D) carry the stress themselves, like -eer in engiNEER. Stress-conserving (A) is not a standard term."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 86, $official_bank_source${"itemId":"5c9c2d34-274e-5d8b-82b0-a67a9f74f9fe","questionId":"95be0a4f-0bcf-5a9c-a5c1-d6d6601d9eff","sourceKey":"bank:GST111:GST111-0139","payload":{"prompt":"A maximum of --------------- consonants are permissible at the beginning of an English syllable.","options":["3","4","5","6"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"The structure of the English syllable is C0-3 V C0-4, so the onset (the consonants before the vowel) can hold up to three consonants, as in spree, straw and sprint. That makes A, 3, correct. Options B, C and D (4, 5, 6) exceed the limit; four consonants are possible only at the end of a syllable, as in strengths."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 87, $official_bank_source${"itemId":"1f618a06-1d7e-55e8-8009-306bee145f54","questionId":"3aef8e01-dc34-5eb0-b54e-3720831ff9dd","sourceKey":"bank:GST111:GST111-0176","payload":{"prompt":"-eer in 'engineer' and -aire in 'millionaire' are examples of -------------------- affixes.","options":["stress-neutral","stress-moving","stress-bearing","stress-conserving"],"correctOption":2,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Stress-bearing affixes are the ones that carry the primary stress themselves, as -eer does in engineer and -aire does in millionaire, so C is correct. A (stress-neutral) affix leaves the stress where it was, B (stress-moving) shifts stress to another syllable of the stem, and D (stress-conserving) is not a recognised category."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 88, $official_bank_source${"itemId":"b9b07c82-826b-538a-8409-68160e765394","questionId":"6fbb7f09-aaa0-5bce-aba6-a59d7df5ae31","sourceKey":"bank:GST111:GST111-0192","payload":{"prompt":"An affix which does not affect the position of stress in a word is ---------------","options":["stress-neutral","stress-bearing","stress-conserving","stress-moving"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"A stress-neutral affix does not change where the stress falls: the word keeps its original stress, as in pleasant and unpleasant, or market and marketing. Option B (stress-bearing) means the affix itself takes the stress, D (stress-moving) shifts it to another syllable, and C (stress-conserving) is not a recognised category."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 89, $official_bank_source${"itemId":"87fa2003-221e-54c0-9081-b3056fa5b5c6","questionId":"84785199-42cd-59fb-86e0-57ed9c0a7ae8","sourceKey":"bank:GST111:GST111-0203","payload":{"prompt":"One of the following is not a criterion for predicting stress.","options":["syntactic","phonological","morphological","semantic"],"correctOption":3,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Stress placement in English words can be predicted using phonological criteria (the structure of the syllables), syntactic criteria (the word class, as in REcord versus reCORD) and morphological criteria (the effect of affixes). Semantic criteria, that is, meaning, are not used, so D is correct, and A, B and C are genuine criteria."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 90, $official_bank_source${"itemId":"e3bc1f9e-bac2-50b6-890f-182653a58fb2","questionId":"5b589e23-c8ae-520f-9a4d-91f9f7b23156","sourceKey":"bank:GST111:GST111-0218","payload":{"prompt":"The word 'challenge' when used as a noun or a verb is respectively stressed as----------------","options":["CHALlenge/chalLENGE","CHALlenge/CHALlenge","CHALLENGE/challenge","chalLENGE/CHALlenge"],"correctOption":1,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"In this course, challenge is treated as an exception to the noun-verb stress rule: unlike EXport/exPORT or REcord/reCORD, it keeps the same stress pattern, CHALlenge, whether it is a noun or a verb. Options A and D wrongly assume the stress shifts between the two uses, and C has the wrong stress for both."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 91, $official_bank_source${"itemId":"9a900fdb-2868-5f45-a098-7475f9bada49","questionId":"0739b7ae-45dd-5686-8525-8ccac9a99056","sourceKey":"bank:GST111:GST111-0224","payload":{"prompt":"Zero stress refers to:","options":["unstressed syllables","tertiary stress","secondary stress","primary stress"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Zero stress refers to unstressed syllables, such as the first syllable of about or the last syllable of mother. Polysyllabic words have three levels: primary, secondary and zero stress. Options C and D are the other two levels, which do carry some prominence, and B (tertiary) is not a level used in this course."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 92, $official_bank_source${"itemId":"e1b47d18-e9d8-51b4-89b4-c32aad0c417f","questionId":"5cb7bef8-4231-5bca-8186-cb7e4a06f860","sourceKey":"bank:GST111:GST111-0225","payload":{"prompt":"Which stress level is marked with a subscript?","options":["secondary","zero","primary","tertiary"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Secondary stress is weaker than primary stress but stronger than an unstressed syllable, and it is marked with a subscript mark at the start of the syllable, as in the first syllable of millionaire or cigarette. Option C (primary) is marked with a raised stroke, B (zero stress) has no mark at all, and D (tertiary) is not a level used here."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 93, $official_bank_source${"itemId":"0be77796-3ee5-5a92-be86-cf3fb2a1e8e8","questionId":"aae46793-0997-5b20-8c8b-a0494b076235","sourceKey":"bank:GST111:GST111-0247","payload":{"prompt":"The syllable in a word which has a --------------------- vowel quality usually attracts stress.","options":["high","strong","round","close"],"correctOption":1,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"A syllable with a strong vowel quality (a long vowel, diphthong or triphthong) tends to attract stress, while syllables with weak vowels such as the schwa are usually unstressed. Options A, C and D describe tongue height or lip shape, not whether a vowel is strong or weak, so they do not predict stress."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 94, $official_bank_source${"itemId":"4d3d60b7-7fb5-5394-9f47-fc86a0295115","questionId":"a29e5d89-415e-5640-a111-e794d606a41c","sourceKey":"bank:GST111:GST111-0261","payload":{"prompt":"English stress is -----------------","options":["fixed","ordered","mixed","free"],"correctOption":3,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"English stress is free, meaning it is not tied to one fixed position, so it can fall on the first, second, third or last syllable of a word, unlike languages where stress is fixed. Option A (fixed) is therefore the direct opposite of the right answer, and B and C are not terms used to describe stress systems."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 95, $official_bank_source${"itemId":"366a20b1-6154-54a1-9a83-f9068f4565fb","questionId":"502044e3-e00c-5da0-969c-897dfd403c6f","sourceKey":"bank:GST111:GST111-0266","payload":{"prompt":"Which of the following is a compound noun?","options":["GREENhouse","black BIRD","an English TEAcher","white HOUSE"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Compound nouns carry stress on the first element, so GREENhouse (a glass building for plants) is a compound noun, whereas a green HOUSE, with stress on the second word, is just a noun phrase meaning a house that is green. Options B, C and D all stress the second element, which is the noun-phrase pattern."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 96, $official_bank_source${"itemId":"24f503a9-7ded-56b7-8f62-e39dbfc9d419","questionId":"ab0d7d05-0631-5dd3-bd57-62800f987347","sourceKey":"bank:GST111:GST111-0273","payload":{"prompt":"Stress prediction based on syllable structure is basically ----------------","options":["syntactic","morphological","phonological","semantic"],"correctOption":2,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"The phonological criterion predicts stress from the number of syllables in a word and their internal structure, especially whether they contain strong or weak vowels, so C is correct. Option B (morphological) is based on affixes and word parts, A (syntactic) is based on word class, and D (semantic) is about meaning, so none of them concerns syllable structure."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 97, $official_bank_source${"itemId":"71f70b19-5084-54ed-b19f-a6114377b95a","questionId":"f9cfb631-fe37-56f5-920e-394f5c8bbc93","sourceKey":"bank:GST111:GST111-0282","payload":{"prompt":"---------------- is the use of the rise and fall of voice pitch to convey meaning.","options":["intonation","stress","rhythm","intensity"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Intonation is the melody of speech: the rise and fall of pitch used to show meaning, such as whether a sentence is a statement or a question, or the speaker's attitude. Option B (stress) is the prominence of one syllable over others in a word, and C and D (rhythm, intensity) are not the names for meaningful pitch movement."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 98, $official_bank_source${"itemId":"1d1f38eb-1554-581c-85e9-4c227d46966a","questionId":"b6d54188-d464-519b-bdba-7c2252f53c1e","sourceKey":"bank:GST111:GST111-0288","payload":{"prompt":"Which of the following statements is not correct?","options":["noun phrases are stressed on the rightmost constituent","compound nouns are usually stressed on the first constituent","nouns are usually stressed.","function words are always stressed"],"correctOption":3,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Statement D is incorrect because function words such as the, of and and are usually unstressed in connected speech, not always stressed. The other statements are correct: noun phrases are stressed on the rightmost element (A), compound nouns on the first element (B), and content words like nouns normally carry stress (C)."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 99, $official_bank_source${"itemId":"c5f3e87e-b421-56d1-9677-7d0ed9f7356a","questionId":"5e4682b1-049b-5be1-a73c-9b3c1ec073ad","sourceKey":"bank:GST111:GST111-0308","payload":{"prompt":"One of the following is not necessary to make a syllable prominent.","options":["length","voice","pitch","loudness"],"correctOption":1,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Four factors make a syllable prominent: loudness, length, pitch and vowel quality. Voice, meaning vocal fold vibration, is what separates sounds like /b/ and /p/, and it is not a feature of stress, so B is not necessary. A, C and D are all prominence factors."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 100, $official_bank_source${"itemId":"e7c66cc2-e5a6-5a42-9bca-cd28e7fdb40d","questionId":"bcffb4b3-4558-5bcc-9dbb-348b00169310","sourceKey":"bank:GST111:GST111-0311","payload":{"prompt":"The ------------------ is the only compulsory element in a syllable.","options":["vowel","verb","consonant","noun"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"A syllable has an onset, a peak and a coda. The onset and coda (consonants) are optional, while the peak, which contains a vowel, is compulsory, so A is correct. Option C is wrong because a syllable like I or eye has no consonant at all, and B and D are word classes, not parts of a syllable."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 101, $official_bank_source${"itemId":"240b5255-1ead-5f09-ada5-9a359b8454c9","questionId":"918405c9-4664-5ab2-9bf1-69589f5017a3","sourceKey":"bank:GST111:GST111-0317","payload":{"prompt":"---------------------, according to experts, produces the strongest effect on stress placement than all the other features.","options":["length","loudness","pitch","vowel quality"],"correctOption":2,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Pitch produces the strongest effect on stress placement of all the prominence factors, so C is correct. Length (A), loudness (B) and vowel quality (D) also contribute to prominence, but none is as powerful as a noticeable change in pitch."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 102, $official_bank_source${"itemId":"d5218beb-6cf2-581a-ad20-721f8b306a24","questionId":"32d73142-ac34-5516-8f4e-27545c731c6d","sourceKey":"bank:GST111:GST111-0320","payload":{"prompt":"Features which apply to units higher than the segments are known as ---------","options":["hierarchicals","phonologicals","segmentals","suprasegmentals"],"correctOption":3,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Features such as stress and intonation operate on the syllable and beyond, not on individual consonant and vowel segments, so they are called suprasegmentals, meaning above the segments. Option C (segmentals) refers to the individual sounds themselves, and A and B are not terms used in phonology for this."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 103, $official_bank_source${"itemId":"f3386444-a32c-5d21-ad30-b38427db6313","questionId":"d32bb005-9eb4-5f16-be4a-184bde823d65","sourceKey":"bank:GST111:GST111-0321","payload":{"prompt":"The ------------ criterion for stress prediction takes the internal structure of the word into consideration.","options":["syntactic","phonological","semantic","morphological"],"correctOption":3,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"The morphological criterion for stress looks at the internal structure of a word, whether it is simple, compound or complex and what affixes it carries, so D is correct. Option B (phonological) looks at syllable and vowel structure, A (syntactic) looks at word class, and C (semantic) is about meaning, so none of them is about the word's internal make-up."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 104, $official_bank_source${"itemId":"176f1ab1-dca3-5458-aeb9-c3d8a0c8b13e","questionId":"04e9c801-1040-5171-b334-af1d0d8502c4","sourceKey":"bank:GST111:GST111-0322","payload":{"prompt":"The prominence of one syllable over other syllables in a word is a function of ...","options":["Stress","pitch","length","intensity"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Stress is the relative prominence of one syllable over the others in a word, so A is correct. Pitch, length and intensity (B, C and D) are the features that create that prominence, but the prominence itself is what we call stress."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 105, $official_bank_source${"itemId":"be4fd60b-fa32-58bb-8361-d9e57727447b","questionId":"3d3a4698-613a-55fe-ad01-7615f7d61280","sourceKey":"bank:GST111:GST111-0327","payload":{"prompt":"In the word 'janitor', stress falls on the ------------------- syllable.","options":["initial","final","medial","none of the above"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Janitor is stressed on the first syllable, so it is said JAnitor, just like reason and message. That makes the answer initial (A). Options B and C would move the stress to -i- or -tor, which is not how the word is pronounced."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 106, $official_bank_source${"itemId":"99a4d63c-e4ec-5e13-a95e-156efd080865","questionId":"0d964992-a0f8-52e8-af95-bc42154674a8","sourceKey":"bank:GST111:GST111-0357","payload":{"prompt":"A three consonant onset obligatorily has -------------- as the first consonant.","options":["/k/","/s/","/t/","/p/"],"correctOption":1,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"A three-consonant onset always starts with /s/, followed by /p/, /t/ or /k/ and then /l/, /r/, /w/ or /j/, as in strike, square and sprite. So B is correct. Options A, C and D (/k/, /t/, /p/) are the sounds that can come second, not first."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 107, $official_bank_source${"itemId":"a66669ac-1a29-5df8-be09-ccff9b55d9ea","questionId":"cbd7f761-f2db-56b5-8e0d-6894a2cf26ec","sourceKey":"bank:GST111:GST111-0386","payload":{"prompt":"One of the following does not usually occur in unstressed syllables.","options":["syllabic consonants","short vowels","the schwa","diphthongs"],"correctOption":3,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Diphthongs are strong vowels that attract stress, so they do not normally appear in unstressed syllables (D). The schwa and syllabic consonants usually occur in unstressed syllables, and weak syllables contain short vowels, which is why A, B and C are not the answer."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 108, $official_bank_source${"itemId":"4c1fba54-ee4f-59dc-a71c-c2967e3f0094","questionId":"ab4c015a-fb5a-5ef0-b891-29b08987bb8d","sourceKey":"bank:GST111:GST111-0414","payload":{"prompt":"A word usually has --------------- primarily-stressed syllable(s).","options":["2","1","3","4"],"correctOption":1,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"In longer words there is usually just one primarily stressed syllable, possibly one more with secondary stress, and several unstressed ones. So a word normally has one primary stress (B). Options A, C and D give too many; extra prominent syllables carry secondary stress, not primary stress."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 109, $official_bank_source${"itemId":"e4eb9783-d7dd-5620-9b36-013a2f8fc0fe","questionId":"9131c72d-e2f0-5ea1-a33e-9b001f86a67e","sourceKey":"bank:GST111:GST111-0426","payload":{"prompt":"The ------------------ tune is used in declarative sentences.","options":["fall-rise","rising","rise-fall","falling"],"correctOption":3,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"The falling tune is used in declarative statements, as well as in commands, wh-questions and exclamations (D). The rising tune (B) is used for yes/no questions and polite requests, the fall-rise (A) is for lists and sentence modifiers, and the rise-fall (C) is not the tune linked with statements."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 110, $official_bank_source${"itemId":"1eb842a5-e7c9-5f94-b28d-9d4867c8d9d6","questionId":"7de3bff3-51ea-569f-ae76-62a17a522805","sourceKey":"bank:GST111:GST111-0428","payload":{"prompt":"When the intonation of a sentence identifies that sentence as a statement, question etc. it is said to perform a/an ------------------ function.","options":["grammatical","attitudinal","accentual","discourse"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Showing whether an utterance is a statement, a question or an exclamation is the grammatical function of intonation (A). The attitudinal function (B) reveals the speaker's emotion or attitude, and the discourse function (D) guides turn-taking in conversation. Accentual (C) relates to stress placement, not sentence type."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 111, $official_bank_source${"itemId":"cc41ce07-9331-5ecf-817f-ce940c1f3b90","questionId":"2789d80e-2ba3-5065-b060-61ed5c361b8f","sourceKey":"bank:GST111:GST111-0442","payload":{"prompt":"A syllable with a CV structure is said to be ----------------------","options":["close","strong","weak","open"],"correctOption":3,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"A CV syllable ends in a vowel, so it has no coda and is an open syllable (D), like the words tea and slow. Closed syllables (A) end in a consonant, as in CVC. Strong and weak (B and C) describe the vowel quality in a syllable, not its structure."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 112, $official_bank_source${"itemId":"61155354-faf7-5325-bf1e-f7b51beb749c","questionId":"3135d660-3939-5a40-823d-1e7cc462849a","sourceKey":"bank:GST111:GST111-0452","payload":{"prompt":"Yes/No questions are naturally asked using the ........................ tune.","options":["rising","fall-rise","falling","rise-fall"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"The rising tune is used to ask yes/no (polar) questions, as in 'Can we go now?' (A). The falling tune (C) is used for statements, commands and wh-questions, the fall-rise (B) is for lists and sentence modifiers, and the rise-fall (D) is not linked with yes/no questions."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 113, $official_bank_source${"itemId":"6652b58d-58d8-5b2f-a49f-079a007e37fd","questionId":"67d89f33-046a-53a2-b1b7-f912d5d5e23c","sourceKey":"bank:GST111:GST111-0461","payload":{"prompt":"The word 'responsibility' is correctly stressed as ------------","options":["respon'sibility","'responsibility","responsi'bility","re'sponsibility"],"correctOption":2,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Responsibility has primary stress on the fourth syllable, bil, and secondary stress on the second syllable, so the correct marking is responsi'bility (C). Option D, re'sponsibility, is tempting because the base word responsible is stressed there, but the suffix -ity moves the primary stress to the syllable just before it."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 114, $official_bank_source${"itemId":"8f408af0-e4fe-5c29-96ce-7999bd31e5b1","questionId":"57b3885d-a107-5cb4-9804-a279efd17504","sourceKey":"bank:GST111:GST111-0468","payload":{"prompt":"-------------- is the use of the pitch of the voice to convey meaning or syntactic information.","options":["rhythm","intonation","stress","phonetics"],"correctOption":1,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Intonation is the use of the pitch of the voice to convey meaning or syntactic information (B). Stress (C) is the extra prominence given to one syllable within a word, rhythm (A) is the timing pattern of speech, and phonetics (D) is the study of speech sounds as a whole."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 115, $official_bank_source${"itemId":"e3ad04ef-ee9e-54fe-8929-8da9dfb371ac","questionId":"f39ff3e3-e2ea-57ba-9da9-10e6d7a6f80f","sourceKey":"bank:GST111:G111N1-032","payload":{"prompt":"The theory that a syllable corresponds to one puff of air from the intercostal muscles is the","options":["Chest Pulse Theory","Coda Theory","Prominence Theory","Peak Theory"],"correctOption":0,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"The Chest Pulse Theory links each syllable to a single puff of air pushed out by the intercostal muscles. The Prominence Theory instead defines the syllable by the most prominent or sonorous sound in its environment."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 116, $official_bank_source${"itemId":"b4010ef8-2d31-5a39-a939-84b7d3cea9d4","questionId":"7e2fbf09-1577-5983-ab5b-5db2318227a1","sourceKey":"bank:GST111:G111N1-033","payload":{"prompt":"Which of the following words is a closed syllable?","options":["tea","no","slow","slap"],"correctOption":3,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"A closed syllable ends in a consonant (a coda), and 'slap' ends in /p/. 'slow', 'tea' and 'no' all end in a vowel sound, so they are open syllables."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 117, $official_bank_source${"itemId":"145118f6-e0d5-56cb-a056-4676220d19fd","questionId":"6a7233e1-258e-59f7-a8bf-7d765d888089","sourceKey":"bank:GST111:G111N1-035","payload":{"prompt":"A student asks a stranger, 'Where is the Faculty of Management Sciences?' to get new information. Which tune is normally used?","options":["Falling-rising","Falling","Rising","Rising-falling"],"correctOption":1,"section":"Speaking Skills II: Syllable, Stress, Intonation","explanation":"Wh-questions that seek new information are said on a falling tune. A rising tune is used for yes/no questions and for wh-questions that ask someone to repeat what was said, which is not the case here."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 118, $official_bank_source${"itemId":"07b5b9b2-6e21-5b22-8866-7ae21de0dc07","questionId":"8c7f8700-3da8-5698-a629-23b7de613bd4","sourceKey":"bank:GST111:GST111-0036","payload":{"prompt":"Selective reading is important to students because","options":["It will be in line with qualitative education","It reduces the stress campus rigors","It may be either impossible or a waste of time to read everything in the text","It reinforces the importance of reading"],"correctOption":2,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Selective reading matters because it may be impossible, or a waste of time, to read everything in a text, so C is correct. Believing you must read every word is a misconception; depending on your purpose and how familiar the material is, you can read selectively. Options A, B and D give vague benefits that do not explain the real reason."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 119, $official_bank_source${"itemId":"b58f305c-95f2-5529-b861-139e278edfed","questionId":"16acf818-7b42-539a-a99b-65643cc40855","sourceKey":"bank:GST111:GST111-0124","payload":{"prompt":"The main purpose of reading is to \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_ a written material.","options":["Practice","Comprehend","Identify","Buy"],"correctOption":1,"section":"Reading Skills I: Effective Reading Strategies","explanation":"The main purpose of reading is to comprehend written material, so B is correct. The eyes link letters and symbols to see what the author says, while the brain interprets what the author means, and the goal of study reading is understanding and retaining the material. Practising (A), identifying (C) and buying (D) are not what reading itself is for."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 120, $official_bank_source${"itemId":"9e1928ff-1f8b-50ba-81c4-bd3dc56dac47","questionId":"b3c52f56-3021-5b5b-beaf-4f62489c09ff","sourceKey":"bank:GST111:GST111-0162","payload":{"prompt":"------------------- is the process of translating written or printed symbols and letters into words and sentences which convey meaning.","options":["listening","speaking","reading","writing"],"correctOption":2,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Reading is the process of translating written or printed symbols and letters into words and sentences which convey meaning, using both the eyes and the brain, so C is correct. Listening (A) decodes spoken words rather than written symbols, while speaking (B) and writing (D) are productive skills that create language rather than interpret it."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 121, $official_bank_source${"itemId":"2d858148-4944-52f4-8e44-19893a0df32b","questionId":"71b0c689-76fe-5be5-be26-f476c814382a","sourceKey":"bank:GST111:GST111-0182","payload":{"prompt":"---------------------- is not a key element to look out for when reading a material.","options":["the conclusion","the introductory section","the author's main point.","spelling errors"],"correctOption":3,"section":"Reading Skills I: Effective Reading Strategies","explanation":"When reading with intent, the key elements to look for are the meaning of the title and subtitles, the introduction, the author's main point (thesis statement), the supporting explanation and the conclusion. Spelling errors are not among them; hunting for them is proofreading, not reading for understanding. A, B and C are all key elements, so D is the exception."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 122, $official_bank_source${"itemId":"9aaade85-51bf-5662-a0e4-d2f0bc2a797d","questionId":"9b48d423-bdc8-5067-9134-d1b493d4fd4b","sourceKey":"bank:GST111:GST111-0191","payload":{"prompt":"One of the following is not a type of reading.","options":["spinning","study reading","scanning","skimming"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"The types of reading are skimming (quick reading for the overall idea), scanning (searching for a specific piece of information) and study reading (intensive, critical reading). Spinning is not a reading technique at all, so A is the odd one out, and B, C and D are all genuine types."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 123, $official_bank_source${"itemId":"62b293fc-7df9-5a17-beff-d08b299b4066","questionId":"6689f4cd-ea78-5f27-b999-d2b7de065531","sourceKey":"bank:GST111:GST111-0216","payload":{"prompt":"Skimming can be classified under---------------","options":["preview before reading","none of the above.","review after reading","reading with intent"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Efficient reading has three stages: preview before reading, read with intent, and review after reading. Skimming gives you the overall idea and familiarises you with the content and organisation, so it belongs to the preview stage, which is why you should not start reading without skimming first. Option D (reading with intent) involves searching for key elements and highlighting, and C (review) comes after reading."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 124, $official_bank_source${"itemId":"c86295a5-816a-5088-9b1b-4812f395a5b0","questionId":"65800c1e-7654-570f-95d3-1960ed07cd4a","sourceKey":"bank:GST111:GST111-0231","payload":{"prompt":"In reviewing an item you have read, one of the following is not necessary.","options":["the annotated items","the heading","references","the highlighted items"],"correctOption":2,"section":"Reading Skills I: Effective Reading Strategies","explanation":"When you review material after reading, you pay attention to the heading, the highlighted or underlined items that point to the main ideas, and the annotated items in the margin. The author's references are not part of this review, so C is the one that is not necessary, while A, B and D are the three items you should look at."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 125, $official_bank_source${"itemId":"90700180-f307-5967-9f43-78abdda09082","questionId":"09cb970d-0376-53e9-abc7-107bfa033c68","sourceKey":"bank:GST111:GST111-0235","payload":{"prompt":"In scanning a reading material. the reader seeks to --------------------","options":["get specific information","ensure grammaticality","have a general idea of the topic","check plagiarism"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"In scanning, your eyes run quickly through a text looking for a particular piece of information, ignoring everything not relevant to it, so A is correct. Option C (a general idea of the topic) describes skimming, not scanning, and B and D (grammaticality, plagiarism) are not purposes of reading at all."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 126, $official_bank_source${"itemId":"a196bd42-4148-5d71-951c-e1ee6a926579","questionId":"42a6d6f7-bc22-5d7e-b8cc-5e2039b94a7a","sourceKey":"bank:GST111:GST111-0290","payload":{"prompt":"When our eyes make a backward movement during reading, it is known as ---------- ----------","options":["clearing","backwarding","forwarding","regression"],"correctOption":3,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Regression is glancing back to re-read words, phrases or sentences, usually because of poor concentration, and it is counted among bad reading habits. Options A, B and C (clearing, backwarding, forwarding) are not terms used for eye movement in reading."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 127, $official_bank_source${"itemId":"99ef7691-5932-5899-9c25-f18692442dee","questionId":"d6f079fb-d8d5-53c6-8fce-89a216160cb4","sourceKey":"bank:GST111:GST111-0302","payload":{"prompt":"The mnemonic -------------------- serves as a guide to productive study reading.","options":["LEARNER","REARER","REALER","NEARER"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"LEARNER is the mnemonic that guides productive study reading: Lay out the purpose, Examine all parts, Ask questions about each subheading, Read all materials on the topic, Note names, places and dates, Ease away from one subject before starting another, and Review before a test. Options B, C and D are not study-reading mnemonics."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 128, $official_bank_source${"itemId":"109d474b-58cd-594f-856f-19f21595fdb7","questionId":"9443debb-c50f-585d-98d2-89cae73443b5","sourceKey":"bank:GST111:GST111-0338","payload":{"prompt":"In scanning, the -------------------- can be very important.","options":["preface","index","foreword","topic sentences"],"correctOption":1,"section":"Reading Skills I: Effective Reading Strategies","explanation":"When you scan, you are hunting for one particular piece of information, so you use the table of contents or the index to find the relevant pages and then read only those. Preface and foreword (A and C) are introductory sections that help with skimming, not with locating a specific fact, and topic sentences (D) help you understand paragraphs rather than find a detail quickly."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 129, $official_bank_source${"itemId":"6c5fea54-6351-5b6d-b2dd-5d46833d8030","questionId":"911fc4c8-1d20-5588-9a0b-5ea1fd4c59a3","sourceKey":"bank:GST111:GST111-0390","payload":{"prompt":"--------------------- is not a bad reading habit.","options":["vocalisation","word-by-word reading","moving the head from side to side","havinga wide span of recognition."],"correctOption":3,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Having a wide span of recognition is a mark of a good reader, because the eyes take in several words at one fixation, so D is not a bad habit. Word-by-word reading, vocalisation and moving the head from side to side (B, A and C) are all reading deficiencies that slow you down and hurt comprehension."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 130, $official_bank_source${"itemId":"f50d10cd-07b1-570c-b469-8574e6d54689","questionId":"a5c78cf5-d001-5151-a238-831540333898","sourceKey":"bank:GST111:GST111-0412","payload":{"prompt":"You will not experience much difficulty with a reading material if you ---------------","options":["follow the appropriate steps","find the style confusing","cannot connect with the author","find the topic uninteresting"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"You will not struggle much with a reading material if you follow the appropriate steps, such as previewing, reading with intent and reviewing (A). Options B, C and D are the usual causes of difficulty, namely a confusing style, not connecting with the author and an uninteresting topic, so they are the opposite of what the question asks for."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 131, $official_bank_source${"itemId":"df23bd94-0b01-56b1-acd7-aac8541504a3","questionId":"989ec3f2-780a-5bbf-b8a4-5c5514ca16f4","sourceKey":"bank:GST111:GST111-0451","payload":{"prompt":"Skimming involves the following except------------------","options":["looking for specific details","reading the abstract","reading the blurb","looking at the table of contents"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Looking for specific details is scanning, not skimming, so A is the exception. In skimming you look at the title, blurb, abstract, table of contents and topic sentences to get a general idea, without hunting for particular facts, which is why B, C and D are all part of skimming."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 132, $official_bank_source${"itemId":"19dfdf9c-a91f-5063-9bce-894142a5e17c","questionId":"6d4c01e3-ad1a-55ef-8945-21248e048b95","sourceKey":"bank:GST111:GST111-0465","payload":{"prompt":"The reading speed adopted depends on all the following except ---------------------------","options":["the nature of the reading material","the reader","the purpose of the reading","the author's prescription"],"correctOption":3,"section":"Reading Skills I: Effective Reading Strategies","explanation":"The nature of the reading material and your purpose decide how thoroughly and how fast you read, and a flexible reader changes speed to suit the material, so A, B and C all matter. The author does not prescribe how fast you read, so D is the odd one out."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 133, $official_bank_source${"itemId":"2e31f50f-0ed6-5b68-a714-fa4bbab18f27","questionId":"6f29934c-9eb1-5e1e-99dc-5e0731090660","sourceKey":"bank:GST111:GST111-0469","payload":{"prompt":"One of the following is NOT essential to reading","options":["printed signs","the eyes","the articulatory system","written signs"],"correctOption":2,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Reading is translating written or printed symbols into meaning, and it involves the eyes and the brain. The articulatory system (lips, tongue, vocal cords) is not needed, and moving the vocal organs while reading is actually a bad habit called vocalisation, so C is the answer. Printed signs, the eyes and written signs (A, B and D) are all essential."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 134, $official_bank_source${"itemId":"6336cefd-1ef4-57ec-ba9c-8efb8583a1ca","questionId":"135c6eb4-083a-5274-8328-a0f1e1636a40","sourceKey":"bank:GST111:G111N1-036","payload":{"prompt":"By the end of a university programme, a student's reading speed should be about","options":["600 words per minute","300 words per minute","200 words per minute","1,000 words per minute"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"The target for reading efficiency is about 600 words per minute by the end of your programme, and it improves only with practice. Lower figures such as 300 words per minute fall well short of this target."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 135, $official_bank_source${"itemId":"ab99d70e-4abf-5c9d-a688-e45f4021947f","questionId":"0bf414b4-f35a-5cf2-ad4f-f1780cd91b2e","sourceKey":"bank:GST111:G111N1-037","payload":{"prompt":"The relationship between the physical aspect of reading and reading speed, which in turn affects comprehension, is known as","options":["span of recognition","reading efficiency","study reading","skimming"],"correctOption":1,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Reading efficiency means having the right skills for efficient physical and mental processing, linking the physical act of reading to speed and comprehension. Span of recognition is narrower: it is only how many words you take in at each eye fixation."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 136, $official_bank_source${"itemId":"f248d00a-7b87-5019-ac4f-47bca8f35ef8","questionId":"60cac6c1-97f3-58f5-8091-f1c5165f3540","sourceKey":"bank:GST111:G111N1-038","payload":{"prompt":"A student in Lagos accepts every claim in a newspaper simply because it has been printed. Which misconception about reading does she hold?","options":["Everything can be read the same way","Everything in print is true","You must read everything","Everything on a page is equally important"],"correctOption":1,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Trusting a claim just because it is printed is the misconception that everything in print is true; a critical reader separates facts from opinions. Believing that everything on a page is equally important is a different misconception, about what to focus on rather than what to believe."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 137, $official_bank_source${"itemId":"88f3bf3c-6514-5aba-bf70-66dc27d2424d","questionId":"fa1fcc80-c291-5c7d-81b4-779ac53f2361","sourceKey":"bank:GST111:G111N1-039","payload":{"prompt":"Which of the following is NOT one of the four misconceptions about reading?","options":["Everything can be read the same way","Reading speed is related to comprehension","Everything on a page is equally important","You must read everything"],"correctOption":1,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Scholars agree that reading speed is directly related to comprehension, so this is a true statement, not a misconception. Believing that you must read everything is one of the four false ideas."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 138, $official_bank_source${"itemId":"f3971742-67e5-5c43-a671-917a8c3e46f8","questionId":"aafb92c5-5563-5cd4-b2e9-74d01a481510","sourceKey":"bank:GST111:G111N1-040","payload":{"prompt":"A reader who moves his lips or whispers the words while reading silently has the bad habit called","options":["regression","finger-pointing","vocalisation","sub-vocalisation"],"correctOption":2,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Moving the lips or vocal apparatus, or whispering, is vocalisation. Sub-vocalisation is close but different: the words are pronounced only in the mind with no movement."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 139, $official_bank_source${"itemId":"7aa42c13-daf1-5cca-9b19-887fc5176040","questionId":"3eecff55-ead1-51bc-afa6-d11906cd0791","sourceKey":"bank:GST111:G111N1-041","payload":{"prompt":"Pronouncing words in the mind while reading, without any movement of the lips, is called","options":["vocalisation","word-by-word reading","regression","sub-vocalisation"],"correctOption":3,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Sub-vocalisation is saying the words silently in the mind, and it slows reading down. Vocalisation involves visible lip movement or whispering, which is not happening here."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 140, $official_bank_source${"itemId":"bea19797-6422-535a-a9d2-6363a4544d8d","questionId":"7f7aba28-0ec7-5a0b-a8c1-b0aa89a1362e","sourceKey":"bank:GST111:G111N1-042","payload":{"prompt":"A reader who recognises only one or two words at each eye fixation has","options":["regression","erratic eye movement","sub-vocalisation","a short span of recognition"],"correctOption":3,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Taking in only one or two words per fixation is a short span of recognition, a bad habit; a good reader has a wide span. Erratic eye movement is about the eyes failing to move rhythmically from phrase to phrase."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 141, $official_bank_source${"itemId":"90c86a0d-d1d8-5d59-8023-b7c7a162b6d4","questionId":"68e52bcc-533d-5f89-94ed-498aad2c355f","sourceKey":"bank:GST111:G111N1-043","payload":{"prompt":"To avoid erratic eye movement, a reader's eyes should move","options":["along the line by following a pointing finger","together with the head from side to side","from the first letter of each word to the next","rhythmically from the middle of one phrase to the middle of the next"],"correctOption":3,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Good readers move their eyes in a steady rhythm from the middle of one phrase to the middle of the next. Following a pointing finger is itself a bad habit, and moving the head is another, since only the eye muscles should be used."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 142, $official_bank_source${"itemId":"afadfbd9-efa3-524f-962b-ecae70a5d288","questionId":"8ee0f705-55bf-5a83-9f2b-b117605da771","sourceKey":"bank:GST111:G111N1-044","payload":{"prompt":"Which of the following is a bad reading habit?","options":["Previewing before reading","Reading with intent","Finger-pointing","Annotating in the margin"],"correctOption":2,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Finger-pointing is one of the eight reading deficiencies or bad habits, along with vocalisation and regression. Previewing, annotating and reading with intent are all recommended strategies for reading efficiently."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 143, $official_bank_source${"itemId":"541a96e5-98c2-5253-b579-e886925d11b2","questionId":"7483c2f7-6199-597d-a324-469145914534","sourceKey":"bank:GST111:G111N1-045","payload":{"prompt":"Regression, the habit of glancing back to re-read, is usually caused by","options":["reading with intent","poor concentration","a wide span of recognition","previewing the text"],"correctOption":1,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Regression usually comes from poor concentration; some is acceptable, but too much hinders reading. A wide span of recognition is a sign of a good reader, so it does not cause regression."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 144, $official_bank_source${"itemId":"a91ccfa9-3bb7-5b69-b2eb-b4efe33ea466","questionId":"2a480302-c095-5ce0-beaa-b48a4dd55418","sourceKey":"bank:GST111:G111N1-046","payload":{"prompt":"What is the correct order of the three stages of reading efficiently?","options":["Preview before reading, review after reading, read with intent","Review before reading, read with intent, preview after reading","Preview before reading, read with intent, review after reading","Read with intent, preview before reading, review after reading"],"correctOption":2,"section":"Reading Skills I: Effective Reading Strategies","explanation":"You first preview the text, then read it with intent, and finally review it after reading. Putting reading with intent first skips the preview stage, where skimming and connecting to your experience take place."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 145, $official_bank_source${"itemId":"4877d345-72c5-523a-9cb5-2196f89fc5f6","questionId":"fe08b989-39c3-5478-b3c9-c024524db031","sourceKey":"bank:GST111:G111N1-047","payload":{"prompt":"Highlighting key points and annotating your impressions belong to which stage of reading efficiently?","options":["Reading with intent","Skimming the text","Reviewing after reading","Previewing before reading"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"When reading with intent you search for key elements, highlight key points and annotate your impressions. Reviewing after reading then focuses on the highlights and annotations already made, rather than creating them."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 146, $official_bank_source${"itemId":"f9c22bc8-45c1-5feb-a94d-f828f646ccb3","questionId":"0f2d5e88-b333-5771-af51-444f4e6125f2","sourceKey":"bank:GST111:G111N1-048","payload":{"prompt":"When reading with intent, the author's main point is usually found in the","options":["thesis statement","blurb on the cover","concluding paragraph","index at the back"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"The author's main point is usually stated in the thesis statement in the first or second paragraph, though it may only be implied. The conclusion is a separate key element that closes the text rather than stating the main point first."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 147, $official_bank_source${"itemId":"52ef1041-ccee-5d5b-9caa-0b8f30354305","questionId":"027e87ea-b5d6-568f-b1ea-19cc95ac8c2a","sourceKey":"bank:GST111:G111N1-049","payload":{"prompt":"Personal comments that a reader writes in the margin of a text are called","options":["previews","annotations","highlights","graphic organisers"],"correctOption":1,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Annotation means writing your own comments in the margin, such as important points, questions and inconsistencies. Highlighting only marks words already in the text and adds nothing of your own."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 148, $official_bank_source${"itemId":"e5659ee6-c80d-557a-8b45-202f26fc3d02","questionId":"4fe16d3c-049f-5db7-ad57-4f6e4c79eb2c","sourceKey":"bank:GST111:G111N1-050","payload":{"prompt":"A diagram that shows the structure of the main points of a text, especially useful when the text is difficult, is a","options":["abstract","annotation","table of contents","graphic organiser"],"correctOption":3,"section":"Reading Skills I: Effective Reading Strategies","explanation":"A graphic organiser is a diagram of how the main points fit together, and it helps with difficult texts. A table of contents lists chapters or sections; it does not map how the ideas relate."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 149, $official_bank_source${"itemId":"74a7ebb7-8ed3-5518-8397-cad516bd4461","questionId":"b2827d71-17bb-5f48-b818-ad11b37433fd","sourceKey":"bank:GST111:G111N1-051","payload":{"prompt":"When highlighting a text, which practice is recommended?","options":["Highlight every sentence that has a date","Read first, then highlight","Highlight before reading the passage","Highlight as much of the text as possible"],"correctOption":1,"section":"Reading Skills I: Effective Reading Strategies","explanation":"The rules are to decide what to highlight, read first and then highlight, be selective, and highlight the thesis and topic sentences. Highlighting as much as possible breaks the rule of being selective."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 150, $official_bank_source${"itemId":"e37f53b3-9612-565d-9c5b-efa0fb8cb23f","questionId":"9ef6e09e-7c75-51e3-a484-3800084fb087","sourceKey":"bank:GST111:G111N1-052","payload":{"prompt":"When should a reader review a text after reading it?","options":["Only if the text was difficult","Only on the eve of the examination","Immediately after reading","About a week after reading"],"correctOption":2,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Review after reading should be done immediately, using the same steps as previewing. Waiting until the eve of an examination means the details will already have faded."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 151, $official_bank_source${"itemId":"40c0a995-6d51-5df2-8930-c192012b3876","questionId":"73ab13c6-d89f-5a44-9e06-84164a488133","sourceKey":"bank:GST111:G111N1-053","payload":{"prompt":"In reading, the eyes do the physical task. Which organ interprets what is read?","options":["The brain","The ears","The vocal apparatus","The eyes"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Reading uses the eyes for the physical task of seeing the symbols and the brain for interpreting them. The eyes only take in the printed symbols; they do not work out the meaning."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 152, $official_bank_source${"itemId":"7ddc5d9f-41da-585e-b63a-4d7f692764c7","questionId":"2c2870e3-0010-5007-b369-08ac4720a3aa","sourceKey":"bank:GST111:G111N1-054","payload":{"prompt":"Which of the following statements about reading as a skill is correct?","options":["It is fully mastered by the end of primary school","It depends only on the eyes","Its efficiency improves without practice","It is a developmental process that is never fully mastered"],"correctOption":3,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Reading keeps developing throughout life and is never fully mastered, and its efficiency improves only with practice. It also uses the brain for interpretation, so 'only the eyes' is wrong."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 153, $official_bank_source${"itemId":"3292d153-6a49-58a2-bd07-7c1fee2da964","questionId":"d7bc42d7-7225-5549-8097-22c0b066b45b","sourceKey":"bank:GST111:G111N1-055","payload":{"prompt":"Which of the following is NOT a step in previewing a text?","options":["Checking the title, subtitles and author","Reading the introduction or first paragraph","Writing a summary from your highlights and annotations","Examining photos, charts, tables and diagrams"],"correctOption":2,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Writing a summary from highlights and annotations is part of reviewing after reading, not previewing. Checking the title and author, reading the introduction and examining charts are all among the seven previewing steps."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 154, $official_bank_source${"itemId":"dd7b3c29-667b-5b43-8f8f-7342e733d00f","questionId":"a03cb75e-6339-5068-8637-5c21ad1c10df","sourceKey":"bank:GST111:G111N1-056","payload":{"prompt":"Which of the following is a way of connecting a text to your own experience before reading?","options":["Thinking of similar situations you have experienced","Reading only the conclusion","Counting the number of paragraphs","Copying the first paragraph word for word"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Connecting to your experience involves thinking of similar situations, asking and answering questions, and writing down ideas as they come. Reading only the conclusion is not a way of connecting to experience and skips most of the text."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 155, $official_bank_source${"itemId":"1ee24e12-83a0-527e-bdb2-b72bcbd60e68","questionId":"e8257bc6-08af-5f87-8491-6bd1875eb0a6","sourceKey":"bank:GST111:G111N1-057","payload":{"prompt":"A trader in Balogun market glances quickly over a newspaper just to get a general idea of what it is about. Which type of reading is this?","options":["Skimming","Regression","Study reading","Scanning"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Skimming is a quick look to get the overall or general idea of a text. Scanning is also quick, but it looks for one specific piece of information, which the trader is not doing."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 156, $official_bank_source${"itemId":"d3b31b4f-c713-507c-8582-30ef83484102","questionId":"170c08a6-0f56-54b9-beef-5031bf031796","sourceKey":"bank:GST111:G111N1-058","payload":{"prompt":"Which type of reading is intensive, thorough and critical?","options":["Previewing","Study reading","Scanning","Skimming"],"correctOption":1,"section":"Reading Skills I: Effective Reading Strategies","explanation":"Study reading is the intensive, thorough and critical type of reading used for serious learning. Skimming and scanning are quick runs through a text for the general idea or a specific detail."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 157, $official_bank_source${"itemId":"2560b49c-f406-54ef-9ee4-0eb66fc5a970","questionId":"4a551306-5cfd-5a7a-9e59-a0bf1d1d302b","sourceKey":"bank:GST111:G111N1-059","payload":{"prompt":"In the study-reading mnemonic LEARNER, the first 'E' stands for","options":["Examine all parts","Ease away from one subject","Evaluate the author","Explain the topic"],"correctOption":0,"section":"Reading Skills I: Effective Reading Strategies","explanation":"In LEARNER, L is lay out the purpose and the first E is examine all parts. 'Ease away from one subject before starting another' is the second E, near the end of the mnemonic."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 158, $official_bank_source${"itemId":"faf5ae31-d3e2-537b-871a-0efdbafb18af","questionId":"3ae16b18-24ae-5862-b9aa-73e3d172429b","sourceKey":"bank:GST111:GST111-0118","payload":{"prompt":"Which of the following is NOT true about writing a summary?","options":["expressions are paraphrased with new words","the major facts are included","quotations from the text are included","the present tense is used"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"A good summary paraphrases the original in new words, presents the major facts and uses the present tense, so A, B and D are all true. Including quotations from the text (option C) goes against the rule of restating ideas in your own words, so C is the statement that is not true."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 159, $official_bank_source${"itemId":"dd0720fa-1d83-5b60-b442-73c0e641e5ec","questionId":"e4ef2fa4-5173-5eeb-bb77-a0a61c6754b0","sourceKey":"bank:GST111:GST111-0258","payload":{"prompt":"Below are the steps involved in summarising a text; arrange them in the appropriate order. i. Express the contents of the text in your own words. ii. Read to find the basic ideas iii. Compare your summary with the original text. iv. Read to find the essentials.","options":["i, iii, ii, iv","iv, iii, ii, i","i,ii,iii,iv","ii, iv, i, iii"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"To summarise a text, you read to find the basic idea, read again to pick out the essentials, express the content in your own words, and finally compare your summary with the original, which is the order ii, iv, i, iii. Options A and C begin with writing the summary before reading, and B begins with the comparison, which can only come last."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 160, $official_bank_source${"itemId":"b9d3664e-7c66-56a0-921d-27566175f764","questionId":"7ef0741e-5426-5cdf-8d97-d903b64d97a5","sourceKey":"bank:GST111:GST111-0278","payload":{"prompt":"A passage written in a technical or difficult language is best read ------------------","options":["at a fast pace","at a slow pace","by scholars","by skimming it once"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"Reading speed should match the difficulty of the passage, so a passage in technical or difficult language should be read at a slow pace to take in the unusual vocabulary. Option A (a fast pace) and D (skimming it once) would only give a rough idea and hurt understanding, and C is wrong because any reader can handle such a passage by slowing down."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 161, $official_bank_source${"itemId":"17c5a7c8-771e-5fa3-a55a-611d71f82846","questionId":"6e23eb88-ede6-5eb6-82aa-b1e9f0f0c5f0","sourceKey":"bank:GST111:GST111-0280","payload":{"prompt":"A comprehension passage is best understood when it is read -----------------","options":["more than once","thrice","once","twice"],"correctOption":0,"section":"Reading Skills II: Comprehension and Summary","explanation":"A comprehension passage is best understood when you read it more than once, with a quick first reading for the general idea and a slower second reading for details. Options B and D fix a specific number, but the advice is not limited to two or three readings, and C (once) goes against the advice completely."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 162, $official_bank_source${"itemId":"f4ad6109-7509-5c74-bdac-b33b274b590d","questionId":"0b88600f-86ca-5e3d-aab3-33bcc8eaf672","sourceKey":"bank:GST111:GST111-0305","payload":{"prompt":"A/an ............ is a condensed version of an original work.","options":["preface","blurb","appendix","summary"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"A summary (also called a recap) is a condensed version of an original work, usually about one-third of its length. Option C, an appendix, adds extra material at the end of a work rather than shortening it, and A (preface) and B (blurb) are front-matter and back-cover texts, not condensed versions of the work."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 163, $official_bank_source${"itemId":"71685ef9-7bdd-5271-9009-d146dad06fb9","questionId":"52dc36cc-6938-5cda-b746-010dadc359be","sourceKey":"bank:GST111:GST111-0314","payload":{"prompt":"In relation to the tools used by examiners to test the candidates' understanding, the following question types can be identified except ....","options":["supposition question","evaluation question","affirmation question","inference question"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"Comprehension questions fall into four categories based on the tools examiners use: direct reference, inference, supposition and evaluation questions. There is no affirmation question among them, so C is the exception, and A, B and D are genuine types."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 164, $official_bank_source${"itemId":"b4b6125c-d8a0-52ae-a299-de21b8bf8d1b","questionId":"6098f779-259a-5d2c-b2ef-dfb1a78bc2c6","sourceKey":"bank:GST111:GST111-0329","payload":{"prompt":"The first step in reading a passage is to ------------------ it.","options":["appreciate","edit","summarise","preview"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"Previewing comes first: you skim the title, headings and opening lines to get an idea of what the passage contains before reading it properly. Summarising (C) only comes after you have read, and editing and appreciating (B and A) are not stages of studying a passage."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 165, $official_bank_source${"itemId":"ea41b9f5-2c6e-544c-93cf-50c4c852bed6","questionId":"cd2611fe-9405-5c09-9d48-126150835d10","sourceKey":"bank:GST111:GST111-0337","payload":{"prompt":"A/an ---------------- is a summary of a plot.","options":["prologue","synopsis","episode","storyline"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"A synopsis is a summary of a plot, the kind of account you give when someone asks what a film or novel was about. Storyline (D) is the plot itself rather than a summary of it, and prologue and episode (A and C) are parts of a work, not condensed versions of it."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 166, $official_bank_source${"itemId":"09b2bae9-c3b9-5b10-925c-65958043ae50","questionId":"d39fa61d-9d5b-5d0d-b911-ee0c6e536ea5","sourceKey":"bank:GST111:GST111-0398","payload":{"prompt":"Questions which require you to refer directly to the text are called ....","options":["supposition questions","inference questions","direct reference questions","evaluation questions"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"Direct reference questions are those that require you to refer directly to the text, for example asking what the passage says about a topic (C). Inference questions (B) ask you to work out relationships between parts of the passage, supposition questions (A) take you beyond the passage, and evaluation questions (D) ask you to judge the writer's language and information."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 167, $official_bank_source${"itemId":"79b1f225-a3c8-591b-a797-74bb9b314d2c","questionId":"527548d9-d9c9-5b31-bb16-f0c28fede9ad","sourceKey":"bank:GST111:G111N1-060","payload":{"prompt":"When previewing a passage titled 'The Causes of Election Violence', a good strategy is to","options":["memorise the title word for word","skip the title and read the conclusion","turn the title into a question","count the paragraphs in the passage"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"Turning the title into a question, such as 'What are the causes of election violence?', gives your reading a purpose from the start. Skipping the title throws away the first clue to what the passage is about."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 168, $official_bank_source${"itemId":"b13c65e5-11fb-57a2-afd1-644a901b856e","questionId":"216f103b-4f97-586b-a1c6-d5e78d0a269b","sourceKey":"bank:GST111:G111N1-061","payload":{"prompt":"The first reading of a comprehension passage should be","options":["focused only on difficult vocabulary","word by word, to check every meaning","rapid, to get a general impression","slow, to separate main ideas from minor ones"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"The first reading is a quick one that gives a general impression of the tone, purpose and theme. Slow reading to separate main from minor ideas is the job of the second reading."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 169, $official_bank_source${"itemId":"ce2075da-d8b8-5a5f-9d7c-f48704958af3","questionId":"ea556653-a9fa-5b79-bb07-963b9e817999","sourceKey":"bank:GST111:G111N1-062","payload":{"prompt":"Separating main ideas from minor ones, and subjective statements from objective ones, is the focus of the","options":["first reading","skimming stage","second reading","preview stage"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"The second reading is slower and is used to separate main from minor ideas, subjective from objective and direct from indirect statements. The first reading is rapid and only gives a general impression."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 170, $official_bank_source${"itemId":"e3dc0e2b-b0a8-527d-a1e8-1d2a95eb09a2","questionId":"21bcec70-ed68-521e-ae14-749e70575e38","sourceKey":"bank:GST111:G111N1-063","payload":{"prompt":"Which of the following is a focus of the FIRST reading of a comprehension passage?","options":["Separating main ideas from minor ones","The writer's tone and attitude","Separating subjective from objective statements","Separating direct from indirect statements"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"During the first, rapid reading you look for the writer's tone and attitude, purpose and central idea. The separating tasks, such as subjective versus objective, belong to the slower second reading."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 171, $official_bank_source${"itemId":"d5c5b95d-b588-5149-9c97-5702a1b847af","questionId":"6039d1f1-2c99-5a06-a0bd-951070c01f84","sourceKey":"bank:GST111:G111N1-064","payload":{"prompt":"Comprehension questions that require you to give answers in your own words are called","options":["traditional type questions","multiple choice questions","zero-answer questions","affirmation questions"],"correctOption":0,"section":"Reading Skills II: Comprehension and Summary","explanation":"The two major formats are multiple choice questions and traditional type questions, and the traditional type expects answers in your own words. Multiple choice questions give you options to pick from instead."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 172, $official_bank_source${"itemId":"d752ab85-11c9-5535-b51e-24e248c5f274","questionId":"8fb2901f-1e02-5f6a-abef-dfdeb83b943d","sourceKey":"bank:GST111:G111N1-065","payload":{"prompt":"Which of the following is a useful clue for answering comprehension multiple choice questions?","options":["Choose the first option that seems partly correct","Always pick the longest option","Use elimination to rule out wrong options","Mark two answers when unsure"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"Using elimination is one of the four MCQ clues, alongside making sure all other options are wrong. Choosing an option that is only partly correct is a trap, because some options are designed to be partly right."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 173, $official_bank_source${"itemId":"ca7c8610-6e0f-54fa-9fcb-332e92084d5b","questionId":"90056ee2-6768-594e-a919-c0c05a2a73ca","sourceKey":"bank:GST111:G111N1-066","payload":{"prompt":"In comprehension MCQs, options such as 'none of the above' and 'don't know' are referred to as","options":["zero answers","suggested answers","inferred answers","partial answers"],"correctOption":0,"section":"Reading Skills II: Comprehension and Summary","explanation":"Options like 'none of the above' or 'don't know' are called zero answers. Partial answers are different: they are options that are only partly correct."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 174, $official_bank_source${"itemId":"c493e47b-8666-5490-9fd2-8f54d3099b51","questionId":"bdf9f55f-eafb-58a9-88c6-1be122822a1b","sourceKey":"bank:GST111:G111N1-067","payload":{"prompt":"A traditional comprehension question asks whether 'cat' in a passage refers to the animal or is used as a metaphor. This question tests","options":["the title of the passage","the meaning of a word in context","the spelling of a word","the reader's personal opinion"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"Asking whether 'cat' is literal or metaphorical tests the meaning of a word in its context. It is not an opinion question, because the answer must come from how the word is used in the passage."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 175, $official_bank_source${"itemId":"e1808eae-90a6-5e83-a14f-330ee518385c","questionId":"6313fd41-063d-59d4-80ea-0dfe4f74f613","sourceKey":"bank:GST111:G111N1-068","payload":{"prompt":"Comprehension questions that require you to establish relationships between parts of the text are","options":["supposition questions","direct reference questions","inference questions","evaluation questions"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"Inference questions ask you to connect parts of the text and see how they relate. Direct reference questions only ask you to point to what the text states."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 176, $official_bank_source${"itemId":"0976fa49-b278-53d1-8648-6c4b7d04acf8","questionId":"499458b1-190d-5c93-bf7b-e2bfdfe2cdf6","sourceKey":"bank:GST111:G111N1-069","payload":{"prompt":"Comprehension questions that require you to think beyond the passage to the outside world are","options":["direct reference questions","inference questions","evaluation questions","supposition questions"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"Supposition questions take you beyond the passage into the outside world. Inference questions stay within the text, linking one part of it to another."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 177, $official_bank_source${"itemId":"ef5e7703-f548-5d9c-a27f-2fad856b5b19","questionId":"d4c4c3c5-8fb3-5d44-bb6f-2404132ae580","sourceKey":"bank:GST111:G111N1-070","payload":{"prompt":"Comprehension questions that require you to judge the information and the effectiveness of the writer's language are","options":["inference questions","evaluation questions","direct reference questions","supposition questions"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"Evaluation questions ask you to judge both the information and how well the writer uses language. Supposition questions ask you to think beyond the passage, not to judge the writer's language."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 178, $official_bank_source${"itemId":"5e0e4339-4c6c-591f-ab3e-d6878bdbc61a","questionId":"fa07818d-cff9-596f-a4dc-09ad3ecda39b","sourceKey":"bank:GST111:G111N1-071","payload":{"prompt":"Which of the following is an evaluation question on a comprehension passage?","options":["How effective is the writer's use of imagery in the last paragraph?","How is the flood in paragraph 1 related to the food shortage in paragraph 3?","In what year was the bridge built, according to the passage?","What might happen in your own town if the same policy were adopted?"],"correctOption":0,"section":"Reading Skills II: Comprehension and Summary","explanation":"Judging how effective the writer's imagery is assesses the writer's language, which is what evaluation questions do. Linking the flood in paragraph 1 to the food shortage in paragraph 3 is an inference question, because it connects parts of the text."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 179, $official_bank_source${"itemId":"c2db8787-0e90-57ec-b073-3b0803229a7d","questionId":"0bb03fbd-6b52-5c2a-958a-d1eff908e8ca","sourceKey":"bank:GST111:G111N1-072","payload":{"prompt":"A comprehension question asks: 'How is the drought described in paragraph 1 related to the rise in food prices in paragraph 4?' This is","options":["an evaluation question","a supposition question","a direct reference question","an inference question"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"The question asks you to establish a relationship between two parts of the text, which makes it an inference question. A direct reference question would only ask for something stated in one place in the text."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 180, $official_bank_source${"itemId":"8fcaeda6-1efc-5257-99f1-30abd4f036ec","questionId":"9d1cd651-2a49-50e8-b49e-d4061afd85b9","sourceKey":"bank:GST111:G111N1-073","payload":{"prompt":"How many categories of comprehension question do examiners use to test understanding?","options":["2","6","4","3"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"There are four categories: direct reference, inference, supposition and evaluation. The figure 2 is the number of question formats (MCQ and traditional type), not categories."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 181, $official_bank_source${"itemId":"f55a1aef-e134-539a-9c11-7057180ce3fe","questionId":"95e144d4-993f-5d9a-8210-8935253eb4a3","sourceKey":"bank:GST111:G111N1-074","payload":{"prompt":"A summary is usually about what fraction of the length of the original work?","options":["Two-thirds","One-third","One-tenth","One-half"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"A summary condenses the original to about one-third of its length. One-half would keep too much of the original to count as a proper condensed version."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 182, $official_bank_source${"itemId":"68a94c40-39fb-5a93-bc52-cf64ba06e036","questionId":"ac346bf2-9b23-5e95-91b4-42f583fa881f","sourceKey":"bank:GST111:G111N1-075","payload":{"prompt":"For which of the following would a synopsis, rather than a summary, be appropriate?","options":["A newspaper editorial","A novel","A research report","A textbook chapter"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"A synopsis summarises a plot, so it is used only for novels, plays and stories. A research report has no plot, so it gets an ordinary summary."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 183, $official_bank_source${"itemId":"537e1746-4f4d-52f9-8f34-31a60c6afca4","questionId":"b37f5966-bec2-5d57-a719-b910680d8a5a","sourceKey":"bank:GST111:G111N1-076","payload":{"prompt":"Short, concise summaries of non-fiction works are called","options":["synopses","abstracts","blurbs","prefaces"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"Short, concise non-fiction summaries are known as abstracts. A synopsis is a plot summary used only for novels, plays and stories, so it does not fit non-fiction."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 184, $official_bank_source${"itemId":"35228cc0-fd2a-52fb-b135-e12ab5010882","questionId":"81d34803-a5b9-5d11-b1d1-8debb2e0a5b7","sourceKey":"bank:GST111:G111N1-077","payload":{"prompt":"The lead of a written summary should give","options":["the title, author, text type and main idea","the summariser's opinion of the text","a direct quotation from the text","the dramatic climax of the text"],"correctOption":0,"section":"Reading Skills II: Comprehension and Summary","explanation":"A written summary begins with a lead stating the title, the author, the type of text and its main idea. A direct quotation is out of place because a summary should not quote from the text."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 185, $official_bank_source${"itemId":"d96c4af7-7ebb-5828-a19b-3497809beab8","questionId":"e5e424e2-b423-5d21-bda8-8bbff8074a37","sourceKey":"bank:GST111:G111N1-078","payload":{"prompt":"Which tense is preferred when writing a summary?","options":["The past perfect tense","The present tense or the historic present","The future tense","The past continuous tense"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"Summaries are best written in the present tense or the historic present. The past tense is allowed for poems, stories and novels, but no past form is the preferred choice."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 186, $official_bank_source${"itemId":"b2395fe7-5b1f-5597-93e7-3daf18a2153e","questionId":"c70bdab3-0d1f-557a-8015-995adaa40bd6","sourceKey":"bank:GST111:G111N1-079","payload":{"prompt":"Concerning tense, what should a writer AVOID in a summary?","options":["Using the present tense for a play","Using the present tense for a novel","Using the historic present","Shifting from one tense to another"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"Whatever tense you choose, you should keep to it and not shift tenses. Using the present tense for a play is not a fault, because drama is summarised in the present tense."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 187, $official_bank_source${"itemId":"a12f4282-b326-58e6-af20-c6c8cb827231","questionId":"08fdc498-b442-5d81-9e6c-0b31d0d0ba65","sourceKey":"bank:GST111:G111N1-080","payload":{"prompt":"When summarising a multi-section document such as a report, each section should have at least how many summarising statements?","options":["One","Two","Five","Three"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"For a multi-section summary, at least three summarising statements are written for each section. One statement per section is closer to a paragraph summary and would leave out too much."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 188, $official_bank_source${"itemId":"d0ce788b-c026-5785-aea7-0cada7513d83","questionId":"c1f63574-e4da-5a78-8594-3b3dc219563e","sourceKey":"bank:GST111:G111N1-081","payload":{"prompt":"A summary strategy that integrates the ideas of a section made up of several paragraphs is a","options":["synopsis","section summary","multi-section summary","paragraph summary"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"A section summary pulls together the ideas of a multi-paragraph section. A paragraph summary deals with only one paragraph at a time."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 189, $official_bank_source${"itemId":"00115857-185c-5cf3-996d-3034dead4c92","questionId":"1ab230a4-d22b-5381-9388-1ce369e8fd57","sourceKey":"bank:GST111:G111N1-082","payload":{"prompt":"In the third step of summarising a paragraph, the writer should","options":["write the content in new words without looking at the original","read again to pick out the essentials","compare the summary with the original and revise it","read to find the basic idea"],"correctOption":0,"section":"Reading Skills II: Comprehension and Summary","explanation":"The third step is to write the content in your own words without looking at the original. Comparing with the original and revising is the fourth and final step."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 190, $official_bank_source${"itemId":"0a6d298e-2bfa-541f-9da4-bd04c245e833","questionId":"ebd27512-cf67-5eb4-a30e-854c21c49961","sourceKey":"bank:GST111:G111N1-083","payload":{"prompt":"What is the FINAL step in summarising a paragraph?","options":["Compare your summary with the original and revise it","Express the content in your own words","Read the paragraph to find the basic idea","Read again to pick out the essentials"],"correctOption":0,"section":"Reading Skills II: Comprehension and Summary","explanation":"The last of the four steps is to compare your version with the original and revise it. Expressing the content in your own words comes just before this, as the third step."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 191, $official_bank_source${"itemId":"55deb4ca-69da-5ea0-ae02-cb12a8f2a084","questionId":"3f0f5968-2402-5142-a322-b10c06c121c0","sourceKey":"bank:GST111:G111N1-084","payload":{"prompt":"When summarising, three or four paragraphs of an original text can be reduced to","options":["three paragraphs","two pages","one word","one paragraph"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"In summarising, a paragraph can become one sentence, and three or four paragraphs can become one paragraph. Keeping three paragraphs would hardly condense the text at all."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 192, $official_bank_source${"itemId":"7fb55eb6-a32a-53fe-ae81-e66f12421ac5","questionId":"805a54c2-5ed4-5088-9adc-e1a490990af4","sourceKey":"bank:GST111:G111N1-085","payload":{"prompt":"A summary of a non-fiction work should present","options":["the summariser's own critique of the author","a dramatic structure that builds suspense","the author's point of view without the summariser's own analysis","long quotations from the original"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"A non-fiction summary gives the author's point of view and leaves out the summariser's own analysis. Adding your own critique turns the summary into a review."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 193, $official_bank_source${"itemId":"0fbca213-e314-5ea4-8c7b-ae1eeefad1dd","questionId":"040488a6-698b-59ae-9be3-c61bd219a01f","sourceKey":"bank:GST111:G111N1-086","payload":{"prompt":"When summarising a book or a dissertation, the summary should use","options":["poetic and figurative language","slang and informal expressions","common scientific language","the writer's own exact sentences"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"For books and dissertations, a summary should use common scientific language. Copying the writer's own exact sentences breaks the rule of paraphrasing rather than quoting."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 194, $official_bank_source${"itemId":"ee972336-48c7-540d-9285-e34a67b9d91e","questionId":"da50e5ec-ad36-50a7-b016-4523b59bfccf","sourceKey":"bank:GST111:G111N1-087","payload":{"prompt":"In Barbara Tuchman's 'A Distant Mirror', used as an illustrative text on summary, the English ordinance of 1349 was reissued in 1351 as the","options":["Poor Law","Bill of Rights","Magna Carta","Statute of Labourers"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"The extract describes the English ordinance of 1349 being reissued in 1351 as the Statute of Labourers. The Magna Carta, Poor Law and Bill of Rights are other English laws that are not connected with this extract."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 195, $official_bank_source${"itemId":"e5d85f5a-7899-5a17-a308-8cea4efcc6be","questionId":"275aa709-f140-5b43-ae1f-16db0a6b1cc0","sourceKey":"bank:GST111:G111N1-088","payload":{"prompt":"When answering a comprehension multiple choice question, how many options should a candidate mark?","options":["Every option that is partly correct","Only one option","None, if the answer is not obvious","Two, to be on the safe side"],"correctOption":1,"section":"Reading Skills II: Comprehension and Summary","explanation":"Never mark more than one answer, since there is usually one correct answer. Marking every option that is partly correct is a trap, because some options are designed to be only partly right."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 196, $official_bank_source${"itemId":"9a032a6e-e1e7-55e1-b95f-cdbcb8ad7ff2","questionId":"2a9cdebb-61c9-5d1b-b559-04131e01a782","sourceKey":"bank:GST111:G111N1-089","payload":{"prompt":"The extract from T. H. Huxley's 'Collected Essays', used as an illustrative text on summary, discusses","options":["the plague and wages in Europe","the first landing on the moon","'pure' versus 'applied' science","racial discrimination in London"],"correctOption":2,"section":"Reading Skills II: Comprehension and Summary","explanation":"Huxley's essay deals with the distinction between 'pure' and 'applied' science. The plague and wages are the subject of the Tuchman extract, a different illustrative text."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 197, $official_bank_source${"itemId":"2f475bb8-07c2-5b21-a3a3-f78aff43bfe3","questionId":"62b19ac0-1618-5218-9001-73d27843b85e","sourceKey":"bank:GST111:G111N1-090","payload":{"prompt":"What should a writer do with the ideas of the original text when writing a summary?","options":["Add a personal judgement of the author","Copy the key sentences exactly","Present them in a dramatic structure","Arrange them clearly and paraphrase them in new words"],"correctOption":3,"section":"Reading Skills II: Comprehension and Summary","explanation":"A written summary arranges the ideas clearly and paraphrases them in new words. Building a dramatic structure is wrong, because a summary should have no dramatic structure."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 198, $official_bank_source${"itemId":"55f51f3e-0d06-5acc-bffe-a57513931e95","questionId":"13874866-e0b1-54ee-8e87-96b9b3366eec","sourceKey":"bank:GST111:GST111-0033","payload":{"prompt":"Prescribed text usually","options":["Contain all the topics to be treated in a subject","Constitute the lecturers sole sources","Direct the reader to supplementary texts","Contain most of the topics to be treated or the basis for discussion in the lectures"],"correctOption":3,"section":"Reading Skills III: Study Reading","explanation":"A prescribed text is the recommended main book for a course, and it usually contains most of the topics to be treated or forms the basis for discussion in lectures, so D is correct. Option A is too strong because no single text covers every topic, and B is wrong because lecturers use many sources. Directing readers to supplementary texts (C) is a minor side role, not its main purpose."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 199, $official_bank_source${"itemId":"f244ee0d-1ee8-5922-876c-ad338c1b7397","questionId":"53e0df58-7056-5718-bff7-b0a018de92c9","sourceKey":"bank:GST111:GST111-0034","payload":{"prompt":"Which one of these is not recommended for efficient studying","options":["Reading with pre-conceived ideas","Generation of guide questions as you read","Adoption of flexible reading speed","Employing memory enhancing devices"],"correctOption":0,"section":"Reading Skills III: Study Reading","explanation":"Reading with pre-conceived ideas (option A) is not recommended because prejudices and emotional attachment to a subject get in the way of understanding; a good reader keeps an open, questioning mind. The other options are good study practices: asking guide questions as you read (B), varying your reading speed to suit purpose and difficulty (C), and using memory aids like mnemonics (D)."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 200, $official_bank_source${"itemId":"2aec54e8-ed2e-50ac-8cbe-a52dedbcd295","questionId":"361775a9-ad37-5016-a34c-2b0fe823d96c","sourceKey":"bank:GST111:GST111-0035","payload":{"prompt":"Supplementary texts are usually given so that","options":["Students may have a wide reading list","Students can have the opportunity to acquire additional information for their courses","Students can fully understand the topics treated in their course","Students educational experience may be balanced"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"Supplementary texts are given so that students can get additional information beyond what the main text covers, which is option B. The word 'supplement' means to add to. A long reading list (A) is not a goal in itself, and full understanding (C) or a balanced education (D) are too vague to be the stated purpose."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 201, $official_bank_source${"itemId":"f387e86b-b787-5984-b4de-219708f632ae","questionId":"cb81a185-9724-53f4-b4b9-e94d4c71bc6b","sourceKey":"bank:GST111:GST111-0082","payload":{"prompt":"During the reading process the saccadic and regressive eye movements are","options":["Defective reading technique","Complementary reading technique","Retrogressive reading technique","Natural reading technique"],"correctOption":3,"section":"Reading Skills III: Study Reading","explanation":"When we read, our eyes move forward in little jumps and stops along the line (saccadic movement) and sometimes move back to words already read (regressive movement). Both are part of how the eyes naturally work in reading, so D, natural reading technique, is correct. They become a problem only when regression is excessive, so A and C are too negative, and B, complementary, is not the term used for these movements."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 202, $official_bank_source${"itemId":"5677b9a4-3ca9-58d0-bd86-061d5578731c","questionId":"bd8aad12-88cd-57ba-9cdc-a5b7b5d7b1cb","sourceKey":"bank:GST111:GST111-0177","payload":{"prompt":"Your mental posture while reading is not affected by ...............","options":["music from the radio or other gadgets","worries about money and affairs","the arrangement of keywords and topic sentences","noise"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"Your mental posture for reading is disturbed by things like music from a radio or phone, noise, and worries about money, love or health. The arrangement of keywords and topic sentences is different: it is a reading strategy that helps you follow the text, so it does not disturb you, and C is the answer. A, B and D are all distractions."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 203, $official_bank_source${"itemId":"f74ba458-f09a-5017-afb6-704144b63895","questionId":"b3ad14c0-f23d-58ac-8ec2-6b71d61cbc66","sourceKey":"bank:GST111:GST111-0188","payload":{"prompt":"---------------- is not associated with sensory memory.","options":["the ears","the brain","the nose","the eyes"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"Sensory memory is tied to the senses, so the organs involved are the ears, eyes, hands, tongue and nose. The brain is not a sense organ; it processes information after the senses have received it, so B is the one not associated with sensory memory. A, C and D are all sense organs."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 204, $official_bank_source${"itemId":"bb8ed1d5-9a55-5286-a7f3-fd9a9a6a4056","questionId":"cb5dec09-5155-5aab-8764-6e46379a5cc4","sourceKey":"bank:GST111:GST111-0233","payload":{"prompt":"Which of the following is not a mark of a serious student?","options":["reading at a specific time and place","reading study materials anywhere","having a reading timetable","avoiding distractions while reading"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"A serious student plans study for a specific time at a regular place, draws up a reading timetable and avoids distractions, because a textbook, unlike a newspaper, needs a quiet, private area for understanding. Reading study materials just anywhere contradicts this, so B is not a mark of a serious student, while A, C and D are all good habits."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 205, $official_bank_source${"itemId":"c454b4e0-ae7c-59aa-8bef-cc3a086320b5","questionId":"25c7c38d-f128-5459-81b4-448eba5e2d92","sourceKey":"bank:GST111:GST111-0236","payload":{"prompt":"3R stands for -----------------","options":["Read, Roll, Repeat","Read, Recite, Repeat","Read, Recall, Review","Read, Replay, Reharsh"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"The 3Rs in the SQ3R technique (Survey, Question, Read, Recall, Review) are Read, Recall and Review. Options A and D include steps such as Roll, Replay and Reharsh that are not part of the method. Option B is the closest trap because Recite is another name for Recall, but Repeat is not the third R."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 206, $official_bank_source${"itemId":"5890ba3f-8b3b-5586-828b-6da573b74755","questionId":"5e543fff-755e-5f86-bd67-3220f234dd48","sourceKey":"bank:GST111:GST111-0283","payload":{"prompt":"Which of the following is true?","options":["We read only for pleasure","None of the above","We read only for exams","We read for knowledge acquisition only"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"People read for many different purposes, from pleasure to serious ones like examinations and acquiring knowledge. Options A, C and D each use the word only, which makes each one false, so B (none of the above) is the only correct choice."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 207, $official_bank_source${"itemId":"edc22c91-59d3-50d3-bb74-31b4ecb953c8","questionId":"ec90fe51-84ef-5934-8309-7cd65455038b","sourceKey":"bank:GST111:GST111-0352","payload":{"prompt":"Reading for the purpose of gathering information that will translate to knowledge is also known as ---------------------","options":["study reading","exploring","scanning","skimming"],"correctOption":0,"section":"Reading Skills III: Study Reading","explanation":"Study reading is the type of reading we do to gather information that will turn into knowledge in a specific area, so A is correct. Scanning and skimming (C and D) are quick reading techniques for finding specific facts or getting a general idea, not for deep learning. Exploring (B) is not a reading type."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 208, $official_bank_source${"itemId":"c102c03b-07f8-543b-ac44-13bab1f54601","questionId":"d0ba627d-7526-5583-8c07-fd9f896a35da","sourceKey":"bank:GST111:GST111-0365","payload":{"prompt":"One of the following is NOT true.","options":["through reading, you improve upon your listening skills","through reading, you diminish your speech ability","through reading, you enlarge your vocabulary","through reading, you improve your writing skills"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"Reading builds your ability to speak rather than weakening it, so B is the false statement. Through reading you enlarge your vocabulary, which in turn improves your listening and writing, and the extra words and structures you meet also feed your speech. Options A, C and D are all real benefits of reading."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 209, $official_bank_source${"itemId":"5077dced-5554-50ee-801d-3e9ae2abcde2","questionId":"e65f97a9-0efc-5c6d-b761-cdf19ba00f5d","sourceKey":"bank:GST111:GST111-0383","payload":{"prompt":"One of the following is a reading technique.","options":["STPQR","QRSTP","PQRST","RSTPQ"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"PQRST is a method of study reading, standing for Preview, Question, Read, Summary and Test, so C is correct. Options A, B and D just scramble the letters and do not match any study technique taught in this course."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 210, $official_bank_source${"itemId":"da71c2ec-1fc7-511e-a165-361755cb30fe","questionId":"9df3dcaf-de34-5bea-8004-4b8269e388d2","sourceKey":"bank:GST111:GST111-0405","payload":{"prompt":"Recalling stored information is enhanced by the following except ---------","options":["review","reproduction","repetition","recitation"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"Recalling stored information is helped by repetition, recitation and review, which are all active ways of strengthening memory. Reproduction is just producing the information, for example in an exam, and does not improve recall, so B is the odd one out."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 211, $official_bank_source${"itemId":"9f049e92-d628-5958-bb61-33a167284627","questionId":"47ac92b5-989e-506d-8990-bc04f5583f0d","sourceKey":"bank:GST111:GST111-0424","payload":{"prompt":"A survey of an article or chapter in a book does not take -------------------- into consideration.","options":["the blurb","the topic sentences","its title","the introduction and conclusion"],"correctOption":0,"section":"Reading Skills III: Study Reading","explanation":"Surveying an article or chapter means checking the title, the first and concluding paragraphs and the topic sentences of each paragraph. The blurb is used when surveying a whole book, since only books carry one, so A is the exception. Options B, C and D are all parts of surveying an article or chapter."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 212, $official_bank_source${"itemId":"8c338305-7662-591e-ad43-be2e4d8ba9df","questionId":"dedce23d-956b-53a8-8bd5-ee4abb2e0089","sourceKey":"bank:GST111:GST111-0427","payload":{"prompt":"How a reading material is read is determined by --------------------.","options":["its nature","the publishers","the author","the reader"],"correctOption":0,"section":"Reading Skills III: Study Reading","explanation":"The nature of a reading material decides how it is read and how rigorously: a newspaper is read once and discarded, while a study book is studied repeatedly (A). Option D, the reader, is tempting because readers vary their speed, but it is the material's nature that determines the approach. The author (C) and publishers (B) have no say in how you read."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 213, $official_bank_source${"itemId":"c5d50845-3eb0-5584-b32a-14dd4550f754","questionId":"402422ea-c915-5abb-8260-e7dd769c0c0b","sourceKey":"bank:GST111:GST111-0447","payload":{"prompt":"Survey, in reading, involves ---------------.","options":["investigating the depth of the content","liaising with surveyors before reading","examining the preliminary matters and blurb of the book","measuring the length and breadth of the book"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"In the survey stage of SQ3R, you examine the preliminary matters of a book, such as the title, preface, foreword and table of contents, and read the blurb for a summary of the book (C). Option A describes deeper study reading, not a survey, and B and D play on the everyday meaning of survey and have nothing to do with reading."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 214, $official_bank_source${"itemId":"1f539f72-1782-50e5-afe5-29c7c5c75fd3","questionId":"c8dc9313-3463-55f4-be09-4595c4174982","sourceKey":"bank:GST111:GST111-0462","payload":{"prompt":"Based on the length of storage of information, memory is classified into ------","options":["visible and invisible","variable and invariable","long and short-term","active and dormant"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"By how long information is kept, memory is divided into short-term memory, which stores information briefly and filters out what is irrelevant, and long-term memory, which is permanent and large (C). Sensory memory is the very brief memory linked to the senses. Active and dormant (D) describe kinds of vocabulary, not memory, and A and B are not memory types at all."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 215, $official_bank_source${"itemId":"18a86db9-7a02-5287-8d56-21a382e1ae9d","questionId":"825b9495-71b8-5e5d-be80-9c3850e2eb91","sourceKey":"bank:GST111:GST111-0474","payload":{"prompt":"The movement of the eyes in the process of reading can be described as ------------","options":["velaric","glottalic","saccadic","pulmonic"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"When we read, our eyes move in little jumps forward and then stop, and this movement is called saccadic (C). Velaric, glottalic and pulmonic (A, B and D) are airstream mechanisms in speech production and have nothing to do with eye movement."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 216, $official_bank_source${"itemId":"95236d67-d7b0-516f-9036-6b6d9d1d4f00","questionId":"3a0528e3-75a6-53cd-860b-9cea8f71efc6","sourceKey":"bank:GST111:G111N1-091","payload":{"prompt":"SQ3R, a method of study reading, stands for","options":["Summarise, Question, Read, Recall, Revise","Survey, Question, Read, Recall/Recite, Review","Scan, Question, Read, Recite, Repeat","Survey, Question, Reflect, Recollect, Review"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"SQ3R is Survey, Question, Read, Recall/Recite and Review. Reflect and Recollect belong to the 3S3R method, not to SQ3R."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 217, $official_bank_source${"itemId":"8022d77e-c52d-5c03-b7f4-59c4e0cb48ca","questionId":"44ae1121-64c2-54bd-b82e-78da5116a596","sourceKey":"bank:GST111:G111N1-092","payload":{"prompt":"What do the letters of the study-reading method PQRST stand for?","options":["Prepare, Question, Read, Study, Test","Preview, Question, Read, Summary, Test","Preview, Question, Recall, Survey, Test","Preview, Quiz, Review, Summary, Text"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"PQRST is Preview, Question, Read, Summary and Test. The other expansions swap in words such as Recall, Study or Review, which do not belong to PQRST."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 218, $official_bank_source${"itemId":"8dbafd30-ea95-574b-ad65-c59e0bc3ff3c","questionId":"ff0b5044-b890-59bf-a790-410ba6beb03f","sourceKey":"bank:GST111:G111N1-093","payload":{"prompt":"In the OK4R method of study reading, the letter 'K' stands for","options":["Key questions","Kind of text","Knowledge","Key points"],"correctOption":3,"section":"Reading Skills III: Study Reading","explanation":"OK4R is Overview, Key points, then Read, Recall, Reflect and Review. 'Key questions' sounds close, but questioning is a step in SQ3R and PQRST, not the K of OK4R."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 219, $official_bank_source${"itemId":"2948b090-71c7-55eb-8d15-ae4338f66136","questionId":"92307e55-8115-5dc4-a123-e421c9374ae1","sourceKey":"bank:GST111:G111N1-094","payload":{"prompt":"Which method of study reading consists of Survey, Study-read, Speech-read, Recite, Reflect and Recollect?","options":["OK4R","SQ3R","PQRST","3S3R"],"correctOption":3,"section":"Reading Skills III: Study Reading","explanation":"The three S steps (Survey, Study-read, Speech-read) and three R steps (Recite, Reflect, Recollect) make up 3S3R. SQ3R also starts with Survey, but its other steps are Question, Read, Recall/Recite and Review."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 220, $official_bank_source${"itemId":"fd8fec16-6bd2-56b2-864a-7e3cdca0b6b2","questionId":"45b9ce64-d932-5b31-b6bc-a0bbc2236971","sourceKey":"bank:GST111:G111N1-095","payload":{"prompt":"Which method of study reading gives priority to information needed for examinations?","options":["SQ3R","3S3R","OK4R","PQRST"],"correctOption":3,"section":"Reading Skills III: Study Reading","explanation":"PQRST, which ends with Summary and Test, gives priority to information needed for exams. SQ3R is a general study-reading method that ends with Review rather than a test."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 221, $official_bank_source${"itemId":"69b8eae9-fc10-5c47-a949-6f863ff68582","questionId":"36b2f79a-1f73-5251-83a2-06e02336106b","sourceKey":"bank:GST111:G111N1-097","payload":{"prompt":"The type of memory that stores information for a short time, organises it and filters out what is irrelevant is","options":["long-term memory","retrieval memory","short-term memory","sensory memory"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"Short-term memory holds information briefly, organises it and removes what is irrelevant. Long-term memory, by contrast, is permanent and limitless."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 222, $official_bank_source${"itemId":"49b3cc31-cade-523d-a673-33a08c26e3cf","questionId":"058935c7-7d3a-58a4-99fc-67f4914346ef","sourceKey":"bank:GST111:G111N1-098","payload":{"prompt":"Which type of memory is described as permanent, large and limitless?","options":["Working memory","Long-term memory","Sensory memory","Short-term memory"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"Long-term memory is permanent, large and limitless. Short-term memory keeps information only for a short time before filtering it."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 223, $official_bank_source${"itemId":"2e61be65-8cab-586b-ab6c-e1f06594134e","questionId":"6be89239-1ac8-5cc4-a1bb-b95e0a05c95d","sourceKey":"bank:GST111:G111N1-099","payload":{"prompt":"The type of memory linked to the senses, such as the eyes, ears and tongue, and which is very ephemeral, is","options":["retrieval memory","sensory memory","long-term memory","short-term memory"],"correctOption":1,"section":"Reading Skills III: Study Reading","explanation":"Sensory memory is tied to the senses and fades almost at once, which is what 'very ephemeral' means. Short-term memory lasts a little longer and organises information."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 224, $official_bank_source${"itemId":"948dfe9f-96a5-55ab-bcfd-133df7972131","questionId":"5127810b-35ae-5559-81e4-faed361649b7","sourceKey":"bank:GST111:G111N1-100","payload":{"prompt":"What is the correct order of the stages of storing information in memory?","options":["Encoding, storage, retrieval","Retrieval, encoding, storage","Storage, encoding, retrieval","Encoding, retrieval, storage"],"correctOption":0,"section":"Reading Skills III: Study Reading","explanation":"Information is first encoded (read, organised and internalised), then stored (retained), and finally retrieved (recalled). Storage cannot come before encoding, because information must be taken in before it can be kept."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 225, $official_bank_source${"itemId":"4eb4660a-8812-5ed4-aa6e-45da17755a88","questionId":"f4c8b3bb-87e1-5494-b822-363dbb11c96e","sourceKey":"bank:GST111:G111N1-101","payload":{"prompt":"Reading, organising and internalising information belong to which stage of storing information?","options":["Encoding","Storage","Recollection","Retrieval"],"correctOption":0,"section":"Reading Skills III: Study Reading","explanation":"Encoding is the stage where you read, organise and internalise information. Storage is the next stage, where the information is retained."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 226, $official_bank_source${"itemId":"8a732172-b58b-5a96-826c-07c056cf2ffa","questionId":"9a789116-aa37-5346-ae6e-8a2eb8d50d0b","sourceKey":"bank:GST111:G111N1-102","payload":{"prompt":"The stage of storing information in which a student recalls what was learnt, aided by attention, is","options":["encoding","survey","retrieval","storage"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"Retrieval is the recall stage, and attention helps it. Storage is only the keeping of information, not bringing it back out."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 227, $official_bank_source${"itemId":"ce0a68ab-1ada-57b6-9959-9169b45f6bb6","questionId":"41530a53-5723-5430-b15e-3804f919b550","sourceKey":"bank:GST111:G111N1-103","payload":{"prompt":"Which of the following is described as the best way to remember what you read?","options":["Verbatim recitation","Highlighting every line","Paraphrasing","Reading once quickly"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"Paraphrasing, putting ideas into your own words, is the best way to remember. Verbatim recitation suits only special cases such as play lines, foreign languages and the sciences."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 228, $official_bank_source${"itemId":"b20e27b6-bfc3-5d13-8a6a-80aea2fe368e","questionId":"289cfc8d-f4c2-55fc-a599-a3c9deb4e96e","sourceKey":"bank:GST111:G111N1-104","payload":{"prompt":"Using 'ROYGBIV' to remember the colours of the rainbow is an example of which study aid?","options":["A graphic organiser","Summarisation through keywords","A flash card","A mnemonic device"],"correctOption":3,"section":"Reading Skills III: Study Reading","explanation":"ROYGBIV is a mnemonic device or acronym in which each letter stands for a colour, from red to violet. A flash card is a separate study aid: a card with visual clues."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 229, $official_bank_source${"itemId":"2c94a6ce-d7ef-5562-83aa-de8584e93bc7","questionId":"613ef458-d895-5e15-84a0-073d66ba994a","sourceKey":"bank:GST111:G111N1-105","payload":{"prompt":"Flash cards recommended as a study aid are usually of which paper size?","options":["A5","A4","A3","A1"],"correctOption":0,"section":"Reading Skills III: Study Reading","explanation":"Flash cards are A5 in size and carry visual clues. A4 is the standard size of a full sheet, which is larger than a flash card needs to be."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 230, $official_bank_source${"itemId":"0c5c09c9-0eee-569d-ab6b-02857db36800","questionId":"6122fe4e-6be0-5c32-8ecb-645fda8fc3df","sourceKey":"bank:GST111:G111N1-106","payload":{"prompt":"Unlike a newspaper, which is usually read once, a course book should be read","options":["once and quickly","only by skimming","repeatedly and with effort","only the night before an exam"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"The nature of what is being read decides how it is read: a newspaper is read once, but a course book is read repeatedly and with effort. Skimming a course book would give only the general idea, not the knowledge it is meant to provide."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 231, $official_bank_source${"itemId":"a32f6b7d-5a5b-5b89-a7d3-8735df07b78d","questionId":"b6188924-af12-5c96-a69d-9701ed73ad7b","sourceKey":"bank:GST111:G111N1-107","payload":{"prompt":"Which of the following is a sub-strategy of the 'Read' stage of SQ3R?","options":["Identify verbal and sense links such as keywords and topic sentences","Assess the work by going over all the steps again","Remember the material from memory and tell it to a friend","Examine the title, preface and table of contents"],"correctOption":0,"section":"Reading Skills III: Study Reading","explanation":"Identifying verbal and sense links is one of the seven sub-strategies of the Read stage. Going over all the steps again is the Review stage, which comes last."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 232, $official_bank_source${"itemId":"07847e9c-0ee3-51ce-b27d-0470ab5fdd1c","questionId":"04e2015c-b7cd-5e04-ac06-e5614d095a1a","sourceKey":"bank:GST111:G111N1-108","payload":{"prompt":"In SQ3R, the stage that is the same as revision is","options":["Survey","Question","Recall/Recite","Review"],"correctOption":3,"section":"Reading Skills III: Study Reading","explanation":"Review means assessing your work, which is the same as revision, by going over all the steps again. Recall/Recite is about remembering from memory, not revising the whole process."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 233, $official_bank_source${"itemId":"eadf95aa-4b7c-525d-b8f6-6b1065bbaa12","questionId":"cca28216-37a8-56c7-8bf0-5df16e7c3a44","sourceKey":"bank:GST111:G111N1-109","payload":{"prompt":"A UNILAG student closes her course book and explains the chapter from memory to a friend in her hostel. Which stage of SQ3R is she practising?","options":["Recall/Recite","Review","Survey","Question"],"correctOption":0,"section":"Reading Skills III: Study Reading","explanation":"Recall/Recite means remembering from memory, by paraphrasing or using the exact words, in writing or to a friend. Review is about assessing the work by going over all the steps again."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 234, $official_bank_source${"itemId":"2935dc97-5f55-5a80-ba9b-a57e2a2edda0","questionId":"26d0d12b-7bba-5b8a-b4ed-69cfe85c302c","sourceKey":"bank:GST111:G111N1-110","payload":{"prompt":"In study reading, asking 'Is the writer objective?' and 'Does it contradict my views?' belongs to which stage of SQ3R?","options":["Survey","Review","Question","Read"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"These are among the example questions of the Question stage of SQ3R. The Survey stage only looks over preliminary matter such as the title, preface and table of contents."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 235, $official_bank_source${"itemId":"9312dfba-628e-5514-b72c-42f11aa3b3f6","questionId":"011ad3b4-fcc3-5f61-99dc-cd0b0e696b3b","sourceKey":"bank:GST111:G111N1-111","payload":{"prompt":"Reading improves a student's listening and writing mainly because it","options":["reduces the need to attend lectures","trains the vocal apparatus","enlarges the student's vocabulary","removes the need for revision"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"Reading enlarges your vocabulary, and a bigger vocabulary in turn improves listening and writing. Training the vocal apparatus is not what reading does; reading uses the eyes and the mental faculty."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 236, $official_bank_source${"itemId":"955e72a6-c2dd-50b3-976f-0032f5026715","questionId":"0861f792-c2cd-542b-9f40-583c09033979","sourceKey":"bank:GST111:G111N1-112","payload":{"prompt":"Reading is described as a process of communication through which","options":["spoken words are decoded","only pleasure is obtained","most formal learning takes place","speech ability is diminished"],"correctOption":2,"section":"Reading Skills III: Study Reading","explanation":"Reading is a process of communication through which most formal learning takes place. Decoding spoken words describes listening, not reading."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 237, $official_bank_source${"itemId":"dc948ef5-1a71-595d-a71f-4253f5f344c1","questionId":"1aba2a86-e6c5-5f57-832d-f47e6562dbfc","sourceKey":"bank:GST111:GST111-0083","payload":{"prompt":"A very important part of a paragraph is","options":["The topic outline","The topic sentence","Sentence structure","Paragraph outline"],"correctOption":1,"section":"Writing Skills I: The Paragraph","explanation":"The topic sentence is the most important part of a paragraph because it states the main idea and works as a summary of the paragraph, so B is correct. A topic outline (A) and a paragraph outline (D) are planning tools rather than parts of the paragraph, and sentence structure (C) concerns individual sentences, not the idea that organizes the paragraph."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 238, $official_bank_source${"itemId":"913dacab-dbc7-5d44-9b05-8056a3e1f4d8","questionId":"03849063-4925-5e91-9a98-6fd837aff193","sourceKey":"bank:GST111:GST111-0107","payload":{"prompt":"The .............. sentence is the most important sentence in a paragraph.","options":["topic","last","concluding","first"],"correctOption":0,"section":"Writing Skills I: The Paragraph","explanation":"The topic sentence is the most important sentence in a paragraph because it states the main idea and acts as a summary of the paragraph, so A is correct. First (D) and last (B) describe positions rather than functions, and the topic sentence can appear in different places. A concluding sentence (C) is optional, so it cannot be the most important."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 239, $official_bank_source${"itemId":"443a391f-2bd1-5db1-88f8-e03dc485ddbf","questionId":"cd3362b5-7f68-5462-ab35-d0c76f69e176","sourceKey":"bank:GST111:GST111-0114","payload":{"prompt":"The element which makes a paragraph easily understandable to the reader is ..............","options":["unity","completeness","development","coherence"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"Coherence, option D, is the quality that makes a paragraph easy for the reader to follow, achieved through logical and verbal bridges such as repeated key words, pronouns and transition words. Unity (A) means the paragraph keeps to a single focus, and development (C) means the topic is fully discussed. Completeness (B) is not one of the named elements of a paragraph."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 240, $official_bank_source${"itemId":"9415b74d-eb7e-595e-89da-b1960c77b903","questionId":"3c1ed1df-60dd-5ba3-9876-7c40391e4ee3","sourceKey":"bank:GST111:GST111-0169","payload":{"prompt":"A/an ---------------- paragraph describes a series of events or a process in some sort of order.","options":["descriptive","explanation","evaluation","sequence"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"A sequence paragraph describes a series of events or a process in some order, usually time order, and it uses helper words like first, second, third and previously. Option B (explanation) tells how or why something happens, C (evaluation) makes judgements, and A (descriptive) paints a picture of a person, place or thing, so none of them is about order of events."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 241, $official_bank_source${"itemId":"1be0b3af-73df-52dd-81c3-7fd4eb23e4a0","questionId":"893ecde0-6088-5112-b0dd-92ed945df02b","sourceKey":"bank:GST111:GST111-0172","payload":{"prompt":"................. is not a step in paragraph development.","options":["choosing a controlling idea","giving examples","none of these","explaining the controlling idea"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"The steps in paragraph development are: choose a controlling idea and write a topic sentence, explain the controlling idea, give an example or examples, explain the examples, and then complete the idea or lead into the next paragraph. Since A, B and D are all genuine steps, C, none of these, is the answer to a question asking which is not a step."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 242, $official_bank_source${"itemId":"1e960e70-5344-5734-925d-458f55e72a6f","questionId":"4b008116-5f67-5872-ae37-9e6322af10b7","sourceKey":"bank:GST111:GST111-0185","payload":{"prompt":"One of the following is a feature shared by both paragraphs and essays:","options":["unity and self sufficiency","cohesion and transparency","transition and cohesion","unity and coherence"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"Both a good paragraph and a good essay show unity and coherence: unity means sticking to a single focus, and coherence means the ideas flow logically and are easy to follow. Options A, B and C each pair in something that is not a core feature, such as self sufficiency or transparency, or name transition, which is only a device for achieving coherence."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 243, $official_bank_source${"itemId":"9f453f14-203c-53f0-aca3-7afe8d73c85b","questionId":"befd4160-086c-5ef1-8e8b-0583c48c234e","sourceKey":"bank:GST111:GST111-0198","payload":{"prompt":"It is NOT ideal to begin a new paragraph when:","options":["readers need a pause in a long stretch of text","the next statement contrasts with the preceding information","you want to introduce a new idea","you are still developing the same main idea"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"A paragraph keeps to a single main idea, so while you are still developing that idea you should stay in the same paragraph, which makes D correct. A new paragraph is the right move when you introduce a new idea (C), when the next statement contrasts with what came before (B), or when readers need a pause (A)."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 244, $official_bank_source${"itemId":"77fc3ef7-e179-53c1-8100-d6dbb79f3775","questionId":"862f3b25-7358-55ea-9e43-06eea9e7c1d7","sourceKey":"bank:GST111:GST111-0199","payload":{"prompt":"A/an ---------------- paragraph explains how or why something happens.","options":["definition","explanation","choice","sequence"],"correctOption":1,"section":"Writing Skills I: The Paragraph","explanation":"An explanation paragraph explains how or why something happens, exploring causes and effects with helper words like because, therefore and thus. Option A (definition) explains key words, C (choice) states a preference, and D (sequence) describes events in time order."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 245, $official_bank_source${"itemId":"0586e333-9fba-5c11-8d28-f078d49a39b3","questionId":"7571607e-0a72-5cdf-8e39-fa5d4f65f01c","sourceKey":"bank:GST111:GST111-0243","payload":{"prompt":"Which of the following is NOT true of paragraphs?","options":["every paragraph begins with a topic sentence","they are of varying lengths","a paragraph is hardly ever longer than the entire essay.","the argument in a paragraph addresses only an aspect of the topic"],"correctOption":0,"section":"Writing Skills I: The Paragraph","explanation":"The topic sentence is often but not always the first sentence of a paragraph: it can come in the middle or at the end, and sometimes the main idea is so obvious that none is stated. So it is not true that every paragraph begins with one, and A is correct. Options B, C and D (varying lengths, shorter than the whole essay, addressing one aspect of the topic) are all true of paragraphs."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 246, $official_bank_source${"itemId":"552e479b-8cd7-52d7-aa90-7b84f2c1d67d","questionId":"96cd83e1-d8c6-52ca-b60d-3ed1c7560dc2","sourceKey":"bank:GST111:GST111-0346","payload":{"prompt":"We need to troubleshoot a paragraph in all the following cases except ..............","options":["when it is too long or too short","when there is a problem with its topic sentence","when it has multiple controlling ideas","when it has issues with transition within the paragraph"],"correctOption":0,"section":"Writing Skills I: The Paragraph","explanation":"A paragraph needs troubleshooting when its topic sentence is faulty, when it has multiple controlling ideas, or when its transitions are weak. Length alone is not a fault, because length does not decide what makes a paragraph, so A is the exception. Options B, C and D are all real reasons to troubleshoot."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 247, $official_bank_source${"itemId":"f51a989c-b3ad-5ef4-b03d-feaab246abf6","questionId":"fbb0a276-e987-5320-94c4-6533988a501e","sourceKey":"bank:GST111:GST111-0364","payload":{"prompt":"One of the following is NOT a way of enhancing coherence.","options":["using transition words","using synonyms","repeating keywords","avoiding the use of pronouns"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"Pronouns that refer back to nouns in earlier sentences help build coherence, so avoiding pronouns does not enhance it; it only makes writing clumsy and repetitive (D). Repeating keywords, using synonyms and using transition words (A, B and C) are all genuine ways of creating verbal bridges between sentences."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 248, $official_bank_source${"itemId":"a352edde-747b-5e01-a4a7-0f2864dac63c","questionId":"71708183-dd13-587e-b394-376b85286588","sourceKey":"bank:GST111:GST111-0372","payload":{"prompt":"A/an -------------- is a unit of any composition comprising a collection of related sentences dealing with a single topic.","options":["sentence","text","essay","paragraph"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"A paragraph is a unit of composition made up of related sentences dealing with a single topic, so D is correct. An essay (C) is bigger, because it combines ideas from one paragraph to another. A sentence (A) is smaller than the unit described, and a text (B) is too general."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 249, $official_bank_source${"itemId":"eee7afb4-7365-5ee2-a908-94045c82f5aa","questionId":"99e11cdf-0c9d-5d10-811a-ed6d119c0b7b","sourceKey":"bank:GST111:GST111-0401","payload":{"prompt":"The ............... in a paragraph states the main idea in that paragraph and works as its summary.","options":["sentence","conclusion","punctuation","topic sentence"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"The topic sentence states the main idea of a paragraph and works as its summary (D). Option B, conclusion, is wrong because the concluding sentence only closes the paragraph and is optional. A sentence in general (A) need not carry the main idea, and punctuation (C) is not a sentence at all."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 250, $official_bank_source${"itemId":"6cc2473c-6fb3-5078-a064-4694e714fc4c","questionId":"652c5758-c0bd-5315-94a7-90acd66967a1","sourceKey":"bank:GST111:GST111-0402","payload":{"prompt":"A paragraph is complete when it has ..............","options":["an initial capital letter and a a final full stop","none of the above","a topic sentence and supporting details","an argument"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"A paragraph has a topic sentence (essential), supporting or detail sentences (essential) and a concluding sentence (optional), so it is complete once it has a topic sentence with supporting details (C). Option A describes the mechanics of a sentence, not a paragraph, and D is wrong because not every paragraph argues a point."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 251, $official_bank_source${"itemId":"5bcbb0cf-9a0a-535f-a109-ff87dee6d1ff","questionId":"d96784f8-7267-571b-918e-308d6b2cdaac","sourceKey":"bank:GST111:GST111-0429","payload":{"prompt":"To develop a paragraph, a .............. step process is advised.","options":["1","5","7","3"],"correctOption":1,"section":"Writing Skills I: The Paragraph","explanation":"Paragraph development follows a 5-step process: decide on a controlling idea and write a topic sentence, explain it, give examples, explain the examples, and complete the idea or move on to the next paragraph. So B is correct, and 1, 7 and 3 (A, C and D) give the wrong number of steps."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 252, $official_bank_source${"itemId":"a1907f26-249a-5c50-8163-1bd0effab30b","questionId":"8c1f3c01-8269-509f-ba6c-d860b4543a4c","sourceKey":"bank:GST111:GST111-0441","payload":{"prompt":"Unity in a paragraph suggests ........","options":["connection with other paragraphs","singularity of focus","elocution","brevity"],"correctOption":1,"section":"Writing Skills I: The Paragraph","explanation":"Unity means the whole paragraph keeps a single focus and does not wander into different ideas, so B is correct. Connection with other paragraphs (A) is about linking paragraphs with transitions, not about unity within one paragraph. Brevity (D) is about length, and elocution (C) concerns speaking."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 253, $official_bank_source${"itemId":"afe38528-3970-5007-9e1b-012a865334b0","questionId":"09939134-f488-59dc-b091-0ec3716add80","sourceKey":"bank:GST111:GST111-0464","payload":{"prompt":"A/an .... is a combination of ideas from one paragraph to another, that creates a united whole.","options":["text","essay","sentence","paragraph"],"correctOption":1,"section":"Writing Skills I: The Paragraph","explanation":"An essay is a combination of ideas from one paragraph to another that creates a united whole, because all the paragraphs support each other (B). A paragraph (D) is the single unit being combined, not the combination itself, a sentence (C) is smaller still, and a text (A) is too general."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 254, $official_bank_source${"itemId":"5876a9fb-383b-58e8-bfcd-43a209691dba","questionId":"38b1b7a0-2009-5390-a944-0ac39cf779aa","sourceKey":"bank:GST111:G111N1-113","payload":{"prompt":"To develop a paragraph properly, a writer should normally write at least","options":["two sentences","ten sentences","one sentence","three sentences"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"A paragraph should have at least three sentences; single-sentence paragraphs are rare. Two sentences is too few, since paragraphs of only two or three sentences risk inadequate development."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 255, $official_bank_source${"itemId":"d8533f28-a2cd-5331-8d18-7a6ce6030667","questionId":"00a24aac-d9f8-57a3-a674-3b1db8cb0b46","sourceKey":"bank:GST111:G111N1-114","payload":{"prompt":"A paragraph that uses expressions such as 'can be divided into', 'falls under' and 'belongs to' is a","options":["sequence paragraph","definition paragraph","classification paragraph","descriptive paragraph"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"These expressions group things into categories, which is what a classification paragraph does. A definition paragraph instead explains key words with phrases such as 'is defined as'."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 256, $official_bank_source${"itemId":"4cb972ba-c2f7-5130-ac80-a72ebb426533","questionId":"4c2ac7a1-a298-53d3-a219-a194a23a9b3b","sourceKey":"bank:GST111:G111N1-115","payload":{"prompt":"A paragraph that uses words such as 'on the other hand', 'in contrast to' and 'differs from' is a","options":["explanation paragraph","classification paragraph","comparison and contrast paragraph","evaluation paragraph"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"These words show similarities and differences, the work of a comparison and contrast paragraph. A classification paragraph groups things into categories rather than setting them against each other."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 257, $official_bank_source${"itemId":"d4f615d0-2abb-526b-a3cd-8224a14c8c4a","questionId":"29f220a2-cad4-5775-8ff0-b396af893b1c","sourceKey":"bank:GST111:G111N1-117","payload":{"prompt":"A paragraph that judges people, ideas or actions against criteria and uses words such as 'suggest', 'recommend' and 'advise' is a/an","options":["explanation paragraph","evaluation paragraph","descriptive paragraph","choice paragraph"],"correctOption":1,"section":"Writing Skills I: The Paragraph","explanation":"An evaluation paragraph judges against criteria (good or bad, correct or incorrect) and makes recommendations. A choice paragraph only states a personal preference without judging against criteria."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 258, $official_bank_source${"itemId":"df5a68e3-46b9-5dd6-9736-1f3c2e80a737","questionId":"9b7e7158-939e-520f-8da3-abd4effe4788","sourceKey":"bank:GST111:G111N1-118","payload":{"prompt":"A paragraph in an economics essay begins: 'Inflation is defined as a sustained rise in the general price level.' What type of paragraph is it most likely to be?","options":["Classification","Description","Evaluation","Definition"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"The helper phrase 'is defined as' marks a definition paragraph, which explains key words. A classification paragraph would use phrases such as 'can be divided into' to group things."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 259, $official_bank_source${"itemId":"51767f7f-4212-54e3-9b81-979985026053","questionId":"c12565ec-724b-5140-b9d7-d04e2de4248e","sourceKey":"bank:GST111:G111N1-119","payload":{"prompt":"A paragraph that uses words of measurement, location, size, colour and shape, and phrases like 'resembles', is a","options":["comparison and contrast paragraph","classification paragraph","definition paragraph","descriptive paragraph"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"Words of size, colour, shape and location, and 'resembles', describe a person, place or thing, which makes a descriptive paragraph. A comparison and contrast paragraph focuses on similarities and differences between two things."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 260, $official_bank_source${"itemId":"035d5c28-02f1-5ad2-92ac-97e4be08a117","questionId":"9a1a57bc-7716-5db7-9dc0-d345308c2a2b","sourceKey":"bank:GST111:G111N1-120","payload":{"prompt":"How many types of paragraph are identified, from definition to evaluation?","options":["6","11","5","8"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"Eight types are identified: definition, classification, descriptive, comparison and contrast, sequence, choice, explanation and evaluation. The figure 11 is the number of methods of paragraph development, a different list."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 261, $official_bank_source${"itemId":"74362142-57ad-5dfd-9a16-2c9089d2f2ca","questionId":"03632b8b-7182-5d95-b02e-570e65076b9d","sourceKey":"bank:GST111:G111N1-121","payload":{"prompt":"A topic sentence is best placed at the END of a paragraph when","options":["the main idea is obvious","the paragraph is very short","the paragraph introduces the essay","specific details lead up to a generalisation"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"When the paragraph builds from specific details towards a general point, the topic sentence goes at the end. When the main idea is obvious, the topic sentence can be left out altogether rather than moved."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 262, $official_bank_source${"itemId":"2a9aaec3-8383-503a-a7ee-dc9fc680a41c","questionId":"82c11d71-5dc6-541d-91ae-0cd38709cac2","sourceKey":"bank:GST111:G111N1-122","payload":{"prompt":"When may a writer leave out the topic sentence of a paragraph?","options":["When the main idea is obvious","When the writer is unsure of the main idea","When the paragraph has many examples","When the paragraph is the conclusion"],"correctOption":0,"section":"Writing Skills I: The Paragraph","explanation":"A topic sentence can be left out when the main idea is already obvious to the reader. Being unsure of the main idea is a reason to fix the paragraph, not to drop the topic sentence."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 263, $official_bank_source${"itemId":"6376009d-b9e7-5164-995e-9e640f17429e","questionId":"e271d0fc-e69d-5fd9-90fb-8f5478d4c59f","sourceKey":"bank:GST111:G111N1-123","payload":{"prompt":"In a concise and emphatic topic sentence such as 'The Nigerian banking system has collapsed', the key word is placed","options":["at the beginning","in the middle","at the end","in a separate sentence"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"A good topic sentence is concise and emphatic, with the key word placed at the end, as 'collapsed' is in the example. Placing it at the beginning loses the emphasis that the final position gives."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 264, $official_bank_source${"itemId":"c3fca061-3763-58d0-8651-fbd8bbe318d6","questionId":"8d7b0665-05fa-537c-b2e4-0c61fc2b247d","sourceKey":"bank:GST111:G111N1-124","payload":{"prompt":"In the structure of a paragraph, the concluding sentence is","options":["essential, and simply repeats the topic sentence","a summary only, with no link to what follows","optional, and leads to the next step","always the first sentence of the paragraph"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"The concluding sentence is optional and is more than a summary, because it leads to the next step. It usually comes last or second-to-last, never first."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 265, $official_bank_source${"itemId":"faa18a32-8932-51e9-9aae-e480951030e4","questionId":"4e0300e2-aae4-58ae-b7be-2e293916adc0","sourceKey":"bank:GST111:G111N1-125","payload":{"prompt":"A body paragraph that is full of evidence but has very little analysis is weak because","options":["it is too short","it lacks a topic sentence","it has no argument","its claim is unsupported"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"Evidence without analysis leaves the paragraph with no argument. An unsupported claim is the opposite problem, which happens when there is plenty of analysis but too little evidence."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 266, $official_bank_source${"itemId":"4e02c83a-5ee8-5353-8c71-db58bedf081b","questionId":"80bfe887-5e06-5843-9dec-81b9b411c225","sourceKey":"bank:GST111:G111N1-126","payload":{"prompt":"Very short paragraphs in an essay often suggest","options":["strong unity","a lack of substance","poor structure","too many controlling ideas"],"correctOption":1,"section":"Writing Skills I: The Paragraph","explanation":"Very short paragraphs suggest a lack of substance. Poor structure is what very long paragraphs tend to suggest, so it is the tempting but wrong choice here."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 267, $official_bank_source${"itemId":"ac04075d-0463-5a16-8ca8-daeb1a951ecd","questionId":"ac258c1b-41d6-55a0-9ad2-1c68ab05465d","sourceKey":"bank:GST111:G111N1-127","payload":{"prompt":"In the five-step process of paragraph development, what comes right after explaining the controlling idea?","options":["Explaining the example or examples","Deciding on a controlling idea","Giving an example or examples","Completing the idea or moving to the next paragraph"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"The steps are: decide on a controlling idea, explain it, give an example, explain the example, then complete the paragraph or transition. Explaining the example is step 4, so it comes after the example has been given."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 268, $official_bank_source${"itemId":"d876124d-916f-5d57-972e-881cfc22fb95","questionId":"10eaaa03-ed81-5d63-8380-8688c82fe8e2","sourceKey":"bank:GST111:G111N1-128","payload":{"prompt":"In the five-step process of paragraph development, which steps may be repeated?","options":["Explaining examples and completing the paragraph (steps 4 and 5)","Giving examples and explaining them (steps 3 and 4)","Explaining the controlling idea and giving examples (steps 2 and 3)","Deciding on and explaining the controlling idea (steps 1 and 2)"],"correctOption":1,"section":"Writing Skills I: The Paragraph","explanation":"Steps 3 and 4, giving an example and explaining it, can be repeated to develop the paragraph further. The controlling idea in steps 1 and 2 is set only once, since a paragraph should have a single focus."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 269, $official_bank_source${"itemId":"720acf10-8087-530c-b8ab-911112f00839","questionId":"8bd70349-1dca-507a-b537-3fc75977cb5a","sourceKey":"bank:GST111:G111N1-129","payload":{"prompt":"A paragraph that contains multiple controlling ideas should be fixed by","options":["adding more examples","removing sentences or splitting the paragraph","replacing keywords with pronouns","adding a concluding sentence"],"correctOption":1,"section":"Writing Skills I: The Paragraph","explanation":"Multiple controlling ideas break unity, so the remedy is to remove the off-focus sentences or split the paragraph. Adding more examples would only make the paragraph longer without fixing its divided focus."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 270, $official_bank_source${"itemId":"1cba4a20-1747-53fb-82d9-e9941d39ec0c","questionId":"c5f0c7b3-6e8c-5afc-9653-a4a824bd0078","sourceKey":"bank:GST111:G111N1-130","payload":{"prompt":"Which of the following is NOT one of the four elements of an effective paragraph?","options":["Considerable length","Coherence","Adequate development","Unity of focus"],"correctOption":0,"section":"Writing Skills I: The Paragraph","explanation":"The four elements are unity, coherence, a topic sentence and adequate development. Length is not one of them; in fact paragraphs are hardly ever longer than one double-spaced page."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 271, $official_bank_source${"itemId":"2e0cf895-8c4f-5b8d-a010-40d553770ccb","questionId":"74c8940e-0101-547e-b707-908d87967da3","sourceKey":"bank:GST111:G111N1-131","payload":{"prompt":"Repeating keywords, using synonyms and using pronouns that refer back to nouns build coherence through","options":["topic sentences","signposts","verbal bridges","logical bridges"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"Verbal bridges are word-level links: repeated keywords, synonyms, pronouns and transition words. Logical bridges work at the level of ideas, carrying the same idea from sentence to sentence or using parallel forms."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 272, $official_bank_source${"itemId":"246f2fd0-9334-5aa9-9a75-325a16c2e18f","questionId":"7746a67b-f9d2-5720-a5d3-d84210fd5732","sourceKey":"bank:GST111:G111N1-132","payload":{"prompt":"Carrying the same idea from sentence to sentence and using parallel sentence forms build coherence through","options":["signposts","verbal bridges","logical bridges","transitions"],"correctOption":2,"section":"Writing Skills I: The Paragraph","explanation":"Logical bridges carry the same idea through the paragraph and use parallel sentence forms. Verbal bridges are word-based links such as repeated keywords and synonyms."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 273, $official_bank_source${"itemId":"cf2634b5-821d-5798-8df9-b25ed74323b2","questionId":"41ea2f82-94ed-5af8-9ec0-9d58232a05a7","sourceKey":"bank:GST111:G111N1-133","payload":{"prompt":"Which of the following is NOT a method of paragraph development?","options":["Punctuation","Anecdote","Testimony","Chronology"],"correctOption":0,"section":"Writing Skills I: The Paragraph","explanation":"Anecdote, testimony and chronology are among the eleven methods of developing a paragraph. Punctuation is a writing convention, not a way of developing an idea."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 274, $official_bank_source${"itemId":"6db37022-b9e7-5190-9fc6-a043b9cbce14","questionId":"e5c7992b-61f2-5d50-95f2-837dbbfe3ac0","sourceKey":"bank:GST111:G111N1-134","payload":{"prompt":"Internal aids, usually several sentences or a whole paragraph, that outline what has been covered and where the text is going are called","options":["signposts","transitions","topic sentences","concluding sentences"],"correctOption":0,"section":"Writing Skills I: The Paragraph","explanation":"Signposts tell the reader what has been covered and what comes next. Transitions are shorter links, one or more sentences, that move from one idea to the next."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 275, $official_bank_source${"itemId":"58986b08-22f9-5b87-9b6f-bda5d2c06f7b","questionId":"711129bd-5971-53ef-b07a-e75fc614dc93","sourceKey":"bank:GST111:G111N1-135","payload":{"prompt":"One or more sentences that move from one idea to the next, often at the end of a paragraph, are called","options":["thesis statements","topic sentences","signposts","transitions"],"correctOption":3,"section":"Writing Skills I: The Paragraph","explanation":"Transitions move the reader from one idea to the next and often sit at the end of a paragraph. Signposts are larger aids that outline what has been covered and where the text is going."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 276, $official_bank_source${"itemId":"b1fdaba2-d83f-536e-91e2-988ec6af85ba","questionId":"bb41af41-1923-5d99-b3a7-1a0134ba8bda","sourceKey":"bank:GST111:GST111-0016","payload":{"prompt":"A full essay must have 3 main features","options":["Appropriate choice of words & acceptable sentences","Good paragraphing & grammatical sentences","Coherence & use of standard writing conventions","All of the above"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Option D, all of the above, is correct because each of A, B and C names a real feature of a full essay: appropriate word choice and acceptable sentences, good paragraphing and grammatical sentences, and coherence with standard writing conventions. Choosing just one of A, B or C would leave out features that are equally required in a complete essay."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 277, $official_bank_source${"itemId":"91017d53-54ab-572b-aecc-f68e689df5c8","questionId":"e7154695-51c2-5008-8df3-34624bd44a92","sourceKey":"bank:GST111:GST111-0017","payload":{"prompt":"Major features of any good writing include;","options":["Introduction, summary, conclusion","Introduction, middle, conclusion","Preamble, definition, main body","None of the above"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Any good piece of writing, like a good lecture or essay, moves from an introduction through a middle (the main body) to a conclusion, so B is correct. Option A wrongly puts the summary in the middle, and C leaves out the conclusion, so neither gives the standard three-part structure."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 278, $official_bank_source${"itemId":"42cf024b-0cde-5ebb-87e1-b2be988ceb9a","questionId":"2bd6ce83-8b43-5b3e-a6e8-5581b199cb4e","sourceKey":"bank:GST111:GST111-0018","payload":{"prompt":"In report writing, the situation must be based on","options":["Hearsay","Arguments","Proof","Facts"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A report presents a situation to readers who may have to act on it, so it must be based on facts, which is option D. Hearsay (A) is unverified talk and has no place in a report, and arguments (B) belong to persuasive writing. Proof (C) is close, but proof is what you use to support a claim; the report itself rests on the facts of the situation observed."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 279, $official_bank_source${"itemId":"803fa14a-990e-533c-9e7b-6c87b43a0d21","questionId":"025a6d9d-9832-5f6e-8b58-9851b4ab6a90","sourceKey":"bank:GST111:GST111-0019","payload":{"prompt":"The narrative essay has all but one of the following feature","options":["Suspense","Story line","Plot","Strong argument"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A strong argument (option D) is the feature a narrative essay does not need. A narrative essay is a sequential or chronological account of an experience or incident, marked by suspense and other devices so the reader feels a good story has been told. Suspense (A), story line (B) and plot (C) are all narrative features, while a strong argument belongs to the argumentative or persuasive essay."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 280, $official_bank_source${"itemId":"f25b77bc-782c-5b2c-8bd6-7b25258dffc5","questionId":"5773ded7-37dd-5298-b992-f5ad00390844","sourceKey":"bank:GST111:GST111-0020","payload":{"prompt":"A thesis statement is to an essay what a topic sentence is to;","options":["An introductory paragraph","A concluding paragraph","The paragraph","The main paragraph"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A topic sentence states the main idea of its paragraph, just as a thesis statement states the central idea of the whole essay, so the parallel is with the paragraph, option C. The topic sentence works as the thesis of the paragraph. Options A, B and D are wrong because every paragraph has a topic sentence that controls it, not just the introductory, concluding or main one."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 281, $official_bank_source${"itemId":"476502f4-dcf3-5bbb-8343-9be3b71ccd28","questionId":"44a91626-bf28-5d44-8b0c-6e1bad2ec693","sourceKey":"bank:GST111:GST111-0021","payload":{"prompt":"A police statement is an example of;","options":["An academic writing","Technical report writing","A narrative writing","A research report"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A police statement recounts what happened step by step, in the order events occurred, so it is narrative writing, option C. Narrative writing is a sequential or chronological account of an experience, procedure or incident, and it is largely reportorial in nature. It is not academic writing (A) or a research report (D), and although it reports facts, it is not a technical report (B) because it does not deal with specialized technical procedures."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 282, $official_bank_source${"itemId":"9cdb1227-8f36-5a91-8786-e603b405ad65","questionId":"254071b5-a295-5ac4-af9e-edb19ce3830e","sourceKey":"bank:GST111:GST111-0022","payload":{"prompt":"The main features of an introductory paragraph are;","options":["Statement of thesis, setting of tone, plan","Quotation, topic sentence, summary of essay","Summary, statement of thesis, definition","None of the above"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"An introductory paragraph states the thesis, sets the tone and gives the reader a plan of what will follow, so A is correct. A good introduction also arouses the reader's interest and keeps attention on the central theme. Options B and C include a summary of the essay, which belongs in the conclusion, not the introduction."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 283, $official_bank_source${"itemId":"ab94732f-c8f7-5fc4-898c-275d2b7fff93","questionId":"290f7534-b103-5636-a756-eb04c1f86c8f","sourceKey":"bank:GST111:GST111-0023","payload":{"prompt":"Mechanics of writing consists of;","options":["Punctuation","Capitalization","Spelling & letter shapes","All of the above"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Mechanics of writing means the symbols and conventions that organize writing on the page rather than the words themselves, and that covers punctuation, capitalization, and spelling and letter shapes. Since A, B and C are each part of mechanics, D, all of the above, is correct. Choosing only one would leave out other parts of mechanics."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 284, $official_bank_source${"itemId":"af4c46e5-8623-5332-994f-5e6bab37f8b6","questionId":"015b24e5-7738-54aa-9155-3dc2a860017c","sourceKey":"bank:GST111:GST111-0050","payload":{"prompt":"One of these is a punctuation mark used in dialogue after a speakers name","options":["Full stop","Semi-colon","University","Colon"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"In written dialogue, a colon follows the speaker's name to introduce the words spoken, as in Okon said: I am hungry, so D is correct. A full stop (A) would end the sentence before the speech begins, a semi-colon (B) joins related clauses, and option C, University, is not a punctuation mark at all."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 285, $official_bank_source${"itemId":"fc7a93c1-76bb-5dac-a6d2-feea039e72e4","questionId":"6d28911f-76fc-5247-8947-a40779138adc","sourceKey":"bank:GST111:GST111-0052","payload":{"prompt":"The ____ is used to mark off initials","options":["Semi-colon","Full stop","Bracket","Dash"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The full stop, option B, marks off initials and abbreviations, as in E. A. Adedun, Mr., Prof. or Ph.D. A semi-colon (A) joins clauses, a bracket (C) encloses extra material and a dash (D) sets off interrupting material, so none of them is used for initials."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 286, $official_bank_source${"itemId":"ec0c309b-8f8c-5d6a-9944-174011ddb045","questionId":"096f4418-eeb4-5dff-99ec-efecfd3557eb","sourceKey":"bank:GST111:GST111-0053","payload":{"prompt":"One of the following punctuation marks is used in pairs","options":["Question mark","Hyphen","Aprostrophe","Quotation"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Quotation marks, option D, always come in pairs: one to open the quoted words and one to close them, enclosing someone's exact words. A question mark (A), hyphen (B) and apostrophe (C) are each used singly, so they do not fit the description."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 287, $official_bank_source${"itemId":"6b40ee61-b746-584b-bb45-e82612521493","questionId":"23158dc5-44ef-5e1a-8c38-9b56105cd60a","sourceKey":"bank:GST111:GST111-0054","payload":{"prompt":"Brackets are used to enclose","options":["A reference","Main ideas","Book titles","A & B"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Brackets enclose material that is additional to the main statement, and a typical example in academic writing is a reference, such as the author and year placed in brackets after a quotation, so A is correct. Main ideas (B) are never bracketed because they must stand out, and book titles (C) are shown in italics or underlined, which also makes D wrong."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 288, $official_bank_source${"itemId":"a1100b43-2065-57a7-9fb7-bb78e648752c","questionId":"9d7ed97b-7123-5719-a1d1-56d96422efa9","sourceKey":"bank:GST111:GST111-0056","payload":{"prompt":"Exclamation marks are used for","options":["Listings","Interjections","Confessions","Music"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The exclamation mark is used at the end of a structure expressing surprise, horror, excitement or any strong feeling, and it punctuates interjections such as ouch, hey and oh, so B is correct. Listings (A) are introduced by a colon, and confessions (C) and music (D) have no special link to the exclamation mark."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 289, $official_bank_source${"itemId":"48e008e2-c632-5b2b-8763-1488554502ba","questionId":"69c7f757-cd31-5978-baa5-dff682a87b32","sourceKey":"bank:GST111:GST111-0058","payload":{"prompt":"One of the following is used to introduce additional information","options":["Full stop","Apostrophe","Dash","Hyphen"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The dash, option C, introduces or sets off additional information that interrupts the main statement, as in All managers - I mean most managers - look forward to vacations. A full stop (A) ends a sentence, an apostrophe (B) shows possession or omission, and a hyphen (D) joins parts of words, so none of these introduces extra information."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 290, $official_bank_source${"itemId":"8af1a477-e15e-5162-86cc-c28ae7ed47fc","questionId":"f0fa55f1-acf5-5baf-9d7c-cf21f83f7fe1","sourceKey":"bank:GST111:GST111-0059","payload":{"prompt":"Capitalization is necessary in all but one of the following","options":["Sentence initial position","Names of common nouns","Isolated 'I'","Names of deities and sacred contexts"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Capital letters are needed at the start of a sentence, for the pronoun I, and for proper nouns, including names of deities and sacred contexts. Common nouns (option B) such as table or city are written in lower case unless they begin a sentence, so B is the one case where capitalization is not necessary."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 291, $official_bank_source${"itemId":"293258b2-6c4f-5ea2-8e6b-8eedb28c8eca","questionId":"b61764cf-f277-5cf5-814a-9c2752cd5493","sourceKey":"bank:GST111:GST111-0061","payload":{"prompt":"Which of the following is used to indicate possession in English?","options":["Inverted commas","Hyphen","Apostrophe","Quotation marks"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The apostrophe, option C, shows possession in English, as in Ade's salary or Moses' allowance. Inverted commas (A) and quotation marks (D) are the same thing and enclose quoted speech, while a hyphen (B) joins parts of compound words."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 292, $official_bank_source${"itemId":"48ed5fa2-2fce-594a-8c33-dd80b21a205b","questionId":"cd3bd65e-60ee-53f9-ab6a-906af504e0b7","sourceKey":"bank:GST111:GST111-0085","payload":{"prompt":"The punctuation mark used for interrogative sentence is ____","options":["Exclamation","Period","Question mark","Colon"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"An interrogative sentence asks a question, and a direct question ends with a question mark, so C is correct. The exclamation mark (A) marks strong feeling, the period or full stop (B) ends a statement or command, and the colon (D) introduces a list or quotation."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 293, $official_bank_source${"itemId":"8ae6b65b-3c83-5d2e-a226-39b08f5b5f4c","questionId":"7d911c0d-2404-5a4a-9568-b23c994a0bcf","sourceKey":"bank:GST111:GST111-0086","payload":{"prompt":"Another name for the period is ___","options":["Semi-colon","Hyphen","Full-stop","Exclamation"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Period is simply the American name for the full stop, so C is correct; it ends declarative and imperative sentences. The semi-colon (A), hyphen (B) and exclamation mark (D) are different marks with different uses, so they are not other names for the period."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 294, $official_bank_source${"itemId":"2ae39dbb-982c-5980-8d16-1c1fddd4df5c","questionId":"de61d780-b65a-5079-a936-c4787c9d36a3","sourceKey":"bank:GST111:GST111-0087","payload":{"prompt":"Brainstorming is one of the fundamentals of ____","options":["Writing a good essay","Passing an examination","Writing a good sentence","Paragraph improvement"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Brainstorming means freely generating and jotting down ideas on a topic before organizing them, and it is a fundamental first step in writing a good essay, so A is correct. It belongs to the planning stage, when the writer gathers material and decides on a central idea. It is not a way of passing examinations in general (B), and it works on ideas for a whole piece rather than a single sentence (C) or improving an already written paragraph (D)."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 295, $official_bank_source${"itemId":"f9890843-1cbb-5220-9c30-502c0ec68da3","questionId":"9f823642-a4f0-5aff-8959-5c659775cc4d","sourceKey":"bank:GST111:GST111-0088","payload":{"prompt":"To ensure that the different paragraphs of an essay are properly related, you must use","options":["Lexical equivalence","Introductory remarks","Linking expressions","Descriptive expressions"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"To make the paragraphs of an essay flow into one another, you use linking expressions, option C, such as first, second, finally, furthermore, in addition and however. They show continuity with the idea already expressed. Lexical equivalence (A) and descriptive expressions (D) are not connecting devices, and introductory remarks (B) only open the essay rather than tie paragraphs together."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 296, $official_bank_source${"itemId":"e7a153b0-ff48-5c67-a649-ffd9513d2af0","questionId":"081e2d8d-f2a0-5f23-b27b-8bdc3a4759f6","sourceKey":"bank:GST111:GST111-0089","payload":{"prompt":"To mark off two or more independent clauses in a sentence, you should use a ___","options":["Paired commas","Semi-colon","Emphasis","Parenthesis"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A semi-colon, option B, marks off two or more independent clauses in one sentence, replacing a comma plus a coordinating conjunction, as in Supply us with three cars; they must all be black. Paired commas (A) and parentheses (D) enclose extra material inside a sentence rather than separating clauses, and emphasis (C) is not a punctuation mark."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 297, $official_bank_source${"itemId":"249e1ab0-dee4-5878-bd6e-284ec277277f","questionId":"750b67b7-c43b-58cc-8ffb-7d9780b57b86","sourceKey":"bank:GST111:GST111-0090","payload":{"prompt":"Which of the following is not a common essay type","options":["Descriptive","Narrative","Expository and argumentative","Proposal"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Essays are commonly classed as narrative, expository (analytical), argumentative (persuasive) or descriptive, so A, B and C are all common essay types. A proposal (option D) is a business or research document that puts forward a plan, not a type of essay, so it is the answer to this 'is not' question."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 298, $official_bank_source${"itemId":"7ec937d3-ba57-5dc4-a4e1-423ecf0f9f76","questionId":"0d26515b-0aae-5fc1-8e86-edcf5fdd1676","sourceKey":"bank:GST111:GST111-0091","payload":{"prompt":"A faithful account of an activity in which the writer participated can be labeled","options":["Report","Memo","Prolegomena","Episode"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A faithful, factual account of an activity in which the writer took part is a report, option A, because a report records what actually happened for others to read and act on. A memo (B) is a short internal message, prolegomena (C) means a preliminary introduction to a book, and an episode (D) is a single event in a story rather than an account of one."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 299, $official_bank_source${"itemId":"7834439c-b38f-5632-b13b-693b6cc63a29","questionId":"11a616cb-b755-5176-abb7-7393de2e9eb6","sourceKey":"bank:GST111:GST111-0092","payload":{"prompt":"A high degree of objectivity is normally expected in","options":["Scientific writing","Informal writing","Formal writing","Doctor-patient writing"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Scientific writing, option A, demands the highest degree of objectivity because it reports observations, data and results that must be verifiable whatever the writer feels. Informal writing (B) is personal by nature, and formal writing (C) is a broad category that includes opinion pieces, so formality alone does not guarantee objectivity. Doctor-patient writing (D) is not a recognized category of writing."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 300, $official_bank_source${"itemId":"73ccd220-1158-5a5f-9f55-a42ebf70e736","questionId":"33a4bb48-4703-573a-983b-d09a77182bf3","sourceKey":"bank:GST111:GST111-0093","payload":{"prompt":"Technical writing may not include","options":["Car manual","Love poems","Police reports","Law reports"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Technical writing deals with factual, practical or specialized information in fields such as engineering, law and public administration, so a car manual (A), police reports (C) and law reports (D) are all technical documents. Love poems (option B) are imaginative and emotional, the opposite of technical writing, so B is what technical writing may not include."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 301, $official_bank_source${"itemId":"e708e40e-f092-5256-bb7b-1d08cf840fee","questionId":"99994e45-2f07-5483-a60f-3f60db8c978f","sourceKey":"bank:GST111:GST111-0097","payload":{"prompt":"Which of the following is not one of the main divisions of the writing process","options":["Writing stage","Proof-reading stage","Publishing stage","Pre-writing stage"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The writing process is usually divided into a pre-writing stage (planning and gathering ideas), a writing stage (drafting) and a proof-reading stage (checking and correcting), so A, B and D are genuine divisions. Publishing (option C) is what may happen to a finished piece afterwards, not a stage of writing it, so C is the one that does not belong."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 302, $official_bank_source${"itemId":"41feabc7-d9ba-5df4-93ec-bd29eafb1be9","questionId":"6169b1c1-5372-55b6-9cc2-ecf624ac4f20","sourceKey":"bank:GST111:GST111-0098","payload":{"prompt":"In technical writing, the acronym SME means","options":["Some subject example","Some managerial expertise","Subject matter expert","Simple marketing expert"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"In technical writing, SME stands for Subject Matter Expert, option C: the specialist whose knowledge the writer draws on to make sure the content is accurate. Options A, B and D are made-up expansions that do not correspond to any recognized term in technical communication."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 303, $official_bank_source${"itemId":"f7bc8bc7-cf28-56d5-a770-ed8c23f60410","questionId":"46579df3-6660-5025-946d-689a459bd5f7","sourceKey":"bank:GST111:GST111-0099","payload":{"prompt":"Which of the following would you write under subscription in a letter","options":["Addressee designation","Yours faithfully","Salutation","Body of the letter"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The subscription of a letter is the closing formula written just before the signature, such as Yours faithfully or Yours sincerely, so B is correct. The addressee's designation (A) belongs in the inside address at the top, the salutation (C) is the opening greeting such as Dear Sir, and the body (D) is the main message of the letter."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 304, $official_bank_source${"itemId":"770e0eda-7545-5ce2-8fd1-5a31139d8d67","questionId":"7938c3e3-2511-5d38-88fa-e2da24345af8","sourceKey":"bank:GST111:GST111-0100","payload":{"prompt":"One of the following will provide information to influence our decisions and actions","options":["Reports","Memorandum","Agenda","Anecdotes"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Reports, option A, are written to supply the information decision makers need in order to decide and act, for example a committee report recommending a course of action. A memorandum (B) mainly passes on brief internal messages, an agenda (C) only lists the items for a meeting, and anecdotes (D) are short entertaining stories, not a reliable basis for decisions."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 305, $official_bank_source${"itemId":"83fc43c6-3614-5af6-90b1-c422d7bc250a","questionId":"c7807703-04fa-5207-9c67-743778409035","sourceKey":"bank:GST111:GST111-0102","payload":{"prompt":"The goal of an argumentative essay is to ..............","options":["persuade the audience","convince the readers","sell an idea","all of the above"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"An argumentative or persuasive essay tries to get readers to accept a point of view: it sells an idea, convinces readers and persuades the audience. Since all three of the listed goals are correct, all of the above is the right answer. Choosing just one of them would give only part of what an argumentative essay sets out to do."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 306, $official_bank_source${"itemId":"b8658fcb-c5ae-5bae-8dfa-6f7473445d7e","questionId":"3027972c-ff52-508f-90f9-0502c3338c88","sourceKey":"bank:GST111:GST111-0110","payload":{"prompt":"\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_is used to introduce a list","options":["colon","full stop","semi colon","comma"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The colon, option A, introduces a list, especially after words like the following or namely, as in Please purchase the following items: a suitcase, a pair of shoes and a bottle of perfume. A full stop (B) ends a sentence, a semi-colon (C) joins related clauses or separates items that already contain commas, and a comma (D) separates the items within the list rather than introducing it."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 307, $official_bank_source${"itemId":"214490ba-ef62-5144-8039-ba0010982dfb","questionId":"70227acd-96b7-5ae6-b44f-41af5496b684","sourceKey":"bank:GST111:GST111-0117","payload":{"prompt":"One of the following is not a type of essay:","options":["experimental","narrative","analytical","descriptive"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Essays are classed by content and purpose into narrative, analytical, persuasive and descriptive types, so narrative (B), analytical (C) and descriptive (D) are all genuine essay types. Experimental, option A, describes a method of scientific inquiry, not a type of essay, so it is the answer to this 'not' question."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 308, $official_bank_source${"itemId":"bb0e8ba9-65de-582d-ab2e-044c172c1ef8","questionId":"3d474ebf-d6e9-519e-8a23-2d3bc0e71351","sourceKey":"bank:GST111:GST111-0123","payload":{"prompt":"Which of the following is correct?","options":["the responsibility is their's","the reward is your's","the dog wagged it's tail","the dog wagged its tail"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Possessive pronouns never take an apostrophe, so the correct forms are theirs, yours and its. Option D, the dog wagged its tail, follows this rule. Options A and B wrongly add apostrophes to possessive pronouns, and option C uses it's, which is a contraction of it is, not the possessive."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 309, $official_bank_source${"itemId":"4da0dcab-12ea-5da8-9198-9735d58e1cc3","questionId":"df0e64e8-4615-5815-86f2-0057a99e739c","sourceKey":"bank:GST111:GST111-0132","payload":{"prompt":"The \"period\" is also written as \\_\\_\\_\\_\\_\\_\\_\\_\\_ in punctuation","options":["colon","quotation mark","full stop","comma"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The mark used at the end of a complete declarative or imperative sentence is called the full stop or period; the two names refer to the same symbol, so C is correct. A colon (A) introduces lists, quotation marks (B) enclose direct speech, and a comma (D) separates items within a sentence, so none of them is another name for the period."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 310, $official_bank_source${"itemId":"560875e9-b67b-57e9-ac13-41152c442a5a","questionId":"61e65902-d48a-5914-b9c2-99d32ee5cbd5","sourceKey":"bank:GST111:GST111-0135","payload":{"prompt":"A .............. essay gives a detailed and often dispassionate account of people, incidents, scenes and situations in a vivid manner.","options":["narrative","analytical","persuasive","descriptive"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A descriptive essay gives a detailed and often dispassionate account of people, incidents, scenes and situations so the reader can picture them as if present, so D is correct. A narrative essay (A) tells events in sequence, an analytical essay (B) explains or evaluates, and a persuasive essay (C) argues for a point of view."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 311, $official_bank_source${"itemId":"43a64917-aade-5d17-b818-23806746eff5","questionId":"c8bc6e04-6492-5c61-aa05-8b53266e651c","sourceKey":"bank:GST111:GST111-0141","payload":{"prompt":"The terminal punctuation includes all except one","options":["comma","full stop","exclamation mark","question mark"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The full stop, question mark and exclamation mark are terminal punctuation marks because they signal the end of a sentence. The comma separates words, phrases and clauses inside a sentence and never ends one, so A is the odd one out. Options B, C and D are all terminal marks."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 312, $official_bank_source${"itemId":"de415bc3-ec8d-5c12-abdc-3077c92269b4","questionId":"ff16d144-b6f9-580c-84ce-59545a180e46","sourceKey":"bank:GST111:GST111-0147","payload":{"prompt":"The main function of \\_\\_\\_\\_\\_\\_\\_\\_ is to separate independent clause","options":["exclamation mark","colon","semi colon","comma"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The semicolon is used to separate two independent clauses that could each stand alone, replacing a comma plus a coordinating conjunction, as in Supply us with three cars; they must all be black. So C is correct. A comma (D) is tempting, but a comma alone between independent clauses creates the error called a comma splice. A colon (B) introduces lists and an exclamation mark (A) ends excited statements."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 313, $official_bank_source${"itemId":"090c05f4-71a9-5e43-a828-8c617abb058b","questionId":"65a609cb-794a-5668-a3f8-04888b9082fa","sourceKey":"bank:GST111:GST111-0149","payload":{"prompt":"................. is referred to as the meat of the essay.","options":["Content","Expression","Mechanics","Organization"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Content is the depth of treatment of the subject matter, and the knowledge and authority brought to the discussion, and it is described in everyday terms as the meat of the essay. So A is correct. Expression (B) is about choice of words, mechanics (C) is about punctuation and similar conventions, and organization (D) is the ordering of material; none of them is the substance itself."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 314, $official_bank_source${"itemId":"a2e3a0bd-0719-553c-9c62-cc0e9848e311","questionId":"3e861ccd-fed6-50e4-b5e8-ed7b96b784f5","sourceKey":"bank:GST111:GST111-0155","payload":{"prompt":"The ................. is the major point which an essay seeks to prove","options":["thesis","synopsis","subject matter","theme"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A good essay proves a major point, and that point is called the thesis, option A; it is the central idea and organizing principle that guides the choice of material. A theme (D) is the general subject area, subject matter (C) is what the essay is about rather than what it argues, and a synopsis (B) is a summary, for example of a plot."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 315, $official_bank_source${"itemId":"0604bacd-4b96-5758-ba73-138947252bc0","questionId":"d775384c-859c-5d68-9d23-30513e91cb0c","sourceKey":"bank:GST111:GST111-0156","payload":{"prompt":"Apostrophes are used \\_\\_\\_\\_\\_\\_\\_\\_","options":["for transitivity","for epithensis","for contractions","to form plurals"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Apostrophes are used for contractions, option C, to show that letters have been omitted, as in won't. They are also used to show possession, as in Ade's salary. Option D is wrong because apostrophes are never used simply to form plurals, and they are not used in possessive pronouns like theirs or its. Options A and B are not functions of any punctuation mark."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 316, $official_bank_source${"itemId":"1404de8a-4057-5eff-908a-3b7771b15309","questionId":"10a75c3f-a1a8-5b42-a74e-3f9d44a18e57","sourceKey":"bank:GST111:GST111-0170","payload":{"prompt":"Clear thinking, accurate data, reliable authority and clear conclusion are applicable to ........ essay.","options":["persuasive","narrative","descriptive","analytical"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"An analytical essay is built on clear thinking, accurate or verified data, reliable authority and clear conclusions drawn from the evidence, so D is correct. Option A (persuasive) leans on details plus appeals to emotion, B (narrative) tells a story in sequence, and C (descriptive) gives vivid accounts of scenes and people."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 317, $official_bank_source${"itemId":"f3d934c2-b9d4-51c2-bcd3-7ce63643e4fe","questionId":"fdcc416f-1e20-536f-8e6a-1a347b9d84d6","sourceKey":"bank:GST111:GST111-0171","payload":{"prompt":"In essay writing, the acronym COEM means ................","options":["Content, Organisation, Entertainment, Mechanics","Content, Organisation, Expression, Mechanics","Comment, Organisation, Expression, Mechanics","Content, Orientation, Expression, Mechanics"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"COEM stands for Content, Organisation, Expression and Mechanics, the four quality-control components of a good essay, so B is correct. The other options each swap one word for a wrong one: A uses Entertainment instead of Expression, C uses Comment instead of Content, and D uses Orientation instead of Organisation."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 318, $official_bank_source${"itemId":"05829610-7542-515c-b6fb-4ddec7da0baa","questionId":"9b0f4686-5fa8-5b6d-8c79-61b37a0a9bc4","sourceKey":"bank:GST111:GST111-0173","payload":{"prompt":"A question mark is not used at the end of ............","options":["a tag question","a direct question","an echo question","an indirect question"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A question mark is not used after an indirect (reported) question, because that kind of question is really a statement, as in The manager demanded to know why production was slow. So D is correct. A direct question (B), a tag question (A) such as She is here, isn't she? and an echo question (C) such as Bisi has travelled? all end with a question mark."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 319, $official_bank_source${"itemId":"81a45893-e877-539a-9cc3-ddfaa7dd5dfa","questionId":"60cbbecd-bfda-557a-869e-d324c5735a86","sourceKey":"bank:GST111:GST111-0174","payload":{"prompt":"............... is the informed evaluation of imaginative writing.","options":["criticism","coherence","blogging","essay writing"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Criticism is the analytical way of writing that gives an informed evaluation of imaginative writing, and critiques are one strategy of the analytical essay. Option B (coherence) is a quality of a good paragraph, C (blogging) is not an academic method, and D (essay writing) is too broad to be the specific word for judging literature."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 320, $official_bank_source${"itemId":"b9eb0587-7a58-5b71-b872-c855c85b328e","questionId":"69313825-86eb-5ba4-8bfc-caa5428a85b6","sourceKey":"bank:GST111:GST111-0179","payload":{"prompt":".............. is the punctuation mark used to express all forms of excitement.","options":["exclamation mark","question mark","semi-colon","colon"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The exclamation mark is used at the end of a structure expressing surprise, horror, disappointment, anger, indeed all forms of excitement, as in Look out! or Oh, boy! Option B (question mark) ends direct questions, C (semi-colon) joins closely related independent clauses, and D (colon) introduces lists."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 321, $official_bank_source${"itemId":"cbad0a46-f710-5b38-9961-4ac4d2e94a9b","questionId":"dc8b0540-8fde-57b4-95d1-0b72e43aad12","sourceKey":"bank:GST111:GST111-0204","payload":{"prompt":"To achieve depth in the treatment of a topic, the writer is advised to ......","options":["punctuate words appropriately","manage transition","limit/narrow the subject","expand the subject"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Depth of content depends on size: a large subject such as population growth cannot be treated exhaustively, so a writer must limit or narrow the subject at the start. Option D (expanding the subject) does the opposite and leads to skimming the surface. A and B (punctuation, transition) belong to mechanics and organisation, not depth of content."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 322, $official_bank_source${"itemId":"04fe36fe-29da-591f-9629-e83af09ff384","questionId":"646fe724-ed95-519c-9afa-bbb44601c1bd","sourceKey":"bank:GST111:GST111-0212","payload":{"prompt":"Identify the incorrectly capitalised sentence","options":["The Parthenon is a temple dedicated to the goddess Athena","The Jewish festival of Passover commemorates the Exodus from Egypt","a parsnip is a root vegetable native to Eurasia","Blaise Pascal is a French scientist and mystic"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Every sentence must begin with a capital letter, and option C starts with a lower-case a (a parsnip is a root vegetable native to Eurasia), so it is incorrectly capitalised. Options A, B and D all begin with capitals and correctly capitalise their proper nouns (Parthenon, Athena, Passover, Egypt, Blaise Pascal, French)."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 323, $official_bank_source${"itemId":"87d80267-7a91-54e9-a14f-876349fbb0f3","questionId":"46af9515-77f1-586f-860e-64cd059b46a3","sourceKey":"bank:GST111:GST111-0284","payload":{"prompt":"What punctuation mark is used to express surprise?","options":["semi colon","full stop","exclamation mark","question mark"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The exclamation mark is used at the end of a structure expressing surprise, horror, disappointment or any strong feeling. Option D (question mark) marks a direct question, B (full stop) ends an ordinary statement, and A (semi colon) separates clauses."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 324, $official_bank_source${"itemId":"888aca7b-d21a-5df4-a34f-78f40b77daa6","questionId":"53a188a0-08bb-5030-a584-ae2d919e8696","sourceKey":"bank:GST111:GST111-0298","payload":{"prompt":"Which of the following should not be capitalised?","options":["Gaelic","Chilean","Guesstimates","Guatemalan"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Gaelic, Chilean and Guatemalan are proper adjectives taken from the names of a language and nationalities, and proper nouns and their related forms take capital letters. Guesstimates is an ordinary common noun, so C should not be capitalised unless it begins a sentence."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 325, $official_bank_source${"itemId":"3482b32d-41c7-5665-ac9e-77828d7b94f9","questionId":"7408da0f-6b22-536a-ae1b-8d13d92304e0","sourceKey":"bank:GST111:GST111-0299","payload":{"prompt":"Identify the sentence that is incorrectly capitalised","options":["The nfl will repeat the best of the season this summer.","I'm going to be taking history next term.","Take a U-turn at that sign.","The PTA will fund our end-of-the-year party."],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Acronyms and initialisms such as UNICEF, FIFA and PTA are written in capital letters, so 'nfl' should be NFL, which makes A incorrectly capitalised. Option B is correct because ordinary school subjects such as history take a small letter, and C and D capitalise U-turn and PTA properly."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 326, $official_bank_source${"itemId":"594ac9f4-6753-560a-93e4-9deca64c1f05","questionId":"fd7e62fc-cd7a-54c4-b33f-e2bd3c6f51ab","sourceKey":"bank:GST111:GST111-0307","payload":{"prompt":"Parentheses are used to enclose\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_ within a sentence","options":["added words to a quote","spelling errors","additional or explanatory information","slang"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Parentheses mark off additional or explanatory information within a sentence, something the sentence still makes sense without. Option A describes square brackets, which enclose words someone else adds to a quotation. Spelling errors and slang (B and D) are not what parentheses are for."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 327, $official_bank_source${"itemId":"44c2cacd-1c9d-5e72-b482-0943889a827c","questionId":"7a93b03e-d6a9-599f-bee2-8c7b56aa7d44","sourceKey":"bank:GST111:GST111-0319","payload":{"prompt":".............. is used to separate phrases and clauses in a series within a sentence when those items already contain commas.","options":["semi-colon","comma","colon","hyphen"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"When items in a series already contain commas, the semicolon separates them so the reader can see where each item ends, as in a list of names and their job titles. Option B (comma) is tempting, but more commas would make such a list confusing. The colon (C) introduces a list rather than separating its items, and the hyphen (D) joins words."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 328, $official_bank_source${"itemId":"a7372d95-d22e-5762-9ad5-e4d0fff1d87c","questionId":"177b7224-8203-5000-b3f4-c26e86ad20cb","sourceKey":"bank:GST111:GST111-0330","payload":{"prompt":"The thesis statement is to an essay what the ............... is to a paragraph.","options":["supporting details","topic sentence","introduction","conclusion"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The topic sentence states the main idea of a paragraph and acts as the thesis of that paragraph, just as the thesis statement carries the central idea of a whole essay. Option A, supporting details, backs up the main idea rather than stating it. Introduction and conclusion (C and D) are parts of an essay, not the single controlling sentence of a paragraph."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 329, $official_bank_source${"itemId":"3565638f-1f97-58a0-8528-1f58e43c0944","questionId":"c718db12-c753-5706-af10-fe227a2e3148","sourceKey":"bank:GST111:GST111-0336","payload":{"prompt":"A good essay should contain .....................","options":["predominantly short paragraphs","a variation of long and short paragraphs","predominantly one-sentence paragraphs","predominantly long paragraphs"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A good essay mixes long and short paragraphs. Too many short paragraphs make the writing choppy, while too many long ones make it boring, so variety improves the flow of ideas (B). Options A, C and D each rely mainly on one length, which is the problem to avoid."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 330, $official_bank_source${"itemId":"ea2e4d07-4257-519a-8504-d7bc4353cc35","questionId":"34ccf606-b137-5646-8113-cfd38bcf2fd8","sourceKey":"bank:GST111:GST111-0344","payload":{"prompt":"One of the following is NOT necessary when writing an argument.","options":["the use of details","creation of a mental picture","none of the above","appeal to emotion"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Creating a mental picture is the aim of descriptive writing, which appeals to visual and sensory perception, so it is not needed in an argument (B). Argument or persuasive writing relies on the use of details and the appeal to emotion, which is why A and D are necessary and therefore not the answer."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 331, $official_bank_source${"itemId":"ebb375ca-288e-541c-be2c-68d93f559685","questionId":"92580dbe-d46e-5036-a3ea-eb6378c550af","sourceKey":"bank:GST111:GST111-0359","payload":{"prompt":"In interpreting the results of experiments, .............. is/are often explored.","options":["empirical methods","critique","rationalisation","all of the above"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"When interpreting the results of experiments, a combination of rationalisation, critique and empirical methods might be needed, so all three are explored and D is the complete answer. Options A, B and C each name only one of the three approaches."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 332, $official_bank_source${"itemId":"8bb9a0ca-b9af-5f52-b91c-dc90ffbe1124","questionId":"f14c5919-2cb7-5cb2-a727-e7b98e3fd07a","sourceKey":"bank:GST111:GST111-0366","payload":{"prompt":"Analytical essays focus on the following except .............","options":["providing a sequential or chronological account","assessment of the implication for human existence","examination of the issue","identification of an issue"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Giving a sequential or chronological account of events is the defining feature of a narrative essay, not an analytical one (A). An analytical essay identifies an issue, examines it in detail and assesses its implications for human existence, which is why B, C and D all belong to analysis."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 333, $official_bank_source${"itemId":"2ccaae01-8e73-5196-b41f-dae5d4bc4365","questionId":"39de6457-2496-59be-b2f7-a149b5a7ee5f","sourceKey":"bank:GST111:GST111-0367","payload":{"prompt":"One of the following is not a linking device:","options":["furthermore","however","finally","Because"],"correctOption":3,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Because is a subordinating conjunction that joins a dependent clause to a main clause inside one sentence, so it is not a linking device in the sense of connecting paragraphs (D). Furthermore, however and finally (A, B and C) are linking devices that show how one idea continues from the one before."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 334, $official_bank_source${"itemId":"db1efbd5-a1af-5d58-869e-ee57c7af99c3","questionId":"ea508d4d-e8b3-5746-8a9d-10a55f0583fa","sourceKey":"bank:GST111:GST111-0370","payload":{"prompt":"Punctuation marks are used for the following except","options":["to separate subordinate idea from major ones in a sentence","to indicate stretches of direct speeches in a discourse","to indicate a writer's background","to show possessive case in proper and common nouns"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Punctuation marks organise and structure writing so it conveys the right meaning: commas separate subordinate ideas from main ones, quotation marks mark direct speech, and the apostrophe shows possession in nouns. Nothing in punctuation reveals a writer's background, so C is the odd one out, while A, B and D are real functions of punctuation."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 335, $official_bank_source${"itemId":"85c0734c-aa0a-594f-bf5f-90ba3aa8468b","questionId":"def3c8d4-cba2-5e9a-9fa4-b3205af339ed","sourceKey":"bank:GST111:GST111-0407","payload":{"prompt":"The colon is used in the following situations except","options":["to introduce a list after words such as 'the following'","to introduce direct speech in some contexts","to join the parts of a compound word such as sister-in-law","to separate a title from its subtitle"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"Joining the parts of a compound word such as sister-in-law is the job of the hyphen, not the colon, so C is the exception. The colon introduces a list, especially after 'the following' or 'as follows' (A), can introduce direct speech, as in Okon said: \"I am hungry.\" (B), and separates a title from its subtitle (D)."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 336, $official_bank_source${"itemId":"fd10ee1a-0159-5b1e-bdbe-41fc4101f9e0","questionId":"68ed30ce-8692-5afa-a94f-d969a71a8fbf","sourceKey":"bank:GST111:GST111-0415","payload":{"prompt":"The __________ is used before a list of items","options":["colon","semicolon","period","question mark"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The colon introduces a list, especially after words like 'these', 'namely', 'the following' or 'as follows' (A). The semicolon (B) separates items within a list that already contain commas, but it does not introduce the list. The period (C) ends a sentence and the question mark (D) ends a direct question."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 337, $official_bank_source${"itemId":"5a94c336-b877-53c5-a04c-73d0ace92b1d","questionId":"130a89f7-d340-5fe9-aaa9-ec2f45365cce","sourceKey":"bank:GST111:GST111-0430","payload":{"prompt":"Another name for the argumentative essay is ........ essay.","options":["authoritative","rational","persuasive","expository"],"correctOption":2,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The argumentative essay is also called the persuasive essay, because the writer takes a stand and tries to get readers to accept a point of view (C). Expository (D) describes writing that explains or informs rather than argues, and authoritative and rational (A and B) are not names of essay types."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 338, $official_bank_source${"itemId":"9185542d-68bb-5ff8-b52f-da0c771203f4","questionId":"e28cf0f1-186c-5f67-a2b1-889354bc3a08","sourceKey":"bank:GST111:GST111-0434","payload":{"prompt":"The chief aim of a narrative essay is to ......","options":["arouse and sustain reader's interest","defend a position","create a mental image of something","explain a process"],"correctOption":0,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"The chief aim of a narrative essay is to arouse and sustain the reader's interest, making them feel a good story has been told (A). Defending a position (B) is the aim of argumentative writing, creating a mental image (C) belongs to the descriptive essay, and explaining a process (D) is expository or analytical."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 339, $official_bank_source${"itemId":"8fee06d1-db19-5baf-ac1f-f6be9f18efda","questionId":"d48185ff-41a4-59b6-acbd-b0b3556e40b6","sourceKey":"bank:GST111:GST111-0435","payload":{"prompt":"An analytical essay provides information such as ..............","options":["rationalisation","all of the above","critique","none of the above"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"In an analytical essay, information comes in two basic forms: rationalisations, which explain the state of things, and critiques, which review and judge quality. Since A and C are both correct, 'all of the above' (B) is the right choice, and 'none of the above' (D) is plainly wrong."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 340, $official_bank_source${"itemId":"b1b7150c-6fd6-55cf-a937-a99ad4e14345","questionId":"f7d119d1-5261-5a19-81da-1d1533153b63","sourceKey":"bank:GST111:GST111-0438","payload":{"prompt":"The ................. essay emphasizes character and setting.","options":["descriptive","narrative","persuasive","analytical"],"correctOption":1,"section":"Writing Skills II: Essay Writing and Punctuation","explanation":"A narrative essay emphasises character and setting so that the reader can identify with the subject and the situation (B). Option A, descriptive, is tempting because description also paints scenes, but character and setting are tied specifically to narration. Persuasive and analytical essays (C and D) focus on arguments and analysis."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 341, $official_bank_source${"itemId":"57d12a91-2141-5636-8f72-088e1537547a","questionId":"8d31cff9-e8e5-51cf-92ec-45e2c465b80e","sourceKey":"bank:GST111:GST111-0039","payload":{"prompt":"The dictionary contain all but information on","options":["The meaning of words","The pronunciation of words","Etymology","The year the words become obsolete"],"correctOption":3,"section":"Vocabulary Development","explanation":"A dictionary gives a word's spelling, meaning, pronunciation, usage, synonyms, etymology (origin) and grammatical functions. So meaning (A), pronunciation (B) and etymology (C) are all found there. The year a word became obsolete (option D) is not recorded; at most a dictionary labels a word as archaic, so D is the answer."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 342, $official_bank_source${"itemId":"7a11b668-4a24-54f7-83c0-0782a2ee4267","questionId":"b6743bca-bb8e-5199-9996-5eccd1a034f4","sourceKey":"bank:GST111:GST111-0040","payload":{"prompt":"Who ______ the telephone?","options":["Discovered","Invented","Founded","Explored"],"correctOption":1,"section":"Vocabulary Development","explanation":"Invented is correct because the telephone is a device that did not exist until someone created it. We discover things that already exist, such as a planet or a mineral, so discovered is the most tempting wrong choice. Founded is used for organisations and explored for places, so neither fits."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 343, $official_bank_source${"itemId":"a8a288aa-7263-5a78-b69d-d8972ace6aca","questionId":"6d5323c6-6e1a-5ff4-a350-5c9b7ce8185b","sourceKey":"bank:GST111:GST111-0041","payload":{"prompt":"The judge was ______ that the man was guilty","options":["Persuaded","Convinced","Believed","Trusted"],"correctOption":1,"section":"Vocabulary Development","explanation":"Convinced is correct because it means made to believe that something is true, which is what happens when a judge accepts that a man is guilty. Persuaded is the tempting choice, but it is normally used for being talked into doing something (persuaded to confess), not for believing a fact. Believed and trusted cannot be used in the pattern 'was ... that' here."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 344, $official_bank_source${"itemId":"e559f46d-a228-52c1-9e49-93187cb1c253","questionId":"a858f133-6afc-55c1-a0fc-54595bcf5434","sourceKey":"bank:GST111:GST111-0042","payload":{"prompt":"He ______ a prize for his diligence","options":["Took","Received","Made","Performed"],"correctOption":1,"section":"Vocabulary Development","explanation":"Received is correct because a prize is given to someone, so that person receives it. Took suggests he seized or helped himself to the prize, which does not fit being rewarded for diligence. Made and performed do not collocate with prize at all."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 345, $official_bank_source${"itemId":"72efe3ba-bd35-59f0-8eaa-4b0345039d3c","questionId":"3a057672-3b79-5a5d-8a05-850bab74e696","sourceKey":"bank:GST111:GST111-0043","payload":{"prompt":"It is not wise to ______ family quarrels","options":["Interfere in","Interfere with","Interfere on","Interfere at"],"correctOption":0,"section":"Vocabulary Development","explanation":"We interfere in matters or affairs that are not our business, such as a family quarrel, so interfere in is correct. Interfere with is used when something disturbs, obstructs or tampers with something else, for example noise interfering with your reading. Interfere on and interfere at are not standard English."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 346, $official_bank_source${"itemId":"4d534f33-4e73-5e17-8454-b5657929f634","questionId":"822b3038-2c4f-5684-91c6-7cdcd2fc5ded","sourceKey":"bank:GST111:GST111-0044","payload":{"prompt":"She did not ______ to go","options":["Accept","Agree","Allow","Admit"],"correctOption":1,"section":"Vocabulary Development","explanation":"To agree to do something means to say yes to a proposal or request, so agree is correct. Accept is the tempting choice, but it takes a noun object, as in accept an offer, so 'she did not accept to go' is non-standard. Allow would need an object (allow him to go), and admit to means to confess, so neither fits."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 347, $official_bank_source${"itemId":"2f5008a0-2c27-5d7e-87e4-b54af9b11079","questionId":"85b23ba8-225e-548c-911f-c0d51267c782","sourceKey":"bank:GST111:GST111-0045","payload":{"prompt":"A butcher ______ meat","options":["Deals with","Deals in","Deals on","Deals at"],"correctOption":1,"section":"Vocabulary Development","explanation":"To deal in something means to buy and sell it as a trade, so a butcher deals in meat. Deals with means to handle or manage a problem or person, which gives the wrong meaning here. Deals on and deals at are not standard expressions."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 348, $official_bank_source${"itemId":"f9c0c516-24b9-572d-a376-093e4c3eb877","questionId":"46120d7d-7abd-5617-ad21-04360c293b03","sourceKey":"bank:GST111:GST111-0046","payload":{"prompt":"How does that man ______ his living?","options":["Earn","Win","Achieve","Score"],"correctOption":0,"section":"Vocabulary Development","explanation":"We earn a living, meaning we work to get the money we need, so earn is correct. Win goes with prizes, games or competitions, so you cannot win your living. Achieve and score do not collocate with living either."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 349, $official_bank_source${"itemId":"6ed352c8-e8c0-550c-9c2d-c5a4652a17d4","questionId":"7b1c9cc2-3a73-5db7-82b6-bf53ce32b73a","sourceKey":"bank:GST111:GST111-0047","payload":{"prompt":"Please ______ me to give the money back","options":["Remember","Remind","Recall","Memorise"],"correctOption":1,"section":"Vocabulary Development","explanation":"To remind someone is to make them remember something, which is exactly what the speaker wants, so remind is correct. Remember is something you do yourself, so 'please remember me to give the money back' is wrong. Recall and memorise also describe your own mental action and cannot take the pattern 'me to give'."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 350, $official_bank_source${"itemId":"05128d6b-9b1e-5682-9afb-3b537f634397","questionId":"33ad8912-9ba1-5575-890e-870e927a5738","sourceKey":"bank:GST111:GST111-0048","payload":{"prompt":"The judge ______ the wrong done to the child","options":["Avenged","Revenged","Retaliated","Rebelled"],"correctOption":0,"section":"Vocabulary Development","explanation":"To avenge a wrong is to punish the wrongdoer on behalf of the victim, which is what a judge does in the name of justice, so avenged is correct. Revenged carries the idea of personal retaliation, as in revenging yourself on an enemy, so it does not fit a judge acting for a child. Retaliated and rebelled cannot take 'the wrong' as a direct object."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 351, $official_bank_source${"itemId":"8a3c5801-fc01-5e6f-ac1c-222ea9c01884","questionId":"b80b9181-37a8-5f66-b692-d6b7825f6aae","sourceKey":"bank:GST111:GST111-0049","payload":{"prompt":"Some people ________ freedom so much that they are ready to die for it","options":["Love","Like","Prefer","Fancy"],"correctOption":0,"section":"Vocabulary Development","explanation":"Love expresses a deep, intense feeling strong enough to make people willing to die for something, so it is correct. Like is far weaker, meaning only to find something pleasant, so it does not match the seriousness of being ready to die. Prefer and fancy are also too weak, and prefer needs a comparison."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 352, $official_bank_source${"itemId":"5d69f665-b0b9-56ac-9c5c-ce4159b06c33","questionId":"73c739f0-aadb-5a66-996e-043bf86ccf96","sourceKey":"bank:GST111:GST111-0060","payload":{"prompt":"The word here that can take the suffix, -NESS, by way of spelling is;","options":["Apt","Sadly","Comfort","Happily"],"correctOption":0,"section":"Vocabulary Development","explanation":"The suffix -ness turns adjectives into nouns, and apt is an adjective, so aptness, option A, is correct. Sadly (B) and happily (D) are adverbs, so they cannot take -ness in that form; the -ness words come from the adjectives sad and happy. Comfort (C) is already a noun, so comfortness is not a word."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 353, $official_bank_source${"itemId":"82192ecf-1890-5ddb-9b6d-33f2a2dbd8c2","questionId":"eb5de8a1-78b0-5709-a636-5d367499df48","sourceKey":"bank:GST111:GST111-0078","payload":{"prompt":"A basic reference tool every university student should personally own for effective study is ___","options":["A good dictionary","A well equipped library","A good encyclopedia","None of the above"],"correctOption":0,"section":"Vocabulary Development","explanation":"A good dictionary, option A, is the most basic tool a student needs, because it gives the meaning, spelling, pronunciation and usage of words needed in every course, and helps you grow your vocabulary. A well equipped library (B) and an encyclopedia (C) are valuable resources, but they are not the personal basic tool every student must own, so D is also wrong."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 354, $official_bank_source${"itemId":"ed9dc9ea-e500-5089-a848-77e83d8f3e63","questionId":"2ce63c16-f7d4-5cdc-a47c-4a1136609090","sourceKey":"bank:GST111:GST111-0094","payload":{"prompt":"Poetic meaning of an expression is usually","options":["Expressive","Denotative","Figurative","Discursive"],"correctOption":2,"section":"Vocabulary Development","explanation":"Poetic meaning is usually figurative, option C, because poets use words beyond their literal dictionary sense to suggest images, feelings and associations. Denotative meaning (B) is the literal meaning, which is the opposite of what poetry relies on, and expressive (A) and discursive (D) are not the standard terms for this kind of meaning."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 355, $official_bank_source${"itemId":"345dcab4-7620-5a24-b695-2be1707f7a8a","questionId":"d42f30c0-a64e-50fd-976d-350268d126cd","sourceKey":"bank:GST111:GST111-0095","payload":{"prompt":"Denotative words are","options":["Words which refer to the past","Listing words in alphabetical order","Words used scientifically","Words which make direct reference"],"correctOption":3,"section":"Vocabulary Development","explanation":"Denotative words make direct, literal reference to things, so D is correct. Denotative meaning is the literal meaning of a word, the one entered in the dictionary; for example, dark denotes the absence of light. Options A, B and C have nothing to do with denotation: referring to the past, alphabetical listing and scientific use are unrelated ideas."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 356, $official_bank_source${"itemId":"8adc45bf-8e25-5ce7-a326-4c3646462cd8","questionId":"2648f367-4270-5b0a-a57d-d517655e620c","sourceKey":"bank:GST111:GST111-0106","payload":{"prompt":"Identify the misspelled word below","options":["sphinx","embarrassment","repertoire","harrassment"],"correctOption":3,"section":"Vocabulary Development","explanation":"The misspelled word is harrassment, option D; the correct spelling is harassment, with one r and two s's. Sphinx (A), embarrassment (B) and repertoire (C) are all spelt correctly. Embarrassment is the one with double r and double s, which is probably why people wrongly add an extra r to harassment."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 357, $official_bank_source${"itemId":"c8722c25-47ab-5341-a10e-1b88836d85ac","questionId":"7fa4bef9-ab5c-595f-85b0-e5019d38bed8","sourceKey":"bank:GST111:GST111-0109","payload":{"prompt":"A dictionary aids vocabulary development by .....","options":["All of these","Suggesting meanings of words","Indicating the ways the words are pronounced","Indicating the context of usage and spelling"],"correctOption":0,"section":"Vocabulary Development","explanation":"A dictionary helps vocabulary grow by giving the meanings of words, showing how they are pronounced, and indicating their spelling and the contexts in which they are used. Since B, C and D are each true, A, all of these, is the correct choice; picking only one of them leaves out the others."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 358, $official_bank_source${"itemId":"c09eb97e-a051-593a-95dc-f011a2fd8971","questionId":"b1ec2421-7056-55d0-be6e-a4fb1544d127","sourceKey":"bank:GST111:GST111-0112","payload":{"prompt":"Meaning in words is largely a matter of ........","options":["Agreement","discord","standardised opinion","Inherence"],"correctOption":0,"section":"Vocabulary Development","explanation":"Meaning in words is largely a matter of agreement, option A, because the link between a word and what it stands for is a convention shared by speakers of a language, not something natural in the word itself. English accepts new words like vuvuzela once speakers agree to use them. Discord (B) is the opposite of shared meaning, and inherence (D) wrongly suggests meaning is built into the word. Standardised opinion (C) is not the term used."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 359, $official_bank_source${"itemId":"10ffe782-b845-5d17-9c15-d447cf246a28","questionId":"0bc4800f-c736-5e2a-8fbc-3fa483cbc342","sourceKey":"bank:GST111:GST111-0130","payload":{"prompt":"Identify the incorrectly spellled word below","options":["chauffeur","souvenier","vagrant","resinous"],"correctOption":1,"section":"Vocabulary Development","explanation":"The misspelled word is souvenier, option B; the correct spelling is souvenir, ending in -ir, not -ier. It is one of the words English borrowed from French. Chauffeur (A), vagrant (C) and resinous (D) are all spelt correctly."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 360, $official_bank_source${"itemId":"9d3bc800-176d-5456-8b28-e9bc7f4ebcce","questionId":"bcc5ce41-6391-51f2-9950-d47f06729f47","sourceKey":"bank:GST111:GST111-0183","payload":{"prompt":"As a prefix, ANTI- means","options":["Congruent","Similar","Dissimilar","Against"],"correctOption":3,"section":"Vocabulary Development","explanation":"The prefix anti- means against or opposed to, as in anti-social, or antibiotic (against the life forms that cause disease). Option C (dissimilar) is tempting because opposing something can suggest difference, but anti- expresses opposition, not just being different. A and B (congruent, similar) point the opposite way. Also take care not to confuse anti- with ante-, which means before."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 361, $official_bank_source${"itemId":"a667db4c-fe89-5f86-8fd2-2b2ea9926c51","questionId":"e86a746a-c33a-504c-a45f-e2552ef79060","sourceKey":"bank:GST111:GST111-0190","payload":{"prompt":"To be elected ................, candidates must have a solid background in law enforcement.","options":["Sheriff","Sherrif","Sherif","Sherriff"],"correctOption":0,"section":"Vocabulary Development","explanation":"The correct spelling is sheriff, with one r and two f's, so A is correct. Option B doubles the r and drops an f, C drops an f, and D doubles both the r and the f, so all three are misspellings."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 362, $official_bank_source${"itemId":"e8ca24f6-aa18-5320-8067-a03765c73c34","questionId":"b9b14168-31b9-5590-add2-d9975d7e6039","sourceKey":"bank:GST111:GST111-0201","payload":{"prompt":"Which of the following words is misspelled?","options":["parachutis","communication","accommodation","swinging"],"correctOption":0,"section":"Vocabulary Development","explanation":"The word in A is misspelt: the correct spelling is parachutist, ending in -ist, but option A has lost its final t. Communication, accommodation and swinging (B, C and D) are all spelt correctly, though accommodation is a common trap because it needs a double c and a double m."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 363, $official_bank_source${"itemId":"aeb1d34e-2d54-5c80-a118-05aa61ca9458","questionId":"4d5ff559-c6d5-562e-956e-6c17a9c08906","sourceKey":"bank:GST111:GST111-0208","payload":{"prompt":"................ is often called the awkward stage.","options":["Adolescense","Adolscence","Adolessents","Adolescence"],"correctOption":3,"section":"Vocabulary Development","explanation":"The correct spelling is adolescence, with -esc- in the middle and the noun ending -ence, and it is the stage of life often called awkward. Option A ends wrongly in -ense, B drops the e after the l, and C is a misspelt plural form (adolescents), which names the people rather than the stage of life."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 364, $official_bank_source${"itemId":"405dece0-55ca-591f-bae5-02ab48442d26","questionId":"1b5a5556-59d4-5340-9319-818fe7ee72df","sourceKey":"bank:GST111:GST111-0219","payload":{"prompt":"If you stay in water too long, your fingertips will","options":["Shriveal","Shrivel","Shrivle","Shrival"],"correctOption":1,"section":"Vocabulary Development","explanation":"The correct spelling is shrivel, ending in -el, and it means to wrinkle and shrink, which is what fingertips do after a long time in water. Option A adds an extra a, C reverses the last two letters, and D wrongly ends in -al."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 365, $official_bank_source${"itemId":"3e4c6e39-f26a-5450-8289-09fbc21d4b75","questionId":"b2e4237e-fd88-527c-b569-9164abe60b93","sourceKey":"bank:GST111:GST111-0227","payload":{"prompt":"If neologism is taken to mean old words that have been given new meanings, which of the following is NOT an example of neologism?","options":["nice","lady","Waterloo","brunch"],"correctOption":3,"section":"Vocabulary Development","explanation":"Brunch is not an old word with a new meaning: it is a blend, made by joining part of breakfast to part of lunch. Nice, lady and Waterloo are all old words whose meanings have shifted, for example Waterloo, once just a place name, now also means a final defeat."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 366, $official_bank_source${"itemId":"9b8f9858-374b-5673-9911-11edd219d219","questionId":"81edc4fe-8eaa-517a-86bb-e0f4307b91e2","sourceKey":"bank:GST111:GST111-0264","payload":{"prompt":"Words that habitually go together, such as \"make a decision\" or \"heavy rain\", are known as","options":["continuation.","composition","connotation","Collocation"],"correctOption":3,"section":"Vocabulary Development","explanation":"A collocation is a group of words that habitually occur together, so we say make a decision rather than do a decision. Option C (connotation) is the feeling or association attached to a single word, not a word grouping, and A and B (continuation, composition) are not terms for words that go together."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 367, $official_bank_source${"itemId":"fef83a42-df19-5698-b234-8277245df066","questionId":"b46b585e-26c2-5c84-b1ac-34d98b619df8","sourceKey":"bank:GST111:GST111-0275","payload":{"prompt":"In which of the following pairs does one word carry a negative connotation?","options":["brave / courageous","persistent / stubborn","brilliant / clever","kind / generous"],"correctOption":1,"section":"Vocabulary Development","explanation":"Connotation is the feeling attached to a word beyond its literal meaning. Persistent is approving, but stubborn suggests an unreasonable refusal to change, so pair B contains a negative word. In A, C and D both words carry a positive feeling."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 368, $official_bank_source${"itemId":"a40b4504-a85c-53a6-8d0c-6472f97144d5","questionId":"447e0197-c221-562c-88e8-df836c08232a","sourceKey":"bank:GST111:GST111-0279","payload":{"prompt":"The process of word formation where old words are given new meanings is called","options":["mixing","coining","blending","neologism"],"correctOption":3,"section":"Vocabulary Development","explanation":"Neologism here means the process in which old words are given new meanings, such as nice, which once meant pretending to be good and now means kind, or Waterloo, which now means a defeat. Option B (coining) creates a word for a specific use, and C (blending) joins parts of two words, as in smog, so neither gives an existing word a new meaning. A (mixing) is not a word-formation process."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 369, $official_bank_source${"itemId":"66b09479-9477-5d09-8a76-6d8e46c3afdd","questionId":"6af6d653-ff8c-5c66-8b00-7469b86f3ae4","sourceKey":"bank:GST111:GST111-0285","payload":{"prompt":"A thesaurus is a","options":["Specialised dictionary","simplified dictionary","pictorial dictionary","phonetic dictionary"],"correctOption":0,"section":"Vocabulary Development","explanation":"A thesaurus is a dictionary of synonyms, and it is classed among specialised dictionaries, alongside scholarly and usage dictionaries. Options B, C and D (simplified, pictorial, phonetic) are not categories under which a thesaurus belongs."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 370, $official_bank_source${"itemId":"40f6cf73-7c1d-56d5-8c4b-8f18b64e4ab3","questionId":"2f61157e-d5db-52be-b5f4-05bfebe426b0","sourceKey":"bank:GST111:GST111-0348","payload":{"prompt":"When a long word is shortened to make it less awkward in speech, it is said to be ...","options":["chopped","clipped","chipped","crimped"],"correctOption":1,"section":"Vocabulary Development","explanation":"Clipping is the shortening of long words that are awkward in everyday speech, as in exam from examination and phone from telephone. Chopped, chipped and crimped (A, C and D) are not terms for word formation."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 371, $official_bank_source${"itemId":"85bbe78e-a26d-5f34-963c-3da4a41281e1","questionId":"4325a630-fcab-5c71-96e3-019b37be51c0","sourceKey":"bank:GST111:GST111-0416","payload":{"prompt":"Prefixes and suffixes are generally known as ----------","options":["Affixation","Root","Stem","Affixes"],"correctOption":3,"section":"Vocabulary Development","explanation":"Prefixes and suffixes together are called affixes, groups of letters added before or after a base (D). Option A, affixation, is the process of adding them, not the name of the elements themselves, while root and stem (B and C) are the bases the affixes attach to."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 372, $official_bank_source${"itemId":"2cc46584-1d62-5b3c-b05f-95044d8d6fe4","questionId":"db952d1c-d574-56f3-82e5-449db141a745","sourceKey":"bank:GST111:GST111-0433","payload":{"prompt":"......occurs when the meaning of a word depends on its environment and usage.","options":["connotation","pronunciation","contextual meaning","Assimilation"],"correctOption":2,"section":"Vocabulary Development","explanation":"Contextual meaning is meaning worked out from the word's environment, using clues in the sentence such as paired words or parallelism (C). Connotation (A) is tempting, but it is the figurative meaning a word carries from feelings and experience, as in 'he's dark' meaning evil. Pronunciation and assimilation (B and D) concern sounds, not meaning."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 373, $official_bank_source${"itemId":"1318f19c-909f-5ea8-86dc-4dc143a3bb6d","questionId":"85ef0a0f-8f8f-5631-8947-84528f782616","sourceKey":"bank:GST111:GST111-0460","payload":{"prompt":"When the meaning of a word is considered in isolation, it is known as ......meaning.","options":["complex","objective","connotative","denotative"],"correctOption":3,"section":"Vocabulary Development","explanation":"Denotative meaning is the literal, dictionary meaning of a word considered on its own, as in 'dark' meaning without light (D). Connotative meaning (C) comes from feelings, emotions and experience, so it is not meaning in isolation. Complex and objective (A and B) are not recognised types of word meaning."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 374, $official_bank_source${"itemId":"9170260b-e0a8-51ec-bd59-f468f992c53d","questionId":"5b750f30-8b19-588c-a317-6147547fb686","sourceKey":"bank:GST111:GST111-0463","payload":{"prompt":"\"un\" in the word \"unfaithful\" is an example of a","options":["subjunction","prefix","conjunct","suffix"],"correctOption":1,"section":"Vocabulary Development","explanation":"An affix added at the beginning of a word, like un- in unfaithful or unpleasant, is a prefix (B). A suffix (D) is added at the end of a word, like -ful in the same word. Subjunction and conjunct (A and C) are not names for word parts; a conjunct is a linking word."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 375, $official_bank_source${"itemId":"725f52f8-5bbd-5c56-92fe-32fad6e4f7b3","questionId":"f467ba63-9fe1-5fa1-80a0-d686657a6e35","sourceKey":"bank:GST111:GST111-0467","payload":{"prompt":"The words fax, prep, gents, zoo and ad are examples of which word-formation process?","options":["clipping","conversion","Blend","Acronym"],"correctOption":0,"section":"Vocabulary Development","explanation":"Clipping is shortening a long word that is awkward in speech, keeping only part of it, as in fax from facsimile or zoo from zoological garden (A). A blend (C) combines parts of two different words, like smog from smoke and fog, and an acronym (D) is formed from the initials of several words. Conversion (B) changes a word's class without changing its form."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 376, $official_bank_source${"itemId":"346287a0-c236-5744-a58f-744d25cca971","questionId":"fc8682d8-4f57-5251-9122-2346947f6bb3","sourceKey":"bank:GST111:GST111-0472","payload":{"prompt":"What is a thesaurus?","options":["A dictionary of synonyms, which is a specialised dictionary","A general dictionary that gives the etymology of most words","A list of sources placed at the end of a research work","A brief summary of a book or article"],"correctOption":0,"section":"Vocabulary Development","explanation":"A thesaurus is a dictionary of synonyms, such as Roget International Thesaurus, and it counts as a specialised dictionary (A). Option B describes a general unabridged dictionary, which covers most words with details and etymology. A list of sources at the end of a work (C) is a bibliography, and a brief summary (D) is an abstract."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 377, $official_bank_source${"itemId":"34e3360b-512f-5007-9a9c-64969326d500","questionId":"9b4b110a-7513-5090-98c9-0959c9f22825","sourceKey":"bank:GST111:GST111-0476","payload":{"prompt":"The caverns were so damp that my skin felt","options":["Clamy","Clammby","Clamby","Clammy"],"correctOption":3,"section":"Vocabulary Development","explanation":"The correct spelling is clammy, with a double m and a y, meaning unpleasantly damp and sticky (D). Option A, clamy, drops the second m, while B and C insert a b that does not belong in the word."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 378, $official_bank_source${"itemId":"525ee67e-4532-5ad0-b243-2e62018154cb","questionId":"8aba780a-1390-599a-8176-ef852f3c0812","sourceKey":"bank:GST111:G111N1-136","payload":{"prompt":"Shakespeare is said to have used about how many words?","options":["21,000","1,000,000","12,000","10,000"],"correctOption":0,"section":"Vocabulary Development","explanation":"Shakespeare is said to have used about 21,000 words. The figure 10,000 is the number that hardly any learner knows, and one million is the estimate of all English words."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 379, $official_bank_source${"itemId":"45800386-2c87-5f00-8589-a919f578926d","questionId":"65fb8fe4-3be3-5566-a47b-0a7fa61ce60e","sourceKey":"bank:GST111:G111N1-137","payload":{"prompt":"French words such as those about the kitchen, cooking and government entered English mainly through","options":["the Renaissance","the arrival of the Angles, Saxons and Jutes","the spread of Christianity","the Norman Conquest of 1066 AD"],"correctOption":3,"section":"Vocabulary Development","explanation":"The Norman Conquest of 1066 AD brought French words about the kitchen, cooking, government and administration into English. The Renaissance is linked instead with Greek and Latin words, while the Angles, Saxons and Jutes brought Anglo-Saxon, the native base of English."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 380, $official_bank_source${"itemId":"93285f3a-6806-595e-8889-a8fc813810b9","questionId":"8a5312a1-c11a-5a5a-ac1d-68d4245f7527","sourceKey":"bank:GST111:G111N1-138","payload":{"prompt":"The words 'dilly-dally', 'nitty-gritty' and 'topsy-turvy' are formed by","options":["clipping","blending","coining","reduplication"],"correctOption":3,"section":"Vocabulary Development","explanation":"Reduplication doubles all or part of a word, usually changing one vowel or consonant, as in 'dilly-dally'. Blending is different: it joins part of one word to part of another, as in 'smog' from smoke and fog."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 381, $official_bank_source${"itemId":"03cab751-887e-5ea8-b29e-744e76494de7","questionId":"09fe0a27-373a-5918-9594-e5cbd24f3d7d","sourceKey":"bank:GST111:GST111-0084","payload":{"prompt":"_____ forms the building block of a sentence","options":["Sounds","Letters","Thoughts","Words"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"Words, option D, are the building blocks of a sentence: they combine to form phrases and clauses, which in turn form sentences. Sounds (A) and letters (B) are the building blocks of words, not sentences, and thoughts (C) are what a sentence expresses rather than what it is made of."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 382, $official_bank_source${"itemId":"4f28c3f0-75fb-5122-aa66-adc5f26f0e0b","questionId":"1644106e-5445-5cae-a323-fefb526924fa","sourceKey":"bank:GST111:GST111-0108","payload":{"prompt":"Prepositions begin phrases that end with","options":["adjective or pronoun","either a noun or pronoun","conjunction or adjunct","verb or adverb"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"Prepositions begin phrases that end with either a noun or a pronoun, called the object of the preposition, as in under the table or at the bus-stop. So B is correct. Options A, C and D name word classes that do not serve as the object of a preposition."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 383, $official_bank_source${"itemId":"c14de02c-d812-5761-bbb6-4cd24f1ea577","questionId":"0c14f326-4bc4-53cd-bae1-c0ded7911ed6","sourceKey":"bank:GST111:GST111-0111","payload":{"prompt":"Words can be in any of the following forms except:","options":["simple","complex","compound-complex","compound"],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"A word can be simple (one unit, like table), compound (two words that can stand alone, like suitcase) or complex (a base with affixes, like unreliable). Compound-complex (option C) is not a word form; it is a type of sentence with two or more main clauses plus a subordinate clause. So C is the form a word cannot take."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 384, $official_bank_source${"itemId":"3ba3da49-9e31-5ff9-b504-27e6acd79974","questionId":"8d25f3ba-8d08-5480-a9f0-c0857c8bc84c","sourceKey":"bank:GST111:GST111-0120","payload":{"prompt":"Interjections are usually punctuated with a/an ____________.","options":["question mark","comma","exclamation mark","period"],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"Interjections express strong or sudden feeling and are usually punctuated with an exclamation mark, as in Ouch! That was painful and Hey! Watch out! So C is correct. A question mark (A) is for direct questions, a period (D) ends ordinary statements, and a comma (B) is used only after mild interjections, which is not the usual punctuation."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 385, $official_bank_source${"itemId":"451550d3-a8f8-5aca-bb51-c32a05c59d29","questionId":"68b3d127-ba33-5cd3-8607-c4c7f6d01a72","sourceKey":"bank:GST111:GST111-0142","payload":{"prompt":"The simple present tense is used to indicate","options":["a completed past action","present","irregularity","regularity"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"The simple present tense is used when someone does something regularly or something goes on all the time, for example I jog every morning or The cock crows at dawn. So it signals regularity, option D. Option B, present, is tempting because of the name, but an action happening right now is the job of the present continuous. A completed past action (A) needs the simple past, and irregularity (C) is the opposite of what this tense shows."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 386, $official_bank_source${"itemId":"0baad9d9-9681-5fb0-ab1d-85a806ab8566","questionId":"d65a601e-3091-5cd3-af9d-ff4555e4bd8b","sourceKey":"bank:GST111:GST111-0145","payload":{"prompt":"Free morphemes are sub-categorized into ---------------","options":["grammatical and functional.","functional and descriptive.","lexical and functional.","descriptive and functional."],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"Free morphemes are words that can stand alone, and they fall into two groups: lexical morphemes, which carry content meaning (nouns, verbs, adjectives and adverbs such as boy, run, happy), and functional morphemes, which do grammatical work (articles, prepositions, conjunctions and pronouns such as the, of, and). So C is correct. Options A, B and D pair functional with a label (grammatical, descriptive) that is not the standard partner term; grammatical is just another word for functional, not a separate class."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 387, $official_bank_source${"itemId":"899aaea7-ba8f-5eb0-bcfc-e1f51491ca00","questionId":"7dde8141-e4dd-5168-b5ae-c78b84898475","sourceKey":"bank:GST111:GST111-0157","payload":{"prompt":"Which of the following are irregular nouns?","options":["man-men, woman-women, louse- lice.","Leaf-leaves, wife-wives, half-halves","all of these","foot-feet, goose-geese, tooth- teeth"],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"Irregular nouns include those that change an internal vowel in the plural (man-men, woman-women, louse-lice, foot-feet, goose-geese, tooth-teeth) and those that change -f or -fe to -ves (leaf-leaves, wife-wives, half-halves). Since A, B and D all give genuine irregular plurals, C, all of these, is correct. Picking any single option leaves out equally valid examples."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 388, $official_bank_source${"itemId":"4e4baf41-1376-58b2-853a-3f0240acc9f8","questionId":"8396d31a-529a-521c-8ca9-5d334291ff35","sourceKey":"bank:GST111:GST111-0158","payload":{"prompt":"In the sentence \"He arrived yesterday\", the word \"yesterday\" is an","options":["adverb of frequency","adverb of time","adverb of degree","adverb of manner"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"In He arrived yesterday, the word yesterday is an adverb of time because it answers the question when did he arrive? So B is correct. An adverb of frequency (A) would answer how often, degree (C) would answer to what extent, and manner (D) would answer how, none of which fits yesterday."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 389, $official_bank_source${"itemId":"77ada61b-50f5-5a53-9e94-b92c34ed457f","questionId":"1ffff0fb-bd64-5f6f-ae30-f1353711c2ff","sourceKey":"bank:GST111:GST111-0159","payload":{"prompt":"The word 'unhappily' contains-----------------","options":["prefix, root, suffix.","root, infix, suffix.","prefix, stem, root.","stem, root, suffix."],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"Unhappily is built from three parts: the prefix un- (meaning not), the root happy, and the suffix -ly, which turns the adjective into an adverb, so A is correct. Option B is wrong because English words like this have no infix, and options C and D list two bases (stem and root) when unhappily has only one, and D also leaves out the prefix."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 390, $official_bank_source${"itemId":"9ef10186-57b5-5bb7-a23b-67b622d66e92","questionId":"ad868e2e-b9d6-5cc9-9c24-6de54412d4ec","sourceKey":"bank:GST111:GST111-0163","payload":{"prompt":"I saw them across the road, the expression across the road can be described as a ------","options":["Verb phrase.","Adjective phrase","Noun phrase","Prepositional phrase"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"A prepositional phrase begins with a preposition and ends with a noun or pronoun called its object, as in under the bed and across the road, so D is correct. Option C, noun phrase, is tempting because the road is a noun phrase, but the whole expression is headed by the preposition across. Options A and B have a verb or adjective as the main word, which is not the case here."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 391, $official_bank_source${"itemId":"402b75ba-ee9a-5966-9684-cf2a7fe9774b","questionId":"5b92b391-36ae-5d78-b41e-5fc66f516ba8","sourceKey":"bank:GST111:GST111-0178","payload":{"prompt":"The category of words to which new words can always be added is called-------","options":["open class words","closed class words","grammatical words","suffixation words."],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"Open class words are word classes that readily accept new members, such as nouns, verbs, adjectives and adverbs, so new words like webinar or selfie can always be added. Closed class words (B) and grammatical words (C), such as prepositions and conjunctions, almost never gain new members. Suffixation words (D) is not a grammatical term."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 392, $official_bank_source${"itemId":"04b6b7d7-7f4f-5a14-a27e-7ef75f88d3fd","questionId":"e79aba5f-c27d-5932-8df4-8bb406b32644","sourceKey":"bank:GST111:GST111-0195","payload":{"prompt":"In \"My mother cooks very well\", the word \"very\" is an","options":["adverb of degree","adverb of place","adverb of manner","adverb of time"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"In My mother cooks very well, the word very tells us to what extent she cooks well, so it is an adverb of degree, option A. Option C (manner) is tempting because well on its own says how she cooks, but very only intensifies well. Options B and D (place, time) do not fit at all."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 393, $official_bank_source${"itemId":"916ad718-2099-52a6-976c-aec41d6154b7","questionId":"bd6d2a6a-f8fb-5fdc-8d17-635670c050d5","sourceKey":"bank:GST111:GST111-0205","payload":{"prompt":"The largest grammatical unit in English is the------and the smallest is the ---------","options":["paragraph, morpheme","sentence, morpheme","clause, word","sentence, phrase"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"The grammatical units run from the morpheme, through the word, phrase and clause, up to the sentence, so the sentence is the largest unit and the morpheme the smallest. Option A is wrong because the paragraph is a unit of writing, not of grammar. Options C and D name units that sit in the middle of the scale, since the word and the phrase are both bigger than the morpheme."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 394, $official_bank_source${"itemId":"6bd6844f-c205-57cb-a653-7fcd135b84b9","questionId":"bd6a9f33-6c4e-575e-b1af-c2f752aaf1e5","sourceKey":"bank:GST111:GST111-0210","payload":{"prompt":"What is the function of the word \"boy\" in the sentence: That boy is my cousin?","options":["Object of the verb","Coplement of the noun","Subject of the verb","Complement of \"that\""],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"In That boy is my cousin, the noun phrase that boy names what the sentence is about and comes before the verb, so boy is the subject of the verb is. Option A (object) would receive the action of a verb, but the linking verb is has no such object. D is wrong because that is a demonstrative determiner pointing to boy, not something boy completes, and B is not a grammatical function."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 395, $official_bank_source${"itemId":"43320e09-6be3-5235-8cc1-912a5f91bc2b","questionId":"cdd1850f-2d48-5654-be17-ee3d959a0a63","sourceKey":"bank:GST111:GST111-0213","payload":{"prompt":"The prefix un- in the word \"unreliable\" can be described as a/an --------- morpheme.","options":["inflectional","free","lexical","derivational"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"The prefix un- is a derivational morpheme because it creates a new word with a different meaning: reliable becomes its opposite, unreliable. Option A is wrong because inflectional morphemes such as -s or -ed only mark grammar like number or tense without making a new word. Options B and C are wrong because un- cannot stand alone, so it is neither a free morpheme nor a lexical (content) word."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 396, $official_bank_source${"itemId":"7f8cbb6f-c1ec-58ef-9e4c-4a084c6b220a","questionId":"f879a12f-2570-5fb3-879d-8e6d19558c7a","sourceKey":"bank:GST111:GST111-0220","payload":{"prompt":"Auxiliary verbs in English are classified into-------","options":["modal and main","primary and secondary","primary and modal","regular and irregular"],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"Auxiliary verbs are of two types: primary auxiliaries (have, be and do), which can also act as main verbs, and modal auxiliaries (can, will, shall, may, must), which never stand alone. Option A (modal and main) mixes an auxiliary type with main verbs, B (primary and secondary) invents a category, and D (regular and irregular) classifies verbs by how they form the past tense, not auxiliaries."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 397, $official_bank_source${"itemId":"31316fe4-7a0f-5727-85a4-4d8819e00e78","questionId":"4042cb78-3034-5a3d-898b-dee8b5e8abca","sourceKey":"bank:GST111:GST111-0229","payload":{"prompt":"Every complex word contains a/an --------------","options":["verb","noun","prefix","affix"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"A morphologically complex word is formed by adding an affix, a group of letters placed before (prefix) or after (suffix) the base, as in unrepentant, disloyal and endearment. So every complex word contains an affix. Option C (prefix) is too narrow, since a word like fairness is complex with only a suffix, and A and B (verb, noun) are word classes, not parts of a word."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 398, $official_bank_source${"itemId":"a89d4747-54e3-55ce-ab3d-71c949536adc","questionId":"ada00635-1da9-5a90-80c2-971f8f4d551d","sourceKey":"bank:GST111:GST111-0239","payload":{"prompt":"In the sentence \"We bought John a guitar\", the phrase \" a guitar\" functions as-------- ?","options":["Object complement","Direct object","Indirect object","Subject complement"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"When a verb has two objects, the direct object answers what was bought, and the indirect object answers for or to whom. In We bought John a guitar, a guitar is what was bought, so it is the direct object, and John is the indirect object (option C). Options A and D (complements) would describe or rename the object or the subject, which a guitar does not do."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 399, $official_bank_source${"itemId":"e28222ea-5f73-5b1a-96c3-9c32fc1ea374","questionId":"00c759a0-7a1f-503f-86a5-8092adc2ad20","sourceKey":"bank:GST111:GST111-0241","payload":{"prompt":"One of the following does not describe a noun:","options":["can be in past or present tense","has a possessive form","can be singular or plural","can be proper or common"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"Tense belongs to verbs, not nouns, so a noun is not something that can be in the past or present tense, and A is correct. A noun can take a plural, have a possessive form, and be proper or common, so B, C and D all describe nouns properly."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 400, $official_bank_source${"itemId":"a8611fb6-bd23-54b0-8fb0-4486d86b9b00","questionId":"e767201a-2911-54ab-8c74-54d4bf59b1c9","sourceKey":"bank:GST111:GST111-0250","payload":{"prompt":"The base word in \"Educational\" is","options":["educate","nal","Ed","duct"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"Educational is built by affixation: the root educate takes the suffix -ion to give education, and then the suffix -al to give educational, so the base is educate. Options B, C and D are only fragments of letters or a suffix and cannot stand alone as words, so none of them is the base."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 401, $official_bank_source${"itemId":"5d64e72d-bc42-5cd1-b693-7084341e57d0","questionId":"c23d5486-b9db-5e85-8555-7e87d2cd442c","sourceKey":"bank:GST111:GST111-0254","payload":{"prompt":"Nouns can be subclassified in the following ways except one.","options":["Possessive and non-possessive","Concrete and abstract","Proper and common","Count and non-count"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"Nouns are subclassified in three pairs: proper and common, count and non-count, and concrete and abstract. Possessive is a form that a noun can take (girl's, girls'), just as singular and plural are forms, so possessive and non-possessive is not a subclass. B, C and D are all genuine subclasses of nouns."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 402, $official_bank_source${"itemId":"2f1d3350-45f7-506c-b516-795be1edf079","questionId":"d2e88882-396b-523c-8cc9-dd8bc8f4101a","sourceKey":"bank:GST111:GST111-0263","payload":{"prompt":"Which of these does not belong in this group?","options":["Lagos","mathematics","John","Kaduna"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"Lagos, John and Kaduna are proper nouns, each naming a particular place or person, and so they begin with capital letters. Mathematics is a common noun naming a general field of study, so B does not belong with the others."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 403, $official_bank_source${"itemId":"a094939b-eb75-5117-b4d1-3de9d4aee97d","questionId":"fc57837c-4e66-5bd6-bced-9e76ba0322a9","sourceKey":"bank:GST111:GST111-0272","payload":{"prompt":"In the sentence \"Mr. Dokunboh donated some books\", the phrase \"some books\" is the","options":["subject complement","indirect object of the verb","subject of the verb","direct object of the verb"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"In Mr. Dokunboh donated some books, some books receives the action of the verb and answers the question what was donated, so it is the direct object. Option B (indirect object) would apply only to a receiver such as the school in donated some books to the school, and C is wrong because Mr. Dokunboh, not the books, performs the action."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 404, $official_bank_source${"itemId":"50092c88-7fd9-5e30-9c6d-1f354f7a0769","questionId":"59ac2fa5-6f2c-5ee4-9abe-081c9409353d","sourceKey":"bank:GST111:GST111-0274","payload":{"prompt":"When an adjective is placed before a noun, it is said to be in what position?","options":["Superlative","Comparative","Attributive","Positive"],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"An adjective placed before the noun it qualifies, as in the beautiful woman, is attributive, whereas one linked to the noun by a verb, as in the food is delicious, is predicative. Options A, B and D (superlative, comparative, positive) are degrees of comparison, which describe the form of an adjective, not its position."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 405, $official_bank_source${"itemId":"66a0201d-6d01-5e25-902e-cc561d2659f4","questionId":"e59da3cc-9a6a-59b6-b9bd-ae70eba19bfa","sourceKey":"bank:GST111:GST111-0276","payload":{"prompt":"----------------- words involve two or more independent words.","options":["compound","compound-complex","simple","complex"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"Compound words are made of two or more words that can each stand independently, such as suitcase or blackboard. Option D (complex) is tempting, but a complex word contains an affix, as in unhappy, rather than two independent words. A simple word (C) has only one morpheme, and compound-complex (B) is a type of sentence, not a word type."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 406, $official_bank_source${"itemId":"8b812dde-c087-5edc-8496-72ec81c62fd6","questionId":"8ab2ff30-e12e-556d-8c9e-c3836cd49200","sourceKey":"bank:GST111:GST111-0277","payload":{"prompt":"Grammar is broadly classified into----------","options":["lexis and structure.","morphemes and units","morphology and syntax","phonology and semantics"],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"Grammar is divided into morphology, the study of how words are formed, and syntax, the study of how words are arranged into phrases, clauses and sentences. Option D names phonology (the sound system) and semantics (meaning), which are other areas of language study, not branches of grammar. Option A is not the standard division, and B mixes a unit with a vague term."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 407, $official_bank_source${"itemId":"1759aba0-79a8-5df7-9c1c-c57206dc11ae","questionId":"03d24a8d-01ad-5c00-a445-3f4a08dc2378","sourceKey":"bank:GST111:GST111-0291","payload":{"prompt":"Which of the following sentences makes use of an intransitive verb?","options":["My sister bought a car","The woman ate the food","Your house is too far.","The baby cried"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"An intransitive verb takes no object, and in The baby cried the verb cried has nothing after it receiving the action. Options A and B are transitive, since bought takes the object a car and ate takes the object the food. Option C uses the linking verb is with a complement, not an action verb without an object."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 408, $official_bank_source${"itemId":"ed0aa8b5-aac0-514b-a85c-cf6134809e90","questionId":"3948e7e0-0aac-5ee7-b024-0590e7aed911","sourceKey":"bank:GST111:GST111-0294","payload":{"prompt":"In the sentence 'The young lady thanked Mr Dokubo', the phrase 'Mr Dokubo' functions as a/an ...","options":["Complement","Indirect object","Qualifier","Direct object"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"In The young lady thanked Mr Dokubo, Mr. Dokubo receives the action of the transitive verb thanked, which makes it the direct object. Option B (indirect object) would need a second object that the action is done for or to, and A (complement) would need the phrase to refer to the same person as the subject."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 409, $official_bank_source${"itemId":"1da72242-44c0-56e2-9297-0ae79481e264","questionId":"e8207776-d936-592d-a9fb-ab110494d9c9","sourceKey":"bank:GST111:GST111-0304","payload":{"prompt":"In the sentence: \"They came late because of the heavy rain\", the phrase the heavy rain is called?","options":["Verb phrase","Noun phrase","Adverbial phrase","Prepositional phrase"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"The heavy rain is built around the head noun rain, with the determiner the and the adjective heavy describing it, so it is a noun phrase. Option D is tempting because the phrase follows because of, but the prepositional phrase is the whole group because of the heavy rain, while the heavy rain on its own is the noun phrase inside it."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 410, $official_bank_source${"itemId":"1aef5324-b6a9-5dfc-ba89-2227d946e560","questionId":"48b033b0-f41a-589c-8ee1-d2b16f339d2f","sourceKey":"bank:GST111:GST111-0306","payload":{"prompt":"A verb which always occurs with an object is a/an \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_ verb.","options":["intransitive","primary auxiliary","transitive","modal auxiliary"],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"A transitive verb lets the action pass from the subject to an object, as in The man shut the door, so it always occurs with an object. Option A (intransitive) is the opposite, with no object, and B and D are helping verbs that accompany main verbs rather than taking objects themselves."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 411, $official_bank_source${"itemId":"3ceb5e4b-e444-5606-a15f-164e8b82c7eb","questionId":"861112ae-1bff-56a8-bcf7-e1fd41b888dc","sourceKey":"bank:GST111:GST111-0312","payload":{"prompt":"The grammatical elements will, shall, could, should can and may are known as ----- --------","options":["Transitive verbs","Main verbs","Intransitive verbs","Modal auxiliaries."],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"Will, shall, could, should, can and may are modal auxiliary verbs, helping verbs that cannot stand alone but combine with main verbs to express ability, permission or obligation. Options A and C classify main verbs by whether they take an object, and B is wrong because modals are helping verbs, not main verbs."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 412, $official_bank_source${"itemId":"16fd1077-2aee-5aa6-94f9-dd2494db9c13","questionId":"346e4603-42fb-5213-95ff-5c1180b02cc0","sourceKey":"bank:GST111:GST111-0323","payload":{"prompt":"Which tense do you use when you want to say that something is happening at the time you are speaking or writing","options":["present perfect tense","future tense","present tense","present continuous tense"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"The present continuous tense is used for something happening at the time you are speaking or writing, and it is formed with be plus the -ing form, as in I am dancing. Option C, the simple present, is for habits and regular events, A (present perfect) links a past action to the present, and B (future) looks ahead."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 413, $official_bank_source${"itemId":"f2e829cc-5bc2-573b-8f11-cbe22236173b","questionId":"58421205-5319-5ad7-b203-ada624dbf485","sourceKey":"bank:GST111:GST111-0325","payload":{"prompt":"The words tall, taller, tallest are examples of what kind of adjective?","options":["Concrete and abstract","Active","Non-gradable","Gradable"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"Tall, taller, tallest shows an adjective that can be expressed in degrees, just like big, bigger, biggest or very big, so it is a gradable adjective (D). Option C, non-gradable, is the opposite: it covers absolute qualities such as perfect, unique or fatal that cannot be graded. A and B are not classes of adjective."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 414, $official_bank_source${"itemId":"c021204f-29f1-5e24-9384-4d1e62537886","questionId":"5d8778d2-dc10-5b97-b173-cc9cffab0c49","sourceKey":"bank:GST111:GST111-0339","payload":{"prompt":"The part of a word to which other elements can be added is called--------","options":["Suffix.","Phrase.","Root or stem.","Prefix."],"correctOption":2,"section":"Grammar I: Word Classes and Phrases","explanation":"The root (or stem) is the part of a word to which other elements are attached; affixation adds prefixes and suffixes to a root word. Options A and D are the elements that get added, not the part they are added to, and B, a phrase, is a group of words rather than part of a word."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 415, $official_bank_source${"itemId":"6221c869-665d-5852-83b9-1b88076cfb57","questionId":"2885ffc4-b0ab-5028-9b55-77806dee6228","sourceKey":"bank:GST111:GST111-0343","payload":{"prompt":"In the sentence 'She walks briskly', the word 'briskly' is a/an ...","options":["adverb of frequency","adverb of manner","adverb of place","adverb of degree"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"In 'She walks briskly', the word briskly tells how the walking is done, so it is an adverb of manner (B). An adverb of frequency (A) would tell how often, place (C) would tell where, and degree (D) would tell to what extent."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 416, $official_bank_source${"itemId":"fad5e2e2-b5d2-504d-bbe6-c719cd9f55de","questionId":"917e2d55-9cc8-5e9b-9026-13925bdda230","sourceKey":"bank:GST111:GST111-0347","payload":{"prompt":"Grammatical hierarchy in English is structured in which of the following ways?","options":["sentence, phrase, clause, word and morpheme.","morpheme, word, clause, phrase and sentence.","sentence, clause, phrase, word and sentence.","morpheme, word, phrase, clause and sentence."],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"The grammatical units rank from smallest to largest as morpheme, word, phrase, clause and sentence, so D is correct. Option A reverses the order, B wrongly puts the clause before the phrase, and C reverses the order and repeats 'sentence'."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 417, $official_bank_source${"itemId":"fc3e6045-ca37-5b70-9287-5f3228bf726e","questionId":"ff052c1b-c670-5f88-ba07-0e5fd71c6efa","sourceKey":"bank:GST111:GST111-0358","payload":{"prompt":"In the sentence 'They lost some extremely valuable documents in the fire', the expression 'extremely valuable' is an example of a/an ...","options":["Adjective phrase","Noun phrase.","Prepositional phrase","Adverbial phrase"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"In 'extremely valuable documents', the adjective valuable is the head word, modified by the adverb extremely, and the whole phrase describes the noun documents, so it is an adjective phrase (A). Option D is tempting because extremely is an adverb, but it is not the head of the phrase, and B would need a noun as the head."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 418, $official_bank_source${"itemId":"419ecf6e-f6a4-5f9c-a875-896c8e82fc4f","questionId":"679a4634-663c-568d-8d27-9772e26de8fa","sourceKey":"bank:GST111:GST111-0368","payload":{"prompt":"In the sentence 'Mr Dokunboh thanked the lady', the phrase 'the lady' is the ...","options":["direct object of the verb","indirect object of the verb","subject of the verb","object complement"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"In 'Mr. Dokunboh thanked the lady', the lady receives the action of the verb, so she is the direct object (A). Option C is wrong because Mr. Dokunboh, who does the thanking, is the subject. Option B, the indirect object, would answer 'to or for whom', and there is only one object in this sentence."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 419, $official_bank_source${"itemId":"e4b66a0b-4e48-55ef-a8f9-65c7f7e9b2c9","questionId":"e63deb75-ef32-58a3-ac8e-1f40fde5b308","sourceKey":"bank:GST111:GST111-0373","payload":{"prompt":"In the sentence 'Tade travelled to Ibadan', the phrase 'to Ibadan' functions as an ...","options":["adverb of manner","adverb of place","adverb of frequency","adverb of time"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"In 'Tade travelled to Ibadan', the phrase to Ibadan tells where Tade travelled, so it is an adverb of place (B). It does not answer how (manner, A), how often (frequency, C) or when (time, D)."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 420, $official_bank_source${"itemId":"1debca59-95a5-58f4-86da-f9fd2896d71b","questionId":"c67a474a-8b2a-5fdf-b29d-4956fd5d5684","sourceKey":"bank:GST111:GST111-0375","payload":{"prompt":"Lexical and functional morphemes are sub-groups of---------","options":["Free morphemes","stem words","root words","Bound morphemes"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"Morphemes are first divided into free morphemes, which can stand alone as words, and bound morphemes, which must attach to a root. Free morphemes are then sub-grouped into lexical morphemes (content words like nouns, verbs and adjectives) and functional morphemes (grammar words like prepositions and conjunctions), so A is correct. Option D is wrong because bound morphemes are affixes such as prefixes and suffixes, and stems and roots (B, C) are not the parent category either."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 421, $official_bank_source${"itemId":"3e278491-f13a-52be-bbf3-d894d2241936","questionId":"494f43e6-635c-5519-a368-bd7d5e222f6d","sourceKey":"bank:GST111:GST111-0388","payload":{"prompt":"How many forms does state-of-being verbs and action verbs have","options":["5","7","2","9"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"Apart from the verb be, which has eight forms, state-of-being verbs and action verbs usually have five forms: the base, the third person singular present, the past tense, the past participle and the -ing form. So A is correct. Two forms (C) is too few, while seven and nine (B and D) are more than any ordinary English verb has."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 422, $official_bank_source${"itemId":"060713df-aefb-5e48-b71e-4fc247d48098","questionId":"47d4d577-8822-5b70-8442-bb287b185cca","sourceKey":"bank:GST111:GST111-0394","payload":{"prompt":"The study of the arrangement of constituents within a sentence is called-------","options":["Grammar.","Syntax.","Graphology.","Morphology."],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"Syntax studies how words are arranged and combined into phrases, clauses and sentences, which is exactly what the question describes (B). Grammar (A) is too broad, since it covers both how words are formed and how they are combined. Morphology (D) studies the internal structure of words, and graphology (C) deals with the writing system."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 423, $official_bank_source${"itemId":"fe2f90ae-cb15-564b-82e2-42c8feae3ff7","questionId":"535c1667-baa7-5839-b6b1-3fb3cbc6a693","sourceKey":"bank:GST111:GST111-0399","payload":{"prompt":"Mr. Dokunboh thanked the lady. (Note: intended underline is \"the lady\")","options":["subject of the verb","object complement","indirect object of the verb","direct object of the verb"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"In 'Mr. Dokunboh thanked the lady', the lady receives the action of the verb, so she is the direct object (D). Option A is wrong because Mr. Dokunboh, who does the thanking, is the subject. Option C, the indirect object, would answer 'to or for whom', and there is only one object here."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 424, $official_bank_source${"itemId":"dbc70a8a-0427-5d8f-8577-f14b8db84080","questionId":"081a6b6a-c530-504b-a55c-27fe405547db","sourceKey":"bank:GST111:GST111-0409","payload":{"prompt":"One of these is not a Correlative conjunctions","options":["even...then","both...and;","neither...nor;","either...or;"],"correctOption":0,"section":"Grammar I: Word Classes and Phrases","explanation":"The correlative conjunctions are both...and, either...or, just as...so, neither...nor, not only...but (also) and whether...or. 'Even...then' is not a recognised correlative pair, so A is the odd one out, while B, C and D are all genuine pairs."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 425, $official_bank_source${"itemId":"a07f623d-fa27-5717-87fa-4236881becb2","questionId":"6306f6a3-0ff9-59e7-9f52-02f1e8fd8895","sourceKey":"bank:GST111:GST111-0420","payload":{"prompt":"The man jogs regularly.","options":["adverb of place","adverb of time","adverb of manner","adverb of frequency"],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"In 'The man jogs regularly', the word regularly tells how often the man jogs, so it is an adverb of frequency (D). Manner (C) would answer how, time (B) would answer when, and place (A) would answer where."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 426, $official_bank_source${"itemId":"2ab65f83-3514-52bd-89b4-c2856a20522e","questionId":"c49c205b-8369-5d58-8bb1-541c265ab948","sourceKey":"bank:GST111:GST111-0437","payload":{"prompt":"One of these is not a type of Pronoun","options":["possessive pronouns","refractive pronouns","interrogative pronouns","reciprocal pronouns"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"The types of pronoun include personal, possessive, interrogative, relative, demonstrative, reciprocal, reflexive, intensive and indefinite pronouns. There is no class called refractive pronouns; the word is a distortion of reflexive, so B is the answer. Possessive, interrogative and reciprocal pronouns (A, C and D) are all genuine types, reciprocal ones being each other and one another."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 427, $official_bank_source${"itemId":"3b70fd0e-7611-5b6d-84f2-613aca43b4d3","questionId":"d93a43aa-4bcb-5ccc-990e-351fde46916d","sourceKey":"bank:GST111:GST111-0445","payload":{"prompt":"Wow! Oh no! and Watch it! are ___________","options":["prepositions","interjections","nouns","conjunctions"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"Interjections are words or phrases that express strong feelings, emotions or exclamation, like Wow! Oh no! and Watch it! (B). Prepositions and conjunctions (A and D) show relationships or join words, and nouns (C) name things, so none of them expresses sudden emotion in this way."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 428, $official_bank_source${"itemId":"85f4358a-e383-5a8f-b76e-e2e56f35f747","questionId":"ca156488-8130-5f14-ac46-dfd2dad82817","sourceKey":"bank:GST111:GST111-0466","payload":{"prompt":"Which of the following phrases contains an indefinite article?","options":["That house","A big fat hen","The Golden Globe awards.","My friend"],"correctOption":1,"section":"Grammar I: Word Classes and Phrases","explanation":"The articles are the (definite) and a or an (indefinite), so 'A big fat hen' contains the indefinite article a (B). Option C uses the definite article the, while that (A) is a demonstrative and my (D) is a possessive determiner."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 429, $official_bank_source${"itemId":"53f3bb20-0986-51d3-b78e-f34f4e827bfe","questionId":"6d2f4287-a73c-515f-a346-40d3ccbe1aaf","sourceKey":"bank:GST111:GST111-0477","payload":{"prompt":"Grammar is categorized into two major sections, namely;","options":["Lexis and morphology.","Syntax and semantics.","Syntax and phonetics.","Morphology and syntax."],"correctOption":3,"section":"Grammar I: Word Classes and Phrases","explanation":"Grammar is traditionally divided into morphology, the study of how words are formed, and syntax, the study of how words are combined into sentences (D). Option B is wrong because semantics is the study of meaning, not a branch of grammar, and C is wrong because phonetics studies speech sounds. Lexis (A) refers to vocabulary rather than grammatical structure."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 430, $official_bank_source${"itemId":"7fd0b58c-dacb-5864-8948-f3503705cad6","questionId":"fe913b07-8ece-54f0-a617-3e681d9aedd7","sourceKey":"bank:GST111:GST111-0113","payload":{"prompt":"One of these is not a minor sentence","options":["Gatekeeper wanted.","No fuel.","No vacancy","God bless you"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"Minor sentences are meaningful but grammatically incomplete structures whose missing parts can be recovered from context, such as Gatekeeper wanted, No fuel and No vacancy (options A, B and C). God bless you, option D, has a subject (God) and a finite verb (bless), so it is a complete major sentence, which makes it the one that is not a minor sentence."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 431, $official_bank_source${"itemId":"5ba7744e-988b-58b5-bdb9-097bf0ff6a28","questionId":"ef6dcb37-db8a-5e9f-abae-062dc52c667f","sourceKey":"bank:GST111:GST111-0133","payload":{"prompt":"A simple sentence has","options":["two clauses and no finite verb","one clause and contains only one finite verb","two clauses and contains only one finite verb","one clause and contains only two finite verb"],"correctOption":1,"section":"Grammar II: Clauses and Sentences","explanation":"A simple sentence makes a single statement, has only one clause and contains only one finite verb, as in The boy killed the snake, so B is correct. Options A and C describe two clauses, which would make the sentence compound, and D gives two finite verbs, which also means more than one clause."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 432, $official_bank_source${"itemId":"c9abd2a6-518c-51b5-a7f3-a5dd2e334b05","questionId":"5a33e432-46fd-5612-9c4c-4fbe32335b9a","sourceKey":"bank:GST111:GST111-0138","payload":{"prompt":"Another name for Adjective Clause is","options":["preemptive clause","restrictive clause","blackball clause","relative clause"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"A subordinate clause that modifies a noun the way an adjective does is called an adjectival clause or relative clause, because it is usually introduced by a relative pronoun such as who, whom, whose, which or that. So D is correct. A restrictive clause (B) is only one sub-type of relative clause, the defining kind, not another name for all adjective clauses, and A and C are not grammatical terms."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 433, $official_bank_source${"itemId":"3f8f860e-f9e3-5f87-b82d-c1b60cc3d37d","questionId":"47589b5b-3cf8-54e6-b63b-10029235ea68","sourceKey":"bank:GST111:GST111-0144","payload":{"prompt":"Interrogative sentences \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_","options":["ask questions","express strong emotion","make statements","give commands"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"Sentences are classified by function into declarative, interrogative, imperative and exclamatory, and an interrogative sentence asks a question, such as What were you doing this morning? So A is correct. Option B describes the exclamatory sentence, C describes the declarative, and D describes the imperative."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 434, $official_bank_source${"itemId":"871396bf-2150-5ce0-a48e-7756bfc20960","questionId":"b24b0352-58b3-575a-a8c9-ba1e02b18eed","sourceKey":"bank:GST111:GST111-0148","payload":{"prompt":"One of these is not a Type of Subordinate Clauses","options":["infinite Clause","the Non- finite Clause","the Finite Clause","the Verbless Clause"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"Subordinate clauses are classified by form into the finite clause (the verb changes with person, number and tense), the non-finite clause (the verb form stays the same) and the verbless clause (no verb at all). There is no such thing as an infinite clause in grammar, so A is the one that does not belong. Options B, C and D are all genuine types."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 435, $official_bank_source${"itemId":"48215cb0-08fa-5ab2-a1f3-8257fcfcf62c","questionId":"16e15808-14af-5270-a003-0a06331b2594","sourceKey":"bank:GST111:GST111-0161","payload":{"prompt":"Sentences can be grouped into all but one of the following types","options":["interrogative","exclamatory","declarative","interlocutory"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"Sentences are grouped by function into four types: declarative (statements), interrogative (questions), imperative (directives) and exclamatory (strong emotion). Interlocutory is a legal and conversational term, not a sentence type, so D is the odd one out. Options A, B and C all belong to the list."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 436, $official_bank_source${"itemId":"96e15ff3-cdbd-56d4-9443-1c9cc0bfa4e7","questionId":"8f3df6a0-576f-5411-89d6-793d20cc1235","sourceKey":"bank:GST111:GST111-0197","payload":{"prompt":"Declarative sentences end with a/an \\_\\_\\_\\_\\_","options":["exclamation point","period","comma","question mark"],"correctOption":1,"section":"Grammar II: Clauses and Sentences","explanation":"A declarative sentence is a statement, and it ends with a full stop or period, as in Our organisation trades in petroleum products. Option A (exclamation point) ends excited or emotional statements, D (question mark) ends direct questions, and C (comma) cannot end a sentence at all."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 437, $official_bank_source${"itemId":"0e45d117-5939-54c5-89ea-948605cb6c3c","questionId":"554a6181-ba1c-5386-8eae-02bad3b2cb43","sourceKey":"bank:GST111:GST111-0223","payload":{"prompt":"The major components of a sentence are","options":["nouns and adjectives","the subject and the predicate","a main clause and a subordinate clause","independent clause and dependent clause"],"correctOption":1,"section":"Grammar II: Clauses and Sentences","explanation":"Every sentence has two major components: the subject, which names the person or thing being talked about, and the predicate, which says something about that subject, as in Birds (subject) fly (predicate). Options C and D (main/subordinate or independent/dependent clauses) describe how complex sentences are built, not the basic parts every sentence has, and A (nouns and adjectives) are word classes, not sentence parts."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 438, $official_bank_source${"itemId":"7a70037d-502e-5ec9-bd63-bd2339001fbd","questionId":"38d76368-0375-5713-821b-6eadda45012f","sourceKey":"bank:GST111:GST111-0237","payload":{"prompt":"A finite clause contains one of the following","options":["two or more verbs","no verb at all","a verb that changes","a verb that remains unchanging"],"correctOption":2,"section":"Grammar II: Clauses and Sentences","explanation":"A finite clause contains a finite verb, a verb form that changes with number, person and tense (visit, visits, visited), so C is correct. Option D (a verb that remains unchanging) describes a non-finite clause, B (no verb) describes a verbless clause, and A (two or more verbs) is not a defining feature of any clause type."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 439, $official_bank_source${"itemId":"684c4b25-d966-5536-af2c-9cc2a4c5c731","questionId":"527e7b7f-17d3-5012-9afa-efe1f2abf064","sourceKey":"bank:GST111:GST111-0249","payload":{"prompt":"Which one of the following is a simple sentence","options":["Ngozi was at the scene, but she didn't witness the accident.","No smoking.","The boy killed the snake","The teacher asked a difficult question and no student could answer it."],"correctOption":2,"section":"Grammar II: Clauses and Sentences","explanation":"A simple sentence makes a single statement with only one finite verb, and The boy killed the snake is exactly that. Options A and D are compound sentences, with two clauses joined by but and and. Option B, No smoking, is a minor sentence because it lacks a subject and a finite verb."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 440, $official_bank_source${"itemId":"e64aa344-3b1f-51a0-b371-848921e152c7","questionId":"84816140-27be-5c1a-b4d2-6ea8847c5afa","sourceKey":"bank:GST111:GST111-0255","payload":{"prompt":"One of the following is not an imperative sentence","options":["Get out\\!","Look out\\!","Have a drink.","Oh, my goodness\\!"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"Oh, my goodness! is an exclamatory sentence, expressing strong emotion, so it is not imperative. Get out!, Have a drink. and Look out! (A, C and B) are imperatives, because they command, invite and warn."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 441, $official_bank_source${"itemId":"f0edd660-9c17-5aa9-86a3-e6aa863cc641","questionId":"02f13845-a329-55e7-a683-9312437cdc01","sourceKey":"bank:GST111:GST111-0265","payload":{"prompt":"Which clause patterns is reflected in this sentence : Kofi became the president.","options":["SVOC","SVA","SVOO","SVC"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"Kofi became the president follows the SVC pattern: Kofi is the subject, became is the verb, and the president is the subject complement because it refers to the same person as the subject. Option A (SVOC) would need an object as well as a complement, and C (SVOO) would need two objects, which this sentence does not have."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 442, $official_bank_source${"itemId":"8c0c2c93-031a-5e9b-9a91-d9c38fbd43af","questionId":"46bfcc2b-3cdf-5cee-973a-517ec0657ada","sourceKey":"bank:GST111:GST111-0289","payload":{"prompt":"In the sentence \"She hung onto his feet as if her life depended on it\", the clause \"as if her life depended on it\" is what type of clause?","options":["adverbial clause of manner","adjectival clause","relative clause of manner","verbal clause"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"In She hung onto his feet as if her life depended on it, the clause as if her life depended on it modifies the verb hung by saying how she held on, so it is an adverbial clause of manner. Options B and C would need the clause to describe a noun, which it does not, and D is not a recognised clause type."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 443, $official_bank_source${"itemId":"0704f8c3-4697-5ec3-80c2-95cc8b5859bb","questionId":"e9e09774-9242-5efd-ae10-39653ca78fd7","sourceKey":"bank:GST111:GST111-0328","payload":{"prompt":"A simple sentence occurring by itself can also be called","options":["glottal","colossal","clause","verbal"],"correctOption":2,"section":"Grammar II: Clauses and Sentences","explanation":"A simple sentence that stands by itself has one subject and one predicate, which is exactly what a clause is, so it can also be called a clause (C). Options A and B are not grammatical units at all, and verbal (D) describes a form of the verb, not a sentence."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 444, $official_bank_source${"itemId":"317758a0-cfd5-5ddf-a902-2c8dc7b4879e","questionId":"6128719f-3df3-5674-b915-0f3fdb22dbb3","sourceKey":"bank:GST111:GST111-0332","payload":{"prompt":"A complex sentence has","options":["one independent clause and one or more dependent clauses.","one independent clause and one dependent clause","two independent clauses and one dependent clause","two independent clauses and one or more dependent clauses"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"A complex sentence has one independent (main) clause and one or more dependent (subordinate) clauses, so A is correct. Option B is too narrow because a complex sentence may have more than one dependent clause. C and D describe sentences with two independent clauses, which are compound-complex sentences."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 445, $official_bank_source${"itemId":"08a4cdd4-21f3-5e0e-a813-a58c49d413a0","questionId":"224f92e0-2fa4-5440-adce-f7faddc85ee9","sourceKey":"bank:GST111:GST111-0340","payload":{"prompt":"How many basic clause patterns are there in the English simple sentence?","options":["4","7","8","6"],"correctOption":1,"section":"Grammar II: Clauses and Sentences","explanation":"There are seven basic clause patterns in the English simple sentence: SV, SVO, SVC, SVA, SVOO, SVOC and SVOA. So B is correct, and 4, 8 and 6 (A, C and D) are the wrong counts."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 446, $official_bank_source${"itemId":"ed0a4879-f090-52fd-859d-f0aba00787d8","questionId":"e7a889d0-5592-52b6-b9ce-53c6e485ec9e","sourceKey":"bank:GST111:GST111-0397","payload":{"prompt":"Which of these words cannot be used to introduce an adverb clause?","options":["although","nevertheless","when","if"],"correctOption":1,"section":"Grammar II: Clauses and Sentences","explanation":"Nevertheless is a conjunctive adverb, which links two independent clauses of equal status rather than making one clause dependent, so it cannot introduce an adverb clause (B). Although, when and if (A, C and D) are genuine subordinating conjunctions that introduce adverb clauses."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 447, $official_bank_source${"itemId":"f39ebf9a-76ab-513d-ada4-d02eed71d1c5","questionId":"2f6ee549-d1b4-5e08-9135-dd39e082c1d4","sourceKey":"bank:GST111:GST111-0400","payload":{"prompt":"Which clause patterns is reflected in this sentence : The man bought his wife a present.","options":["SVOO","SVOC","SVOA","SV"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"In 'The man bought his wife a present', the man is the subject, bought is the verb, his wife is the indirect object and a present is the direct object, which is the SVOO pattern (A). SVOC (B) would need a complement describing the object, and SVOA (C) would need an adverbial of time or place, neither of which appears here."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 448, $official_bank_source${"itemId":"ecaa1a87-dac3-5895-939d-37c9993fdd1f","questionId":"5094d574-20cb-58dd-b97e-4dd9ad287cc8","sourceKey":"bank:GST111:GST111-0403","payload":{"prompt":"Identify the imperative sentence below","options":["Take the bus home.","I don't believe that!","Did you take the bus home?","She walked quickly to the bus stop."],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"An imperative sentence gives a directive such as a command, instruction or piece of advice, usually with the subject 'you' understood, so 'Take the bus home.' is the imperative (A). Option B is an exclamatory sentence expressing strong feeling, C is an interrogative because it asks a question, and D is a declarative that simply makes a statement."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 449, $official_bank_source${"itemId":"d78bc7c7-111f-5ade-bbd5-f45a39b5136f","questionId":"12535230-cf09-5655-974f-91e95b3bccce","sourceKey":"bank:GST111:GST111-0404","payload":{"prompt":"Which of these sentences has a plural compound subject","options":["The man and his wife were present.","Hot lemonade and honey is good for a cold.","The MD and Chief Executive Officer of the company was introduced","Waiter is the rice and beans ready?"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"A compound subject joined by 'and' is plural, so 'The man and his wife' takes the plural verb were (A). In B, C and D the members are thought of as a single unit, such as one drink (lemonade and honey), one dish (rice and beans) or one person holding two titles, so those compound subjects are singular."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 450, $official_bank_source${"itemId":"1cfeb2e8-2805-5487-820c-a34e29e5730f","questionId":"6a5ff15b-fca6-519b-a74f-4346708989dd","sourceKey":"bank:GST111:GST111-0410","payload":{"prompt":"One of these is not a basic clause pattern in the English simple sentence","options":["SVA","SVCC","SVOA","SVO"],"correctOption":1,"section":"Grammar II: Clauses and Sentences","explanation":"The seven basic clause patterns are SV, SVO, SVC, SVA, SVOO, SVOC and SVOA. SVCC is not one of them because a clause does not take two complements in this way, so B is the answer. SVA, SVOA and SVO (A, C and D) are all genuine patterns."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 451, $official_bank_source${"itemId":"e33d1b48-a089-5811-83e4-e88b091e257d","questionId":"18ab668c-df0e-588f-80ae-1986c8638770","sourceKey":"bank:GST111:GST111-0440","payload":{"prompt":"She hung onto his feet as if her life depended on it. What type of clause is 'as if her life depended on it'?","options":["adjectival clause","verbal clause","adverbial clause of manner","relative clause of manner"],"correctOption":2,"section":"Grammar II: Clauses and Sentences","explanation":"In 'as if her life depended on it', the clause modifies the verb hung by telling how she held on, so it is an adverbial clause of manner (C). An adjectival clause (A) would modify a noun, not a verb, and 'relative clause of manner' (D) is not a recognised clause type. Option B is not a clause type either."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 452, $official_bank_source${"itemId":"84398f53-077c-5f14-9541-7909525c8001","questionId":"b562a667-54a2-5ef9-afc2-97bd4ec51202","sourceKey":"bank:GST111:GST111-0450","payload":{"prompt":"Which clause patterns is reflected in this sentence : Jesus wept.","options":["SV","SVC","SVO","SVA"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"In 'Jesus wept', Jesus is the subject and wept is the verb, with no object, complement or adverbial, so the pattern is SV (A). SVO (C) would need something receiving the action, and SVC and SVA (B and D) would need a complement or an adverbial after the verb."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 453, $official_bank_source${"itemId":"8e654e96-eee0-59ed-b78e-4209656f69bb","questionId":"ce926c9b-605d-51f0-a757-61b461d9d9e2","sourceKey":"bank:GST111:GST111-0470","payload":{"prompt":"Which of the following is NOT a coordinating conjunction used to join the clauses of a compound sentence?","options":["so that","but","and","yet"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"So that is a subordinating conjunction that makes one clause depend on another, which produces a complex sentence, so it is not used in compound sentences (A). Compound sentences use coordinating conjunctions such as and, but, or, nor, for and yet, which is why B, C and D are not the answer."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 454, $official_bank_source${"itemId":"ced605ba-e8ee-5ff3-914d-0b272fd8d4a1","questionId":"cdbe567c-a827-5a20-82e0-2a00362c6c45","sourceKey":"bank:GST111:GST111-0481","payload":{"prompt":"Which clause patterns is reflected in this sentence : The priest pronounced the couple man and wife.","options":["SVOC","SVA","SVC","SVOO"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"In 'The priest pronounced the couple man and wife', the priest is the subject, pronounced is the verb, the couple is the object and man and wife is the object complement, which describes the same people as the object. That is the SVOC pattern (A). SVOO (D) would need two different objects, such as a receiver and a thing given, while SVA and SVC (B and C) have no object at all."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 455, $official_bank_source${"itemId":"3b596f28-1d0c-5560-8af7-2155a736786c","questionId":"24338763-25da-5fd5-9b81-45b6d38cdb2e","sourceKey":"bank:GST111:G111N2-001","payload":{"prompt":"Which of the following is a non-finite clause?","options":["because he visited us","having died down","who came here today","while in prison"],"correctOption":1,"section":"Grammar II: Clauses and Sentences","explanation":"A non-finite clause has a verb that does not change for number, person or tense, and it often has no subject; \"having died down\" fits this exactly. \"While in prison\" is tempting, but it has no verb at all, so it is a verbless clause, not a non-finite one."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 456, $official_bank_source${"itemId":"513df50e-24ef-5f58-b4e1-73e1fe16c80d","questionId":"5e704c62-7fdf-58b7-8d42-0ac82fe53e64","sourceKey":"bank:GST111:G111N2-002","payload":{"prompt":"In the sentence \"While in prison, he wrote a novel\", the clause \"while in prison\" is best described as a","options":["finite clause","non-finite clause","verbless clause","noun clause"],"correctOption":2,"section":"Grammar II: Clauses and Sentences","explanation":"\"While in prison\" has no verb and no subject of its own; the missing subject is understood from the main clause (he), which makes it a verbless clause. It is not a non-finite clause, because a non-finite clause still contains a verb form such as \"being repaired\" or \"to leave\"."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 457, $official_bank_source${"itemId":"b292ae7d-a882-5c2c-bdef-2bf8b0566ee1","questionId":"2288e18e-7710-5697-89b2-5245efed8a55","sourceKey":"bank:GST111:G111N2-003","payload":{"prompt":"What does the sentence \"The students who arrived late were locked out\" mean?","options":["None of the students arrived on time","All the students were locked out","The students came late because they were locked out","Only the students who came late were locked out"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"Without commas, \"who arrived late\" is a defining relative clause: it identifies which students are meant, so only some of them, the late ones, were locked out. If the clause were set off by commas (\"The students, who arrived late, were locked out\"), it would be non-defining and would mean that all the students were locked out."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 458, $official_bank_source${"itemId":"2abde2ae-b7d8-5d95-8d37-d2adb74f36e6","questionId":"2b41e2c0-e33f-5ac4-a06b-6f9ab8efe7b8","sourceKey":"bank:GST111:G111N2-004","payload":{"prompt":"Which relative pronoun can NOT be used to introduce a non-defining relative clause?","options":["that","whose","which","who"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"A non-defining clause adds extra information about a noun that is already known, is set off by paired commas, and does not allow \"that\" (so \"Chike, that had never been ...\" is wrong). \"Which\" is a tempting choice, but it can introduce a non-defining clause, for example \"The car, which was new, broke down\"."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 459, $official_bank_source${"itemId":"0a68732e-f006-5ed7-8c6c-d77e39bcd0a1","questionId":"7708a6cb-ab16-5aff-8f6e-721d8cc09e6c","sourceKey":"bank:GST111:G111N2-005","payload":{"prompt":"In the sentence \"The fact that she is not here worries everyone in the department\", the clause \"that she is not here\" functions as","options":["a direct object","a subject complement","a prepositional complement","an appositive"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"The noun clause \"that she is not here\" explains what \"the fact\" is, so it stands in apposition to that noun. It is not a direct object, because it does not come after a verb as the thing acted on; it is attached to the noun \"fact\"."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 460, $official_bank_source${"itemId":"a19256c9-a8ab-51bd-8444-5ccc5072f21d","questionId":"587da658-c216-5ce2-b22a-83214f7faa4d","sourceKey":"bank:GST111:G111N2-006","payload":{"prompt":"A sentence that has two or more main clauses and at least one subordinate clause is called a","options":["compound sentence","compound-complex sentence","complex sentence","multiple sentence"],"correctOption":1,"section":"Grammar II: Clauses and Sentences","explanation":"A compound-complex sentence combines the features of both types: two or more main clauses plus at least one subordinate clause. A complex sentence is the closest wrong choice, but it has only one main clause with one or more subordinate clauses."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 461, $official_bank_source${"itemId":"fdb1211d-ebde-57ac-a44e-53cb866e7120","questionId":"b46a3017-f52e-5525-b7ab-6b0052154009","sourceKey":"bank:GST111:G111N2-007","payload":{"prompt":"A major sentence made up of three or more independent clauses is known as a","options":["complex sentence","compound sentence","multiple sentence","compound-complex sentence"],"correctOption":2,"section":"Grammar II: Clauses and Sentences","explanation":"When three or more independent clauses are joined together, the result is a multiple sentence. A compound sentence is the nearest wrong answer, but it joins two independent clauses with coordinating conjunctions or conjunctive adverbs."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 462, $official_bank_source${"itemId":"1487f0ce-bae8-513f-afea-de6e1b0c7b8c","questionId":"00d54404-daf5-5c21-8e32-dc1b7bde4855","sourceKey":"bank:GST111:G111N2-008","payload":{"prompt":"The imperative sentence \"Let me see.\" expresses which type of directive?","options":["Pleading","Suggesting","Meditating","Permitting"],"correctOption":2,"section":"Grammar II: Clauses and Sentences","explanation":"\"Let me see\" is the speaker thinking aloud, which is the meditating type of directive. It may look like \"Let's go by bus\", but that one is suggesting, because it proposes an action to others; \"Suit yourself\" is permitting and \"Have mercy\" is pleading."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 463, $official_bank_source${"itemId":"a7c494c4-7d35-5f9b-bedf-54a9f9b069d0","questionId":"8d295053-bd8c-562c-a253-faed61e53243","sourceKey":"bank:GST111:G111N2-009","payload":{"prompt":"Which clause pattern does the sentence \"The plane took off at eight o'clock\" show?","options":["SVA","SVC","SVOA","SVO"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"\"The plane\" is the subject, \"took off\" is the verb and \"at eight o'clock\" is an adverbial of time, giving SVA. SVOA is tempting, but there is no object here, since nothing receives the action of taking off."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 464, $official_bank_source${"itemId":"c267dbea-284a-5ea8-8b41-dd19557fc916","questionId":"f1e0a05a-0550-599d-bacb-58292ebee81d","sourceKey":"bank:GST111:G111N2-010","payload":{"prompt":"Choose the correct verb: Either you or I ____ responsible for the shop in Balogun market.","options":["are","were","is","am"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"With \"either ... or\" joining mixed members, the verb follows the concord of proximity and agrees with the nearest subject, which is \"I\", so \"am\" is correct. \"Are\" is the tempting choice because \"you\" takes \"are\", but \"you\" is not the member closest to the verb."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 465, $official_bank_source${"itemId":"713d5e5a-afe4-50a7-a292-8ce06680de09","questionId":"b8a553f3-82bd-570a-86df-7be98385208a","sourceKey":"bank:GST111:G111N2-011","payload":{"prompt":"Choose the correct verb: The Manager, together with all his staff, ____ at the bank's end-of-year party in Victoria Island.","options":["was","were","have been","are"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"A singular subject followed by \"together with\" still takes a singular verb, because the phrase after \"together with\" is not part of the subject; the subject is \"The Manager\". \"Were\" is tempting because \"all his staff\" sounds plural, but those words do not control the verb."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 466, $official_bank_source${"itemId":"a8d60dda-1593-56bb-8a1f-cbbaa741ff97","questionId":"654865b7-bffd-55ff-8547-7cadc5771f00","sourceKey":"bank:GST111:G111N2-012","payload":{"prompt":"Which of the following sentences is grammatically correct?","options":["The number of students in the department is rising.","The number of students in the department are rising.","A number of students is absent from the test.","A number of students was absent from the test."],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"\"The number of\" refers to a single figure, so it takes a singular verb (is), while \"a number of\" means several and takes a plural verb (were or are). The sentence with \"The number of students ... are rising\" is the most tempting wrong option, but it wrongly treats \"the number\" as plural."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 467, $official_bank_source${"itemId":"4199d488-56ae-5afd-8e05-e88c6cd67391","questionId":"3c041eea-c747-58b4-96be-5e1f77802a7c","sourceKey":"bank:GST111:G111N2-013","payload":{"prompt":"\"The jury has reached a verdict\" takes a singular verb because the jury is thought of as one unit. This type of agreement with collective nouns is called","options":["pronoun-antecedent concord","concord of proximity","tense concord","notional concord"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"Collective nouns follow notional concord: the verb is singular when the group acts as a unit and plural when its members act as individuals (\"The jury are still arguing\"). Concord of proximity is a different rule, used when a verb agrees with the nearest member of an \"either ... or\" or \"neither ... nor\" subject."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 468, $official_bank_source${"itemId":"dee4c530-1858-5cfc-838e-e76e6c2b193b","questionId":"a20db94d-febd-5b44-b1a9-1ddc66519f1d","sourceKey":"bank:GST111:G111N2-014","payload":{"prompt":"\"Returning home late one night, a snake bit Olu.\" This sentence contains which fault?","options":["A run-on sentence","A padded sentence","A comma splice","A dangling modifier"],"correctOption":3,"section":"Grammar II: Clauses and Sentences","explanation":"The phrase \"Returning home late one night\" should modify Olu, but it sits next to \"a snake\", making it seem the snake was returning home; this is a dangling modifier. It can be corrected as \"Returning home late one night, Olu was bitten by a snake\". It is not a comma splice, because a comma splice joins two complete sentences with only a comma."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 469, $official_bank_source${"itemId":"0be2c567-f009-52cb-9371-e58704ab1687","questionId":"189de8c0-31d4-5999-a84a-977e370cd8df","sourceKey":"bank:GST111:G111N2-015","payload":{"prompt":"A student writes \"Because I was hungry.\" as a complete sentence. This is an example of","options":["a sentence fragment","a simple sentence","an imperative sentence","a minor sentence"],"correctOption":0,"section":"Grammar II: Clauses and Sentences","explanation":"\"Because\" makes the clause dependent, so \"Because I was hungry.\" is an incomplete thought standing alone, which is a sentence fragment and is unacceptable. A minor sentence such as \"No vacancy.\" is tempting, but a minor sentence is acceptable because its missing parts can be recovered from the context."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 470, $official_bank_source${"itemId":"238d32db-576a-5a0a-a361-b5b36204c0e1","questionId":"4a9d7028-1871-588e-9949-68c7645ca866","sourceKey":"bank:GST111:GST111-0015","payload":{"prompt":"Weeding as a library term means","options":["Dusting the shelves","Clearing the tables","Screening library users","Removing outdated books"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"In library work, weeding means removing outdated, damaged or no-longer-useful books from the collection so the shelves hold current, relevant material, which is option D. The word borrows the gardening idea of pulling out unwanted plants. Options A and B are ordinary cleaning jobs and C is about controlling users, none of which is what librarians mean by weeding."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 471, $official_bank_source${"itemId":"0c94e4bb-51bc-580c-8e68-d6903c215cc2","questionId":"08475156-e7a8-5449-b9e1-b47f1ec60d00","sourceKey":"bank:GST111:GST111-0026","payload":{"prompt":"Books are placed on reserve to","options":["Minimize wear and tear","To prevent them from getting to unregistered users","To preserve them for serious-minded library-going students","To facilitate a rapid and wider circulation of scarce materials among users"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"Books are placed on reserve so that scarce or heavily demanded material can circulate quickly among many users instead of being borrowed by one person for weeks, which is option D. Reserved items are rare and valuable, are not placed on long loan and must be consulted in the reading room. Options A, B and C are wrong because reserving is about sharing access, not protecting books from wear, keeping them from unregistered users or saving them for only serious students."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 472, $official_bank_source${"itemId":"4fdb4c86-6f25-5b6d-baea-2a6ffc047b4f","questionId":"c6af6028-6906-52e0-8caa-17096c3de1a6","sourceKey":"bank:GST111:GST111-0027","payload":{"prompt":"The circulation section of the library deals with","options":["Borrowing and returning of books","The distribution of books among affiliated libraries","The acquisition of new materials","The cataloguing and classification of acquired materials"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"The circulation section handles the lending and return of books, so A is correct; the circulation desk is also where you can ask for help locating a book. Option B is interlibrary lending, a separate service, while acquiring new materials (C) and cataloguing and classifying them (D) are done by the acquisitions and cataloguing sections."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 473, $official_bank_source${"itemId":"e700f576-4735-5084-89b0-f0ccdb5da6f4","questionId":"16482db8-f1fa-5546-bfce-711b5719fd8a","sourceKey":"bank:GST111:GST111-0028","payload":{"prompt":"Reference books are those","options":["Used to write research papers","That cannot be borrowed","That are quite bulky","They contain a wealth of materials which cut across various disciplines"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"Reference books such as dictionaries, encyclopaedias and handbooks are consulted for specific facts rather than read from cover to cover, so libraries keep them in the reference section and they cannot be borrowed, which is option B. Option A is too narrow, C (bulky) is irrelevant, and D describes general collections rather than what makes a book a reference book."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 474, $official_bank_source${"itemId":"5cedf52c-2f41-5281-be30-ba76d0925b0b","questionId":"cf4db145-8a83-5235-ae27-ba119de60341","sourceKey":"bank:GST111:GST111-0031","payload":{"prompt":"The encyclopedia is","options":["A book or a set of books on Britain","A book or a set of books on America","A book or a set of books on one or all branches of knowledge","A book or a set of books compiled by chambers"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"An encyclopaedia is a book or set of books that gives background and current information on one or all branches of knowledge, so C is correct. Encyclopaedias can be general, like Britannica or Americana, or subject-based, like an encyclopaedia of philosophy. Options A, B and D mistake the names Britannica, Americana and Chambers for the definition; those are just titles or publishers."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 475, $official_bank_source${"itemId":"137b639f-d71e-58ac-b29b-b14f96691535","questionId":"2e32801e-c1d0-5814-bd7a-f6d584c4a1f4","sourceKey":"bank:GST111:GST111-0032","payload":{"prompt":"Books put in the reserve section of the library","options":["Are intended for use by library staff only","Cannot be borrowed","Can be borrowed for a full semester","Out of the reach of students"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"Books in the reserve section cannot be borrowed out of the library, so B is correct. They are rare or valuable, kept on closed access, and must be consulted in the reading room, although photocopying is allowed. Option C is wrong because reserve items are never placed on long loan, and they are meant for students, not staff only (A), so they are not out of students' reach (D)."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 476, $official_bank_source${"itemId":"ead71c1a-f158-5031-9c7d-e41f495b2414","questionId":"0a74fbdc-0e40-5625-9ce7-b30182ecb091","sourceKey":"bank:GST111:GST111-0101","payload":{"prompt":"One of the attributes of information is .................","options":["Citation","Printing","Relevance","Non-reliability"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"Relevance, option C, is one of the attributes of good information, alongside availability, accuracy, reliability and timeliness. Citation (A) and printing (B) are things done with information, not qualities of it, and non-reliability (D) is the opposite of reliability, which is a required attribute."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 477, $official_bank_source${"itemId":"53ac0030-b5dc-5667-861f-daa7639a187c","questionId":"ff5e8272-f5b5-5492-8f54-6e3077df23fc","sourceKey":"bank:GST111:GST111-0104","payload":{"prompt":"An example of a specialized dictionary is ..........","options":["Webster english dictionary","Oxford English dictionary","Dictionary of American slang","None"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"The Dictionary of American Slang, option C, is a specialized dictionary because it is compiled for a particular purpose and covers only one area of vocabulary. Other specialized examples include the Dictionary of the Yoruba Language and the Dictionary of Modern Politics. Webster's (A) and the Oxford English Dictionary (B) are general dictionaries, so D, none, is also wrong."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 478, $official_bank_source${"itemId":"1705a03e-f47c-5918-adb2-c234701a13cc","questionId":"1d073446-6f06-58c6-819d-e8b5e773b1f5","sourceKey":"bank:GST111:GST111-0115","payload":{"prompt":"A secondary source is one that ............. and ................ a primary source.","options":["Critiques and disqualify","Reviews and manipulates","All","Analyzes & explains"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"A secondary source analyzes, critiques, reviews or explains a primary source, and is written by scholars who have studied the original and drawn their own conclusions. So D, analyzes and explains, matches the definition. Options A and B use words like disqualify and manipulates that are not part of the definition, so C, all, is also wrong."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 479, $official_bank_source${"itemId":"4613a692-19e4-5547-b0d2-617c4c8778f0","questionId":"990a83f3-c30b-53ce-837b-1398e984be4c","sourceKey":"bank:GST111:GST111-0122","payload":{"prompt":"Radio, Tape-recorder, Gramophone and Audio cassette player are examples of ............","options":["Visual materials","Audio materials","Audio-visual materials","Electronic material"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"Radio, tape-recorder, gramophone and audio cassette player all deliver information through sound alone, so they are audio materials, option B; in the University of Lagos library they are found in the Music Library. Visual materials (A), such as maps and pictures, appeal to the eye only, audio-visual materials (C) like television and LCD projectors combine sound and picture, and electronic material (D) is too broad a label for this group."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 480, $official_bank_source${"itemId":"f2c30f83-9b29-5cce-be7c-7d5b4ef9137a","questionId":"a09a5057-7d3a-55bc-8362-500bab498844","sourceKey":"bank:GST111:GST111-0125","payload":{"prompt":"Article/journal search can be carried out or done in these sections of the library","options":["Serials and E-library","Cataloguing Section","Acquisition section","University Librarian's office"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Journal and article searches are done in the Serials section, which holds publications issued in successive parts such as journals, newspapers and magazines, and in the E-library, where electronic journals and databases are accessed. So A is correct. The Cataloguing section (B) and Acquisition section (C) are back-office units that process materials, and the University Librarian's office (D) is administrative."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 481, $official_bank_source${"itemId":"1207574a-45f8-5240-a5da-283ace7280fa","questionId":"940377e5-fec0-5ed3-b841-c40d2c40b6b9","sourceKey":"bank:GST111:GST111-0129","payload":{"prompt":"Index may be published as part of a book or separately","options":["Partially false","Partially true","False","True"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"The statement is true, option D: an index may be published as part of a book, like the index at the back of that book, or separately, like a periodical index that stands alone. Options A, B and C treat the statement as wholly or partly false, but both forms of publication really exist, with no qualification needed."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 482, $official_bank_source${"itemId":"e4527f61-5066-500f-b0f7-b780c861d8ca","questionId":"4e0541f8-bd21-51f5-aa9d-5f87ca78c74d","sourceKey":"bank:GST111:GST111-0140","payload":{"prompt":".............. is consulted mostly by speech makers and writers","options":["Book of Quotation","Biographical book","Manual","Book of reference"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"A book of quotation supplies quotations on various subjects by particular authors, and it is mostly consulted by speech makers and writers, so A is correct. A biographical book (B) gives facts about individuals, a manual (C) explains how to do things, and a book of reference (D) is too general to be the answer."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 483, $official_bank_source${"itemId":"d56b9545-63b5-5303-b4d5-08fe1a2060c5","questionId":"02a98128-c10d-5697-a841-f8510b29f783","sourceKey":"bank:GST111:GST111-0143","payload":{"prompt":"................. are allowed access into Gandhi Library","options":["External users only","Researchers and Post graduate students","Library staff only","None of the listed"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"Access to the University of Lagos Research and Bibliographic Department, known as the Gandhi Library, is strictly for researchers and postgraduate students, so B is correct. Undergraduates are admitted only on presenting a letter from a head of department, supervisor or course lecturer. Options A and C name groups that are not the ones admitted, and D is wrong because a specific group is named."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 484, $official_bank_source${"itemId":"b901336c-67e1-5f8a-ae30-1c899b7570a2","questionId":"f06c81d7-8d16-517f-9404-4fd9b961e5e5","sourceKey":"bank:GST111:GST111-0146","payload":{"prompt":"Publications issued in successive parts, at regular intervals, and intended to be continued indefinitely are .......","options":["Serials collection","None","Serials report","Collective report"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"A publication issued in successive parts, at regular intervals, and usually intended to continue indefinitely is a serial, so A, serials collection, is correct. Newspapers, magazines, journals, indexes and abstracts are examples. Serials report and collective report (C and D) are not library terms, and B is wrong because the definition fits a serial exactly."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 485, $official_bank_source${"itemId":"e3566d3f-cec8-59ff-b76b-7e1c330e9a4c","questionId":"cf828391-59f1-56b8-8741-964c698f4673","sourceKey":"bank:GST111:GST111-0150","payload":{"prompt":"Africana materials are not loanable and users are not permitted to take them out of gandhi library","options":["Partially true","True","False","Partially false"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"The statement is true, option B: Africana materials in the Gandhi Library (the Research and Bibliographic Department) are not loanable and cannot be taken out of that department. They may only be consulted there, although photocopying is allowed. Options A, C and D treat the statement as wholly or partly false, which is not correct."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 486, $official_bank_source${"itemId":"d954456a-34db-51fb-ae23-d60454d657e7","questionId":"9aa6c1d8-a711-50a4-bff5-86f7f5893f80","sourceKey":"bank:GST111:GST111-0151","payload":{"prompt":"Example of Audio-visual materials is","options":["Map","Book","Television","Journal"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"Television, option C, is an audio-visual material because it combines sound and picture; other examples are LCD projectors, computers and VCD players. A map (A) is a visual material only, while a book (B) and a journal (D) are print resources."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 487, $official_bank_source${"itemId":"182d488a-b12a-5fa3-b2bc-b92b65ddea32","questionId":"2725f2d9-408d-5ec3-b6e7-894e13a5532a","sourceKey":"bank:GST111:GST111-0154","payload":{"prompt":"The person who provides reference services is called...........","options":["Reference Librarian","Chief Librarian","University Librarian","Library Officer"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"The librarian whose job is to help users find information and answer enquiries at the reference section is the reference librarian, option A; the title describes the service offered. A chief librarian (B) and a university librarian (C) are titles for the overall head of the library, and a library officer (D) is a general staff designation rather than the person who provides reference services."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 488, $official_bank_source${"itemId":"73aca271-f16b-54a6-af17-18cb5c27aa18","questionId":"4b4ad0c7-e13b-573e-b53b-eb6f30af412f","sourceKey":"bank:GST111:GST111-0160","payload":{"prompt":"................. is not a type of abstract","options":["Informative abstract","Indicative abstract","Review abstract","Evaluative abstracts"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"The three recognized types of abstract are the indicative, informative and evaluative abstracts. Review abstract (option C) is not one of them, so it is the answer. Options A, B and D are all genuine types."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 489, $official_bank_source${"itemId":"b6d63747-4219-56c6-b5f2-9c96ae715b7d","questionId":"ed209f36-ad3c-52d4-b696-19d590710adf","sourceKey":"bank:GST111:GST111-0165","payload":{"prompt":"The Research and Bibliographic section of the library houses ..........","options":["PhD theses","Both A and D","Law books","Old and current newspapers"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"The Research and Bibliographic Department, known as the Gandhi Library, holds research materials including PhD theses and old and current newspapers dating back to 1930, so B, which combines A and D, is correct. Choosing A or D alone leaves out the other holding. Law books (C) are not what this department is known for."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 490, $official_bank_source${"itemId":"390f0658-a68a-555c-80a4-6afc809f4376","questionId":"8adffd28-7ed8-5a76-999d-0cbf97efd4fd","sourceKey":"bank:GST111:GST111-0168","payload":{"prompt":"Reference materials include the following EXCEPT:","options":["Encyclopaedia","Journals","Indexes","Dictionaries"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"Journals are serials, meaning they are published in successive parts at regular intervals, so they are not classed as reference materials. Reference materials are things like dictionaries, encyclopaedias, indexes, biographies, handbooks and manuals, which you consult for quick facts. That is why A, C and D are all reference materials and B is the exception."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 491, $official_bank_source${"itemId":"1239080e-2a23-542c-8129-e7467746dbe4","questionId":"8dd4a520-75b5-521c-9a34-d08925061c5d","sourceKey":"bank:GST111:GST111-0181","payload":{"prompt":"The ability to recognize when information is needed is called .........","options":["Information knowledge","Data","Information explosion","Information literacy"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"Information literacy is the ability to locate, retrieve, evaluate and apply information, and it includes recognising when information is needed (this is the American Library Association's definition). Option B (data) means raw facts, C (information explosion) is the rapid growth in the amount of information available, and A is not a recognised term."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 492, $official_bank_source${"itemId":"c5b86059-06f7-5672-ab0b-4d308cfc186a","questionId":"92f34410-eafe-54db-bb8f-b9784562d120","sourceKey":"bank:GST111:GST111-0187","payload":{"prompt":"The main kinds of electronic materials in most libraries are:","options":["e-books and e- periodicals","pamphlets and cassettes","cards and newspapers","pamphlets and videotapes"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Electronic library materials are things like electronic books, electronic journals, electronic images and full-text records from the internet, so e-books and e-periodicals fit. Pamphlets, cassettes and videotapes (in B and D) are print or audio-visual items, not electronic ones, and option C (cards, newspapers) lists print formats."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 493, $official_bank_source${"itemId":"9f55f94a-c3f8-5139-aa01-fac776c1701e","questionId":"573879d8-d71c-5d3d-a57b-72d1bb818908","sourceKey":"bank:GST111:GST111-0196","payload":{"prompt":"Generally, information sources are divided into which of the following categories?","options":["Both C and D","Tertiary","Secondary","Primary"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Information sources fall into two categories: primary sources (first-hand accounts such as original research reports, diaries or novels) and secondary sources (works that analyse or explain a primary source). So the correct choice is A, which combines C and D. Choosing C or D alone leaves out the other category, and B (tertiary) is not one of the two categories."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 494, $official_bank_source${"itemId":"5d440daa-f079-5dc8-b752-fb04eeaceb70","questionId":"c7d415d7-d6ba-58e3-a590-c4f332ed7a5e","sourceKey":"bank:GST111:GST111-0202","payload":{"prompt":"............. collections are not expected to be read from cover to cover like books","options":["Reference","Abstract","Americana","Africana"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Reference collections, such as dictionaries, encyclopaedias, indexes and fact sources, are consulted for specific pieces of information, so they are not meant to be read from cover to cover. Option D (Africana) is a research collection of materials on Africa, and its books and theses are studied like other books. Option B (abstract) is only one type of reference source, not a library collection, and C (Americana) is the name of an encyclopaedia, not a collection."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 495, $official_bank_source${"itemId":"8170f264-5a21-5506-8957-0025ef937221","questionId":"14009a56-f441-523f-8876-a48ead305015","sourceKey":"bank:GST111:GST111-0211","payload":{"prompt":"The two sources of information are:","options":["Books and Online sources","Library and Internet sources","Print and electronic sources","Primary and secondary sources"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"The two sources of information are primary and secondary. Primary sources give first-hand accounts such as original research, letters or novels, while secondary sources analyse, review or explain a primary source. Option C (print and electronic) is tempting because it is a real division of library resources by format, but it divides them by medium, not by kind of source. A and B are informal groupings, not the standard categories."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 496, $official_bank_source${"itemId":"e19747c9-c5b8-5259-9930-51ea45e87421","questionId":"08267278-fe9f-55bb-a8e8-b30824b25545","sourceKey":"bank:GST111:GST111-0215","payload":{"prompt":"Publications conveying recent original research and observation are known as..............","options":["Tables","Translations","Textbooks","Journals"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"Journals are serials valued for the currency of their content, which is why recent original research and observations are published in them. Option C (textbooks) summarise established knowledge rather than report new findings, and A and B (tables, translations) are not publication types for original research."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 497, $official_bank_source${"itemId":"7803ad25-e918-52a4-986d-e8a0e590c807","questionId":"c609e0b2-668b-5c56-94f2-835e77e294bf","sourceKey":"bank:GST111:GST111-0222","payload":{"prompt":"Another word for data is......................","options":["Information","Fact","None of the above","Opinion"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"Data means facts, or facts, figures or instructions in a form that can be processed, so another word for data is fact. Option A (information) is tempting, but information is data that has been processed to improve the user's knowledge, so the two are not the same. Option D (opinion) is a personal view, not raw facts."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 498, $official_bank_source${"itemId":"379fdbcd-91ef-551f-ae00-7e5579de150d","questionId":"7b961fb1-707b-5217-b4a8-dfcba4c4bda2","sourceKey":"bank:GST111:GST111-0226","payload":{"prompt":"Faculty handbook is an example of small ready reference source","options":["Partially false","True","No","False"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"The statement is true: a handbook is a small ready reference source that gives facts on places, techniques, institutions and subjects, and Faculty and Departmental Handbooks are standard examples. Options A, C and D all deny or partly deny that."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 499, $official_bank_source${"itemId":"7681df2f-868a-50d8-9f7f-a52da576b35f","questionId":"3d29a02a-1549-569f-b82b-06f87111deee","sourceKey":"bank:GST111:GST111-0238","payload":{"prompt":"The following are characteristics of information except .........","options":["Accessibility","News","Accuracy","Reliability"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"The characteristics of good information are availability or accessibility, accuracy, reliability, timeliness and relevance. News is one form that information can take, not a quality it has, so B is the exception, while A, C and D are all characteristics."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 500, $official_bank_source${"itemId":"d6884eec-7d2e-5e6c-bbe3-076d063a976e","questionId":"249c596b-c8e4-5050-8d0b-8cfc5ccad39d","sourceKey":"bank:GST111:GST111-0245","payload":{"prompt":"Information can be in form of ................","options":["Numbers","All","Graphs& charts","Texts"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"Information can take many forms: oral, textual, numeric, bibliographic, graphical (graphs and charts) and multimedia. Since numbers (A), graphs and charts (C) and texts (D) are all valid forms, the right answer is B, all of them. Picking any one alone leaves out the others."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 501, $official_bank_source${"itemId":"352c6c4a-1191-5a5e-9f90-d5e8da5d05a6","questionId":"b4e02ac1-4a95-5d09-bf8d-15d2df83aac4","sourceKey":"bank:GST111:GST111-0252","payload":{"prompt":"Where information is not provided on time for the purpose for which it is required, it becomes ........","options":["Useful","Relevant","Relevant& useful","Irrelevant"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"Timeliness is a quality of good information: it must be provided on time for the purpose it is needed for. If it comes late, it becomes irrelevant, so D is correct. Options A, B and C all describe good information, which is the opposite of what late information turns into."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 502, $official_bank_source${"itemId":"d8123016-21cb-5fe9-a57c-2689e1b8e42e","questionId":"91ca97c5-5082-59ef-b161-813d249e65a3","sourceKey":"bank:GST111:GST111-0257","payload":{"prompt":"Multimedia information pertains to the use of diversified medium of communication such as","options":["Text","Graphs","Audio-visual","Numbers"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"Multimedia information uses a mix of media of communication such as audio, visual and audio-visual, so C is correct. Text, graphs and numbers (A, B and D) are each a single type of information, textual, graphical and numeric, rather than a mix of media."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 503, $official_bank_source${"itemId":"57b8b289-ec76-53d4-9413-23985f39dd2e","questionId":"0ecb93d3-2e70-5abb-81eb-d172afabecaf","sourceKey":"bank:GST111:GST111-0267","payload":{"prompt":"An ............. is a summary of a publication or article","options":["Abstract","Anthology","Atlas","Index"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"An abstract is a summary of a publication or article that gives enough bibliographic detail to trace the original. Option D (index) only points to where information can be found, B (anthology) is a collection of writings, and C (atlas) is a book of maps."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 504, $official_bank_source${"itemId":"c4d3a19f-327b-5227-a4f4-010995ee402e","questionId":"3d275286-6af3-543e-9169-c1f2f64c84dd","sourceKey":"bank:GST111:GST111-0270","payload":{"prompt":"Notable reference collection includes all of these EXCEPT......................","options":["Facts sources","Dictionaries","Books","Encyclopaedia"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"General books are not part of the reference collection, because reference materials are not read from cover to cover the way books are. Notable reference collections include dictionaries, encyclopaedias, fact sources, biographies, indexes and abstracts, so A, B and D are all included and C is the exception."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 505, $official_bank_source${"itemId":"e03f31a1-8424-5114-b30d-c0954325d8ab","questionId":"13a959ad-8010-541b-84b8-1744c88d5745","sourceKey":"bank:GST111:GST111-0287","payload":{"prompt":".................. is not a type of dictionary","options":["Subject dictionary","Anthem dictionary","General dictionary","Specialized dictionary"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"The three types of dictionary are general dictionaries, specialised dictionaries and subject dictionaries. There is no such thing as an anthem dictionary, so B is the one that is not a type, while A, C and D are all real types."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 506, $official_bank_source${"itemId":"1b37f8b4-5c41-5e56-9d11-eff7b5aeb891","questionId":"a2f152fa-264b-54d3-9a6e-f05ee80c498b","sourceKey":"bank:GST111:GST111-0293","payload":{"prompt":"Enquiries on how to access any of the resources in a library can be made at the ........... Section","options":["Reference","Akintunde Ojo Building","Serials","Readers' Services"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"Enquiries on how to access any of the library's resources are made at the Readers' Services point, so D is correct. Option B is a building, not a service point, and A (Reference) and C (Serials) are collections rather than the enquiry desk."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 507, $official_bank_source${"itemId":"3de4c55b-e8b4-5844-84b5-7cf312921e72","questionId":"847031ca-dd26-545f-b29a-e96b4c1bb74b","sourceKey":"bank:GST111:GST111-0310","payload":{"prompt":"Biographical sources are reference materials that provide individual information such as .....","options":["All of these","Date of birth","Place of birth","Career achievements"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Biographical sources give information on individuals such as date of birth, place of birth, education and career. Since B, C and D are all things they provide, A (all of these) is the complete answer, and picking one alone leaves out the others."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 508, $official_bank_source${"itemId":"01c2357d-9c2a-5227-b531-38c86cb5c82d","questionId":"7de02e25-0d16-5faa-bb73-89516242ac36","sourceKey":"bank:GST111:GST111-0315","payload":{"prompt":"Africana collection is found in ...............","options":["Serials","Gandhi Library","Reserved collection","Reference collection"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"At the University of Lagos Library, the Africana collection is housed in the Research and Bibliographic Department, known as the Gandhi Library, in the basement of the main library. Options C and D are separate collections on the ground floor, and A (Serials) is the collection of journals and periodicals."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 509, $official_bank_source${"itemId":"2099c6c6-d16a-5219-8a08-a395f5cd82a4","questionId":"c42f49aa-ff5c-5b40-b0ad-acac398b0230","sourceKey":"bank:GST111:GST111-0316","payload":{"prompt":"Which of the following is not a secondary source of information?","options":["Digest","Textbooks","Encyclopaedias","Thesis"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"A thesis is a primary source: it is original research produced by the researcher and counts as grey literature. Textbooks, encyclopaedias and digests (B, C and A) compile, explain or review other people's work, which makes them secondary sources, so D is the one that is not secondary."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 510, $official_bank_source${"itemId":"c2c7ad20-5a32-56ab-9aaa-30e8e9b664c3","questionId":"5d47d3c7-0023-5a39-bc45-7136f5b5cd3c","sourceKey":"bank:GST111:GST111-0318","payload":{"prompt":"Electronic resources allows for ............ usage of resources at the same time","options":["Multiple","Restricted","Single","Complex"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Electronic (non-print) resources allow multiple people to use the same material at the same time, unlike a printed book that only one person can hold at once, so A is correct. Option C (single) describes how a print copy is used, and B and D do not describe this feature."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 511, $official_bank_source${"itemId":"e3d8387b-3a6f-5ce8-8341-33fa66575b8d","questionId":"a3ee913f-e727-5489-be4b-de84dbe484f6","sourceKey":"bank:GST111:GST111-0326","payload":{"prompt":"The biographical source 'International Who's Who' is an example of a/an ....... source.","options":["National and current","Universal & current","International and local","National & local"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"International Who's Who is a universal and current biographical source, because it covers notable people from all over the world and is kept up to date. Options A and D describe sources limited to one country, such as Africa Who's Who or Newswatch Who's Who. Option C, 'international and local', is not a category used for biographical sources."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 512, $official_bank_source${"itemId":"c3d0b6ef-1e25-5902-9503-6a47145f8b90","questionId":"1193c977-9ada-5f5b-b0eb-8ce9121b30ef","sourceKey":"bank:GST111:GST111-0331","payload":{"prompt":"Directories, handbooks, yearbooks and almanacs are ............. sources","options":["None of these","Bibliographical","Geographical","Fact"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"Directories, handbooks, yearbooks and almanacs are fact sources: reference materials that give facts on a wide range of current issues. Option B refers to lists of books and articles on a subject, and C covers maps, atlases and gazetteers, so neither matches these four."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 513, $official_bank_source${"itemId":"06810ffb-fe05-5174-9615-3e38ec893820","questionId":"aef2fda9-ec6e-51f1-a842-56c766825ac7","sourceKey":"bank:GST111:GST111-0361","payload":{"prompt":"Reference materials contain facts and rarely contain opinions.","options":["True","False","Partially true","Partially false"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"The statement is true: reference materials mainly contain facts and rarely contain opinions, which is why we consult them for specific information instead of reading them from cover to cover. That rules out False (B) and the hedged options C and D."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 514, $official_bank_source${"itemId":"3d3f7f91-40a0-5172-8cba-d05b3366143e","questionId":"1e3d4c5b-3ed6-5a38-8707-64b96bbfc45b","sourceKey":"bank:GST111:GST111-0369","payload":{"prompt":"An index serves as .............. to required information","options":["Pointer","Indicator","Pointer and indicator","None"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"An index serves as both an indicator and a pointer to required information, giving a systematic guide to the contents of a book or text, so C is the complete answer. Options A and B each capture only half of the definition, which is why C is the best choice."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 515, $official_bank_source${"itemId":"7f213142-4358-52c3-80bc-ac0d4f315885","questionId":"8d02c381-4ddd-5049-a069-f799d54e13f7","sourceKey":"bank:GST111:GST111-0381","payload":{"prompt":"University of Lagos Library has ..................library resources","options":["All of these","Print resources","Non-print resources","Audio-visual resources"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"The University of Lagos Library has three categories of resources: print, non-print and audio-visual. Since all three are present, 'All of these' (A) is correct. Options B, C and D each name only one category, so each is incomplete on its own."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 516, $official_bank_source${"itemId":"4f9f05a6-5ea0-566b-9c9d-be7628d8c9d2","questionId":"2723a8da-f026-580c-9ccb-a7f9d8ade90a","sourceKey":"bank:GST111:GST111-0389","payload":{"prompt":"The following are categories of resources in the library except .........","options":["Serials collection","Reserved collection","American collection","Africana collection"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"The print collections of the University of Lagos Library are Africana, Reference, Reserved, Serials and Recent accessions. There is no American collection, so C is the odd one out, while A, B and D are genuine categories."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 517, $official_bank_source${"itemId":"9ca2ba05-9a4b-5a40-baa9-67d2b53360fa","questionId":"4e0c6401-4ba4-5c20-b7f3-1dd221690d6d","sourceKey":"bank:GST111:GST111-0391","payload":{"prompt":"Ability to locate, retrieve and evaluate information is known as.........","options":["Information support","Information asset","Information literacy","Information discovery"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"Information literacy is the ability to locate, retrieve, evaluate and apply information, and to recognise when information is needed, so C is correct. Information discovery (D) sounds close but covers only finding information, not evaluating and using it. Options A and B are not terms used for this skill."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 518, $official_bank_source${"itemId":"cbe6384f-594e-5d01-968d-b9195eb4fa0f","questionId":"adb25553-f770-5bf3-94e2-83078187cbec","sourceKey":"bank:GST111:GST111-0393","payload":{"prompt":"................. provide information on places and physical features","options":["Bibliographical source","None","Fact source","Geographical source"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"Geographical sources provide information on places such as towns and countries and on physical features such as mountains and rivers; examples are maps, atlases, gazetteers and travel guides. Bibliographical sources (A) list books and articles, and fact sources (C) give facts on current issues, so neither deals with places and physical features."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 519, $official_bank_source${"itemId":"4c6b183e-9471-58eb-8e50-6233a0274eb5","questionId":"dd05f964-dd1a-5359-aa47-6bef941a7174","sourceKey":"bank:GST111:GST111-0395","payload":{"prompt":"\"Map of Nigeria\" and \"Travel guide\" are examples of ..................","options":["Biographical source","Fact source","Bibliography","Geographical source"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"Maps such as the Map of Nigeria, atlases, gazetteers and travel guides are geographical sources, which give information on places and physical features (D). Option B, fact sources, covers directories, handbooks, yearbooks and almanacs, not places. Biographical sources (A) are about people, and a bibliography (C) is a list of publications."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 520, $official_bank_source${"itemId":"3e3c9c12-b87f-58d0-9e95-6eaa33d37d3e","questionId":"f7958842-2b89-5c3c-aa2f-9f2f34cd67f9","sourceKey":"bank:GST111:GST111-0396","payload":{"prompt":"Collections published on Africa or African authors can be found in the University Library at the ........section","options":["Africana collection","Reserved collection","Serials","Reference collection"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Africana collections are print materials published on Africa by African and non-African authors, housed in the Research and Bibliographic Department (Gandhi Library), so A is correct. The reserved collection (B) holds rare and valuable materials across disciplines, serials (C) are periodicals, and the reference collection (D) holds dictionaries, encyclopedias and similar tools."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 521, $official_bank_source${"itemId":"73dfbde3-a5f1-5f2c-81f4-62bed6465266","questionId":"2f3023e5-7b5b-58d5-b6d8-ffa6ffa8fa32","sourceKey":"bank:GST111:GST111-0413","payload":{"prompt":"A Closed Access System of collection in a library refers to ...............","options":["Restricted access","Materials to be borrowed for home use","Materials to be retrieved directly by the user","Materials not to be photocopied"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"In a closed access system, users may not take materials from the shelves themselves; the desk officer fetches the material once the bibliographic details are given, so access is restricted (A). Option C describes the opposite, open access, and B and D are about borrowing and copying rules, not about how materials are accessed."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 522, $official_bank_source${"itemId":"4bf1fa47-32bb-5cb9-9ff3-12f1e2c64d78","questionId":"a4aa14eb-4e0c-5ac7-b407-0d41b2886c76","sourceKey":"bank:GST111:GST111-0417","payload":{"prompt":"Fact sources at the University of lagos Library are housed at the ..........","options":["MTN Library","Boulos Library","Reference section","Automation Section"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"Fact sources such as directories, handbooks, yearbooks and almanacs are reference materials, so they are housed at the reference section of the library (C). The MTN Connect Library (A) and the Automation Section (D) deal with electronic, non-print resources, and the Boulos Library (B) is not where fact sources are kept."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 523, $official_bank_source${"itemId":"c6d2a5fd-9cbf-5e39-b26d-d0d0c1d620b3","questionId":"6de998bb-865d-5faf-8385-3bac7cba8655","sourceKey":"bank:GST111:GST111-0421","payload":{"prompt":"Types of libraries include all of these EXCEPT ..................","options":["Public","Special","Reserved","Academic"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"Public, academic and special libraries, along with school and private libraries, are types of library. Reserved (C) is not a type of library but a collection within a library, holding valuable and rare materials on closed access. A law or court library, for example, is a kind of special library (B)."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 524, $official_bank_source${"itemId":"f7204022-290b-55ba-9e11-69c00bb1fdcd","questionId":"4e049a11-25ab-5ee6-ad94-9aa7d0b81924","sourceKey":"bank:GST111:GST111-0431","payload":{"prompt":"Reserved collections in University of lagos Library are run on ............. access system","options":["Closed","Open","Self-service","Reserve"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Reserved collections run on a closed access system: a user requests an item by giving its bibliographic details, and the material is fetched and used within the reading room (A). Open access (B) and self-service (C) would let users take materials from the shelves themselves, which is not allowed for reserved items. 'Reserve' (D) is the name of the collection, not the access system."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 525, $official_bank_source${"itemId":"a334a554-3b42-5c3a-ac7b-cf40fef8fe15","questionId":"10f68433-209e-5eae-b7af-2ac8a9e3aebd","sourceKey":"bank:GST111:GST111-0436","payload":{"prompt":"University of lagos Library has newspapers dating as far back as .........","options":["1860","1920","1930","1960"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"The Gandhi Library holds newspapers, old and current, dated as far back as 1930, including the West African Pilot, so C is correct. Options A, B and D give other dates: 1860 (A) is far too early, and 1960 (D) would leave out the pre-independence papers the library holds."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 526, $official_bank_source${"itemId":"a27c7aa3-5691-54b7-a566-4315315ca810","questionId":"95872953-e830-5687-9aea-5ce63da3fe58","sourceKey":"bank:GST111:GST111-0439","payload":{"prompt":"Electronic journals, electronic images, library software, CD-ROMS are ................","options":["Non-print resources","Print and non-print","Audio-visual resources","Print resources"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Electronic books, electronic journals, electronic images, library software and CD-ROMs are non-print resources, managed by the Automation Section and accessed in the E-Library (A). Audio-visual resources (C) refer to aids like projectors, televisions and tape recorders, and B and D wrongly include print materials."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 527, $official_bank_source${"itemId":"b72b5993-4a46-58d3-ab82-c52e0c658141","questionId":"bfa6fe48-46a2-5de1-aca4-7fa89366652d","sourceKey":"bank:GST111:GST111-0444","payload":{"prompt":"Libraries perform all of these functions EXCEPT .....................","options":["Organisation","Preservation","Book selling","Acquisition"],"correctOption":2,"section":"Understanding the Library and Information Resources","explanation":"All libraries perform the basic functions of selection, acquisition, organisation, preservation and dissemination of information resources. Book selling is a commercial activity, not a library function, so C is the odd one out, while A, B and D are all library functions."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 528, $official_bank_source${"itemId":"369561dc-ee83-557c-bd2e-4c1343037746","questionId":"597eb893-43e2-5b21-bdf1-e4c55419440c","sourceKey":"bank:GST111:GST111-0448","payload":{"prompt":"Which of the following are types of index?","options":["Book index, periodical index and newspaper index","Indicative, informative and evaluative indexes","General, specialised and subject indexes","Primary and secondary indexes"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Indexes are pointers to published information, and they include the book index, the index to collections, the periodical index and the newspaper index (A). Option B is tempting, but indicative, informative and evaluative are the types of abstract, not index. General, specialised and subject (C) are types of dictionary, and primary and secondary (D) are sources of information."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 529, $official_bank_source${"itemId":"8ea3f5f5-43a9-5e47-8c30-b93236dc025c","questionId":"5b87f293-908c-56e4-992c-c95d81f30acf","sourceKey":"bank:GST111:GST111-0454","payload":{"prompt":"Yearbooks are also known as ........","options":["Annual","Dictionary","Handbook","Directory"],"correctOption":0,"section":"Understanding the Library and Information Resources","explanation":"Yearbooks are published once a year to record the facts and events of that year, which is why they are also called annuals (A). Handbooks and directories (C and D) are separate kinds of fact source alongside yearbooks, not other names for them, and a dictionary (B) deals with words, not yearly facts."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 530, $official_bank_source${"itemId":"3ff952eb-d2b5-56e5-95bf-52c479136f2f","questionId":"dfb96b82-36b6-552b-9a62-69cbdcffa11f","sourceKey":"bank:GST111:GST111-0473","payload":{"prompt":"An index serves as .............. to required information","options":["A full-text copy","Pointer and indicator","None","A summary"],"correctOption":1,"section":"Understanding the Library and Information Resources","explanation":"An index is a directional aid that points to and indicates where information can be found, so it serves as a pointer and indicator (B). It does not give the full text of the material (A), and a brief summary of a document (D) is an abstract, not an index."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 531, $official_bank_source${"itemId":"1dcd7eef-62e8-50a0-9cb3-ad31a54c5881","questionId":"c4feeaef-20a4-524a-8e0e-b351fb45a5e1","sourceKey":"bank:GST111:GST111-0480","payload":{"prompt":"Dictionaries are used as quick ------- sources in the library","options":["Publication","Manual","Serial","Reference"],"correctOption":3,"section":"Understanding the Library and Information Resources","explanation":"Dictionaries are reference materials, consulted quickly for specific information such as spelling, meaning and pronunciation, and housed at the reference section of the library (D). Serial (C) refers to publications issued in successive parts, like journals and newspapers, and publication and manual (A and B) are not the category dictionaries belong to."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 532, $official_bank_source${"itemId":"fd348cdd-8682-52b6-afbe-687b2a082e01","questionId":"c25aba99-0bce-50e5-b392-c18b8abcdf29","sourceKey":"bank:GST111:GST111-0029","payload":{"prompt":"The system of classification in the University of Lagos main library is","options":["The call mark","The dewey decimal system","The library of congress system","The card catalogue"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"The University of Lagos main library organizes its items using the Library of Congress (LC) classification scheme, so C is correct. LC uses letters A to Z for the main classes with numbers added. Option B, the Dewey Decimal system, is a different scheme, while a call mark (A) and the card catalogue (D) are tools for locating books, not classification systems."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 533, $official_bank_source${"itemId":"7f6e0eaf-26be-578f-960e-d2fdc9748f5d","questionId":"18c22671-223b-507c-9503-10bb141774d1","sourceKey":"bank:GST111:GST111-0030","payload":{"prompt":"One of the following is not part of the card catalogue in library","options":["Index card","Author card","Subject","Title card"],"correctOption":0,"section":"Information Retrieval Tools","explanation":"The manual card catalogue is arranged by author, title and subject, so author cards (B), subject cards (C) and title cards (D) are all part of it. An index card (option A) is not a type of catalogue card, which makes it the odd one out and the correct answer."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 534, $official_bank_source${"itemId":"a9c3925a-4d88-5129-92ab-a9c6fb761600","questionId":"d351f6be-6bc4-5980-af3a-91f0f47a0bdb","sourceKey":"bank:GST111:GST111-0080","payload":{"prompt":"The Dewey Decimal classification system assigns numbers in the following manner","options":["000 - 909","001 - 099","010 - 990","000 - 999"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"The Dewey Decimal system divides all knowledge into ten main classes numbered from 000 to 999, so D is correct, with 000 for general works up to 900 for history and geography. Options A, B and C give ranges that stop short of the full three-digit span. Note that the UNILAG main library uses the Library of Congress scheme rather than Dewey."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 535, $official_bank_source${"itemId":"0c6d8d36-e304-5319-8226-44205aac226f","questionId":"731c1a6e-8e54-5546-a961-22bb0fc7d830","sourceKey":"bank:GST111:GST111-0081","payload":{"prompt":"In the library of congress classification system, law and languages take the following letters","options":["A and K","L and P","K and P","A and P"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"In the Library of Congress system, K stands for Law and P for Language and Linguistics, so law and languages take K and P, option C. Option B is wrong because L is the class for Education, not Law, and options A and D wrongly include A, which is the class for General Works."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 536, $official_bank_source${"itemId":"af390b49-ae7b-5deb-92fe-4882ae2646a8","questionId":"7eff6e9c-369b-54e9-b81a-168fcdee7a3f","sourceKey":"bank:GST111:GST111-0116","payload":{"prompt":"An --------- summarizes the accurate content and presentation of a document","options":["Abstract","Electronic source","Index","Advance search"],"correctOption":0,"section":"Information Retrieval Tools","explanation":"An abstract, option A, is a brief summary of the contents of a book, article, thesis or conference paper that tells the user what the document contains without reading it from beginning to end. An index (C) only points to where information can be found, an electronic source (B) is a format rather than a summary, and advanced search (D) is a searching technique."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 537, $official_bank_source${"itemId":"f4628aca-24a6-5da8-af92-a8d7cab1c9ae","questionId":"560410ed-e533-56dc-9cf1-00314448f391","sourceKey":"bank:GST111:GST111-0121","payload":{"prompt":"Mixed notation refers to the use of letters of the alphabet as well as .............","options":["Arabic alphabets","Roman numerals","Arabic numerals","Greek symbols"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"Mixed notation means combining letters of the alphabet with Arabic numerals (0 to 9), as the Library of Congress classification does, which is why it is called alpha-numeric. So C is correct. Roman numerals (B) and Greek symbols (D) are not used in this scheme, and Arabic alphabets (A) is a confusion, since the scheme uses the ordinary letters A to Z."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 538, $official_bank_source${"itemId":"d8d6ec46-af74-5021-863a-b807ad655d35","questionId":"ffafb7da-c902-5b77-b346-40fa8af0f222","sourceKey":"bank:GST111:GST111-0128","payload":{"prompt":"Letter T is assigned to books on .......... in the Library of Congress Classification Scheme","options":["Arts","Technology","Science","Medicine"],"correctOption":1,"section":"Information Retrieval Tools","explanation":"In the Library of Congress scheme, the letter T is assigned to Technology, option B. Arts come under N (Fine Art), Science under Q and Medicine under R, so options A, C and D are wrong."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 539, $official_bank_source${"itemId":"dd1384ac-82dc-531c-a522-b912db4a8b3b","questionId":"8ff6ac46-5139-589a-86fa-2f36f5f41af4","sourceKey":"bank:GST111:GST111-0134","payload":{"prompt":"Arrangement in the library catalogue is in \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_ order","options":["Chronological","Triangular","Alphabetical","Decimal"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"A library catalogue is arranged by author, title and subject, and its entries are filed in alphabetical order so users can look up a name or heading quickly, which is option C. Chronological order (A) would arrange by date, which is not how catalogues work. Triangular (B) is not an arrangement at all, and decimal (D) refers to a classification scheme for shelving, not the catalogue."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 540, $official_bank_source${"itemId":"d1ab9bf3-1fb7-5ceb-bd9c-efac7c336580","questionId":"f98ae421-477d-5957-b5c6-a5a1f8dc4388","sourceKey":"bank:GST111:GST111-0137","payload":{"prompt":"Information can be evaluated using the following criteria EXCEPT","options":["Accuracy","Relevancy","Size","Currency"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"Information is evaluated using criteria such as currency, relevancy, authority, accuracy and purpose. Size (option C) is not one of them, since a long book or article is not more credible just because it is bigger. Accuracy (A), relevancy (B) and currency (D) are all genuine evaluation criteria."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 541, $official_bank_source${"itemId":"91f732fc-5639-5cdb-9536-ff925e4dc320","questionId":"ef541c40-cfb1-5395-a60e-eb1ba870e79f","sourceKey":"bank:GST111:GST111-0153","payload":{"prompt":"Arrangement of materials on the shelves is done using\\_\\_\\_\\_\\_\\_\\_\\_\\_\\_","options":["Catalogue","Nominal roll","Classification scheme","Planned steps"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"Materials on the shelves are arranged using a classification scheme, option C. The University of Lagos main library uses the Library of Congress Classification Scheme (and the National Library of Medicine scheme at the College of Medicine), so books are shelved by their classification call numbers. A catalogue (A) is tempting, but it is the tool you search to find the call number, not the system that arranges the shelves. Options B and D are not library tools."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 542, $official_bank_source${"itemId":"c302311c-9067-5c38-9aca-fbc96abeb797","questionId":"1b847786-0c37-5862-8798-3e11a9538836","sourceKey":"bank:GST111:GST111-0200","payload":{"prompt":"Criteria to evaluate credibility of Information resources are; currency, authority, ...... and ......","options":["Relevancy & intelligence","Strategy & accuracy","Relevancy & accuracy","None"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"The criteria for judging information resources are currency, relevancy, authority, accuracy and purpose. With currency and authority already given, the missing two are relevancy and accuracy, so C is correct. Option A pairs relevancy with intelligence and B pairs accuracy with strategy, and neither of those is a criterion. D is wrong because a correct pair is listed."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 543, $official_bank_source${"itemId":"6b8aff80-fe67-5dca-af3b-f1385fb18bd1","questionId":"7e72aa51-6357-5c24-817c-99bb92ae549d","sourceKey":"bank:GST111:GST111-0206","payload":{"prompt":"A library's entire holding is held in a manual database called --------","options":["Book box","Check list","Library holdings","Library catalogue"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"The library catalogue is the index and essential tool for retrieving library resources, and it gives access to everything the library holds. It exists as a manual card catalogue and as the Online Public Access Catalogue (OPAC). Options A and B (book box, check list) are not library tools, and C (library holdings) is just the name for the collection itself, not the database that records it."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 544, $official_bank_source${"itemId":"a0b57501-f385-53f6-aa35-1839ae284b3e","questionId":"d69db7a2-e776-523a-a61c-425088fd1d78","sourceKey":"bank:GST111:GST111-0228","payload":{"prompt":"One of the major benefits of using library databases is ............","options":["The fast internet speed","That they are subscribed to by the library to support students' assignments and research","All of the above","The value you get for your money"],"correctOption":1,"section":"Information Retrieval Tools","explanation":"A major benefit of library databases is that they are designed by publishers or aggregators and subscribed to by the library to support student assignments and research, and they are more organised and easier to cite than general web results. Options A and D (internet speed, value for money) are not benefits of this kind, and C cannot be right since those two are wrong."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 545, $official_bank_source${"itemId":"4ecb5974-d8b7-5c65-93ac-2f5635041546","questionId":"c1380980-a8b9-5618-aeb9-8b9d4dc1770b","sourceKey":"bank:GST111:GST111-0244","payload":{"prompt":"Ranking of articles retrieved from databases is by ...........","options":["No of times the search was conducted","All of the above","The number of records","Date and relevance"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"Databases mostly rank results chronologically by date, with the most recent records first, and by relevancy, based on how often and how prominently the search terms appear in a record. Options A (number of times the search was run) and C (number of records) are not ranking methods, so B (all of the above) is also wrong."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 546, $official_bank_source${"itemId":"0c65d18b-5e9d-5e32-b737-c6e37db80b9b","questionId":"867ef24a-55ff-5f43-81a0-b0e95cac9a21","sourceKey":"bank:GST111:GST111-0256","payload":{"prompt":"Which of these letters of the alphabet cannot be found in the Library of Congress Classification Scheme?","options":["Letter G","Letter S","Letter C","Letter O"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"In the Library of Congress scheme, main classes are given letters of the alphabet, but O, X and Y are reserved for future expansion, so there is no Class O. Options A, B and C are all used: G is Geography and Anthropology, S is Agriculture and C is History."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 547, $official_bank_source${"itemId":"d10d56eb-e62b-5ede-946d-4433c6e4c6b1","questionId":"54db52ce-f50f-541a-b1bb-18300077f4bb","sourceKey":"bank:GST111:GST111-0296","payload":{"prompt":"The various tools for accessing information are called ...............","options":["Information guides","Information keys","Information banks","Information retrieval tools"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"The tools used to access information, such as library catalogues, the OPAC, indexes, abstracts and bibliographies, are called information retrieval tools. Options A, B and C (information guides, keys and banks) are not the terms used for these tools."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 548, $official_bank_source${"itemId":"a5377a19-811f-5d92-a9b6-6ddcccdc86ca","questionId":"bd236046-9e7a-5daa-af65-fd6b0eb7f208","sourceKey":"bank:GST111:GST111-0342","payload":{"prompt":"Law books in the University of Lagos Library can be found in.............","options":["Class H","Class K","Class G","Class M"],"correctOption":1,"section":"Information Retrieval Tools","explanation":"Law books in the University of Lagos Library are found in Class K, because K is the Law class in the Library of Congress scheme the library uses. Options A, C and D are other classes: H is Social Science, G is Geography and Anthropology, and M is Music."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 549, $official_bank_source${"itemId":"98a495ce-c13f-5dc3-85c7-550a9065ec1e","questionId":"28be301a-79c4-516c-8424-ae4a9be76bc0","sourceKey":"bank:GST111:GST111-0350","payload":{"prompt":"UNILAG students have remote access to UNILAG Library online resources via","options":["Matric number","The telephone directory","Hall of residence","UNILAG Library website"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"UNILAG students reach the library's databases and e-resources through the UNILAG Library website, using a password for some fee-based databases when connecting from outside the campus network. A matric number, the telephone directory and a hall of residence (A, B and C) are not gateways to the online resources."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 550, $official_bank_source${"itemId":"e8ecbf23-52a5-5d67-bb87-7652c2d6bbc8","questionId":"9afce08b-75f7-509f-9108-d996ff2d1ad8","sourceKey":"bank:GST111:GST111-0363","payload":{"prompt":"The URL of a website accredited to a post-secondary institution or institution of higher learning usually ends with ..........","options":[".com",".gov",".org",".edu"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"The .edu ending is used only by accredited post-secondary institutions, so D is correct. The other endings are open to wider groups: .com (A) can be bought by anyone, .gov (B) belongs to government, and .org (C) is for organisations of any kind."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 551, $official_bank_source${"itemId":"6e80ea0e-9a51-5e39-ad51-83c726b896ce","questionId":"19f0aeae-8b44-5b0b-aa87-afaa98d74788","sourceKey":"bank:GST111:GST111-0371","payload":{"prompt":"The number generated when a library material is catalogued is called ...........","options":["Library number","Book number","Cataloguing number","Call number"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"The number generated when a material is catalogued is the call number, also known as the call mark, which you need to find the book on the shelf. So D is correct. Library number, book number and cataloguing number (A, B and C) are not the technical term used in the library."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 552, $official_bank_source${"itemId":"5d25d69e-66b9-536c-bd61-6ceeb9ae9d94","questionId":"39f2dd01-8de9-5b9a-b4b0-cf8861ab5f4b","sourceKey":"bank:GST111:GST111-0374","payload":{"prompt":"Any information retrieved from the Internet can be considered accurate","options":["True","Partially true","False","Yes"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"The statement is false: anyone with access can put false information online and there are no general rules on web accuracy, so information from the Internet must always be evaluated before you trust it (C). Options A, B and D all accept the claim in some form, which is risky."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 553, $official_bank_source${"itemId":"dd2188ba-13ca-599a-9018-4fa61de64713","questionId":"3c1e3755-257d-527d-a056-dcab5c91fe08","sourceKey":"bank:GST111:GST111-0377","payload":{"prompt":"Books on Sociology in the University of Lagos Library can be found in ........","options":["Shelf TA","Shelf HM","Shelf NA","Shelf HC"],"correctOption":1,"section":"Information Retrieval Tools","explanation":"The University of Lagos main library uses the Library of Congress scheme, where class H is Social Science and the sub-class HM is Sociology (General), so B is correct. HC is Economic History and Conditions, which makes D wrong, and TA and NA fall under Technology and Fine Art, not the social sciences."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 554, $official_bank_source${"itemId":"7f93c03a-957c-5e2f-a572-e30ffd2eeca7","questionId":"b5797702-e047-5fa5-aff1-b74053598446","sourceKey":"bank:GST111:GST111-0384","payload":{"prompt":"The acronym 'OPAC' means ................","options":["Online primary access catalogue","Online Public Access Catalogue","Online private access catalogue","None"],"correctOption":1,"section":"Information Retrieval Tools","explanation":"OPAC stands for Online Public Access Catalogue, the electronic version of the library catalogue, which can be searched by title, author, series and keywords. Options A and C change 'Public' to 'primary' or 'private', which is wrong because the catalogue is open to all library users."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 555, $official_bank_source${"itemId":"83b43841-fa4a-527b-a4ad-c73958749012","questionId":"2d1b4e8b-d950-5e40-8508-4022a28158f1","sourceKey":"bank:GST111:GST111-0411","payload":{"prompt":"One can search the library catalogue for information materials using all EXCEPT .........","options":["Language","Title","Author","Subject"],"correctOption":0,"section":"Information Retrieval Tools","explanation":"The manual catalogue is searched by author, title and subject, and the OPAC adds series and keywords. Language is not an access point of the library catalogue, so A is the odd one out, while B, C and D are standard ways of searching."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 556, $official_bank_source${"itemId":"7d65c508-526b-5766-80b7-2a674c25c97f","questionId":"1b1e6dcc-33b0-51dc-b40d-07e30a88fae8","sourceKey":"bank:GST111:GST111-0446","payload":{"prompt":"The Classification Scheme used for classifying and arranging library books in the University of Lagos Library is:","options":["American Library Classification Scheme","University Classification Scheme","Library of Congress Classification Scheme","Cataloguing and Classification Scheme"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"The University of Lagos main library arranges its items by the Library of Congress (LC) classification scheme, which uses the letters A to Z for the main classes (C). Options A and B are not real schemes, and D, cataloguing and classification, describes the general activity rather than a named scheme."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 557, $official_bank_source${"itemId":"59988e88-fe27-5644-a9e1-5aca54a2b198","questionId":"dd4dc378-ddcc-551b-bc16-20d42ad509d7","sourceKey":"bank:GST111:G111N2-016","payload":{"prompt":"The College of Medicine Library, Idi-Araba, classifies its books using the","options":["Dewey Decimal Classification scheme","National Library of Medicine (NLM) scheme","Universal Decimal Classification scheme","Library of Congress (LC) scheme"],"correctOption":1,"section":"Information Retrieval Tools","explanation":"The College of Medicine Library at Idi-Araba uses the National Library of Medicine scheme, which is designed for the medical sciences. The Library of Congress scheme is the tempting choice because the UNILAG main library uses it, but the medical library follows NLM."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 558, $official_bank_source${"itemId":"8aceedc9-7836-5c1e-85f2-09a21647c33a","questionId":"e5ff8e43-87f8-5858-b175-2a8716bc8200","sourceKey":"bank:GST111:G111N2-017","payload":{"prompt":"The two public catalogue cabinets in the UNILAG library are the","options":["Title and Series catalogues","Shelf-list and Authority catalogues","Author and Keyword catalogues","Author/Title and Subject catalogues"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"UNILAG has two public catalogue cabinets: one for Author/Title and one for Subject. The Shelf-list and Authority catalogues also exist, but they are for official (staff) use, not for the public."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 559, $official_bank_source${"itemId":"510cebe4-7b92-5ee4-b00c-8fd30e9176d6","questionId":"1c4b1207-af0f-576f-b94e-9821c0e4e904","sourceKey":"bank:GST111:G111N2-018","payload":{"prompt":"Which catalogues in the library are meant for official use rather than for library users?","options":["The card catalogue and the OPAC","The index and the abstract","The Shelf-list and Authority catalogues","The Author/Title and Subject catalogues"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"The Shelf-list and the Authority catalogues are kept for official use by library staff. The Author/Title and Subject catalogues are the tempting wrong answer, but those are the two public cabinets that users consult."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 560, $official_bank_source${"itemId":"02062a20-d828-5956-b00b-e8432cf8300f","questionId":"654c5985-9803-59e6-843e-eaff84de4043","sourceKey":"bank:GST111:G111N2-019","payload":{"prompt":"Indexes and abstracts are often described as","options":["bridges to published information","official-use catalogues","gateways to the library shelves","controlled vocabularies"],"correctOption":0,"section":"Information Retrieval Tools","explanation":"Indexes and abstracts are called bridges to published information because they lead the user to articles and documents that have been published. They are not official-use catalogues; that term refers to the Shelf-list and Authority catalogues kept by library staff."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 561, $official_bank_source${"itemId":"459e8827-bc66-5cf9-9f34-2346038e39de","questionId":"c9df1685-d7f0-576c-8ad6-a341916c0ed3","sourceKey":"bank:GST111:G111N2-020","payload":{"prompt":"Which of the following best describes an index?","options":["A pointer that gives entry points to information but not the full text","A brief summary of a book, article or thesis","The number that shows where a book is shelved","A list of books or written works on a subject"],"correctOption":0,"section":"Information Retrieval Tools","explanation":"An index is a pointer or indicator: it tells you where information can be found but does not give you the full text. A brief summary of a book or article is an abstract, which is a different tool, even though the two are often mentioned together."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 562, $official_bank_source${"itemId":"48b21976-0561-5077-b429-950b5ce12944","questionId":"08fc8660-0b00-5db7-8efe-53ccdb9eb163","sourceKey":"bank:GST111:G111N2-021","payload":{"prompt":"Engineering Index and Index Medicus are examples of","options":["bibliographies","indexes","abstracts","library catalogues"],"correctOption":1,"section":"Information Retrieval Tools","explanation":"Engineering Index, Index Medicus and the Newspaper Index are all indexes, which point to where information can be found. They are not abstracts; examples of abstracts are Chemical Abstracts, Dissertation Abstracts and LISA, which give brief summaries of documents."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 563, $official_bank_source${"itemId":"f85a428d-6e29-5f21-84d6-6c035c2c2e67","questionId":"7771243e-dbc7-5639-b47d-2327919bd70d","sourceKey":"bank:GST111:G111N2-022","payload":{"prompt":"NBN and BNB are examples of which information retrieval tool?","options":["Library databases","Bibliographies","Indexes","Abstracts"],"correctOption":1,"section":"Information Retrieval Tools","explanation":"A bibliography is a list of books or other written works on a subject, and NBN and BNB are examples of such lists. Indexes are tempting because they also point to information, but examples of indexes are Engineering Index and Index Medicus."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 564, $official_bank_source${"itemId":"180171ec-2bfe-5b30-8007-430b2a33cdc9","questionId":"fc420290-5944-50ac-9ddc-eb201a3bd221","sourceKey":"bank:GST111:G111N2-023","payload":{"prompt":"In a library catalogue, terms that lead the user from known terms to unknown ones and back are called","options":["call numbers","authority entries","cross-references","subject keywords"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"Cross-references link related terms in the catalogue, taking the user from a term they know to one they do not know, and back. A call number is different: it is the number generated when an item is catalogued and shows where it is located."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 565, $official_bank_source${"itemId":"d2b33e40-a321-54c3-b4ae-0793ac6c87a8","questionId":"dabf10ef-841e-52d4-b047-407943fba70e","sourceKey":"bank:GST111:G111N2-024","payload":{"prompt":"A UNILAG student searching the OPAC with \"Author (last name first)\" for a book by Chinua Achebe should type","options":["Chinua Achebe","Chinua A.","Achebe, Chinua","Chinua, Achebe"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"An author search with \"last name first\" requires the form LAST NAME, FIRST NAME, so the entry is \"Achebe, Chinua\". \"Chinua Achebe\" is how the name is normally written, which makes it tempting, but it puts the first name first."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 566, $official_bank_source${"itemId":"bf988e11-02bc-5c22-9c07-e2189c128121","questionId":"d2cd91e0-011f-51a1-a956-5f9f5ef08f6e","sourceKey":"bank:GST111:G111N2-025","payload":{"prompt":"A law student at UNILAG wants databases devoted to legal information. Which group should she use?","options":["EBSCOhost and JSTOR","Jaypee Digital","Westlaw, HeinOnline and LexisNexis","Dogpile and Metacrawler"],"correctOption":2,"section":"Information Retrieval Tools","explanation":"Westlaw, HeinOnline and LexisNexis are the law databases. EBSCOhost and JSTOR are tempting because they are well known, but they are interdisciplinary databases covering many subjects, not law specifically."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 567, $official_bank_source${"itemId":"b08f700d-54cd-56d0-a64e-c485c2b2ab90","questionId":"2731a631-2e5f-5850-add9-56ae682523a2","sourceKey":"bank:GST111:G111N2-026","payload":{"prompt":"When results in a library database are ranked by date, they are arranged","options":["chronologically, on a first in, first out basis","chronologically, on a last in, first out basis","alphabetically by author's surname","by how often the search terms appear"],"correctOption":1,"section":"Information Retrieval Tools","explanation":"Ranking by date is chronological and follows LIFO, last in, first out, so the newest items appear first. Ranking by how often the search terms appear is a different method, ranking by relevance."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 568, $official_bank_source${"itemId":"6433d4a2-3fd3-5fbd-b198-659e4ed56bd4","questionId":"ab786255-ac24-5ac1-933f-0027b2df79d9","sourceKey":"bank:GST111:G111N2-027","payload":{"prompt":"In the Library of Congress scheme, books on Mathematics are found in subclass","options":["QA","QD","QC","HA"],"correctOption":0,"section":"Information Retrieval Tools","explanation":"Under class Q (Science), QA is Mathematics. QC is Physics and QD is Chemistry, and HA, though it holds Statistics, belongs to the Social science class H."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 569, $official_bank_source${"itemId":"c195682d-5f71-5367-a0f7-c29a8f37d0d3","questionId":"d2d5523b-bcff-52d5-bd64-78ee8558b472","sourceKey":"bank:GST111:G111N2-028","payload":{"prompt":"A Business Administration student at UNILAG wants books on finance. Under the Library of Congress scheme, she should go to subclass","options":["HG","HF","HC","HB"],"correctOption":0,"section":"Information Retrieval Tools","explanation":"Under class H (Social science), HG is Finance. HF is the closest wrong choice, but it holds Commerce, while HB is Economic theory and HC is Economic history."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 570, $official_bank_source${"itemId":"c32ae9e8-9433-5d61-b919-05d7657700df","questionId":"f288dec9-8139-5cfc-921c-7c4bf74cd133","sourceKey":"bank:GST111:G111N2-029","payload":{"prompt":"In the National Library of Medicine (NLM) scheme, the preclinical sciences are classed in","options":["R","W to WZ","QA to QR","QS to QZ"],"correctOption":3,"section":"Information Retrieval Tools","explanation":"NLM places the preclinical sciences, such as Human Anatomy (QS) and Physiology (QT), in QS to QZ. W to WZ is the tempting choice, but that range is used for medicine itself, such as WY Nursing."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 571, $official_bank_source${"itemId":"41b94466-233b-5628-ac86-80262d704b95","questionId":"1119c776-644a-5299-bfb3-8981a1ef0304","sourceKey":"bank:GST111:G111N2-030","payload":{"prompt":"A UNILAG student needs a book held only by another university's library. Since students do not have reciprocal borrowing rights at all Nigerian universities, the service to use is","options":["interlibrary loan","an OPAC advanced search","cross-referencing","the Shelf-list"],"correctOption":0,"section":"Information Retrieval Tools","explanation":"Interlibrary loan lets UNILAG obtain an item from another library for its user, although it can take a week or more. An OPAC advanced search is tempting, but it only searches the library's own catalogue and cannot bring in a book from elsewhere."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 572, $official_bank_source${"itemId":"1688edaf-6b0a-55ff-8e56-eb7cbe72e37c","questionId":"59cbca13-7137-5afd-beba-4399c65baf10","sourceKey":"bank:GST111:GST111-0103","payload":{"prompt":"Meta Search involves use of ........................","options":["meta search engines","primary search engines","advanced search engines","basic search engines"],"correctOption":0,"section":"Search Strategies","explanation":"A meta search uses meta search engines, option A, such as Dogpile, Metacrawler, Search.com and Vivisimo, which send your query to several ordinary search engines at once and gather the results together. Options B, C and D (primary, advanced or basic search engines) describe single search engines or search modes, not the tool that performs a meta search."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 573, $official_bank_source${"itemId":"3b62bba1-49b2-5494-ae4d-958811ada71a","questionId":"3e5bd0e5-a64d-5399-9705-1716929758a0","sourceKey":"bank:GST111:GST111-0186","payload":{"prompt":"A quote is used in research write up to..................","options":["show off your writing skills","use vocabulary","convince your supervisor","support an argument"],"correctOption":3,"section":"Search Strategies","explanation":"You use a quotation to add the power of the author's own words to support your argument, and also to disagree with an author, compare points of view or note existing research, so D is correct. Showing off your writing skills, using vocabulary or convincing your supervisor (A, B and C) are not academic reasons for quoting."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 574, $official_bank_source${"itemId":"bbd46b80-c3cd-5f04-adfe-722346aa3707","questionId":"66b9d99c-b3f3-5e8b-8561-aa74815ee98d","sourceKey":"bank:GST111:GST111-0209","payload":{"prompt":"\"OR\" is used as a search strategy when a user wants to ........... the search","options":["Limit","Develop","Broaden","Narrow"],"correctOption":2,"section":"Search Strategies","explanation":"The Boolean operator OR connects similar concepts or synonyms and broadens your search, because it tells the database that any of the terms may be present. Options A and D (limit, narrow) describe what AND and NOT do, and B (develop) is not a search function."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 575, $official_bank_source${"itemId":"d9b765fc-bd84-51b0-a978-ca9df412d00b","questionId":"f46c24d2-5bc9-543e-81ee-a32a0ca18bf2","sourceKey":"bank:GST111:GST111-0217","payload":{"prompt":".............. is done to reduce the amount of items retrieved in advanced search","options":["Filtering","Exercises","Research","Simple search"],"correctOption":0,"section":"Search Strategies","explanation":"Filtering is what you do in an advanced search to refine for relevancy and reduce the number of items retrieved, using multiple search fields. Option D (simple search) does the opposite, often returning a huge amount of output, and B and C (exercises, research) are not search operations."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 576, $official_bank_source${"itemId":"a510ad44-d0ef-5ae9-bc0c-96b7d96a2db7","questionId":"bc391d14-739d-580a-b2b2-91e99ba4ddc5","sourceKey":"bank:GST111:GST111-0251","payload":{"prompt":"Subject Searching allows one to ...........","options":["Browse from Library OPAC","Browse for items by subject","Browse for items by clause heading","Browse for items by phrase heading"],"correctOption":1,"section":"Search Strategies","explanation":"A subject search lets you browse for items by subject heading, returning only records where the term appears in the subject field. Option A is too general, since the OPAC can also be searched by title, author, series or keyword, and C and D name search types that do not exist."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 577, $official_bank_source${"itemId":"bfa13ce1-1058-59db-910e-0a25c02067e3","questionId":"c76a27e1-2b44-562b-aacf-4a1a160e9d85","sourceKey":"bank:GST111:GST111-0259","payload":{"prompt":"A useful search tool for academic information is ..............","options":["Web crawler","Opera mini","Google scholar","Google"],"correctOption":2,"section":"Search Strategies","explanation":"Google Scholar is a useful search tool for academic information because it indexes scholarly materials such as books, patents, journal articles and conference papers. Option D (Google) is tempting, but ordinary Google searches the whole web with no selection for scholarly quality. A (web crawler) is a program that collects web pages and B (Opera Mini) is a browser, not a search tool."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 578, $official_bank_source${"itemId":"362214fe-bd2f-594e-b6c3-772a60b878cb","questionId":"88c93f8f-3759-5176-9276-7044ec06c640","sourceKey":"bank:GST111:GST111-0268","payload":{"prompt":"Advanced search allows you to limit your searches by:","options":["Size of book","Year of publication","Number of pages","Volume of book"],"correctOption":1,"section":"Search Strategies","explanation":"Advanced or field searching lets you narrow a search by specific fields such as year of publication, language or author, so B is correct. Size, number of pages and volume (A, C and D) are not standard limiters in library databases."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 579, $official_bank_source${"itemId":"553d5cee-efc2-5d0b-a213-338e569e98b2","questionId":"a010950e-250f-5c47-b37e-2dd1b6e38560","sourceKey":"bank:GST111:GST111-0292","payload":{"prompt":"When keywords are embedded in quotes, the type of search performed is ..............","options":["Phrase search","Subject search","Boolean search","Basic search"],"correctOption":0,"section":"Search Strategies","explanation":"Phrase searching puts the keywords in quotation marks so the search engine returns only records where those words appear side by side in that order. Option C (Boolean search) uses operators like AND and OR, and B (subject search) searches the subject field, so neither depends on quotation marks."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 580, $official_bank_source${"itemId":"d499cf5b-fd26-557b-a0c7-1ef97986722f","questionId":"b50a10e5-da12-5c87-98a5-37848f43b340","sourceKey":"bank:GST111:GST111-0295","payload":{"prompt":"............. allows a User to apply multiple search fields","options":["Complex search","Quick search","Advanced search","Simple search"],"correctOption":2,"section":"Search Strategies","explanation":"Advanced search lets the user apply multiple search fields and filters to narrow down results. Options B and D (quick and simple search) use a single keyword box, and A (complex search) is not a recognised search type."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 581, $official_bank_source${"itemId":"7298789f-bd72-5aa3-aca3-e232826d8de4","questionId":"2d5fc16d-50e1-5bfb-b2c2-14ac4336cdcb","sourceKey":"bank:GST111:GST111-0297","payload":{"prompt":"All of these are the advantages of using advanced search EXCEPT ...........","options":["Ability to filter search","Ability to reduce number of items retrieved","Ability to use multiple search fields","Ability to retrieve huge amount of information"],"correctOption":3,"section":"Search Strategies","explanation":"The advantages of advanced search are that you can apply filters, reduce the number of items retrieved and use multiple search fields. Retrieving a huge amount of information is what a simple search tends to do, not an advantage of advanced search, so D is the exception."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 582, $official_bank_source${"itemId":"304df88d-3ed2-58ad-8742-37668e82f252","questionId":"8946dba4-403f-5ae8-a724-97d09cac33dc","sourceKey":"bank:GST111:GST111-0300","payload":{"prompt":"When there are too few sources retrieved for a search, one can ............","options":["Use the AND Boolean operator","Combine synonymous terms with the OR Boolean operator","Use the NOT Boolean operator","None of the above"],"correctOption":1,"section":"Search Strategies","explanation":"When too few sources come back, you should broaden the search by combining synonymous terms with the OR operator. Options A and C (AND and NOT) do the opposite, since both narrow a search and are used when there are too many results."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 583, $official_bank_source${"itemId":"87a4a598-0a7d-5df8-98e7-ebd90921792e","questionId":"5cbfcf1a-b3bd-5242-a79b-753bcde00408","sourceKey":"bank:GST111:GST111-0309","payload":{"prompt":"The use of keywords to perform quick information search is known as ............","options":["Simple search","Complex search","Meta search","Advanced search"],"correctOption":0,"section":"Search Strategies","explanation":"A simple search uses a few keywords to carry out a quick information search in a database or search engine. Option D (advanced search) involves filters and multiple fields, and C (meta search) uses several search engines at once, so neither is the quick keyword search described. Option B is not a recognised type."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 584, $official_bank_source${"itemId":"b7942d59-f20d-58c4-a739-ef488a2d19be","questionId":"c67e6d5a-3643-5047-a567-3abd3d6cdaea","sourceKey":"bank:GST111:GST111-0313","payload":{"prompt":"Effective use of the library resources requires ...............","options":["Punctuality","Search strategies","Smartness","Maturity"],"correctOption":1,"section":"Search Strategies","explanation":"Effective use of library resources requires search strategies, which is the art of planning and conducting searches to get the most efficient result. Punctuality, smartness and maturity (A, C and D) are personal qualities that do not by themselves help you find information."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 585, $official_bank_source${"itemId":"8e728f8c-e869-5b36-a1a5-da839714ac65","questionId":"185f947c-907f-5337-91ff-a015479fc89b","sourceKey":"bank:GST111:GST111-0341","payload":{"prompt":"The Boolean operator \"OR\" is used in a search to .............","options":["Differentiate words","All","Connect synonyms","Exclude words"],"correctOption":2,"section":"Search Strategies","explanation":"OR connects two or more similar concepts or synonyms and broadens a search, because any one of the terms can appear in the results. Option D describes NOT, which excludes words, and A does not describe any Boolean operator."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 586, $official_bank_source${"itemId":"deb67e75-062e-5cee-9a78-bdb94ec82f0c","questionId":"52207aed-8717-56c6-9d85-931da88e92aa","sourceKey":"bank:GST111:GST111-0351","payload":{"prompt":"A research exercise must be ..............driven","options":["Strategy","Lesson plan","Subject/topic","Subject plan"],"correctOption":2,"section":"Search Strategies","explanation":"A research exercise must be driven by a subject or topic, because identifying the subject matter is the first step in a search strategy. Option A, strategy, is the overall plan built around the topic, and B and D are not terms used in this context."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 587, $official_bank_source${"itemId":"022b031f-8819-530d-b37d-d9cce23a99e7","questionId":"f1b7cd69-4ca4-56bf-b4bf-b0750e8556ac","sourceKey":"bank:GST111:GST111-0356","payload":{"prompt":"Any of these can be used as method of saving information materials retrieved from an electronic source EXCEPT \\_\\_\\_\\_\\_\\_\\_\\_\\_\\_","options":["Email the document","Save the citation information/full text article","Memorise the source","Print the document"],"correctOption":2,"section":"Search Strategies","explanation":"Memorising a source leaves you no record to return to, so it is not a way of saving retrieved information (C). Catalogues and databases let you email, print or save the citation information and often the full text of an article, which is why A, B and D are all valid, and keeping a back-up copy is wise."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 588, $official_bank_source${"itemId":"8a29e30b-f7aa-595f-a697-1c343fa21cca","questionId":"e29f8982-0099-5f37-9d0e-c8a99dad83da","sourceKey":"bank:GST111:GST111-0376","payload":{"prompt":"The following are search techniques EXCEPT..............","options":["Truncation","Boolean","Wild card","Filtering"],"correctOption":3,"section":"Search Strategies","explanation":"Filtering is not a search technique in its own right; it is something advanced searching does to reduce the number of items retrieved (D). The recognised search techniques are Boolean searching, parenthesis, phrase searching, truncation, wildcards and field searching, which is why A, B and C are not the exception."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 589, $official_bank_source${"itemId":"b4906fe4-9bfc-5c7e-b124-f22bb84d017a","questionId":"5bdc39f8-9a51-5711-a1ad-02132f28c071","sourceKey":"bank:GST111:GST111-0425","payload":{"prompt":"When you retrieve research results that are too broad or unrelated, the way out is to...........","options":["Change your search strategy","Change your topic","Change the author","Change your location"],"correctOption":0,"section":"Search Strategies","explanation":"When your results are too broad or unrelated, you need to rethink your search strategy, for example by adding AND terms, using phrase searching or choosing more specific vocabulary (A). Changing your topic (B) abandons the research rather than improving the search, and changing the author or your location (C and D) would not make the results more relevant."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 590, $official_bank_source${"itemId":"c10b2651-8765-557f-a92a-287cd33f3a0f","questionId":"b765bdaf-c793-5a28-9255-5272f20338d7","sourceKey":"bank:GST111:GST111-0449","payload":{"prompt":"What is the process employed in achieving effective search results?","options":["Key","Search strategy","Call up number","Concept"],"correctOption":1,"section":"Search Strategies","explanation":"Search strategy is the art of planning and conducting searches to get the most efficient result, so it is the process asked about (B). Key (A) and concept (D) are elements you use within a search, while a call number (C) is the shelf address of a book, not a process."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 591, $official_bank_source${"itemId":"a2ef3721-728b-5277-b75c-2f65f356bf26","questionId":"3caf1369-1fbe-563d-b550-336be1034717","sourceKey":"bank:GST111:GST111-0456","payload":{"prompt":"When a user deploys a variety of search tools simultaneously, it is called ........","options":["Meta search","Advanced search","Simple search","Search tool"],"correctOption":0,"section":"Search Strategies","explanation":"A meta search is one where the user uses a variety of search tools at the same time, through meta search engines such as Dogpile and Metacrawler that search Google, Yahoo and others at once (A). Advanced search (B) applies filters and multiple fields within one tool, and simple search (C) uses a few keywords in a single search box."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 592, $official_bank_source${"itemId":"522e51ed-921a-5a8b-adb3-67e3a9cfe8fc","questionId":"91503b61-95ce-585c-8a51-130fe25ae100","sourceKey":"bank:GST111:GST111-0459","payload":{"prompt":"The asterisk sign (\\*) in a search is known as .............","options":["Simple search","Wild card","Phrase search","Truncation"],"correctOption":3,"section":"Search Strategies","explanation":"Truncation means putting an asterisk (*) after the root of a word so the search retrieves all its variations, for example teen* finding teens and teenagers (D). Option B, wildcard, is tempting, but wildcards replace a single letter and most commonly use the ? symbol, as in colo?r. Phrase searching (C) uses quotation marks, and simple search (A) is a basic keyword search."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 593, $official_bank_source${"itemId":"2946db2c-1182-547e-9d1d-e6486ca15c59","questionId":"d20bc69f-f93b-58cb-9d08-cc269f82a6d2","sourceKey":"bank:GST111:G111N2-031","payload":{"prompt":"In a basic search strategy, a general overview of a topic is best obtained from","options":["abstracts and indexes","a general encyclopaedia such as Britannica or Americana","a meta search engine","the card catalogue or OPAC"],"correctOption":1,"section":"Search Strategies","explanation":"After identifying the topic, the second step is to get a general overview, for example from a general encyclopaedia such as Britannica or Americana. Abstracts and indexes are tempting, but they belong to the third step, the narrower overview."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 594, $official_bank_source${"itemId":"e89a6314-da72-5e5e-b5d3-0c70fff291ff","questionId":"1d0e11b2-cf51-54c5-8e3f-e97887defe19","sourceKey":"bank:GST111:G111N2-032","payload":{"prompt":"Which of the following shows the correct order of the three basic steps in a search strategy?","options":["Identify the topic, take a narrower overview, get a general overview","Get a general overview, identify the topic, take a narrower overview","Identify the topic, get a general overview, take a narrower overview","Take a narrower overview, get a general overview, identify the topic"],"correctOption":2,"section":"Search Strategies","explanation":"A search begins by identifying the subject or topic, then moves to a general overview, and ends with a narrower overview using abstracts, indexes, bibliographies or the catalogue. Starting with the general overview is tempting, but a research exercise must be topic-driven, so the topic comes first."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 595, $official_bank_source${"itemId":"3bf24a9e-062b-5434-9b77-45685b78314d","questionId":"6d3d7c19-49b4-59bd-8d3b-d95887ca7a27","sourceKey":"bank:GST111:G111N2-033","payload":{"prompt":"In the five stages of electronic searching, what is the final stage?","options":["Decide which resources to use","Run the search","Review and refine","Define your information need"],"correctOption":2,"section":"Search Strategies","explanation":"The five stages end with reviewing the results and refining the search. Running the search is tempting, but it is the fourth stage; after it you still review what you found and adjust."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 596, $official_bank_source${"itemId":"3006a1a1-ef74-5be6-af80-6751eaef5c3e","questionId":"56420d73-c7c6-5651-8efd-33f562bc49e7","sourceKey":"bank:GST111:G111N2-034","payload":{"prompt":"In the five stages of electronic searching, which stage comes immediately after \"Decide which resources to use\"?","options":["Find out what search options they offer","Define your information need","Review and refine","Run the search"],"correctOption":0,"section":"Search Strategies","explanation":"Once you have chosen your resources, the next stage is to find out what search options they offer, and only then do you run the search. \"Run the search\" is tempting, but it is the fourth stage, not the third."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 597, $official_bank_source${"itemId":"bdfddbbe-f738-59aa-a349-17bc7ff04da1","questionId":"96494bbe-9cbd-522b-9f6c-17994ae025a8","sourceKey":"bank:GST111:G111N2-035","payload":{"prompt":"Boolean searching is based on the symbolic logic developed by","options":["George Boole, a 20th-century American librarian","Charles Boole, a 19th-century English philosopher","George Boole, a 19th-century English mathematician","George Bool, an 18th-century Scottish engineer"],"correctOption":2,"section":"Search Strategies","explanation":"Boolean searching takes its name from George Boole, a 19th-century English mathematician whose symbolic logic underlies the AND, OR and NOT operators. The option describing him as a 20th-century American librarian gets the name right but his century, nationality and profession wrong."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 598, $official_bank_source${"itemId":"3806d08f-53bf-5217-b5f9-3aafc9f20bf0","questionId":"2fa93436-48a0-5a84-84d7-e62e5d362db8","sourceKey":"bank:GST111:G111N2-036","payload":{"prompt":"What is the effect of using AND between search terms?","options":["It excludes the second term from the results","It makes the terms appear side by side as a phrase","It broadens the search, because any of the terms may appear","It narrows the search, because all the terms must appear"],"correctOption":3,"section":"Search Strategies","explanation":"AND narrows a search because every record retrieved must contain all the terms. Broadening, where any of the terms may appear, is what OR does, so that option is the most tempting mix-up."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 599, $official_bank_source${"itemId":"69bd3a1e-be97-5846-aaa5-c37b73cabb79","questionId":"dfbb1fdd-ae00-574d-8107-09346799e930","sourceKey":"bank:GST111:G111N2-037","payload":{"prompt":"A student searches for \"cloning NOT sheep\". What will the results contain?","options":["Records on sheep that do not mention cloning","Records on cloning that do not mention sheep","Records on both cloning and sheep","Records on either cloning or sheep"],"correctOption":1,"section":"Search Strategies","explanation":"NOT excludes the term that follows it, so the search keeps records on cloning and removes any that mention sheep. Records on both cloning and sheep would come from AND, which is the most likely confusion."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 600, $official_bank_source${"itemId":"37aea149-9413-5635-a173-a08571072f08","questionId":"bf6f9c73-8750-56a4-9eb7-58a310e3e08b","sourceKey":"bank:GST111:G111N2-038","payload":{"prompt":"When you type several words into Google without any operator between them, Google treats them as if they were joined by","options":["NOT","OR","AND","quotation marks"],"correctOption":2,"section":"Search Strategies","explanation":"Google implies AND between the terms you type, so it looks for pages containing all of them. It does not assume quotation marks; without them the words do not have to appear side by side as a phrase."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 601, $official_bank_source${"itemId":"7f05ee96-06e5-55c3-9ff2-28ca837ec075","questionId":"15986335-a8c7-524e-9273-d0be44699d01","sourceKey":"bank:GST111:G111N2-039","payload":{"prompt":"In the search \"(vomit OR diarrhoea) AND blood\", why are vomit OR diarrhoea placed in parentheses?","options":["So that those terms are excluded from the search","So that the search ignores different word endings","So that the two words must appear side by side","So that the terms inside the parentheses are read first"],"correctOption":3,"section":"Search Strategies","explanation":"Terms inside parentheses are read first, so the search first gathers records on vomit or diarrhoea and then keeps those that also mention blood. Making words appear side by side is the job of quotation marks in phrase searching, not parentheses."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 602, $official_bank_source${"itemId":"e75e3957-2def-57bb-96b3-5174ebce0d8c","questionId":"24dd791c-c8ca-5abe-8816-9a454ed5927d","sourceKey":"bank:GST111:G111N2-040","payload":{"prompt":"Which of the following search techniques broadens a search?","options":["Truncation","Phrase searching","Using NOT","Using AND"],"correctOption":0,"section":"Search Strategies","explanation":"Truncation broadens a search because a root with an asterisk retrieves all its endings, such as teen, teens and teenager. Phrase searching is tempting because it also uses a symbol, but quotation marks force the words to appear side by side, which narrows the search."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 603, $official_bank_source${"itemId":"04a52f4a-99b6-5e59-81be-8a730ae441bf","questionId":"bfd561fd-ca78-57a8-a605-21ade8b96b4c","sourceKey":"bank:GST111:G111N2-041","payload":{"prompt":"A search for \"colo?r\" that retrieves both \"color\" and \"colour\" is using","options":["field searching","truncation","phrase searching","a wildcard"],"correctOption":3,"section":"Search Strategies","explanation":"A wildcard, usually \"?\", stands for one character, which makes it useful for US and UK spellings such as color and colour. Truncation is the closest wrong answer, but it uses an asterisk at the end of a root to pick up all possible endings."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 604, $official_bank_source${"itemId":"74a09eb0-696d-5462-b970-4cb7caba2707","questionId":"bea7c899-2f72-5ab0-813e-ad922b26aab7","sourceKey":"bank:GST111:G111N2-042","payload":{"prompt":"A student in Ikeja limits a search so that her keyword must appear in the title and the results must be PDF files. Which technique is she using?","options":["Truncation","Boolean searching","Wildcard searching","Field searching"],"correctOption":3,"section":"Search Strategies","explanation":"Field searching restricts the search to a specific part of the record, such as the title, author, date range, language, domain or file type. Boolean searching is tempting, but it combines terms with AND, OR and NOT rather than targeting parts of the record."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 605, $official_bank_source${"itemId":"278f9ca3-b636-5c9e-b9f2-214b0f9dccd5","questionId":"63d3eeae-9a26-5aab-92ee-6a87e9d06fd7","sourceKey":"bank:GST111:G111N2-043","payload":{"prompt":"Which type of searching uses controlled vocabulary and searches only the subject or descriptor field?","options":["Subject searching","Meta search","Simple search","Keyword searching"],"correctOption":0,"section":"Search Strategies","explanation":"Subject searching relies on fixed subject headings (controlled vocabulary) and looks only in the subject or descriptor field, which makes it less flexible but gives very relevant results. Keyword searching is the opposite: it matches natural-language words anywhere in the record."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 606, $official_bank_source${"itemId":"5f1d0074-25b8-557a-bbce-48fe5b688ee0","questionId":"8233e1bf-83dd-549b-a804-556864388f26","sourceKey":"bank:GST111:G111N2-044","payload":{"prompt":"Search engines build their huge databases of Internet files by using","options":["librarians who select and evaluate each file","call numbers assigned during cataloguing","a crawler, robot or spider","controlled vocabulary and subject headings"],"correctOption":2,"section":"Search Strategies","explanation":"Search engines collect Internet files automatically with programs called crawlers, robots or spiders. Librarians who select and evaluate each file is the tempting wrong option, but search engines have no selection or evaluation policy at all."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 607, $official_bank_source${"itemId":"03bc165d-5e4b-5179-822e-ae472d7f0579","questionId":"f035a3a9-7d10-5349-96b2-c1f84d26c32e","sourceKey":"bank:GST111:G111N2-045","payload":{"prompt":"Which of the following statements about search engines such as Google is true?","options":["They have no selection or evaluation policy","They index only peer-reviewed journal articles","They search only the subject or descriptor field","They are subscribed to by the university library"],"correctOption":0,"section":"Search Strategies","explanation":"Search engines collect whatever their crawlers find and have no selection or evaluation policy, which is why their results must be judged carefully. Being subscribed to by the library describes library databases such as JSTOR and EBSCOhost, not search engines."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 608, $official_bank_source${"itemId":"ec27d6db-82c5-55e8-8a8c-bfb97e3b45af","questionId":"cf1d682c-b7ce-5806-b7e9-890aa42bfdf3","sourceKey":"bank:GST111:G111N2-046","payload":{"prompt":"Which of the following is a meta search engine?","options":["EBSCOhost","Google Scholar","JSTOR","Dogpile"],"correctOption":3,"section":"Search Strategies","explanation":"Dogpile, like Search.com and Metacrawler, is a meta search engine that searches several tools such as Google and Yahoo at the same time. JSTOR and EBSCOhost are library databases, and Google Scholar is a single search tool for academic information."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 609, $official_bank_source${"itemId":"9c27d100-4bf2-53ea-b7d0-4e223570283a","questionId":"20ce50c0-5dbc-5d9e-93a8-8d3c4473afef","sourceKey":"bank:GST111:G111N2-047","payload":{"prompt":"A 100L student researching \"the effects of acid rain on the crops in Ogun State\" should prepare keywords by","options":["keeping only the verbs in the sentence","typing the full sentence exactly as written","using nouns and noun phrases and dropping articles and prepositions","putting the whole sentence in quotation marks"],"correctOption":2,"section":"Search Strategies","explanation":"Good keywords are nouns and noun phrases, such as acid rain, crops and Ogun State, with words like \"the\" and \"on\" left out. Typing the full sentence is tempting, but searches work poorly with full sentences because the extra words add nothing useful."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 610, $official_bank_source${"itemId":"c74c96dd-5d1f-5760-b74c-c04d9dd4d2dc","questionId":"d62c49be-46af-5bb2-bb57-791de845451c","sourceKey":"bank:GST111:G111N2-048","payload":{"prompt":"A search returns too many unrelated results. Which of the following would help?","options":["Using broader vocabulary","Searching the title field only","Dropping the least important concept","Combining synonyms with OR"],"correctOption":1,"section":"Search Strategies","explanation":"Restricting the search to the title field narrows the results, as do AND, NOT, phrase searching and more specific vocabulary. Combining synonyms with OR is the most tempting wrong option, but it broadens a search and is the remedy for too few results."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 611, $official_bank_source${"itemId":"1dfa4a5a-05a9-521b-876c-016325a6b351","questionId":"b635121d-17e7-5c9d-afce-e493608ab279","sourceKey":"bank:GST111:G111N2-049","payload":{"prompt":"A simple search is most suitable when","options":["you need to filter results by year of publication","you are unsure of what you need or the topic is unfocused","you want to use many search tools at the same time","you want to apply several search fields at once"],"correctOption":1,"section":"Search Strategies","explanation":"A simple search is a quick keyword search that suits an unfocused topic such as \"Malaria and Africa\", although it brings back a huge, often irrelevant output. Filtering by year of publication and applying several search fields are features of advanced search."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 612, $official_bank_source${"itemId":"4b7cf968-361d-5ded-8d3e-91e326b8ebde","questionId":"9592251b-5283-5100-8b99-2bd0294e87cc","sourceKey":"bank:GST111:GST111-0038","payload":{"prompt":"If a scholar does not acknowledge all quoted and borrowed ideas as he reads and writes, he is guilty of","options":["Perjury","Plagiarism","Permutation","Permissiveness"],"correctOption":1,"section":"Style Manual: Citation and Referencing","explanation":"Plagiarism is using someone's work or ideas without permission or without acknowledging where it came from, and it is often called academic theft, so B is correct. A scholar who does not acknowledge quoted and borrowed ideas is guilty of it. Perjury (A) is lying under oath, and permutation (C) and permissiveness (D) have nothing to do with academic honesty."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 613, $official_bank_source${"itemId":"a7585adf-cf69-51d4-95a2-d02d849827ae","questionId":"5f0719c1-4b92-5c21-a2a6-1396fb66d9ab","sourceKey":"bank:GST111:GST111-0055","payload":{"prompt":"A full entry in a bibliography must show:","options":["Authors name & year of publication","Title of work & place of publication","Publisher","All of the above"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"A full bibliography entry must identify the work completely, so it gives the author's name and year of publication, the title of the work, the place of publication and the publisher. Each of A, B and C is only part of a complete entry, so D, all of the above, is correct."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 614, $official_bank_source${"itemId":"a02f75de-530a-57b2-8110-01718ba8fe54","questionId":"ceab1b5b-44f1-51c2-8d6d-ca929be9d821","sourceKey":"bank:GST111:GST111-0057","payload":{"prompt":"The arrangement of bibliography is","options":["Chronological","Idiosyncratic","Alphabetical","Whimsical"],"correctOption":2,"section":"Style Manual: Citation and Referencing","explanation":"A bibliography is arranged alphabetically, option C, using the author's surname (or the title if there is no author), so readers can find any source quickly. Chronological order (A) is not the standard, and idiosyncratic (B) or whimsical (D) arrangements would make the list useless to readers."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 615, $official_bank_source${"itemId":"3ee3181f-b614-53d7-8748-f3a11a924ca5","questionId":"4c98c328-eeb6-5ea7-9fa2-5baa55aeb7b2","sourceKey":"bank:GST111:GST111-0096","payload":{"prompt":"The bibliography is usually located at ___ part of a research work","options":["The beginning","The middle","The end","The preliminary"],"correctOption":2,"section":"Style Manual: Citation and Referencing","explanation":"The bibliography, or reference list, is placed at the end of a research work, option C, so readers can follow the brief in-text citations to the full details of each source. The beginning (A) and preliminary pages (D) hold items like the title page and abstract, and nothing like a bibliography goes in the middle (B)."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 616, $official_bank_source${"itemId":"99b77ebf-e835-5646-98a1-aa2017e89529","questionId":"50f69090-c534-5885-a426-fb2f8e808831","sourceKey":"bank:GST111:GST111-0127","payload":{"prompt":"All of the following sources can be cited in a reference list EXCEPT.........","options":["Chapter or article in edited book","Web page","Books","None of the above"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"Books, chapters or articles in edited books, and web pages can all be cited in a reference list, so every source in A, B and C is allowed. Since none of them is excluded, D, none of the above, is correct. Choosing A, B or C would wrongly suggest that a legitimate source type cannot be referenced."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 617, $official_bank_source${"itemId":"8538d825-54f7-590d-932a-4e0beccab52a","questionId":"e792f86e-1943-57cc-a56a-de49ca3c6cc8","sourceKey":"bank:GST111:GST111-0131","payload":{"prompt":"In-text citation appears in the body of the manuscript.","options":["False","Partially true","True","Partially false"],"correctOption":2,"section":"Style Manual: Citation and Referencing","explanation":"The statement is true, option C. Referencing has two parts: the in-text citation, which appears in the body of the manuscript right where another writer's idea or words are used, and the reference list at the end of the work. Options A, B and D wrongly suggest the in-text citation sits somewhere other than the manuscript."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 618, $official_bank_source${"itemId":"510f38cc-ab1c-5827-8919-bdea58f39a1f","questionId":"012ac432-30ce-5181-bded-57947b8ddacd","sourceKey":"bank:GST111:GST111-0166","payload":{"prompt":"Copyrighted works are protected by .............","options":["Book seller","Law","The author","Publisher"],"correctOption":1,"section":"Style Manual: Citation and Referencing","explanation":"Copyright law (or author's right) says that no one may use a creative work without the owner's permission, and anyone who does so is liable to prosecution, so B, law, is correct. The author (C) owns the right, but the protection comes from the law, while a book seller (A) and a publisher (D) merely sell or produce the work."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 619, $official_bank_source${"itemId":"5a325fda-27fc-5dba-8f5f-c6d6a8525751","questionId":"06a3ff62-f24e-582c-a811-770aae1a71da","sourceKey":"bank:GST111:GST111-0167","payload":{"prompt":"A student that has committed plagiarism can be ...........","options":["Suspended or rusticated","Jailed","Given an award","Promoted"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"A student caught plagiarising can be suspended or rusticated, meaning sent away from school for a period, so A is correct. Option B, jailed, is tempting because prosecution is possible, but the usual penalty for a student is suspension or rustication. Options C and D (an award, a promotion) are rewards, not punishments."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 620, $official_bank_source${"itemId":"08834c3b-8655-5395-a914-df670ac91956","questionId":"5e3244d7-a9a3-55cd-a0a5-a767ca728f5f","sourceKey":"bank:GST111:GST111-0180","payload":{"prompt":"To avoid plagiarism","options":["Other people's ideas must be paraphrased and cited","A lecturer must be consulted","One must use library properly","Manuscript must be read"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"Plagiarism is avoided by acknowledging the work you use: paraphrasing other people's ideas properly and citing the sources in the prescribed style and the reference list. Option A captures exactly that. Consulting a lecturer (B), using the library (C) or reading the manuscript (D) may be good habits, but none of them by itself stops you from plagiarising."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 621, $official_bank_source${"itemId":"fa16d176-39a1-57b7-9c3c-55b547462b08","questionId":"a444f5f8-83c1-5144-9648-601069156e66","sourceKey":"bank:GST111:GST111-0189","payload":{"prompt":"One of these does not appear in the reference list","options":["Author's name","Page","Title of a work","Keyword"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"A reference list entry records the author's surname and initials, the title of the work, and publication details such as place, publisher, date and page numbers. A keyword is just a term you type into a search engine or database to find material, so it never appears in a reference entry. That makes D correct, while A, B and C are all standard parts of a reference."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 622, $official_bank_source${"itemId":"86610587-ca4e-5599-80b5-5a63711bf1c8","questionId":"5c2f6fec-9afe-510c-87ba-dd6609f138b2","sourceKey":"bank:GST111:GST111-0207","payload":{"prompt":"All are eligible for copyright according to World Intellectual Property Organization, EXCEPT ........","options":["Painting","Music","Books","Complimentary cards"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"Works eligible for copyright under the World Intellectual Property Organization include books, music, paintings, sculpture, films, computer programs, databases, advertisements, maps and technical drawings. Complimentary cards are not on that list, so D is the exception, while A, B and C are all eligible."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 623, $official_bank_source${"itemId":"06ce0eb2-b6e4-55f0-89fe-35c99fee7fea","questionId":"08e030fe-0803-5039-9ab5-f37403c66de1","sourceKey":"bank:GST111:GST111-0214","payload":{"prompt":"Fair use allows the usage of copyrighted works for ............","options":["Business purposes","Prosecution purposes","Publishing purposes","Academic purposes"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"Fair use allows copyrighted works to be used without permission for purposes such as criticism, comment, news reporting and teaching, in short for academic purposes within certain limits. Options A and C (business, publishing) are commercial uses that need permission, and B (prosecution) is what can happen when copyright is infringed, not a permitted use."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 624, $official_bank_source${"itemId":"038fa583-a150-5793-9608-a52466b2a8bf","questionId":"be9dc44f-51c2-5028-9db9-a0aa6c1fd1ed","sourceKey":"bank:GST111:GST111-0242","payload":{"prompt":"The most commonly used citation style in Social sciences is ..............","options":["APA","MLA","Harvard","Chicago"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"APA (American Psychological Association) style is the one most commonly used to cite sources in the social sciences. Option B (MLA) is associated with composition and language courses, D (Chicago) with the humanities, and C (Harvard) is an author-date style popular with university students generally but not tied to the social sciences."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 625, $official_bank_source${"itemId":"ee4db8fb-89fe-5505-a1f4-a37a2da7fa7c","questionId":"7e52ed47-c03e-5b20-9cdf-593cc69edc17","sourceKey":"bank:GST111:GST111-0260","payload":{"prompt":"To avoid plagiarism, all used works must be ........","options":["Cited","Typed","Noted","Grouped"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"To avoid plagiarism, any work you use must be cited, through proper in-text citation and a reference list, so the original author gets credit. Typing, noting or grouping the works (B, C and D) does not credit the author and so does not prevent plagiarism."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 626, $official_bank_source${"itemId":"7ee8e8f5-a621-5c3d-bf6b-29231eae3f9b","questionId":"adcaf318-513c-54be-ba81-7de12e9726b4","sourceKey":"bank:GST111:GST111-0262","payload":{"prompt":"APA recommends that a book without an author should be cited in the text using .........","options":["The year of publication only","The publisher's name","The first few words of the title","The name of the library"],"correctOption":2,"section":"Style Manual: Citation and Referencing","explanation":"When a book has no author, APA uses the first few words of the title in place of the author's name in the in-text citation, followed by the year. Option A is wrong because the year alone cannot tell the reader which source is meant, and B and D (publisher, library) are never used in place of the author."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 627, $official_bank_source${"itemId":"edac063f-a839-5086-87a0-fde7463017a0","questionId":"a259b208-cedd-5177-904f-cc142decf91a","sourceKey":"bank:GST111:GST111-0286","payload":{"prompt":"............ is when a researcher paraphrases correctly","options":["Unfair use","Academic theft","Plagiarism","Fair use"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"Fair use allows copyrighted material to be used for academic purposes within limits, and paraphrasing correctly, with acknowledgment, is one of the skills that keeps a researcher within it. Option C (plagiarism) is using someone's work without acknowledgment, and A (unfair use) is copying indiscriminately, so correct paraphrasing is the opposite of both. Option B is not the term used."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 628, $official_bank_source${"itemId":"eef380a3-4e12-5c7f-8fc6-c479c096780b","questionId":"ab3973e9-2e66-5f64-926c-460e234b3e3b","sourceKey":"bank:GST111:GST111-0303","payload":{"prompt":"An offence of self-plagiarism is said to have been committed if ..........","options":["None of these","You copy from your previous assignment for a new assignment without acknowledgment","You copy from your lecturer's handout without acknowledgement","You copy from the internet without acknowledgement"],"correctOption":1,"section":"Style Manual: Citation and Referencing","explanation":"Self-plagiarism happens when you copy from your own previous assignment for a new one without acknowledgment, because even your own earlier work must be cited. Options C and D describe ordinary plagiarism of other people's material, since the handout and the internet content are not your own work. Option A is wrong because B fits."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 629, $official_bank_source${"itemId":"d4f09b82-fa1d-5144-9ac8-7ae561af9f6c","questionId":"56ced0bf-bd3d-56e6-9f2a-8befd612d092","sourceKey":"bank:GST111:GST111-0334","payload":{"prompt":"Bibliography refers to...................","options":["All of these","A list of the written sources of information on a subject","A list of books and articles that have been used by someone when writing on a subject","List of books, magazines, articles, etc. about a particular subject"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"A bibliography is a list of written sources of information on a subject, including the books and articles consulted while preparing a piece of work. Because B, C and D each express part of that definition, 'All of these' (A) is the best answer."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 630, $official_bank_source${"itemId":"b9ccf4f9-b0fa-5db7-90cb-21f88d127f6b","questionId":"ec05a3bf-b1ba-59e9-85fe-48281f4b8259","sourceKey":"bank:GST111:GST111-0354","payload":{"prompt":"............. is the act of using copyrighted work without permission or acknowledging the source.","options":["Dubbing","Copying and pasting","Plagiarism","Copying"],"correctOption":2,"section":"Style Manual: Citation and Referencing","explanation":"Plagiarism is using someone's work without permission or without acknowledging the source, and it is often described as academic theft. Copying and pasting, and copying (B and D) are actions that can lead to plagiarism but are not the name of the offence, and dubbing (A) means adding a new soundtrack to a film."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 631, $official_bank_source${"itemId":"660d5022-d168-5626-b019-a5a8f1c46c5b","questionId":"02cc3ab4-3a0f-59bf-b143-3feb1bec1abc","sourceKey":"bank:GST111:GST111-0360","payload":{"prompt":"Which of the reference style excludes the year of publication in the in-text citation?","options":["MLA","APA","MPA","Harvard"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"In MLA style, the in-text citation gives the author's last name and the page number, for example (McDonagh 80), with no year. APA and Harvard (B and D) are author-date styles that include the year, and MPA (C) is not a referencing style."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 632, $official_bank_source${"itemId":"74ea372b-4731-58d6-81d7-dc15c3293d4f","questionId":"73933141-fd30-5fec-a887-3ceb1c77e60f","sourceKey":"bank:GST111:GST111-0362","payload":{"prompt":"Referencing is composed of two parts namely...................","options":["In-text referencing and reference list","Off-text referencing and referral list","Out-text referencing and bibliographies","On-text referencing and guide list"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"Referencing has two parts: in-text referencing, which is the brief citation in the body of your work, and the reference list at the end, which gives the full details. So A is correct. Options B, C and D use labels that do not exist in any referencing style."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 633, $official_bank_source${"itemId":"7f22af26-ccfb-594c-98d3-7a22cd825a68","questionId":"a3c23934-c56c-55be-8ed5-ae737e8fb9bf","sourceKey":"bank:GST111:GST111-0378","payload":{"prompt":"All of these are referencing styles EXCEPT ............","options":["MLA","NLA","APA","Harvard"],"correctOption":1,"section":"Style Manual: Citation and Referencing","explanation":"APA, MLA, Harvard and Chicago are the main referencing styles, so A, C and D are all real styles. NLA is not a referencing style, which makes B the exception."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 634, $official_bank_source${"itemId":"5e215187-584c-582e-a871-e35d6fbcc9e6","questionId":"e97710ea-ec02-5c7e-9d1d-ed87adf41a4f","sourceKey":"bank:GST111:GST111-0379","payload":{"prompt":"When you paraphrase a quote,","options":["you use your own words","you quote verbatim","you reuse it in another language","you use the exact words"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"To paraphrase is to express another writer's ideas in your own words. Options B and D describe quoting verbatim, which is the opposite of paraphrasing, and C, reusing it in another language, is translation, not paraphrase."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 635, $official_bank_source${"itemId":"8a55053c-55e6-5d63-8cb3-03967b49248d","questionId":"bbe25e00-d3f7-523e-a7a8-1d0be446602f","sourceKey":"bank:GST111:GST111-0380","payload":{"prompt":"When using the American Psychological Association (APA) referencing style, the reference list should be arranged in ....... order","options":["Numerical","Chronological","Alphabetical","Citation"],"correctOption":2,"section":"Style Manual: Citation and Referencing","explanation":"An APA reference list is set out in alphabetical order, using the author's surname, or the title when there is no author. Chronological order (B) is wrong because the date comes after the author, not first. Numerical order (A) belongs to numbered styles, not APA, and citation order (D) is not an APA rule."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 636, $official_bank_source${"itemId":"722e229f-1bb0-57bf-a600-f7580fbd0f8d","questionId":"9a477378-84e5-54f9-8e15-d4e6e5babf26","sourceKey":"bank:GST111:GST111-0408","payload":{"prompt":"Citation is a skill that must be learnt ...........","options":["For Library usage","For information retrieval","For chatting online","For academic purposes"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"Citation is a skill students must learn for academic purposes: to avoid plagiarism in an academic setting you must paraphrase correctly and acknowledge every source you use (D). Options A and B describe library skills rather than the reason for citing, and chatting online (C) has nothing to do with acknowledging sources."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 637, $official_bank_source${"itemId":"3217e60b-f949-5695-b98a-ede6b51ee71e","questionId":"a153031c-2142-51cf-a0a7-6a59216356bf","sourceKey":"bank:GST111:GST111-0423","payload":{"prompt":"The punishment for violating copyright law is ..............","options":["Prosecute the offender under the law","All of the above","Ban the offender from the library","Kill the offender"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"Copyrighted works are protected by law, so anyone who violates copyright can be prosecuted under the law (A). 'All of the above' (B) cannot be right because it would include killing the offender (D), which is not a legal punishment. A library ban (C) is not the legal penalty for breaking copyright law."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 638, $official_bank_source${"itemId":"781dc850-0a35-581f-88b9-daacd947d0d5","questionId":"077fc16f-0da0-5272-bb65-9d614c1350f0","sourceKey":"bank:GST111:GST111-0457","payload":{"prompt":"Using the APA referencing style, any article retrieved from a website with no date of publication should be cited in the reference list but the following information must be included:","options":["The url from where the article was accessed","The date the article was retrieved","The date and URL from where the document was obtained","None of the above"],"correctOption":2,"section":"Style Manual: Citation and Referencing","explanation":"An APA reference for a web document with no date uses (n.d.) and then states when and where it was obtained, as in 'Retrieved October 17, 2008, from' followed by the URL, so both the retrieval date and the URL are needed (C). Options A and B each give only one of the two required pieces of information, so they are incomplete."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 639, $official_bank_source${"itemId":"c04a07d4-75ef-5981-b7b3-56fd6d2b871d","questionId":"e17a6182-dc4b-597a-a23c-86360577c552","sourceKey":"bank:GST111:G111N2-050","payload":{"prompt":"The word \"plagiarism\" comes from the Latin word plagiarius, which means","options":["thief of books","copier","forger","kidnapper"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"Plagiarism comes from the Latin plagiarius, meaning \"kidnapper\", because the plagiarist carries off someone else's work as if it were his own. \"Thief of books\" is tempting since plagiarism is called academic theft, but that is not the meaning of the Latin word."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 640, $official_bank_source${"itemId":"8dc6752e-7263-54f8-bc8d-629dc7d49e7d","questionId":"2211c373-cfb0-5281-9daa-2a289da4028c","sourceKey":"bank:GST111:G111N2-051","payload":{"prompt":"Using the Internet to take another person's ideas or expression without acknowledgement is known as","options":["secondary citation","fair use","cyber plagiarism","self-plagiarism"],"correctOption":2,"section":"Style Manual: Citation and Referencing","explanation":"Cyber plagiarism is plagiarism carried out through the Internet, such as copying text from a website. Self-plagiarism is tempting, but it means copying from your own earlier assignment for a new one without acknowledgement."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 641, $official_bank_source${"itemId":"605e565c-c7f5-506d-ab74-7e20c14803a9","questionId":"9739c840-6be2-5f64-af2b-09bbefc8e394","sourceKey":"bank:GST111:G111N2-052","payload":{"prompt":"Using APA style, which of the following is cited in the text but NOT included in the reference list?","options":["A journal article read in JSTOR","A telephone conversation with a bank manager in Lagos","A book on management principles","A government report found on a website"],"correctOption":1,"section":"Style Manual: Citation and Referencing","explanation":"Personal communications such as conversations and emails cannot be retrieved by the reader, so they are cited only in the text. A government report on a website is tempting, but it can be retrieved, so it appears in both the text and the reference list."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 642, $official_bank_source${"itemId":"06d364c5-208d-50ee-862d-7b2c13f37a31","questionId":"2bc739d4-537c-5526-a348-2165c6169006","sourceKey":"bank:GST111:G111N2-053","payload":{"prompt":"In APA style, a direct quotation of 40 words or more should be","options":["placed within the text in single quotation marks and italics","moved to a footnote at the bottom of the page","placed within the text in double quotation marks","set as a block on a new line, indented, without quotation marks"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"A quotation of 40 words or more is set as a block starting on a new line, indented 5 spaces, with no quotation marks. Putting it in the text within double quotation marks is the rule for quotations of fewer than 40 words, which is why that option is tempting."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 643, $official_bank_source${"itemId":"8e062f28-9ff8-5efb-98a5-b61951bfbdf3","questionId":"22ad1cf9-97c5-52e7-a11b-9da6f54fba80","sourceKey":"bank:GST111:G111N2-054","payload":{"prompt":"A student read Talbot and Verrinder (2005), who quote Palfrey (2000), but she never read Palfrey's own work. In APA style, which work goes in her reference list?","options":["Palfrey (2000) only","Both Palfrey (2000) and Talbot and Verrinder (2005)","Talbot and Verrinder (2005) only","Neither source"],"correctOption":2,"section":"Style Manual: Citation and Referencing","explanation":"In a secondary citation, only the work you actually read goes in the reference list, so Talbot and Verrinder is listed and Palfrey is mentioned in the text as \"as cited in\". Listing both is tempting, but Palfrey's work was not consulted directly."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_gst111', 'add', 644, $official_bank_source${"itemId":"1e7dd323-2a9b-5187-b5bc-eedecee74a4b","questionId":"7793c89a-9b62-5087-91e4-f757cad5c43c","sourceKey":"bank:GST111:G111N2-055","payload":{"prompt":"Which of the following is a correctly formatted Harvard in-text citation?","options":["(Austen 64)","(Austen 1813, p. 64)","(1813 Austen, p. 64)","(Austen, 1813, p. 64)"],"correctOption":1,"section":"Style Manual: Citation and Referencing","explanation":"Harvard is an author-date style with no comma between the author and the year, as in (Austen 1813, p. 64). The version with a comma after Austen looks very similar, but that comma is the APA pattern, while (Austen 64) is the MLA author-page form."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 645, $official_bank_source${"itemId":"b55fe8e9-2f1c-58e9-9654-9ec5bf85f720","questionId":"a7ff7428-7267-5d74-bf6d-82baf8dbb789","sourceKey":"bank:GST111:G111N2-056","payload":{"prompt":"Which of the following is an entry in MLA Works Cited format?","options":["McDonagh, Sean. Why are we Deaf to the Cry of the Earth. Dublin: Veritas, 2001.","McDonagh, S. (2001). Why are we deaf to the cry of the earth. Dublin: Veritas.","Sean McDonagh, 2001. Dublin: Veritas. Why are we Deaf to the Cry of the Earth.","McDonagh, S 2001, Why are we deaf to the cry of the earth, Veritas, Dublin."],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"MLA Works Cited entries follow the pattern Last name, First name. Title. Place: Publisher, Year, with the year at the end. The entry with \"(2001)\" straight after the initial is the APA pattern, and the one with the year after the name and no brackets is Harvard."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 646, $official_bank_source${"itemId":"6b0e99eb-60d3-5f66-aaed-a7f438e8651f","questionId":"5c6156a2-cda5-53fe-851b-9467a9dd2a34","sourceKey":"bank:GST111:G111N2-057","payload":{"prompt":"In the APA reference \"Australian Nursing Journal, 12(7), 23-25\", which part is italicised along with the journal title?","options":["The volume number, 12","Both the volume and the issue numbers","The page range, 23-25","The issue number, 7"],"correctOption":0,"section":"Style Manual: Citation and Referencing","explanation":"In APA, the journal title and its volume number are italicised, while the issue number in brackets is not. Italicising both the volume and issue numbers is the tempting mistake, because they sit side by side."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 647, $official_bank_source${"itemId":"654263b8-6368-5b36-a254-4206aa683123","questionId":"86a550c9-7972-594f-9614-2bc82cfc2fba","sourceKey":"bank:GST111:G111N2-058","payload":{"prompt":"Which of the following is NOT a purpose allowed under fair use?","options":["Criticism and comment","Selling photocopies of a published book for profit","News reporting","Teaching"],"correctOption":1,"section":"Style Manual: Citation and Referencing","explanation":"Fair use permits criticism, comment, news reporting, teaching and similar non-commercial uses of copyrighted works. Selling photocopies for profit is commercial, so it falls outside fair use; teaching may look like it needs permission, but it is one of the allowed purposes."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 648, $official_bank_source${"itemId":"b1320982-b19b-5ccf-b6dc-97a1c8bfb8ca","questionId":"6944825a-5262-5712-bf54-54bbf66ba396","sourceKey":"bank:GST111:G111N2-059","payload":{"prompt":"Copying a copyrighted work indiscriminately, with or without acknowledgement, is called","options":["fair use","self-plagiarism","paraphrasing","unfair use"],"correctOption":3,"section":"Style Manual: Citation and Referencing","explanation":"Unfair use is indiscriminate copying of a copyrighted work, and acknowledging the author does not make it acceptable. Fair use is the tempting opposite: it is use for academic and similar purposes up to a certain limit."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 649, $official_bank_source${"itemId":"95bb2d28-6a43-5678-80ea-a883ecfb0177","questionId":"f1468137-6653-5a86-9419-a1b27d8575fb","sourceKey":"bank:GST111:G111N2-060","payload":{"prompt":"A member of staff found guilty of plagiarism can face","options":["loss of hostel accommodation","summary dismissal","a written warning only","rustication"],"correctOption":1,"section":"Style Manual: Citation and Referencing","explanation":"For staff, the consequence of plagiarism is summary dismissal, and prosecution is also possible. Rustication is tempting, but it is a penalty for students, together with suspension."}}$official_bank_source$::jsonb),
  ('official_bank_gst111', 'add', 650, $official_bank_source${"itemId":"c7afc734-cf5b-563b-9b3e-04a6b58a27a8","questionId":"51661132-9e5d-5c0b-8e91-3a131aa8f46b","sourceKey":"bank:GST111:G111N2-061","payload":{"prompt":"In APA style, page numbers are NOT required in the in-text citation when you","options":["quote fewer than 40 words directly","paraphrase or summarise an author's idea","quote 40 words or more as a block","quote a definition word for word"],"correctOption":1,"section":"Style Manual: Citation and Referencing","explanation":"A paraphrase or summary needs only the author's surname and the year, with no page number. Any direct quotation, short or long, needs the page number as well, which rules out the other three options."}}$official_bank_source$::jsonb);
